window.BINDMODEL_SEARCH = [{"title":"소개","group":"시작하기","section":"소개","url":"guide/introduction.html","text":"문서 시작하기 시작하기 01 소개 비즈니스 로직과 화면을 분리하는 BindModel의 설계와 특징을 알아봅니다. 한국어 문서 약 4분 BindModel 은 React 와 Vue 같은 현대적인 웹 프레임워크와 유연하게 연동되면서, 비즈니스 로직과 UI의 분리를 지원하는 독립적인 프레임워크입니다. SPA와 MPA 아키텍처를 모두 지원하며, 서버 측과 클라이언트 측에서 SSR과 CSR을 포함한 다양한 렌더링 방식을 제공합니다. 이를 통해 개발자는 비즈니스 로직의 재사용성을 극대화하고, 점진적인 개발을 통해 높은 생산성을 경험할 수 있습니다."},{"title":"소개","group":"시작하기","section":"핵심 기능","url":"guide/introduction.html#핵심-기능","text":"핵심 기능 비즈니스 로직의 분리 및 재사용성 비즈니스 로직과 UI를 철저히 분리(MVC 패턴) 동일한 비즈니스 로직을 여러 화면에서 재사용 가능 React 및 Vue 연동 Props Drilling 문제 해결 다양한 프론트엔드 프레임워크와의 호환성 제공 유연한 데이터 관리 MetaTable , MetaView 같은 엔티티를 통해 구조화된 데이터 처리 지원 데이터 상태 변경 추적 및 중앙 집중식 데이터 관리 가능 구조화된 데이터 처리 및 일반화를 지원하여 비즈니스 로직을 효과적으로 관리 명령 기반 개발 패턴 명령을 중심으로 비즈니스 로직을 구조화하고, 이를 일관된 방식으로 실행 명령을 조합해 복잡한 비즈니스 로직을 효율적으로 처리"},{"title":"소개","group":"시작하기","section":"특징","url":"guide/introduction.html#특징","text":"특징 독립적인 프레임워크 특정 프레임워크에 종속되지 않으며 독립적으로 사용 가능 유연한 개발 방식 점진적 개발 방식을 지원해 초기 설계 없이도 프로젝트를 시작 가능 HTML 기반 개발에서 컴포넌트 기반 개발로 자연스럽게 확장 가능 다양한 렌더링 방식 지원 SPA(React, Vue와의 연동) 및 MPA(Multi Page Application) 지원 서버 사이드 렌더링(SSR)과 클라이언트 사이드 렌더링(CSR)을 모두 지원 낮은 학습 곡선 새로운 문법 지시자가 아닌 전통적인 개발 스타일 기반 특정 프레임워크에 종속되지 않아 기존 지식으로 빠르게 적응 가능 생산성과 유지보수성 강화 재사용 가능한 비즈니스 로직과 엔티티 기반 구조로 코드를 간결하게 유지 데이터와 UI의 분리로 복잡한 애플리케이션도 쉽게 유지보수 가능 확장 및 통합 가능성 ES5와의 호환성을 통해 넓은 범용성 확보 기존 프로젝트 또는 새로운 프로젝트에 쉽게 통합 가능 단일 코드로 웹, Node.js 등 다양한 환경에서 작동 가능 BindModel 은 데이터 중심 애플리케이션 개발을 효율적으로 지원하며, 복잡한 비즈니스 로직을 관리하고 재사용 가능한 코드를 작성하는 데 적합합니다."},{"title":"소개","group":"시작하기","section":"기본 사용법","url":"guide/introduction.html#기본-사용법","text":"기본 사용법 BindModel 은 화면 요소와 데이터를 연결하고, 서버와의 데이터 송수신을 단순화하는 기능을 제공합니다. 이 섹션에서는 서버에 데이터를 전송하거나, 서버에서 받은 데이터를 화면에 매핑하는 기본적인 사용 방법을 설명합니다."},{"title":"소개","group":"시작하기","section":"1. 입력 요소 준비","url":"guide/introduction.html#1-입력-요소-준비","text":"1. 입력 요소 준비 HTML에서 사용할 입력 요소를 정의합니다. html < input id = \"u_name\" type = \"text\" value = \"Neo\" />"},{"title":"소개","group":"시작하기","section":"2. BindModel 객체 생성 및 컬럼 매핑","url":"guide/introduction.html#2-bindmodel-객체-생성-및-컬럼-매핑","text":"2. BindModel 객체 생성 및 컬럼 매핑 JavaScript 코드에서 BindModel 객체를 생성한 후, 컬럼과 화면 요소를 연결합니다. js // BindModel 객체 생성 var bm = new BindModel (); // 셀렉터 값으로 'idx' 컬럼을 추가하고, 'cmd1' 명령의 매핑 bm. addSelector ( 'u_name' , '#u_name' , 'cmd1' );"},{"title":"소개","group":"시작하기","section":"3. 서버와 데이터 송수신","url":"guide/introduction.html#3-서버와-데이터-송수신","text":"3. 서버와 데이터 송수신 command['cmd1'] 명령을 통해 서버로 데이터를 전송하거나, 서버로부터 데이터를 가져와 화면 요소에 자동으로 매핑할 수 있습니다. 서버로 데이터 전송 js bm. command [ 'cmd1' ]. execute ( 'SEND' , '/user' ); // 서버 경로 : /user // 전송 데이터 : { \"u_name\": \"Neo\" } 'item1'에 입력된 값을 서버로 전송합니다. 서버 응답 데이터 수신 js // 서버 경로 : /data/1 // 응답 데이터 : { \"u_name\": \"Jane\" } bm. command [ 'cmd1' ]. execute ( 'VIEW' , '/data/1' ); bm. columns [ 'item1' ]. value === 'Jane' ; // true 서버에서 데이터를 수신하여 'item1' 컬럼값에 설정합니다. Tip 다음과 같이 별칭 속성을 사용할 수 있습니다: bm.cmd['cmd1'].exec('SEND', '/user'); bm.cmd['cmd1'].exec('VIEW', '/data/1'); 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 다음 문서 빠른 시작"},{"title":"빠른 시작","group":"시작하기","section":"빠른 시작","url":"guide/quick-start.html","text":"문서 시작하기 시작하기 01 빠른 시작 설치부터 첫 데이터 바인딩까지, 작은 예제로 시작해 보세요. 한국어 문서 약 8분 예제 기준: logic-bind-model 1.1.13 Node.js에서는 npm 패키지를, 브라우저에서는 아래 CDN 파일을 사용하세요. 서버 요청 예제의 /user 는 직접 준비한 API 주소로 바꿔 주세요."},{"title":"빠른 시작","group":"시작하기","section":"BindModel 이란?","url":"guide/quick-start.html#bindmodel-이란","text":"BindModel 이란? BindModel 은 비즈니스 로직과 UI를 분리하여 재사용성과 유지보수를 극대화한 독립적인 웹 프레임워크입니다. React , Vue 와 같은 SPA 부터 MPA 및 SSR 환경까지 유연하게 지원하며, 구조화된 데이터 처리와 명령 기반 개발 패턴으로 생산성과 확장성을 제공합니다. HTML 기반의 전통적인 개발 스타일을 유지하면서도 최신 TypeScript와 ES5 호환성을 동시에 갖춘 범용 솔루션입니다."},{"title":"빠른 시작","group":"시작하기","section":"설치하기","url":"guide/quick-start.html#설치하기","text":"설치하기"},{"title":"빠른 시작","group":"시작하기","section":"node 환경","url":"guide/quick-start.html#node-환경","text":"node 환경 bash npm install logic-bind-model"},{"title":"빠른 시작","group":"시작하기","section":"브라우저 환경","url":"guide/quick-start.html#브라우저-환경","text":"브라우저 환경 html < script src = \"https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.js\" > </ script >"},{"title":"빠른 시작","group":"시작하기","section":"node 환경에서 사용하기","url":"guide/quick-start.html#node-환경에서-사용하기","text":"node 환경에서 사용하기"},{"title":"빠른 시작","group":"시작하기","section":"CommonJS 환경","url":"guide/quick-start.html#commonjs-환경","text":"CommonJS 환경 require 구문을 사용하여 모듈을 가져옵니다. js const { BindModel } = require ( 'logic-bind-model' ); const bm = new BindModel (); Tip MetaTable , MetaView , HTMLColumn 등 다양한 클래스를 가져올 수 있습니다."},{"title":"빠른 시작","group":"시작하기","section":"ESM 환경","url":"guide/quick-start.html#esm-환경","text":"ESM 환경 import 구문을 사용하여 모듈을 가져옵니다. js import { BindModel } from 'logic-bind-model' ; const bm = new BindModel ();"},{"title":"빠른 시작","group":"시작하기","section":"Typescript 환경","url":"guide/quick-start.html#typescript-환경","text":"Typescript 환경 TypeScript 에서도 import 구문을 동일하게 사용합니다. ts import { BindModel } from 'logic-bind-model' ; const bm : BindModel = new BindModel (); Tip 모듈 경로에 logic-bind-model/ko 를 지정하면 한글 타입 정보를 사용할 수 있습니다. 이는 다국어 타입 지원을 위한 준비 기능이며, 추후 다음 언어들이 순차적으로 지원될 예정입니다: 'ja', 'zh', 'hi', 'es', 'pt', 'ru', 'fr', 'de'"},{"title":"빠른 시작","group":"시작하기","section":"브라우저 환경에서 사용하기","url":"guide/quick-start.html#브라우저-환경에서-사용하기","text":"브라우저 환경에서 사용하기"},{"title":"빠른 시작","group":"시작하기","section":"ESM 환경","url":"guide/quick-start.html#esm-환경-2","text":"ESM 환경 브라우저에서 모듈 형식으로 사용하려면 type=\"module\" 속성을 사용합니다. html < script type = \"module\" > import { BindModel } from 'https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.esm.js' ; const bm = new BindModel (); </ script > Tip 위 경로의 JS 파일을 프로젝트 내에 복사한 후, 로컬 경로로도 불러올 수 있습니다."},{"title":"빠른 시작","group":"시작하기","section":"레거시 환경 (비모듈 브라우저)","url":"guide/quick-start.html#레거시-환경-비모듈-브라우저","text":"레거시 환경 (비모듈 브라우저) 레거시 환경에서는 전역 객체 _L 을 통해 접근합니다. html < script src = \"https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.js\" > </ script > < script > var BindModel = _L. BindModel ; var bm = new BindModel (); </ script > Tip _L 전역 변수로 MetaTable , MetaView , HTMLColumn 등 다양한 클래스에 접근할 수 있습니다."},{"title":"빠른 시작","group":"시작하기","section":"CDN 버전 및 유형 지정","url":"guide/quick-start.html#cdn-버전-및-유형-지정","text":"CDN 버전 및 유형 지정 파일 타입 지정 UMD/CJS/레거시 호환 https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.js ES 모듈 https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.esm.js Node.js CJS https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.node.cjs 버전 지정 문서 검증 버전(1.1.13) https://unpkg.com/logic-bind-model@1.1.13/dist/bind-model.js 특정 버전 지정 (1.1.2) https://unpkg.com/logic-bind-model@1.1.2/dist/bind-model.js 버전 범위 (예 : 1.1.x 의 최신) https://unpkg.com/logic-bind-model@v1.1/dist/bind-model.js 베타 버전 사용 https://unpkg.com/logic-bind-model@beta/dist/bind-model.js Tip 버전, 형식, 압축 여부는 URL 경로를 조합하여 자유롭게 지정할 수 있습니다."},{"title":"빠른 시작","group":"시작하기","section":"예제 소스","url":"guide/quick-start.html#예제-소스","text":"예제 소스 이 예제는 웹 애플리케이션에서 서버로부터 회원 정보를 조회하여 화면에 표시 하는 기본적인 구현 사례입니다."},{"title":"빠른 시작","group":"시작하기","section":"서버 응답 예시","url":"guide/quick-start.html#서버-응답-예시","text":"서버 응답 예시 json { \"u_code\" : 1234 , \"u_name\" : \"Neo\" }"},{"title":"빠른 시작","group":"시작하기","section":"HTML 구조","url":"guide/quick-start.html#html-구조","text":"HTML 구조 html < h2 id = \"u_code\" > </ h2 > < input id = \"u_name\" type = \"text\" />"},{"title":"빠른 시작","group":"시작하기","section":"JavaScript 구성","url":"guide/quick-start.html#javascript-구성","text":"JavaScript 구성 BindModel 은 사용 목적에 따라 다양한 방식으로 구성할 수 있습니다. 아래는 세 가지 패턴을 소개합니다. 간단하게 구성하기 가장 간단한 방법으로, 컬럼을 selector 형식으로 등록하고, 명령 실행시 경로와 타입을 지정합니다. js // BindModel 객체 생성 const bm = new BindModel (); // 컬럼을 selector 형식으로 등록하고, 'cmd1' 명령의 'output' 뷰에 매핑 bm. addSelector ( 'u_code' , '#u_code' , 'cmd1' , 'output' ); bm. addSelector ( 'u_name' , '#u_name' , 'cmd1' , 'output' ); // 'cmd1' 명령 실행: 서버에서 데이터를 조회하여 화면에 매핑 bm. command [ 'cmd1' ]. execute ( 'VIEW' , '/user' ); // 결과 // bm.columns['u_code'].value == 1234 // bm.columns['u_name'].value == 'Neo' 'cmd1'은 명령 이름이고, 'output'은 해당 명령의 출력 뷰 이름입니다. 명령 옵션 : 'SEND', 'VIEW', 'ALL', 'PICK' 뷰 종류: valid , bind , output , misc 단계별로 구성하기 각 단계를 명확히 분리하여 명령, 컬럼, 셀렉터를 순차적으로 설정합니다. js // BindModel 객체 생성 const bm = new BindModel (); // 서버 URL 설정 bm. url = '/user' ; // 'cmd1' 명령 추가 ('VIEW'는 출력 옵션) bm. addCommand ( 'cmd1' , 'VIEW' ); // 컬럼 등록 및 뷰 연결 bm. addColumn ( 'u_code' , 'cmd1' , 'output' ); bm. addColumn ( 'u_name' , 'cmd1' , 'output' ); // 컬럼에 화면 요소(셀렉터) 연결 bm. columns [ 'u_code' ]. selector = { key : '#u_code' , type : 'text' }; bm. columns [ 'u_name' ]. selector = { key : '#u_name' , type : 'value' }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); // 결과 // bm.columns['u_code'].value == 1234 // bm.columns['u_name'].value == 'Neo' 'VIEW' 옵션은 서버 응답에서 지정한 뷰(예: 'output')의 첫 번째 데이터(rows)를 컬럼에 할당합니다. 서비스객체로 구성 서비스 객체를 통해 모델 구성을 한 번에 정의할 수 있습니다. js const bm = new BindModel ({ // 서버 URL 설정 url : '/user' , // 컬럼 및 셀렉터 정의 items : { u_code : { selector : { key : '#u_code' , type : 'text' } }, u_name : { selector : { key : '#u_name' , type : 'value' } } }, // 명령 정의 command : { cmd1 : { outputOption : 'VIEW' } }, // 매핑 설정: 명령 'cmd1'의 'output' 뷰에 컬럼 매핑 mapping : { u_code : { cmd1 : [ 'output' ] }, u_name : { cmd1 : [ 'output' ] } } }); // 명령 실행 bm. command [ 'cmd1' ]. execute (); // 결과 // bm.columns['u_code'].value == 1234 // bm.columns['u_name'].value == 'Neo' Tip 서비스 객체 방식은 구성 정보를 분리하여 관리할 수 있어, 코드의 재사용성과 유지보수성 을 크게 향상시킵니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 소개 다음 문서 핵심 개념"},{"title":"핵심 개념","group":"시작하기","section":"핵심 개념","url":"guide/core-concepts.html","text":"문서 시작하기 시작하기 01 핵심 개념 모델, 명령, 테이블과 뷰. BindModel을 구성하는 기본 개념을 살펴봅니다. 한국어 문서 약 12분 핵심 개념을 숙지하면 BindModel 을 보다 자유롭게 제어할 수 있습니다."},{"title":"핵심 개념","group":"시작하기","section":"MetaTable 의 이해","url":"guide/core-concepts.html#metatable-의-이해","text":"MetaTable 의 이해 MetaTable 은 데이터를 컬럼(column)과 행(row)으로 구성하는 객체입니다. • 컬럼 : 데이터를 정의하는 columns 컬렉션 • 행 : 데이터를 저장하는 rows 컬렉션 MetaTable 은 .NET 의 DataTable 과 유사한 구조를 가지고 있어, 이에 익숙하다면 쉽게 사용할 수 있습니다. classDiagram MetaTable o--> MetaTableColumnCollection : columns MetaTableColumnCollection ..> HTMLColumn : [column name] MetaTable o--> MetaRowCollection : rows MetaRowCollection ..> MetaRow : [index] class MetaTable { + columns : MetaTableColumnCollection + rows : MetaRowCollection + constructor(name) + newRow() MetaRow + getValue() MetaRow + setValue(row) } class MetaTableColumnCollection { +column name... +add(name) +addValue(name, value) } class MetaRowCollection { +add(row) +insertAt(pos, row) } class MetaRow { +[column name]... +constructor(table) } class HTMLColumn { +required: boolean +value +constraints +constructor(name) } 구조와 흐름을 설명하는 다이어그램 MetaTable 클래스 생성자 ts declare class MetaTable { constructor ( tableName : string ); } js import { MetaTable } from 'logic-bind-model' ; const table = new MetaTable ( '테이블명' ); table. columns . add ( 'name' ); // 'name' 컬럼 추가 table. columns . add ( 'age' ); // 'age' 컬럼 추가 let row = new table. newRow (); // 새로운 행 생성 row[ 'name' ] = 'Neo' ; // 'name' 컬럼에 값 할당 row[ 'age' ] = 20 ; // 'age' 컬럼에 값 할당 table. rows . add (row); // 행을 rows 컬렉션에 추가 // table.rows[0]['name'] === 'Neo' // table.rows[0]['age'] === 20 // table.rows.count === 1 // table.columns.count === 2 columns.add(columnName) : columns 컬렉션에 컬럼을 추가합니다. newRow() : 컬럼 스키마에 기반한 새로운 MetaRow 객체를 생성합니다. rows.add(row) : 생성된 MetaRow 객체를 rows 컬렉션에 추가합니다. Tip columns 의 단축형인 'cols'를 사용할 수 있습니다."},{"title":"핵심 개념","group":"시작하기","section":"컬럼의 현재값과 데이터 구성","url":"guide/core-concepts.html#컬럼의-현재값과-데이터-구성","text":"컬럼의 현재값과 데이터 구성 MetaTable 의 컬럼값은 현재값을 나타내며, rows 는 이러한 컬럼값들의 집합으로 구성됩니다. js import { MetaTable } from 'logic-bind-model' ; const table = new MetaTable ( '테이블명' ); table. columns . add ( 'age' ); // 'age' 컬럼 추가 table. columns [ 'age' ]. value = 10 ; // 'age' 컬럼의 값 설정 let row = new table. newRow (); // 새로운 행 생성 row[ 'age' ] = 20 ; // 행에 데이터 추가 table. rows . add (row); // 행을 rows 컬렉션에 추가 // table.columns['age'].value === 10 (현재 컬럼값) // table.rows[0]['age'] === 20 (첫번째 행의 값) Tip columns.addValue(컬럼명, 컬럼값) 을 사용하여 컬럼 등록과 초기 값을 동시에 설정할 수 있습니다."},{"title":"핵심 개념","group":"시작하기","section":"초기값 설정 및 데이터 추가","url":"guide/core-concepts.html#초기값-설정-및-데이터-추가","text":"초기값 설정 및 데이터 추가 컬럼값은 MetaRow 타입으로 얻을 수 있으며, MetaRow 타입은 컬럼값(value)으로 지정할 수 있습니다. js import { MetaTable } from 'logic-bind-model' ; const table = new MetaTable ( '테이블명' ); table. columns . add ( 'age' ); // 'age' 컬럼 추가 table. columns [ 'age' ]. value = 10 ; // 현재값 설정 let row = table. getValue (); // 현재값 기반 MetaRow 생성 table. rows . add (row); // 행 추가 // table.columns['age'].value === 10 (현재 컬럼값) // table.rows[0]['age'] === 10 (첫번째 행의 값) table. rows [ 0 ][ 'age' ] = 20 ; // 첫 번째 행 값 수정 table. setValue (table. rows [ 0 ]); // 수정된 행을 컬럼의 현재값으로 설정 // table.columns['age'].value === 20 (업데이트된 컬럼값) getValue() : 컬럼의 현재값으로 구성된 MetaRow 객체를 반환합니다. setValue(row) : 주어진 MetaRow 객체를 컬럼의 현재(value)값으로 설정합니다. 제약조건 MetaTable 의 rows 컬렉션에 데이터를 추가한 이후에는 columns 컬렉션에 새로운 컬럼을 추가하거나 기존 컬럼을 제거할 수 없습니다. 이는 데이터의 일관성을 유지하기 위한 제약입니다."},{"title":"핵심 개념","group":"시작하기","section":"MetaView 의 이해","url":"guide/core-concepts.html#metaview-의-이해","text":"MetaView 의 이해 MetaView 는 MetaTable 과 유사하지만, 중요한 차이점이 있습니다. MetaView 는 columns 컬렉션에 컬럼의 참조값을 등록할 수 있습니다. 이를 통해 원본 컬럼을 공유하거나, 필요에 따라 독립적으로 처리할 수 있습니다. Tip MetaTable 에 컬럼을 추가하면 해당 컬럼은 항상 독립적으로 구성됩니다. 반면, MetaView 는 참조 컬럼을 활용하여 원본 컬럼을 공유할 수도 있습니다."},{"title":"핵심 개념","group":"시작하기","section":"모든 컬럼을 참조로 등록","url":"guide/core-concepts.html#모든-컬럼을-참조로-등록","text":"모든 컬럼을 참조로 등록 MetaView 를 생성할 때 baseEntity 를 지정하면, 해당 객체( MetaTable 또는 MetaView )의 컬럼들이 MetaView 에 참조값으로 등록됩니다. 만약 baseEntity 를 지정하지 않으면 MetaTable 과 동일한 방식으로 작동합니다. MetaView 클래스 정의 ts declare class MetaView { constructor ( name : string , baseEntity ?: MetaView | MetaTable ); } Tip baseEntity 는 MetaTable 또는 MetaView 타입만 지정할 수 있습니다. 만약 MetaView 를 지정하면 순환 규칙에 따라 원본 컬럼에 참조합니다. js import { MetaTable , MetaView } from 'logic-bind-model' ; const table = new MetaTabe ( 't1' ); const view = new MetaView ( 'v1' , table); // 'baseEntity' 속성을 't1'으로 설정 view. columns . add ( 'age' ); // 'age' 컬럼 추가 view. columns . add ( 'gender' ); // 'gender' 컬럼 추가 // table.colmmns.count === 2 // view.colmmns.count === 2 // view.columns['age'] === table.columns['age'] // view.columns['gender'] === table.columns['gender'] view1.columns['age'] 는 table1.columns['age'] 의 참조값입니다. Tip MetaView 생성 이후에도 _baseEntity 를 설정할 수 있습니다. 이 경우, 이후에 추가되는 컬럼부터 참조가 적용됩니다. classDiagram table o--> MetaTableColumnCollection : columns MetaTableColumnCollection o--> age : owner MetaTableColumnCollection o--> gender : owner view o--> MetaViewColumnCollection : columns MetaViewColumnCollection ..> age : [refer] MetaViewColumnCollection ..> gender : [refer] class MetaTableColumnCollection { +[age] +[gender] } class MetaViewColumnCollection { +[age] +[gender] } 구조와 흐름을 설명하는 다이어그램"},{"title":"핵심 개념","group":"시작하기","section":"특정 컬럼만 참조로 등록","url":"guide/core-concepts.html#특정-컬럼만-참조로-등록","text":"특정 컬럼만 참조로 등록 특정 컬럼만 참조로 등록하려면, 컬럼을 추가할 때 대상 컬렉션을 명시적으로 지정해야 합니다. 함수 정의 ts declare function add ( columnName : string , refCollection ?: MetaViewColumnCollection ): number ; js import { MetaTable , MetaView } from 'logic-bind-model' ; const table = new MetaTabe ( 't1' ); const view = new MetaView ( 'v1' ); view. columns . add ( 'age' ); // 'view'에 독립 컬럼 추가 view. columns . add ( 'gender' , table1. columns ); // 't1'의 컬럼 참조 추가 // table.colmmns.count === 1 // view.colmmns.count === 2 // view.columns['gender'] === table.columns['gender'] 컬럼 추가시 기존에 등록된 컬럼을 지정하여 참조로 등록할 수 있습니다. views.columns.add(table.columns['memo']) Tip 특정 컬렉션을 지정하여 컬럼을 추가하면, 지정된 컬렉션에 컬럼이 추가되고, 해당 컬럼의 참조값이 MetaView 에 등록됩니다. classDiagram table1 o--> MetaTableColumnCollection : columns MetaTableColumnCollection o--> gender : owner view1 o--> MetaViewColumnCollection : columns MetaViewColumnCollection o--> age : owner MetaViewColumnCollection ..> gender : [refer] class MetaTableColumnCollection { +[gender] } class MetaViewColumnCollection { +[age] +[gender] } 구조와 흐름을 설명하는 다이어그램 이렇게 테이블과 뷰의 조합을 통해서 다양한 구조를 구현할 수 있습니다."},{"title":"핵심 개념","group":"시작하기","section":"BindModel 구조의 이해","url":"guide/core-concepts.html#bindmodel-구조의-이해","text":"BindModel 구조의 이해 BindModel 객체는 기본으로 MetaTable(first)을 포함하며, 명령(BindCommand)을 추가할 수 있습니다. 각각의 명령은 MetaTable (first)을 참조하는 MetaView (valid, bind, output)로 구성됩니다. classDiagram BindModel o--> MetaTable : first BindModel o--> BindCommand : command['key'] BindCommand o--> MetaView : valid BindCommand o--> MetaView : bind BindCommand o--> MetaView : output class BindModel { + first: MetaTable + command : PropertyCollection + addCommand(cmdName) } class MetaTable { + columns + rows } class BindCommand { + valid : MetaView + bind : MetaView + output : MetaView } class MetaView { + columns + rows } 구조와 흐름을 설명하는 다이어그램 js import { BindModel } from 'logic-bind-model' ; const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // 'cmd1' 명령 추가 // bm.first : MetaTable // bm.command['cmd1'] : BindCommand // bm.command['cmd1'].valid : MetaView // bm.command['cmd1'].bind : MetaView // bm.command['cmd1'].output : MetaView 모델(BindModel)에 추가된 명령(BindCommand)의 뷰(valid, bind, output)는 _baseEntity 에서 지정한 MetaTable 을 참조합니다. 동일한 이름의 컬럼을 사용하거나 독립된 컬럼을 사용하려면, 테이블을 추가하여 컬럼을 지정할 수 있습니다. Tip 명령에 따라 별도의 테이블을 생성하고 컬럼을 독립적으로 관리하면 데이터 구조를 더욱 체계적으로 설계할 수 있습니다. 참조 : 테이블 관리 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 빠른 시작 다음 문서 모델 구성"},{"title":"모델 구성","group":"기능 가이드","section":"모델 구성","url":"guide/features/model.html","text":"문서 기능 가이드 기능 가이드 02 모델 구성 모델을 생성하고 명령, 컬럼, 서버 연결을 구성합니다. 한국어 문서 약 22분 BindModel 은 프레임워크의 핵심 객체로, 비즈니스 로직과 데이터 흐름을 관리하는 중심 역할을 수행합니다. 주요 기능 명령 추가 : BindCommand 객체를 추가하여 다양한 명령을 관리합니다. 컬럼 추가 : HTMLColumn 객체를 추가하여 MetaTable 데이터를 정의합니다. 테이블 추가 : 데이터 구조를 정의하는 MetaTable 객체를 추가합니다. 기본 콜백함수 제공 : 단계별 기본 콜백함수를 제공합니다. (6단계) 서비스 객체 주입 : 서비스 객체를 주입하여 BindModel 객체를 구성합니다. 참조 : 명령 구성 , 컬럼 관리 , 테이블 관리 , 흐름 제어"},{"title":"모델 구성","group":"기능 가이드","section":"모델 객체 생성","url":"guide/features/model.html#모델-객체-생성","text":"모델 객체 생성 BindModel 클래스는 비즈니스 로직과 데이터 흐름을 정의하는 중심 객체로, 웹 애플리케이션의 명령 실행과 데이터 바인딩을 구조적으로 관리할 수 있도록 설계되었습니다. ts declare class BindModel { constructor ( service ?: ServiceType ); } service 선택적이며, 서비스 객체를 주입 할 수 있습니다."},{"title":"모델 구성","group":"기능 가이드","section":"기본 생성","url":"guide/features/model.html#기본-생성","text":"기본 생성 js const bm = new BindModel (); 인자를 전달하지 않을 경우, 빈 상태로 초기화됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"서비스 객체를 통한 초기 구성","url":"guide/features/model.html#서비스-객체를-통한-초기-구성","text":"서비스 객체를 통한 초기 구성 js const bm = new BindModel ({ tables : [ 'second' , 'three' ], }); tables 속성을 포함한 서비스 객체를 생성자에 전달함으로써 초기 설정이 반영됩니다. 서비스 객체는 tables , items , command , mapping 의 속성을 포함하는 객체로 구성됩니다. 참조 : 서비스 객체 구성"},{"title":"모델 구성","group":"기능 가이드","section":"명령 추가","url":"guide/features/model.html#명령-추가","text":"명령 추가 BindModel 객체는 addCommand() 메서드를 통해 명령(Command)을 동적으로 등록할 수 있습니다. 등록된 명령은 내부적으로 BindCommand 인스턴스로 생성되며, 명령 실행 시 사용되는 outputOption 값을 함께 지정할 수 있습니다."},{"title":"모델 구성","group":"기능 가이드","section":"사용 예시 1: 기본 명령 등록","url":"guide/features/model.html#사용-예시-1-기본-명령-등록","text":"사용 예시 1: 기본 명령 등록 js const bm = new BindModel (); bm. addCommand ( 'create' ); // bm.command['create'] instanceof BindCommand === true // bm.command['create'].outputOption === { option: 'SEND', schema: 'AUTO', index: 0 } === true create 라는 이름의 명령이 등록됩니다. 명령 객체는 BindCommand 타입으로 생성됩니다. outputOption 의 기본값은 { option: 'SEND', schema: 'AUTO', index: 0 } 로 설정됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"사용 예시 2: 명령 등록 시 옵션 지정","url":"guide/features/model.html#사용-예시-2-명령-등록-시-옵션-지정","text":"사용 예시 2: 명령 등록 시 옵션 지정 js const bm = new BindModel (); bm. addCommand ( 'read' , 'ALL' ); // bm.cmd['read'] instanceof BindCommand === true // bm.cmd['read'].outOpt === { option: 'ALL', schema: 'AUTO', index: 0 } === true outputOption 은 명령 실행 시 서버와의 통신 또는 뷰 갱신 방식에 영향을 미칩니다. 참조 JSON 스키마 가이드 명령 구성 > 출력 옵션 설정 명령 복수 출력 구성 > 복수 출력 인덱스"},{"title":"모델 구성","group":"기능 가이드","section":"관련 속성 및 메서드 요약","url":"guide/features/model.html#관련-속성-및-메서드-요약","text":"관련 속성 및 메서드 요약 항목 설명 addCommand(name) 명령 이름만으로 명령을 추가하며 기본 옵션은 'SEND'입니다. addCommand(name, outOpt) 명령 이름과 함께 outputOption 을 지정할 수 있습니다. command 또는 cmd 명령 객체들이 저장되는 속성으로, 등록된 각 명령에 접근할 수 있습니다. outputOption 또는 outOpt 명령 실행 시 처리 방식(SEND, VIEW, ALL, PICK)을 지정합니다. 참조 : 명령 구성"},{"title":"모델 구성","group":"기능 가이드","section":"컬럼 추가","url":"guide/features/model.html#컬럼-추가","text":"컬럼 추가 BindModel에서는 데이터를 구성하는 핵심 단위인 컬럼(Column) 을 정의하고, 각 명령과 뷰(valid, bind, output)에 적절히 연결할 수 있습니다."},{"title":"모델 구성","group":"기능 가이드","section":"1. 셀렉터 기반 컬럼 추가","url":"guide/features/model.html#1-셀렉터-기반-컬럼-추가","text":"1. 셀렉터 기반 컬럼 추가 addSelector()는 HTML 요소의 셀렉터를 기반으로 컬럼을 추가합니다. 사용자는 명령 이름과 역할(뷰)을 함께 지정하여 데이터 처리 흐름을 제어할 수 있습니다. js const bm = new BindModel (); bm. addSelector ( 'aa' , '#u_id' ); bm. addSelector ( 'bb' , '#email' , 'cmd1' ); // 전체 뷰 매핑 bm. addSelector ( 'cc' , '#gender' , 'cmd2' , [ 'valid' , 'bind' ]); // bm.columns.count === 3 ('aa', 'bb', 'cc') // bm.command['cmd1'].valid.columns.count === 1 ('bb') // bm.command['cmd1'].bind.columns.count === 1 ('bb') // bm.command['cmd1'].output.columns.count === 1 ('bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0 aa 컬럼은 명령에 매핑하지 않습니다. 각 컬럼은 columns 컬렉션에 등록됩니다. 셀렉터( #u_id , #email , #gender )를 통해 DOM의 값을 참조합니다. bb 컬럼은 전체 뷰에 매핑되고, cc 컬럼은 지정한 뷰(valid, bind)에 매핑됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"2. 값 기반 컬럼 추가","url":"guide/features/model.html#2-값-기반-컬럼-추가","text":"2. 값 기반 컬럼 추가 addColumnValue()를 사용하면 HTML 요소 없이 직접 값을 지정하여 컬럼을 추가할 수 있습니다. js const bm = new BindModel (); bm. addColumnValue ( 'aa' , 100 ); bm. addColumnValue ( 'bb' , 'BB' , 'cmd1' ); // 전체 뷰 매핑 bm. addColumnValue ( 'cc' , 'CC' , 'cmd2' , [ 'valid' , 'bind' ]); // bm.columns.count === 3 ('aa', 'bb', 'cc') // bm.command['cmd1'].valid.columns.count === 1 ('bb') // bm.command['cmd1'].bind.columns.count === 1 ('bb') // bm.command['cmd1'].output.columns.count === 1 ('bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0 'aa' 컬럼에는 숫자 100, 'bb'는 문자열 'BB', 'cc'는 문자열 'CC'가 초기값으로 지정됩니다. 명령과 뷰의 연결 구조는 셀렉터 방식과 동일하게 반영됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"3. 빈 값 기반 컬럼 추가","url":"guide/features/model.html#3-빈-값-기반-컬럼-추가","text":"3. 빈 값 기반 컬럼 추가 addColumn()을 사용하면, 컬럼의 기본값(value)은 빈 문자열('')로 설정되어 추가됩니다. js const bm = new BindModel (); bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' , 'cmd1' ); // 전체 뷰 매핑 bm. addColumn ( 'cc' , 'cmd2' , [ 'valid' , 'bind' ]); // bm.columns.count === 3 ('aa', 'bb', 'cc') // bm.command['cmd1'].valid.columns.count === 1 ('bb') // bm.command['cmd1'].bind.columns.count === 1 ('bb') // bm.command['cmd1'].output.columns.count === 1 ('bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0 aa, bb, cc 컬럼의 value 속성은 모두 빈 문자열('')로 설정되어 있습니다. 컬럼의 구조를 먼저 정의한 뒤, selector 속성 등을 활용하여 해당 컬럼을 HTML 요소에 바인딩할 수 있습니다."},{"title":"모델 구성","group":"기능 가이드","section":"4. 컬럼 및 명령 일괄 등록","url":"guide/features/model.html#4-컬럼-및-명령-일괄-등록","text":"4. 컬럼 및 명령 일괄 등록 setMapping() 메서드는 컬럼과 명령별 역할(뷰)을 일괄 등록하는 기능을 제공합니다. js const bm = new BindModel (); // 기본 생성 bm. setMapping ({ aa : {}, bb : { cmd1 : '$all' }, // 전체 뷰 매핑 cc : { cmd2 : [ 'valid' , 'bind' ] } }); // bm.columns.count === 3 ('aa', 'bb', 'cc') // bm.command['cmd1'].valid.columns.count === 1 ('bb') // bm.command['cmd1'].bind.columns.count === 1 ('bb') // bm.command['cmd1'].output.columns.count === 1 ('bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0 bb 컬럼은 'create' 명령의 모든 뷰(valid, bind, output)에 자동으로 등록됩니다. cc 컬럼은 'update' 명령의 valid 및 bind 뷰에만 설정됩니다. Tip setMapping() 메서드는 컬럼 정의, 명령 추가, 뷰 매핑을 한 번에 처리하여 설정 작업을 간소화할 수 있습니다. 메서드 설명 addSelector(name, selector, cmd?, views?, bTable?) HTML 요소와 연동되는 컬럼을 추가 addColumnValue(name, value, cmd?, views?, bTable?) 직접 값을 지정하여 컬럼을 추가 addColumn(name, cmd?, views?, bTable?) 빈 값을 갖는 컬럼 추가 setMapping(service) 컬럼과 명령 간 매핑 구조 일괄 등록 참조 : 컬럼 관리"},{"title":"모델 구성","group":"기능 가이드","section":"기본 콜백함수","url":"guide/features/model.html#기본-콜백함수","text":"기본 콜백함수 BindModel 객체는 명령(BindCommand)의 실행 흐름을 제어하기 위해 단계별 콜백 함수를 정의할 수 있습니다. 이 중 기본 콜백 함수(Base Callback) 는 특정 명령에 콜백이 명시되지 않았을 경우 자동으로 호출됩니다. 구분 기본 콜백 <br>(BindModel) 명령 콜백 <br>(BindCommand) 설명 1:시작<br> cbBaseBegin cbBegin 명령 실행이 시작될 때 호출됩니다. 2:유효성 검사 cbBaseValid cbValid valid 단계에서 MetaView 의 유효성 검사 전에 호출됩니다. 3:서버 요청 cbBaseBind cbBind bind 단계에서 서버 요청 직전에 호출됩니다. 4:응답 결과 cbBaseResult cbResult 서버 응답을 받은 후, 데이터 처리 단계에서 호출됩니다. 5:결과 출력 cbBaseOutput cbOutput output 단계에서 MetaView 에 매핑 후 호출됩니다. ('VIEW', 'ALL', 'PICK' 일 경우) 6:종료 cbBaseEnd cbEnd 명령 실행이 끝났을 때 호출됩니다. execute()가 호출되면, 해당 명령의 실행 흐름 중 가장 처음에 호출되는 콜백입니다. js // 명령 시작 전 URL 설정 bm. cbBaseBegin = function ( model, cmd ) { cmd. url = '/member/1' ; }; 참조 : 흐름 제어 >시작 콜백 execute()가 실행되면, valid(MetaView)의 유효성 검사가 진행되기 전에 해당 콜백이 먼저 호출됩니다. js // 유효성 검사 전 사용자 검사 bm. cbBaseValid = function ( valid, cmd, model ) { if (valid. colums . count > 0 ) return true ; alert ( 'valid(MetaView) 컬럼이 없습니다.' ); }; 참조 : 흐름 제어 > 유효성 검사 콜백 execute()가 호출되면, bind(MetaView) 컬럼의 값을 서버에 요청하기 전에 콜백이 먼저 실행됩니다. bind(MetaView)의 value 값은 config.data 속성에 지정되며, 이는 axios 요청 시 config 설정으로 사용됩니다. js // 유효성 검사 전 사용자 검사 bm. cbBaseBind = function ( bind, cmd, config ) { // bind.columns['aa'].value === config.data['aa'] }; execute()가 실행된 후 서버로부터 응답을 수신하면, 해당 콜백이 호출되어 응답 데이터를 처리합니다. js // 서버 응답을 데이터를 받은 후 처리 bm. cbBaseResult = function ( data ) { return { rows : data }; }; // data = [ // { name: 'Neo', gender: 'M' }, { name: 'Jane', gender: 'W' } // ] // // return { rows: [ // { name: 'Neo', gender: 'M' }, { name: 'Jane', gender: 'W' } // ]} 참조 : 흐름 제어 > 응답 처리 콜백 , 명령 구성 > 응답 데이터 스키마 execute() 호출시, 응답 데이터를 output(MetaView)에 매핑한 후 호출됩니다. js // 콘솔 출력 bm. cbBaseOutput = function ( outputs ) { outputs[ 0 ]. rows . forEach ( ( row, i ) => { console . log (i, row[ 'name' ], row[ 'gender' ]); }); }; // 0 Neo M // 1 Jane W DOM 을 활용할 경우, 출력 형식에 맞게 변경하여 사용할 수 있습니다. 참조 : 흐름 제어 > 출력 콜백 Tip 기본 콜백 함수란 , 명령(BindCommand)의 단계별 콜백 함수가 명시적으로 정의되지 않았을 때 실행되는 함수입니다. 예를 들어, cbBaseBegin 은 execute() 호출 시 해당 명령에 cbBegin 이 정의되어 있지 않다면 대신 호출됩니다. 명령 간의 일관성을 유지하거나 반복적인 공통 처리를 간소화할 수 있습니다."},{"title":"모델 구성","group":"기능 가이드","section":"서비스 객체 주입","url":"guide/features/model.html#서비스-객체-주입","text":"서비스 객체 주입 서비스 객체(Service Object)는 BindModel 객체의 설정 정보를 구조화된 형태로 전달하여 손쉽게 주입할 수 있도록 도와주는 기능입니다. 이를 통해 코드의 가독성을 높이고, 여러 인스턴스 간 구성의 일관성을 유지할 수 있습니다. 서비스 객체에는 다음과 같은 속성을 포함할 수 있습니다. url, baseConfig : 서버 요청 경로와 axios 설정 객체(config)를 정의합니다. tables : 메타 테이블의 이름을 배열 형태로 정의합니다. items : 각 컬럼의 공통 속성(초기값, 제약 조건 등)을 설정합니다. command : 각 명령에 대한 설정 정보(예: outputOption , url , 콜백 함수 등)를 정의합니다. mapping : 컬럼에 대해 명령별로 어떤 뷰( valid , bind , output 등)에 매핑할지를 정의합니다. js const svc = { // 기본 요청 URL 경로 url : '/user' , // 추가 테이블 tables : [ 'second' , 'three' ], // 컬럼 공통 속성 items : { aa : 'AA' , bb : 1000 , cc : { required : true } }, // 명령 구성 command : { create : { url : '/register' }, update : { outputOption : 'VIEW' , cbValid : function ( valid, cmd ) { return confirm ( '수정하시겠습니까?' ); } } }, // 컬럼과 명령의 뷰간의 매핑 설정 mapping : { aa : { create : 'valid' }, bb : { create : [ 'valid' , 'bind' ], update : 'output' }, cc : { update : 'output' } } }; const bm1 = new BindModel (svc); // 객체 생성시 서비스 객체 설정 const bm2 = new BindModel (); bm2. setService (svc); // 서비스 객체 설정 // bm1.equal(bm2) === true // bm.command['create'].valid.columns.count === 2 ('aa', 'bb') // bm.command['create'].bind.columns.count === 1 ('bb') // bm.command['create'].output.columns.count === 0 // bm.command['update'].valid.columns.count === 0 // bm.command['update'].bind.columns.count === 0 // bm.command['update'].output.columns.count === 2 ('bb', 'cc') 기본 서버 요청 경로는 '/user'이며, 'create' 명령의 요청 경로는 '/register'입니다. 'create' 명령의 option 은 'SEND'이고, 'update' 명령의 option 은 'VIEW'입니다. 아이템은 items 컬렉션에 등록되며, 각 컬럼의 공통 속성으로 사용됩니다. 'aa', 'bb', 'cc' 컬럼은 'create' 및 'update' 명령에 지정된 뷰에 매핑됩니다. bm1 과 bm2 는 동일한 구성 요소와 속성 구조를 갖는 BindModel 객체입니다. 객체 생성 시 서비스 객체를 인자로 전달하거나, setService() 메서드를 통해 점진적으로 주입할 수도 있습니다. Tip 서비스 객체를 활용하여 BindModel 객체를 구성할 수 있으며, 이는 비즈니스 로직의 분리와 재사용에 유용합니다. 참조 : 서비스 객체 주입"},{"title":"모델 구성","group":"기능 가이드","section":"서버 요청 경로 설정","url":"guide/features/model.html#서버-요청-경로-설정","text":"서버 요청 경로 설정"},{"title":"모델 구성","group":"기능 가이드","section":"기본 경로 설정하기","url":"guide/features/model.html#기본-경로-설정하기","text":"기본 경로 설정하기 url 속성은 서버 요청에 사용될 기본 URL 경로를 설정하는 데 사용됩니다. 단, 명령(BindCommand) 객체에 별도로 url 경로가 설정된 경우, BindModel 의 url 값은 무시됩니다. js var bm = new BindModel (); bm. url = '/user' ; // 기본 URL 경로 설정 Tip BindModel 의 url 속성은 내부적으로 baseConfig.url 값을 참조합니다. 이때 baseConfig 속성은 'axios' 모듈이 서버에 요청할 때 사용하는 설정(config) 객체로 활용됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"명령별 경로 설정하기","url":"guide/features/model.html#명령별-경로-설정하기","text":"명령별 경로 설정하기 각 명령(BindCommand)에 대해 개별적으로 url 을 설정할 수 있습니다. 명령(BindCommand)에 url 이 설정되지 않은 경우에는 BindModel 에 정의된 기본 url 값이 사용됩니다. js var bm = new BindModel (); bm. url = '/list' // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); // 명령별 URL 경로 설정 bm. command [ 'cmd2' ]. url = '/user/1' ; // bm.command['cmd1'].execute() : '/list' // bm.command['cmd2'].execute() : '/user/1' 명령(BindCommand)의 url 속성은 내부적으로 config.url 값으로 설정됩니다. Tip 명령(BindCommand)의 config 객체는 모델의 baseConfig 객체와 병합되어 axios 요청의 최종 config 객체로 사용됩니다. 이때, 병합 시 명령의 config 객체가 baseConfig 보다 우선적으로 적용 됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"동적 경로 설정","url":"guide/features/model.html#동적-경로-설정","text":"동적 경로 설정 명령(BindCommand)이 execute()로 호출될 때, 실행 흐름에 따라 단계별 콜백 함수가 순차적으로 호출됩니다. 이 중 가장 먼저 호출되는 콜백은 cbBegin 이며, 해당 명령에 cbBegin 이 정의되지 않은 경우에는 cbBaseBegin 이 대신 호출됩니다. 특정 명령에 따라 요청 경로(url)를 동적으로 변경해야 하는 경우, cbBegin 또는 cbBaseBegin 콜백 함수 내에서 url 값을 설정할 수 있습니다."},{"title":"모델 구성","group":"기능 가이드","section":"기본 동적 경로 설정하기","url":"guide/features/model.html#기본-동적-경로-설정하기","text":"기본 동적 경로 설정하기 모델 객체의 cbBaseBegin 콜백 함수를 활용하여 모델(BindModel)의 기본 경로(url)를 설정합니다. js const bm = new BindModel (); bm. addColumnValue ( 'idx' , 10 , 'cmd1' ); // idx 컬럼 추가 및 'cmd1' 명령에 등록 bm. cbBaseBegin = function ( model, cmd ) { let idx = model. columns [ 'idx' ]. value ; // 10 model. url = `/user/ ${idx} ` ; }; bm. command [ 'cmd1' ]. execute (); // bm.url === '/user/10' bm.addColumnValue() : idx 이름의 컬럼을 추가하고, cmd1 명령의 모든 뷰에 매핑합니다. 함수 내 model 인자 : execute() 실행 시 현재 모델(BindModel) 객체를 가리킵니다. 함수 내 cmd 인자 : execute() 실행 시 현재 명령(BindCommand) 객체를 가리킵니다. 함수 내 model.columns : 모델(BindModel)의 columns 컬렉션을 가르킵니다. 참조 : 흐름 제어"},{"title":"모델 구성","group":"기능 가이드","section":"명령별로 동적 경로 설정하기","url":"guide/features/model.html#명령별로-동적-경로-설정하기","text":"명령별로 동적 경로 설정하기 명령(BindCommand)별로 cbBegin 콜백 함수를 활용하여 개별적으로 경로(url)를 설정합니다. js const bm = new BindModel (); bm. addColumnValue ( 'idx' , 10 , 'cmd1' ); // idx 컬럼 추가 및 'cmd1' 명령 등록 bm. command [ 'cmd1' ]. cbBegin = function ( model, cmd ) { let idx = model. columns [ 'idx' ]. value ; // 10 cmd. url = `/user/ ${idx} ` ; }; bm. command [ 'cmd1' ]. execute (); // bm.url === '/user/10' bm.command 속성 : 모든 명령(BindCommand)객체의 컬렉션 키를 제공합니다. Tip cbBegin 콜백 함수는 cbBaseBegin 보다 우선순위가 높습니다. 두 콜백 함수가 모두 설정된 경우, cbBegin 만 호출됩니다."},{"title":"모델 구성","group":"기능 가이드","section":"axios 환경 설정","url":"guide/features/model.html#axios-환경-설정","text":"axios 환경 설정 모델(BindModel)은 HTTP 통신을 위해 axios 모듈을 사용합니다."},{"title":"모델 구성","group":"기능 가이드","section":"기본 환경 설정하기","url":"guide/features/model.html#기본-환경-설정하기","text":"기본 환경 설정하기 모델(BindModel) 객체의 baseConfig 속성은 axios 요청 설정(config) 객체로 사용됩니다. js const bm = new BindModel (); bm. baseConfig . baseURL = 'https://api.example.com' ; bm. baseConfig . url = '/user' ; // 기본 URL 설정 (참고: bm.url) bm. baseConfig . method = 'post' ; // 요청 메서드 (기본값: 'get') url : 요청에 사용될 서버 URL 입니다. method : 요청 방식을 설정합니다. (종류 : 'get', 'post', 'patch', 'delete') baseURL : url 이 절대값이 아닌 경우 baseURL 은 URL 앞에 붙습니다. 상대 경로를 사용하는 요청을 쉽게 구성하려면 baseURL 설정이 유용합니다. 참조 : axios config 설정 #참조"},{"title":"모델 구성","group":"기능 가이드","section":"명령별 환경 설정 하기","url":"guide/features/model.html#명령별-환경-설정-하기","text":"명령별 환경 설정 하기 명령(BindCommand) 객체의 config 속성은 명령별로 개별적인 axios 요청 설정(config) 객체로 사용됩니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. config . baseURL = 'https://api.example.com' ; bm. command [ 'cmd1' ]. config . url = '/user' ; bm. command [ 'cmd1' ]. config . method = 'get' ; 위 설정에 따라 서버 요청 경로는 https://api.example.com/user 가 됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 핵심 개념 다음 문서 명령 구성"},{"title":"명령 구성","group":"기능 가이드","section":"명령 구성","url":"guide/features/command.html","text":"문서 기능 가이드 기능 가이드 02 명령 구성 유효성 검사부터 서버 요청과 출력까지, 명령으로 흐름을 구성합니다. 한국어 문서 약 21분 BindCommand 객체는 유효성 검사, 서버 요청, 서버 응답과 관련된 MetaView 와 콜백(hooking)함수로 구성되어 있으며 execute() 호출을 통해 실행됩니다."},{"title":"명령 구성","group":"기능 가이드","section":"주요 기능","url":"guide/features/command.html#주요-기능","text":"주요 기능 유효성 검사 : 컬럼에 제약 조건을 설정하여 유효성 검사를 수행합니다. (valid) 서버 요청 : 컬럼값을 서버로 요청합니다. (bind) 응답 관리 : 서버의 응답 데이터를 MetaView에 바인딩합니다. (output) 컬럼 추가 : HTMLColumn 객체를 추가하여 MetaTable의 데이터를 정의합니다. 흐름 제어 : 단계별 콜백 함수를 사용하여 실행 흐름을 제어합니다. Tip 흐름 제어란 execute() 호출 시 단계별로 실행되는 콜백 함수를 통해 작업 흐름을 제어하는 것을 말합니다. 주요 콜백 함수로는 cbBegin(실행 시작), cbValid(유효성 검사), cbBind(서버 요청), cbResult(서버 응답 처리), cbOutput(결과 출력), cbEnd(실행 완료)이 있습니다."},{"title":"명령 구성","group":"기능 가이드","section":"명령 추가","url":"guide/features/command.html#명령-추가","text":"명령 추가 명령(BindCommand) 객체는 모델(BindModel)의 처리 단위로, MetaView 타입의 valid , bind , output , misc 속성을 포함합니다. Tip misc(MetaView)는 execute() 실행 시 아무런 처리를 하지 않습니다. 사용자가 컬럼 그룹화 등 특수한 목적으로 사용할 수 있도록 정의된 MetaView 입니다. ts type OptionType = 'SEND' | 'VIEW' | 'ALL' | 'PICK' ; // default 'SEND' type SchemaType = 'AUTO' | 'DATA' | 'ENTITY' ; // default 'AUTO' type IndexType = number | number []; // // default 0 type OutOptType = { option : OptionType , schema : SchemaType , index : IndexType } declare function addCommand ( cmdName : string , outputOption ?: OutOptType | OptionType | SchemaType | IndexType , bTable ?: string | MetaTable ): BindCommand ; cmdName : 명령 이름입니다. outputOption : output(MetaView)에 서버 응답 데이터를 바인딩하는 방식입니다. SEND : 바인딩하지 않음. (기본값) VIEW : 지정한 인덱스 데이터(rows)를 컬럼값(value)으로 설정합니다. (단일 데이터) ALL : 응답 데이터를 모든 컬럼과 행으로 가져옵니다. (전체 데이터) PICK : output.columns 컬렉션에 정의된 컬럼과 매칭되는 데이터를 가져옵니다. (지정 데이터) number 타입은 VIEW 옵션 지정시 데이터(rows) 의 index 값입니다. (기본값 : 0) bTable : 기본테이블을 지정합니다. outputOption 의 schema 속성을 지정하여 서버 응답 데이터의 형식을 설정할 수 있습니다. 참조 : JSON 스키마 가이드 Tip 명령(BindCommand)을 추가할 때 bTable 을 지정하면, 해당 값이 _baseTable 로 설정됩니다. 이에 따라 MetaView(valid, bind, output, misc)의 _baseEntity 가 자동으로 지정됩니다. 이후 추가되는 컬럼(HTMLColumn)은 기본적으로 해당 MetaTable 에 등록되며, 참조값은 MetaView 에 등록됩니다. addCommand()를 호출하여 명령(BindCommand) 객체를 생성하고, 이를 command 컬렉션에 등록합니다. 또한, outputOption 값을 지정하여 서버 응답 데이터를 output(MetaView)에 바인딩하는 방식을 설정할 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'create' ); bm. addCommand ( 'read' , 'ALL' ); // bm.command['create'] instanceof BindCommand // bm.command['read'] instanceof BindCommand // bm.command['create'].outputOption.option == 'SEND' // bm.command['read'].outputOption.option == 'ALL' // bm.cmd['create'] instanceof BindCommand // bm.cmd['read'] instanceof BindCommand Tip 추가된 명령(BindCommand) 객체는 command 컬렉션을 통해 접근할 수 있습니다. cmd 속성은 command 속성의 별칭입니다."},{"title":"명령 구성","group":"기능 가이드","section":"명령에서 컬럼 추가","url":"guide/features/command.html#명령에서-컬럼-추가","text":"명령에서 컬럼 추가 모델(BindModel)객체에서 컬럼을 추가하고 초기값을 설정할 수 있습니다. ts type viewsType = 'valid' | 'bind' | 'output' | 'misc' | string /* 추가 뷰*/ ; declare function addColumn ( column : string | MetaColumn , views ?: '$all' | viewsType | viewsType[], bTable ?: string | MetaTable ): BindCommand ; declare function addColumnValue ( columnName : string , value : string | number | boolean | { /* 컬럼속성 */ }, views ?: viewsType | viewsType[], bTable ?: string | MetaTable ): BindCommand ; addColumn() : 컬럼 객체 또는 이름으로 빈('') 컬럼을 추가합니다. column : 추가할 컬럼 객체 또는 컬럼명 입니다. views : 참조를 등록할 뷰( MetaView ) 이름을 지정합니다. bTable : 컬럼이 등록될 테이블( MetaTable )을 지정합니다. addColumnValue() : 컬럼을 추가하고 초기값을 설정합니다. columnName : 추가할 컬럼명 입니다. value : 컬럼의 초기값입니다. views : 참조를 등록할 뷰( MetaView ) 이름을 지정합니다. bTable : 컬럼이 등록될 테이블( MetaTable )을 지정합니다. Tip views 값으로 $all 또는 undefined 지정하면 모든 뷰( valid , bind , output , misc )에 참조가 추가됩니다."},{"title":"명령 구성","group":"기능 가이드","section":"유효성 검사 컬럼 설정","url":"guide/features/command.html#유효성-검사-컬럼-설정","text":"유효성 검사 컬럼 설정 유효성 검사를 설정하려면 valid (MetaView)를 구성하고, 컬럼(MetaColumn)의 required 및 constraints 속성을 설정해야 합니다. addColumnValue() 메서드를 호출하여 초기값과 함께 컬럼을 생성합니다. 생성된 컬럼은 BindModel 객체의 columns 컬렉션에 추가되며, 해당 명령(BindCommand)의 MetaView 에 참조로 등록됩니다. js const bm = new BindModel (); bm. addCommand ( 'create' ); // 'create' 명령 추가 bm. command [ 'create' ]. addColumnValue ( 'u_no' , { required : true }, 'valid' ); bm. command [ 'create' ]. addColumnValue ( 'u_name' , { constraints : { regex : /[a-zA-Z]+/ , msg : '이름은 영문자만 가능합니다.' } }, 'valid' ); // bm.command['create'].valid instanceof MetaView // bm.command['create'].valid.count === 2 // bm.columns['u_no'] === bm.cmd['create'].valid.columns['u_no'] // bm.columns['u_name'] === bm.cmd['create'].valid.columns['u_name'] u_no 컬럼 : 필수값입니다. (공백 입력시 실패) u_name 컬럼 : 선택값입니다. 값을 입력시 영문 이외의 문자는 실패 합니다. (공백 입력시 성공) 실패시 msg 는 cbFail 콜백함수를 통해 출력됩니다. 컬럼을 먼저 등록한 후, 필요한 속성은 나중에 지정할 수도 있습니다. js // 'valid' 뷰에 컬럼 등록 bm. command [ 'create' ]. addColumnValue ( 'u_no' , 10 , 'valid' ); bm. command [ 'create' ]. addColumnValue ( 'u_name' , 'Jane' , 'valid' ); // 컬럼 속성 설정 bm. columns [ 'u_no' ]. required = true ; bm. columns [ 'u_name' ]. constraints = { regex : /[a-zA-Z]+/ , msg : '이름은 영문자만 가능합니다.' }; 컬럼의 제약조건을 활용하여 다양하게 구성할 할 수 있습니다. #참조 참조 : 컬럼 관리 > 제약조건 Tip BindModel 객체에서는 서비스객체 주입, addColumn(), addColumnValue() 메서드를 사용하여 컬럼을 추가할 수 있습니다. 또한, 명령(BindCommand) 객체의 addColumn(), addColumnValue(), setColumn() 메서드를 통해 다양한 방식으로 유효성 검사 컬럼을 설정할 수 있습니다."},{"title":"명령 구성","group":"기능 가이드","section":"서버 요청 컬럼 설정","url":"guide/features/command.html#서버-요청-컬럼-설정","text":"서버 요청 컬럼 설정 서버 요청을 위해서는 bind (MetaView) 뷰를 구성해야 합니다."},{"title":"명령 구성","group":"기능 가이드","section":"명령에서 컬럼 등록하기","url":"guide/features/command.html#명령에서-컬럼-등록하기","text":"명령에서 컬럼 등록하기 명령(BindCommand)을 등록한 후, 해당 명령의 bind (MetaView) 뷰에 컬럼을 추가합니다. js const bm = new BindModel (); bm. addCommand ( 'create' ); // 'create' 명령 추가 // 'bind' 뷰에 컬럼 등록 bm. command [ 'create' ]. addColumnValue ( 'u_no' , 10 , 'bind' ); bm. command [ 'create' ]. addColumnValue ( 'u_name' , 'Jane' , 'bind' );"},{"title":"명령 구성","group":"기능 가이드","section":"명령과 뷰 동시 등록하기","url":"guide/features/command.html#명령과-뷰-동시-등록하기","text":"명령과 뷰 동시 등록하기 컬럼을 등록하면서 동시에 명령(BindCommand)과 bind (MetaView) 뷰에 참조를 추가할 수도 있습니다. js const bm = new BindModel (); // 컬럼 등록과 함께 'create' 명령 및 'bind' 뷰에 참조 추가 bm. addColumnValue ( 'u_no' , 10 , 'create' , 'bind' ); bm. addColumnValue ( 'u_name' , 'Jane' , 'create' , 'bind' );"},{"title":"명령 구성","group":"기능 가이드","section":"서버 응답 컬럼 설정","url":"guide/features/command.html#서버-응답-컬럼-설정","text":"서버 응답 컬럼 설정 서버 응답 데이터를 매핑하려면 outputOption 을 설정하고, output (MetaView) 뷰를 구성해야 합니다. Tip outputOption을 통해 응답 데이터를 output(MetaView)에 매핑하는 방식을 지정할 수 있습니다."},{"title":"명령 구성","group":"기능 가이드","section":"명령에 컬럼 등록하기","url":"guide/features/command.html#명령에-컬럼-등록하기","text":"명령에 컬럼 등록하기 명령(BindCommand)를 등록한 후, 해당 명령의 output (MetaView)에 컬럼을 추가합니다. js const bm = new BindModel (); bm. addCommand ( 'list' , 'VIEW' ); // // 'list' 명령 추가 및 outputOption 설정 // 'output' 뷰에 컬럼 등록 bm. command [ 'list' ]. addColumnValue ( 'u_no' , 10 , 'output' ); bm. command [ 'list' ]. addColumnValue ( 'u_name' , 'Jane' , 'output' ); // bm.cmd['list'].outputOption.option === 'VIEW'"},{"title":"명령 구성","group":"기능 가이드","section":"명령과 뷰 동시 등록하기","url":"guide/features/command.html#명령과-뷰-동시-등록하기-2","text":"명령과 뷰 동시 등록하기 컬럼을 등록하면서 동시에 명령(BindCommand)과 output (MetaView)에 참조를 추가할 수 있습니다. js const bm = new BindModel (); // 컬럼 등록과 함께 'list' 명령 및 'output' 뷰에 참조 추가 bm. addColumnValue ( 'u_no' , 10 , 'list' , 'output' ); bm. addColumnValue ( 'u_name' , 'Jane' , 'list' , 'output' ); // outputOption 설정 bm. command [ 'list' ]. outputOption = 'VIEW' ; // bm.cmd['list'].outputOption.option === 'VIEW'"},{"title":"명령 구성","group":"기능 가이드","section":"출력 옵션의 종류","url":"guide/features/command.html#출력-옵션의-종류","text":"출력 옵션의 종류 outputOption 을 설정하여 output (MetaView)의 데이터 바인딩 방식을 제어할 수 있습니다. 옵션 설명 비고 'SEND' 바인딩 안함 기본값 'VIEW' 정의된 컬럼의 데이터를 가져오고, 지정된 인덱스의 데이터를 컬럼값으로 설정합니다. 'ALL' 모든 컬럼의 데이터를 가져옵니다. 'PICK' 정의된 컬럼과 매칭되는 데이터를 가져옵니다. 옵션 'SEND' : 바인딩 안함 bind(MetaView)의 값(value)은 서버로 전송되지만 응답데이터를 output (MetaView)에 데이터를 가져오지 않습니다. js const bm = new BindModel (); // 'create' 명령 추가 (옵션 'SEND' 설정) bm. addCommand ( 'create' , 'SEND' ); // 'aa' 컬럼 추가 bm. cmd [ 'create' ]. addColumnValue ( 'aa' , 10 ); // 명령 실행 bm. cmd [ 'create' ]. execute (); // bm.columns.count == 1 // bm.columns['aa'].value == 10 // bm.cmd['create'].output.rows.count == 0 Tip 이 옵션은 등록, 수정, 삭제와 같이 응답 데이터가 필요 없는 경우에 주로 활용됩니다. 옵션 'VIEW' : 지정 데이터 + 컬럼값 설정 응답 데이터에서 정의된 컬럼과 매칭되는 데이터를 가져오고, 지정된 인덱스의 데이터를 컬럼값으로 설정합니다. json { \"rows\" : [ { \"u_id\" : 10 , \"u_name\" : \"Alice\" , \"active\" : true , \"age\" : 30 } , { \"u_id\" : 20 , \"u_name\" : \"Bob\" , \"active\" : false , \"age\" : 40 } ] } 응답 데이터에서 정의된 컬럼과 매칭되는 데이터만 가져오며, 인덱스 값의 rows 데이터를 컬럼값으로 설정합니다. Tip 기본 인덱스 값은 0 이며, 필요에 따라 outputOption.index = 1 과 같이 설정할 수 있습니다. js const bm = new BindModel (); // 'read' 명령 추가, 옵션 'VIEW' 사용 bm. addCommand ( 'read' , 'VIEW' ); // 컬럼 추가 bm. cmd [ 'read' ]. addColumn ( 'u_id' ); bm. cmd [ 'read' ]. addColumn ( 'u_name' ); bm. cmd [ 'read' ]. addColumn ( 'active' ); // 명령 실행 bm. cmd [ 'read' ]. execute (); // bm.columns.count == 3 // bm.columns['u_id'].value == 10 // bm.columns['u_name'].value == \"Alice\" // bm.columns['active'].value == true Tip 이 옵션은 단일 조회 데이터를 컬럼값으로 설정할 때 유용합니다. 옵션 'ALL' : 모든 데이터 응답 데이터를 output (MetaView)에 모두 가져옵니다. 컬럼을 사전에 정의하지 않아도 응답 데이터를 기반으로 동적으로 생성됩니다. json { \"rows\" : [ { \"u_id\" : 10 , \"u_name\" : \"Alice\" , \"active\" : true } , { \"u_id\" : 20 , \"u_name\" : \"Bob\" , \"active\" : false } ] } 컬럼이 미리 정의되지 않더라도 응답 데이터에 기반하여 동적으로 생성됩니다. js var bm = new BindModel (); // 'list' 명령 추가 (옵션 'VIEW' 설정) bm. addCommand ( 'list' , 'ALL' ); // 명령 실행 bm. cmd [ 'list' ]. execute (); // bm.columns.count == 3 // bm.cmd['list'].output.rows.count == 2 // bm.cmd['list'].output.rows[0]['u_id'] == 10 // bm.cmd['list'].output.rows[0]['u_name'] == \"Alice\" // bm.cmd['list'].output.rows[0]['active'] == true // bm.cmd['list'].output.rows[1]['u_id'] == 20 // bm.cmd['list'].output.rows[1]['u_name'] == \"Bob\" // bm.cmd['list'].output.rows[1]['active'] == false cmd 속성은 command 속성의 별칭입니다. Tip 이 옵션은 목록 처리에 활용되며, 응답 데이터의 전체 구조를 확인하거나 cbOutput 콜백 함수에서 출력할 컬럼을 지정하는 데 사용할 수 있습니다. 옵션 'PICK' : 지정 데이터 응답 데이터에서 output (MetaView)에 정의된 컬럼과 매칭되는 데이터만 가져옵니다. json { \"rows\" : [ { \"u_id\" : 10 , \"u_name\" : \"Alice\" , \"active\" : true } , { \"u_id\" : 20 , \"u_name\" : \"Bob\" , \"active\" : false } ] } 응답 데이터에 키 값이 정의한 컬럼과 매칭되는 데이터만 가져옵니다. js var bm = new BindModel (); // 'list' 명령 추가 (옵션 'PICK' 설정) bm. addCommand ( 'list' , 'PICK' ); // 컬럼 'id', 'name' 추가 bm. cmd [ 'list' ]. addColumn ( 'u_id' ); bm. cmd [ 'list' ]. addColumn ( 'u_name' ); // 명령 실행 bm. cmd [ 'list' ]. execute (); // bm.columns.count == 2 // bm.cmd['list'].output.rows.count == 2 // bm.cmd['list'].output.rows[0]['u_id'] == 10 // bm.cmd['list'].output.rows[0]['u_name'] == \"Alice\" // bm.cmd['list'].output.rows[1]['u_id'] == 20 // bm.cmd['list'].output.rows[1]['u_name'] == \"Bob\" rows 키가 active 인 데이터는 가져오지 않습니다. Tip 이 옵션은 목록 처리에 유용하며, output (MetaView)에 정의된 컬럼의 데이터만 가져옵니다."},{"title":"명령 구성","group":"기능 가이드","section":"출력 옵션의 설정","url":"guide/features/command.html#출력-옵션의-설정","text":"출력 옵션의 설정 명령(BindCommand)의 서버 응답 데이터를 output (MetaView)에 매핑하는 방식을 설정합니다. 출력 옵션 타입 ts type OptionType = 'SEND' | 'VIEW' | 'ALL' | 'PICK' ; // default 'SEND' type SchemaType = 'AUTO' | 'DATA' | 'ENTITY' ; // default 'AUTO' type IndexType = number | number []; // // default 0 type OutOptType = { option : OptionType , schema : SchemaType , index : IndexType } type outputOption = OutOptType | OptionType | SchemaType | IndexType ; option : output (MetaView) 의 매칭 방식을 지정합니다. (기본값: 'SEND') schema : 데이터의 스키마 모드를 지정합니다. (기본값: 'AUTO') index : 컬럼(value)값에 설정할 rows 인덱스 위치를 지정합니다.(기본값: 0) Tip outputOption 을 Number 타입으로 지정하면, 해당 값이 index 로 설정됩니다. outputOption 을 string 타입으로 지정하면 option 또는 schema 가 설정됩니다. outputOption 속성의 별칭 속성 outOpt 을 사용할 수 있습니다. 명령 추가시 설정 명령(BindCommand)을 추가할 때 outputOption 매개변수를 전달하여 설정할 수 있습니다. js const bm = new BindModel (); // 명령 추가 시 outputOption 설정 bm. addCommand ( 'cmd1' ); // default 'SEND' bm. addCommand ( 'cmd2' , 'VIEW' ); bm. addCommand ( 'cmd3' , { option : 'ALL' , index : 3 }); // bm.cmd['cmd1'].outOpt === { option: 'SEND', index: 0, schema: 'AUTO' } // bm.cmd['cmd2'].outOpt === { option: 'VIEW', index: 0, schema: 'AUTO' } // bm.cmd['cmd3'].outOpt === { option: 'ALL', index: 3, schema: 'AUTO' } 직접 설정 명령(BindCommand) 객체의 outputOption 속성을 직접 설정할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. addCommand ( 'cmd3' ); // outputOption 속성 설정 bm. command [ 'cmd1' ]. outputOption = 'PICK' ; bm. command [ 'cmd2' ]. outputOption . option = 'ALL' ; bm. command [ 'cmd3' ]. outputOption = { option : 'VIEW' , index : 1 }; // bm.cmd['cmd1'].outOpt === { option: 'PICK', index: 0, schema: 'AUTO' } // bm.cmd['cmd2'].outOpt === { option: 'ALL', index: 0, schema: 'AUTO' } // bm.cmd['cmd3'].outOpt === { option: 'VIEW', index: 1, schema: 'AUTO' }"},{"title":"명령 구성","group":"기능 가이드","section":"응답 데이터 스키마","url":"guide/features/command.html#응답-데이터-스키마","text":"응답 데이터 스키마 서버 응답 데이터의 형식은 아래와 같습니다. ts type DataType = string | number | boolean ; type SingleEntity = { rows : Record < string , DataType > | Record < string , DataType >[], columns ?: Record < string , ColumnType > }; type MultiEntity = SingleEntity []; ColumnType 타입은 문서를 하세요. 참조 : 컬럼 관리 > 컬럼 주요 속성 , 공통 컬럼 속성 아래와 같은 형식의 데이터를 가져올 수 있습니다. Tip 서버 응답 데이터의 구조가 다를 경우, cbResult 콜백 함수를 사용하여 데이터 스키마로 변환할 수 있습니다. 객체 데이터 json { \"aa\" : 10 } json [ { \"aa\" : 10 } , { \"aa\" : 20 } ] 엔티티 데이터 json { \"rows\" : { \"aa\" : 10 } } json { \"rows\" : [ { \"aa\" : 10 } , { \"aa\" : 20 } ] } Tip rows 속성은 object 또는 object[] 타입으로 지정할 수 있습니다. 복수 엔티티 데이터 json [ { \"rows\" : [ { \"aa\" : 10 , \"bb\" , 20 , \"cc\" : 30 } , { \"aa\" : 11 , \"bb\" , 21 , \"cc\" : 31 } ] } , { \"rows\" : [ { \"dd\" : 40 , \"ee\" , 50 } , { \"dd\" : 41 , \"ee\" , 51 } , { \"dd\" : 42 , \"ee\" , 52 } ] } ] 자세한 내용은 JSON 스카미 가이드를 참조해주세요. 참조 : JSON 스키마 가이드 , 명령 복수 출력 구성 서버 응답 데이터가 복수의 엔티티를 가지는 경우 \" 명령 복수 출력 구성 \" 을 참조하십시요. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 모델 구성 다음 문서 컬럼 관리"},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 관리","url":"guide/features/columns.html","text":"문서 기능 가이드 기능 가이드 02 컬럼 관리 컬럼을 만들고 화면 요소와 명령에 연결하는 방법을 알아봅니다. 한국어 문서 약 27분 MetaColumn 은 모델(BindModel)의 기본 구성 단위 입니다. 컬럼은 다음 세가지 방식으로 추가할 수 있습니다: 모델(BindModel) 객체에서 추가 명령(BindCommand) 객체에서 추가 서비스객체에서 추가"},{"title":"컬럼 관리","group":"기능 가이드","section":"셀렉터 속성으로 컬럼 추가","url":"guide/features/columns.html#셀렉터-속성으로-컬럼-추가","text":"셀렉터 속성으로 컬럼 추가 모델(BindModel) 객체에 컬럼을 추가하고, 해당 컬럼에 selector 속성을 지정합니다. ts type KeyType = 'value' | 'text' | 'html' | 'attr.*' | 'prop.*' | 'css.*' | 'none' ; type SelectorType = { key : string , type : KeyType }; type viewsType = 'valid' | 'bind' | 'output' | 'misc' | string /* 추가 뷰*/ ; declare function addSelector ( columnName : string , selector : string | SelectorType , cmds ?: string | string [], views ?: '$all' | viewsType | viewsType[], bTable ?: string | MetaTable ): void ; addSelector() : 컬럼 객체 또는 이름으로 컬럼을 추가 selector 객체를 설정합니다. columnName : 추가할 컬럼명 입니다. selector string : selector 문자열을 지정합니다. ('value', 'text', 'html') SelectorType : selector 객체를 지정합니다. cmds : 명령(BindCommand) 이름을 지정합니다. views : 참조를 등록할 뷰( MetaView ) 이름을 지정합니다. bTable : 컬럼이 등록될 테이블( MetaTable )을 지정합니다. Tip selector 에 문자열 키를 지정하면, 해당 DOM 요소를 검사하여 value , text , html 중 적절한 타입이 자동으로 지정됩니다. 이 외의 타입을 사용하려면, 객체를 통해 직접 지정해야 합니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 추가하기","url":"guide/features/columns.html#컬럼-추가하기","text":"컬럼 추가하기 기본테이블(first)의 columns 컬렉션에 컬럼을 추가합니다. js const bm = new BindModel (); // 컬럼 추가 및 selector 초기값 설정 bm. addSelector ( 'aa' , '#u_id' ); bm. addSelector ( 'bb' , { key : '#u_name' , type : 'value' }); // bm.first.columns.count === 2 (aa, bb) // bm.columns.count === 2 (aa, bb) aa 컬럼 : 컬럼을 추가하고 #u_id selector 속성을 자동으로 지정합니다. bb 컬럼 : 컬럼을 추가하고 #u_name selector 속성을 명시적으로 지정합니다. Tip columns 속성은 first 테이블의 columns 컬렉션을 가르킵니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 추가 및 매핑하기","url":"guide/features/columns.html#컬럼-추가-및-매핑하기","text":"컬럼 추가 및 매핑하기 기본 테이블(first)의 columns 컬렉션에 컬럼을 추가한 후, 지정한 명령(BindCommand)의 뷰(MetaView)에 참조를 등록합니다. js const bm = new BindModel (); // 컬럼 추가 및 selector 초기값 설정 bm. addSelector ( 'cc' , '#addr' , 'read' ); bm. addSelector ( 'dd' , '#tel' , 'read' , [ 'valid' , 'bind' ]); // bm.columns.count === 2 (cc, dd) // bm.cmd['read'].valid.columns.count === 2 (cc, dd) // bm.cmd['read'].bind.columns.count === 2 (cc, dd) // bm.cmd['read'].output.columns.count === 1 (cc) cc 컬럼 : #addr selector 로 컬럼을 추가하고, 'read' 명령의 모든 뷰에 참조를 등록합니다. 모든 뷰 : valid, bind, output, misc dd 컬럼 : #tel selector 로 컬럼을 추가하고, 'read' 명령의 bind , valid 뷰에 참조를 등록합니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"모델에서 컬럼 추가","url":"guide/features/columns.html#모델에서-컬럼-추가","text":"모델에서 컬럼 추가 모델(BindModel)객체에서 컬럼을 추가하고 초기값을 설정할 수 있습니다. ts type viewsType = 'valid' | 'bind' | 'output' | 'misc' | string /* 추가 뷰*/ ; declare function addColumn ( column : string | MetaColumn , cmds ?: '$all' | string | string [], views ?: '$all' | viewsType | viewsType[], bTable ?: string | MetaTable ): BindCommand ; declare function addColumnValue ( columnName : string , value : string | number | boolean | { /* 컬럼속성 */ }, cmds ?: string | string [], views ?: viewsType | viewsType[], bTable ?: string | MetaTable ): BindCommand ; addColumn() : 컬럼 객체 또는 이름으로 빈 컬럼을 추가합니다. column : 추가할 컬럼 객체 또는 컬럼명 입니다. cmds : 명령(BindCommand) 이름을 지정합니다. views : 참조를 등록할 뷰( MetaView ) 이름을 지정합니다. bTable : 컬럼이 등록될 테이블( MetaTable )을 지정합니다. addColumnValue() : 지정한 이름으로 컬럼을 추가하고 초기값을 설정합니다. columnName : 추가할 컬럼명 입니다. value : 컬럼의 초기값입니다. cmds : 명령(BindCommand) 이름을 지정합니다. views : 참조를 등록할 뷰( MetaView ) 이름을 지정합니다. bTable : 컬럼이 등록될 테이블( MetaTable )을 지정합니다. Tip cmds 값으로 $all 을 지정하면, 등록된 모든 명령( BindCommand )에 참조가 추가됩니다. views 값으로 $all 또는 undefined 지정하면 모든 뷰( valid , bind , output , misc )에 참조가 추가됩니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 추가하기","url":"guide/features/columns.html#컬럼-추가하기-2","text":"컬럼 추가하기 기본테이블(first)의 columns 컬렉션에 컬럼을 추가합니다. js const bm = new BindModel (); // 'aa' 컬럼 추가 bm. addColumn ( 'aa' ); // 'bb' 컬럼 추가 및 초기값 설정 bm. addColumnValue ( 'bb' , 10 ); // bm.first.columns.count == 2 // bm.columns.count == 2 // bm.columns['aa'].value == '' // bm.columns['bb'].value == 10 addColumn() : 컬럼을 추가합니다. addColumnValue() : 컬럼을 추가하고 초기값을 설정합니다. Tip columns 속성은 first 테이블의 columns 컬렉션을 가르킵니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 추가 및 매핑하기","url":"guide/features/columns.html#컬럼-추가-및-매핑하기-2","text":"컬럼 추가 및 매핑하기 기본 테이블(first)에 컬럼을 추가한 후, 지정한 명령(BindCommand)의 뷰(MetaView)에 참조를 등록합니다. js const bm = new BindModel (); // 'aa' 컬럼을 'cmd1'의 모든 뷰에 매핑 bm. addColumn ( 'aa' , 'cmd1' ); // 'bb' 컬럼을 'cmd2', 'cmd3'의 'valid', 'bind'에 매핑 bm. addColumn ( 'bb' , [ 'cmd2' , 'cmd3' ], [ 'valid' , 'bind' ]); // 'cc' 컬럼을 모든 명령의 'output'에 매핑 bm. addColumn ( 'cc' , '$all' , 'output' ); // bm.columns.count == 3 ('aa', 'bb', 'cc') // bm.command['cmd1'].valid.columns.count == 1 ('aa') // bm.command['cmd1'].bind.columns.count == 1 ('aa') // bm.command['cmd1'].output.columns.count == 2 ('aa', 'cc') // bm.command['cmd2'].valid.columns.count == 1 ('bb') // bm.command['cmd2'].bind.columns.count == 1 ('bb') // bm.command['cmd2'].output.columns.count == 1 ('cc') // bm.command['cmd3'].valid.columns.count == 1 ('bb') // bm.command['cmd3'].bind.columns.count == 1 ('bb') // bm.command['cmd3'].output.columns.count == 1 ('cc') aa 컬럼 : 빈 컬럼을 추가하고, 지정한('cmd1') 명령의 모든 뷰에 참조값을 매핑합니다. bb 컬럼 : 빈 컬럼을 추가하고, 지정한('cmd1', 'cmd2') 명령의 특정('valid', 'bind') 뷰에 참조값을 매핑합니다. cc 컬럼 : 빈 컬럼을 추가하고, 전체 명령의 특정('output') 뷰에 참조값을 매핑합니다. Tip addColumnValue() 를 사용하면 컬럼 추가와 초기값 설정을 동시에 수행하고 매핑할 수 있습니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"명령에서 컬럼 추가","url":"guide/features/columns.html#명령에서-컬럼-추가","text":"명령에서 컬럼 추가 명령( BindCommand ) 객체에서 컬럼을 추가하거나 초기값을 설정할 수 있습니다. ts type viewsType = 'valid' | 'bind' | 'output' | 'misc' | string /* 사용자 정의 뷰 */ ; declare function addColumn ( column : string | MetaColumn , views ?: '$all' | viewsType | viewsType[], bTable ?: string | MetaTable ): BindCommand ; declare function addColumnValue ( columnName : string , value : string | number | boolean | { /*property*/ }, views ?: viewsType | viewsType[], bTable ?: string | MetaTable ): BindCommand ; addColumn() : 컬럼 객체 또는 이름으로 컬럼을 추가합니다. column : 추가할 컬럼 객체 또는 컬럼명 입니다. views : 참조를 등록할 뷰(MetaView) 이름를 지정합니다. bTable : 컬럼의 등록되는 테이블(MetaTable)입니다. addColumnValue() : 컬럼을 추가하고 초기값을 설정합니다. columnName : 추가할 컬럼명 입니다. value : 컬럼의 초기값입니다. views : 참조를 등록할 뷰( MetaView ) 이름를 지정합니다. bTable : 컬럼의 등록되는 테이블(MetaTable)입니다. Tip views 에 '$all' 을 지정하면, 모든 뷰( valid , bind , output , misc )에 참조가 추가됩니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 추가 및 매핑하기","url":"guide/features/columns.html#컬럼-추가-및-매핑하기-3","text":"컬럼 추가 및 매핑하기 기본 테이블( first )에 컬럼을 추가하고, 대상 명령( BindCommand )의 뷰( MetaView )에 참조를 등록합니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 'aa' 컬럼을 'valid' 뷰에 매핑 bm. command [ 'cmd1' ]. addColumn ( 'aa' , 'valid' ); // 'bb' 컬럼을 'bind'와 'output' 뷰에 매핑 bm. command [ 'cmd1' ]. addColumn ( 'bb' , [ 'bind' , 'output' ]); // 'cc' 컬럼을 모든 뷰에 매핑 bm. command [ 'cmd1' ]. addColumn ( 'cc' , '$all' ); // 'dd' 컬럼을 모든 뷰에 매핑 bm. command [ 'cmd1' ]. addColumn ( 'dd' ); // bm.columns.count == 4 ('aa', 'bb', 'cc', 'dd') // bm.command['cmd1'].valid.columns.count == 3 ('aa', 'cc', 'dd') // bm.command['cmd1'].bind.columns.count == 3 ('bb', 'cc', 'dd') // bm.command['cmd1'].output.columns.count == 3 ('bb', 'cc', 'dd') aa 컬럼 : 빈 컬럼을 추가하고, 지정한 명령의 특정 뷰('valid')에 참조값을 매핑합니다. bb 컬럼 : 빈 컬럼을 추가하고, 지정한 명령의 특정 뷰('bind', 'output')에 참조값을 매핑합니다. cc 컬럼 : 빈 컬럼을 추가하고, 지정한 명령의 전체 뷰에 참조값을 매핑합니다. dd 컬럼 : 빈 컬럼을 추가하고, 지정한 명령의 전체 뷰에 참조값을 매핑합니다. Tip '$all' 지시자는 명령의 모든 뷰(valid, bind, output, misc)와 함께, 사용자가 정의한 추가 출력 뷰까지 포함하여 참조합니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"기존 컬럼 매핑하기","url":"guide/features/columns.html#기존-컬럼-매핑하기","text":"기존 컬럼 매핑하기 이미 등록된 컬럼을 MetaView 에 참조로 등록하거나 해제할 수 있습니다. ts type TableNameType = string ; type ColumnType = string ; type FullColumnType = ` ${TableNameType} . ${ColumnType} ` ; type ColumnDotType = FullColumnType | ColumnType ; type ViewType = 'valid' | 'bind' | 'output' | 'misc' | string /* 사용자 정의 뷰 */ ; declare function setColumn ( colName : ColumnDotType , views : '$all' | ViewType | ViewType [], bTable ?: string | MetaTable ): void ; declare function release ( colName : string , views ?: ViewType | ViewType [] ): void ; setColumn() : 기존에 등록된 컬럼을 지정한 뷰( MetaView )에 참조로 등록합니다. release() : 지정한 뷰(MetaView)에 참조를 해제합니다. 뷰를 지정하지 않으면, 해당 명령의 모든 뷰에서 컬럼이 해제됩니다. 이미 등록된 컬럼을 특정 뷰( MetaView )에 참조로 등록합니다. js const bm = new BindModel (); // 테이블 추가 bm. addTable ( 'second' ); // 기본 테이블(first)에 컬럼 추가 bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' ); // 확장 테이블(second)에 컬럼 추가 bm[ 'second' ]. columns . add ( 'cc' ); bm[ 'second' ]. columns . add ( 'dd' ); // 명령 추가 bm. addCommand ( 'test' ); // 'aa'를 'valid' 뷰에 매핑 bm. command [ 'test' ]. setColumn ( 'aa' , 'valid' ); // 'bb'와 second 테이블의 'cc'를 'bind' 뷰에 매핑 bm. command [ 'test' ]. setColumn ([ 'bb' , 'second.cc' ], 'bind' ); // second 테이블의 'dd'를 모든 뷰에 매핑 bm. command [ 'test' ]. setColumn ( 'second.dd' , '$all' ); // bm.first.columns.count == 2 ('aa', 'bb') // bm.second.columns.count == 2 ('cc', 'dd') // bm.command['test'].valid.columns.count == 2 ('aa', 'dd') // bm.command['test'].bind.columns.count == 2 ('bb', 'cc') // bm.command['test'].output.columns.count == 2 ('cc', 'dd') addTable() : 지정한 이름으로 MetaTable 을 추가합니다. columns.add() : 테이블에 컬럼을 추가합니다. Tip 컬럼을 설정할 때는 테이블명 + . + 컬럼명 표기법을 사용하여 특정 테이블의 컬럼을 지정할 수 있습니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 해제하기","url":"guide/features/columns.html#컬럼-해제하기","text":"컬럼 해제하기 release() 메서드를 사용하여 특정 뷰 또는 모든 뷰에서 컬럼 참조를 해제합니다. js // 'valid' 뷰에서 'aa' 컬럼 참조 해제 bm. command [ 'test' ]. release ( 'aa' , 'valid' ); // 'bind' 뷰에서 'bb'와 'cc' 컬럼 참조 해제 bm. command [ 'test' ]. release ([ 'bb' , 'cc' ], 'bind' ); // 모든 뷰에서 'dd' 컬럼 참조 해제 bm. command [ 'test' ]. release ( 'dd' , '$all' ); // bm.command['test'].valid.columns.count == 0 // bm.command['test'].bind.columns.count == 0 // bm.command['test'].output.columns.count == 0 컬럼을 해제할 때는 테이블명을 생략하고, 컬럼명만 지정하면 됩니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 및 명령 일괄 등록","url":"guide/features/columns.html#컬럼-및-명령-일괄-등록","text":"컬럼 및 명령 일괄 등록 setMapping() 메서드는 컬럼과 명령별 역할(뷰)을 일괄 등록하는 기능을 제공합니다. ts type ColumnKey = string ; // 예: 'aa', 'first.bb', 'second.cc' type CommandKey = string | '$all' ; // 예: 'read', 'write', '$all' type ViewEntry = 'valid' | 'bind' | 'output' | 'misc' | '$all' ; type CommandMapping = Record < CommandKey , ViewEntry | ViewEntry []> | {}; type MappingObject = Record < ColumnKey , CommandMapping >; declare function setMapping ( mapping : MappingObject , bTable ?: string | MetaTable ): void ; bTable : 매핑 시 컬럼 키에 테이블명이 생략된 경우 기본적으로 사용할 테이블을 지정합니다. (기본값: 'first') js const bm = new BindModel (); // 기본 생성 bm. setMapping ({ aa : {}, bb : { cmd1 : '$all' }, // 전체 뷰 매핑 cc : { cmd2 : [ 'valid' , 'bind' ] } }); // bm.columns.count === 3 ('aa', 'bb', 'cc') // bm.command['cmd1'].valid.columns.count === 1 ('bb') // bm.command['cmd1'].bind.columns.count === 1 ('bb') // bm.command['cmd1'].output.columns.count === 1 ('bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0 컬럼 키에 테이블명 + '.' + 컬럼명 형식을 사용하면, 컬럼은 기본 테이블이 아닌 해당 테이블에 등록됩니다. js const bm = new BindModel (); // 기본 생성 bm. setMapping ({ 'aa' : {}, 'first.bb' : { cmd1 : '$all' }, // 전체 뷰 매핑 'second.cc' : { cmd2 : [ 'valid' , 'bind' ] } }); // bm.columns.count === 2 ('aa', 'bb') // bm.first.columns.count === 2 ('aa', 'bb') // bm.second.columns.count === 1 ('cc') // bm.command['cmd1'].valid.columns.count === 1 ('bb') // bm.command['cmd1'].bind.columns.count === 1 ('bb') // bm.command['cmd1'].output.columns.count === 1 ('bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0 columns 속성은 first.columns 컬렉션의 참조 속성입니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼 주요 속성","url":"guide/features/columns.html#컬럼-주요-속성","text":"컬럼 주요 속성 HTMLColumn 은 모델(BindModel)에서 사용되며, MetaColumn 을 상속하여 확장된 구성 요소입니다. 항목 타입 설명 value string | number | boolean 컬럼의 현재 값을 나타냅니다. default string | number | boolean 컬럼의 기본 값을 설정합니다. getter () => any value 값을 가져오는 getter 함수입니다. setter (val: any) => void value 값을 설정하는 setter 함수입니다. getFilter (val: any) => any value 값을 가져올 때 적용되는 filter 함수입니다. setFilter (val: any) => any value 값을 설정할 때 적용되는 filter 함수입니다. selector { key: string, type: string} 셀렉터를 정의합니다. required boolean 필수 여부를 설정합니다. constraints {regex: RegExp, msg: string} <br>(val: any) => boolean 컬럼의 제약 조건을 정의합니다.(복수 제약조건) columnName string 컬럼의 이름을 나타냅니다. alias string 컬럼의 별칭을 나타냅니다. caption string 컬럼에 대한 설명을 제공합니다."},{"title":"컬럼 관리","group":"기능 가이드","section":"컬럼값(value)","url":"guide/features/columns.html#컬럼값value","text":"컬럼값(value) 컬럼 값(value)을 조회하거나 설정할 때는 다음과 같은 속성을 활용하여 다양한 처리를 수행할 수 있습니다. default , getter , setter , getFilter , setFilter , selector 참조 : 컬럼값 호출 구조 #참조"},{"title":"컬럼 관리","group":"기능 가이드","section":"제약 조건","url":"guide/features/columns.html#제약-조건","text":"제약 조건 MetaColumn 에 제약조건은 required 와 constraints 속성을 통해 value 값을 검사할 수 있습니다. ts type ConstraintType = { regex : RegExp , msg : string , match : boolean }; type FunctionType = ( value : any ) => boolean ; type complexType = ConstraintType | FunctionType ; type constraints = complexType[] | complexType; required : 필수값 여부를 지정합니다. true 로 설정하면 필수값으로 지정되며, 기본값은 false 입니다. constraints : 함수 또는 객체 타입으로 설정하여 제약 조건을 지정합니다. regex : 정규 표현식 msg : 검사 실패 시 출력할 메시지 match : 매칭 방식 false 로 설정하면 비매칭 조건으로 처리됩니다. (기본값: true )"},{"title":"컬럼 관리","group":"기능 가이드","section":"제약조건 사용 빈도","url":"guide/features/columns.html#제약조건-사용-빈도","text":"제약조건 사용 빈도 컬럼의 특성에 따라 조건을 혼합하여 구성할 수 있습니다. 기본값은 선택 조건 입니다. 사용빈도 required constraints 설명 50% 선택값입니다. 30% true 필수값입니다. 15% {…} | Function 선택값이며, value 에 제약조건이 있습니다. 5% true {…} | Function 필수값이며, value 에 제약조건이 있습니다. 필수 조건 컬럼 추가 시 초기값으로 required 속성을 설정합니다. js bm. addColumnValue ( 'u_code' , { required : true }); 필수 조건으로 설정되며, 공백일 경우 실패 처리되고 cbFail 콜백 함수가 호출됩니다. 매칭 제약 조건 컬럼 추가 시 초기값으로 constraints 속성에 매칭할 정규식을 설정합니다. js bm. addColumnValue ( 'u_code' , { constraints : { regex : /[a-zA-Z0-9]{6,}/ , msg : \"Please enter at least 6 chars.\" } }); 값이 없으면 통과되며, 값이 있을 경우 사용자 정의 함수가 true를 반환해야 조건을 만족합니다. required의 기본값은 false이며, 이는 선택 입력 조건을 의미합니다. 비매칭 제약 조건 컬럼 추가 시 초기값으로 constraints 속성에 비매칭 조건과 match 값을 false 로 설정합니다 js bm. addColumnValue ( 'u_code' , { constraints : { regex : /[0-9]/ , msg : \"No numbers\" , match : false } }); 선택 조건으로 동작하며, 값이 공백일 경우 유효성 검사를 통과합니다. 단, 값이 입력된 경우에는 지정된 정규식과 매칭되지 않아야 통과됩니다. 사용자 함수 제약 조건 컬럼 추가 시 초기값으로 constraints 속성에 사용자 정의 함수를 설정합니다. js bm. addColumnValue ( 'u_code' , { constraints : ( val ) => { return val. length > 8 } }); 선택 조건으로 설정되며, 값이 공백일 경우 유효성 검사를 통과합니다. 그러나 값이 입력된 경우에는, 사용자 정의 함수가 true를 반환해야 유효성 검사를 통과합니다. 혼합 제약 조건 컬럼 추가 시 초기값으로 constraints 속성에 배열로 사용자 정의 함수와 정규식을 설정합니다. js bm. addColumnValue ( 'u_code' , { constraints : [ { regex : /# .{6}$/ , msg : \"Minimum 6 characters required\" }, { regex : /[0-9]/ , msg : \"Numbers are not allowed\" , match : false }, ( val ) => { return val. length >= 8 } // // Must be at least 8 characters ], required : true }); 필수 조건으로 설정되며, 숫자를 제외한 문자의 길이가 6 이상 8 이하 일 경우 유효성 검사를 통과합니다. Tip 복수의 constraints 를 설정하려면 배열로 추가할 수 있으며, 모든 조건이 충족되어야 성공으로 간주됩니다. 기존 constraints 에 조건을 추가하려면 addConstraint() 메서드를 사용하세요."},{"title":"컬럼 관리","group":"기능 가이드","section":"별칭(alias)","url":"guide/features/columns.html#별칭alias","text":"별칭(alias) 별칭은 서버로 데이터를 전송하거나 서버에서 데이터를 받을 때 컬럼명과 데이터 키를 매칭 하는 데 사용됩니다. 제약조건 별칭 이름은 기존의 컬럼명이나 다른 별칭과 중복될 수 없습니다 . 데이터를 전송할 경우 서버로 데이터를 전송할 때 별칭이 설정된 컬럼은 별칭 이름으로 전송됩니다. js const bm = new BindModel (); // 'create' 명령 추가 bm. addCommand ( 'create' ); // 'aa', 'bb' 컬럼 추가 bm. command [ 'create' ]. addColumnValue ( 'aa' , 10 ); bm. command [ 'create' ]. addColumnValue ( 'bb' , 20 ); // 'AA' 별칭 설정 bm. columns [ 'aa' ]. alias = 'AA' ; // 'create' 명령 실행 bm. cmd [ 'create' ]. execute ( 'SEND' , '/user' ); json // SEND DATA { \"AA\" : 10 , \"bb\" : 20 } 'aa' 컬럼은 전송시 'AA' 이름으로 전송됩니다. 데이터를 가져올 경우 서버에서 데이터를 받을 때, 별칭을 기준으로 로우 데이터를 컬럼명과 매칭 합니다. json // SERVER DATA { \"AA\" : 10 , \"bb\" : 20 , \"cc\" : 30 } js const bm = new BindModel (); // 'list' 명령 추가 bm. addCommand ( 'list' , 'VIEW' ); // 'list' 명령의 서버 경로 설정 bm. command [ 'list' ]. url = '/user' ; // 'aa', 'bb' 컬럼 추가 bm. command [ 'list' ]. addColumnValue ( 'aa' , 10 ); bm. command [ 'list' ]. addColumnValue ( 'bb' , 20 ); // 별칭 설정 bm. columns [ 'aa' ]. alias = 'AA' ; // 'list' 명령 실행 bm. cmd [ 'list' ]. execute (); // bm.columns['aa'].value == 10 // bm.columns['bb'].value == 20 // bm.cmd['list'].output.rows[0]['AA'] == 10 // bm.cmd['list'].output.rows[0]['bb'] == 20 서버 응답 데이터 중 'AA'라는 이름의 항목은, 내부적으로 'aa' 컬럼에 값으로 설정됩니다. Tip MetaRow 객체 내부에서 별칭은 속성값으로 참조됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 명령 구성 다음 문서 공통 컬럼 속성"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"공통 컬럼 속성","url":"guide/features/shared-column-properties.html","text":"문서 기능 가이드 기능 가이드 02 공통 컬럼 속성 아이템으로 여러 컬럼의 공통 설정을 관리합니다. 한국어 문서 약 14분 공통 컬럼 속성이란? 모델(BindModel)에서 컬럼을 직접 관리할 수 있지만, 다음과 같은 경우에는 공통 속성 을 사용하는 것이 유리합니다: 여러 테이블에서 동일한 컬럼 속성을 공유해야 할 때 서비스 객체를 구성하며 컬럼 속성을 정의해야 할 때 컬럼의 selector 속성의 유효성을 검사해야 할 때 모델(BindModel)의 기본 테이블(first) 외에 추가 테이블을 사용하는 경우, 중복되는 컬럼 속성을 효율적으로 관리 하기 위해 공통 속성을 활용합니다. 또는 서비스 객체 주입 을 통해 컬럼 속성을 통합적으로 관리할 수도 있습니다."},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"아이템 구성","url":"guide/features/shared-column-properties.html#아이템-구성","text":"아이템 구성 items 속성은 컬럼의 공통 속성 객체 관리하는 컬렉션입니다. 아이템을 구성할 때, 각 항목은 컬럼 속성으로 사용되는 타입입니다. ts type KeyType = 'value' | 'text' | 'html' | 'attr.*' | 'prop.*' | 'css.*' | 'none' ; type ValType = string | number | boolean ; type RegExpType = { reg : RegExp , msg : string , match ?: boolean }; type FuncType = ( value : any ) => boolean ; type ConstraintType = RegExpType | FuncType ; type ColumnType = { columnName ?: string , selector ?: { key : string , type : KeyType }, getter ?: () => any , setter ?: ( val : any ) => any , getFilter ?: () => any , setFilter ?: ( val : any ) => any , default ?: string | number | boolean | null , // 기본값 value ?: ValType , alias ?: string , caption ?: string , constraints ?: ConstraintType | ConstraintType [], // 제약조건 required ?: boolean , // 필수여부 };"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"컬렉션에서 아이템 구성하기","url":"guide/features/shared-column-properties.html#컬렉션에서-아이템-구성하기","text":"컬렉션에서 아이템 구성하기 ts declare function add ( key : string , prop : Record < string , ColumnType > | ValType ): number ; add() : items 컬렉션에 키의 속성값을 추가합니다. key : 아이템 이름(중복 불가) prop : 컬럼 기본값 또는 컬럼의 주요 속성 키와 값 MetaView(valid)에서 value 에 대한 유효성 검사를 위해 required 및 constraints 속성을 사용합니다. 값(value)을 설정하거나 가져올때는 selector , getter , setter , getFilter , setFilter 를 활용할 수 있습니다. js const bm = new BindModel (); // 아이템 추가 bm. items . add ( 'aa' , 10 ); bm. items . add ( 'bb' , 'B' ); bm. items . add ( 'cc' , { columnName : 'CCC' }); bm. items . add ( 'dd' , { selector : { key : '#ID' , type : 'value' } }); // bm.items.count === 4 // bm.items['aa'] === 10 // bm.items['bb'] === 'B' // bm.items['cc'] === { columnName: 'CCC' } // bm.items['dd'] === { selector: { key:'#ID', type: 'value' } }"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"서비스객체로 아이템 구성하기","url":"guide/features/shared-column-properties.html#서비스객체로-아이템-구성하기","text":"서비스객체로 아이템 구성하기 items 속성은 서비스 객체를 통해 정의하여 보다 구조적으로 관리할 수 있습니다. ts type ItemType = Record < string , ColumnType > | ValType ; // `string` 은 컬럼 속성명 type ServiceType = { items ?: Record < string , ItemType > // `string` 은 아이템명 /* etc ... */ }; declare function setService ( service : ServiceType , chkService : boolean ): void ; setService() : 서비스객체에 items 속성을 통해 아이템을 등록할 수 있습니다. js const bm = new BindModel (); bm. setService ({ items : { aa : 10 , bb : 'B' , cc : { columnName : 'CCC' }, dd : { selector : { key : '#ID' , type : 'value' } }, } }); // bm.items.count === 4 // bm.items['aa'] === 10 // bm.items['bb'] === 'B' // bm.items['cc'] === { columnName: 'CCC'} // bm.items['dd'] === { selector: { key:'#ID', type: 'value'}} Tip 서비스 객체에는 items 속성 외에도 command , mapping , fn 속성 을 포함할 수 있습니다. 참조 : 서비스객체 주입"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"아이템 매핑","url":"guide/features/shared-column-properties.html#아이템-매핑","text":"아이템 매핑 아이템의 속성을 여러 테이블에 매핑하여 등록할 수 있습니다. 매핑 객체에 대한 타입 정의 ts type ColumnKey = string ; // 예: 'aa', 'first.bb', 'second.cc' type CommandKey = string | '$all' ; // 예: 'read', 'write', '$all' type ViewEntry = 'valid' | 'bind' | 'output' | 'misc' | '$all' ; type CommandMapping = Record < CommandKey , ViewEntry | ViewEntry []> | {}; type MappingObject = Record < ColumnKey , CommandMapping >; type ServiceType = { mapping ?: MappingObject /* etc ... */ }; CommandMapping 에 {} 를 지정하면, 해당 컬럼은 명령과는 매핑되지 않고, 단순히 아이템 객체를 컬럼으로만 등록됩니다. CommandKey 로 지정하면, 해당 키에 해당하는 명령이 존재하지 않을 경우 새로운 명령(BindCommand) 객체가 해당 키로 추가됩니다. Tip MappingObject 는 서비스 객체의 mapping 속성 또는 setMapping(mapping) 메서드의 인자 타입으로 사용됩니다."},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"서비스객체로 매핑","url":"guide/features/shared-column-properties.html#서비스객체로-매핑","text":"서비스객체로 매핑 모델(BindModel) 객체를 생성할 때, 서비스 객체를 활용하여 여러 컬럼을 일괄 등록할 수 있습니다. js const bm = new BindModel ({ tables : [ 'second' ], // 추가할 테이블 이름 items : { aa : 10 , bb : 20 , cc : 30 }, mapping : { 'aa' : {}, // 기본 테이블(first)에 'aa' 매핑 'first.bb' : {}, // 기본 테이블(first)에 'bb' 매핑 'second.bb' : {}, // 'second' 테이블에 'bb' 매핑 'second.cc' : {}, // 'second' 테이블에 'cc' 매핑 } }); // bm.items.count == 3 ('aa', 'bb', 'cc') // bm.first.columns.count == 2 ('aa', 'bb') // bm.second.columns.count == 2 ('bb', 'cc') // bm.first.columns['aa'].value == 10 // bm.first.columns['bb'].value == 20 // bm.second.columns['bb'].value == 20 // bm.second.columns['cc'].value == 30 tables : 추가할 테이블 이름을 지정합니다. 매핑에 지정한 테이블이 존재하지 않으면, 해당 테이블이 자동으로 생성됩니다. mapping : 아이템과 테이블 컬럼 간 매핑을 설정합니다. Tip 매핑 이름 규칙 : [테이블명 . ]컬럼명 | 아이템명 테이블명이 생략 되면 기본테이블에 등록됩니다. 적용 대상 : mapping(), setColumn(), items 정의"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"등록된 아이템 매핑하기","url":"guide/features/shared-column-properties.html#등록된-아이템-매핑하기","text":"등록된 아이템 매핑하기 이미 등록된 아이템에 공통 속성을 지정하여 매핑하거나, 빈 속성을 사용해 컬럼과 명령별 역할(뷰)을 일괄 등록 할 수 있습니다. 기존에 items 컬렉션에만 공통 속성이 정의되어 있는 경우, 컬럼을 새로 등록한 후 명령별 역할(뷰)에 매핑합니다. 반면, 테이블에 이미 등록된 컬럼의 경우에는 해당 컬럼을 명령별 역할(뷰)에 그대로 매핑하여 처리합니다. ts declare function setMapping ( mapping : MappingObject , // 아이템 매핑 타입 참조 bTable ?: MetaTable | string ): void ; mapping : 매핑 객체 또는 매핑 컬렉션 객체. bTable : 기본 테이블로 지정할 테이블 이름 또는 MetaTable 객체. 예제 : 아이템을 테이블에 컬럼으로 등록하기 명령 매핑을 빈객체 {} 로 표현할 경우 대상테이블에 컬럼이 등록됩니다. js const bm = new BindModel (); // 테이블 추가 bm. addTable ( 'second' ); // 아이템 추가 bm. items . add ( 'aa' , 10 ); bm. items . add ( 'bb' , 20 ); bm. items . add ( 'cc' , 30 ); // 매핑 설정 bm. setMapping ({ 'aa' : {}, // 기본 테이블(first)에 'aa' 매핑 'first.bb' : {}, // 기본 테이블(first)에 'bb' 매핑 'second.bb' : {}, // 'second' 테이블에 'bb' 매핑 'second.cc' : {}, // 'second' 테이블에 'cc' 매핑 }); // bm.items.count == 3 ('aa', 'bb', 'cc') // bm.first.columns.count == 2 ('aa', 'bb') // bm.second.columns.count == 2 ('bb', 'cc') // bm.first.columns['aa'].value == 10 // bm.first.columns['bb'].value == 20 // bm.second.columns['bb'].value == 20 // bm.second.columns['cc'].value == 30 addTable() : 지정한 이름의 테이블을 추가합니다. setMapping() : 매핑 객체를 사용해 아이템과 테이블 간 매핑을 처리합니다. 예제 : 컬럼 등록 및 명령에 매핑하기 아이템을 지정한 명령의 역활(뷰)에 매핑힙니다. js const bm = new BindModel (); bm. items . add ( 'aa' , 10 ); bm. items . add ( 'bb' , 20 ); bm. items . add ( 'cc' , 30 ); // 매핑 설정 bm. setMapping ({ 'aa' : { cmd1 : '$all' }, // 기본 테이블(first)에 'aa' 매핑 'first.bb' : { cmd1 : 'output' }, // 전체 뷰 매핑 'second.cc' : { cmd2 : [ 'valid' , 'bind' ] } }); // bm.items.count == 3 ('aa', 'bb', 'cc') // bm.first.columns.count == 2 ('aa', 'bb') // bm.second.columns.count == 1 ('cc') // bm.first.columns['aa'].value == 10 // bm.first.columns['bb'].value == 20 // bm.second.columns['cc'].value == 30 // bm.command['cmd1'].valid.columns.count === 1 ('aa') // bm.command['cmd1'].bind.columns.count === 1 ('aa') // bm.command['cmd1'].output.columns.count === 1 ('aa', 'bb') // bm.command['cmd2'].valid.columns.count === 1 ('cc') // bm.command['cmd2'].bind.columns.count === 1 ('cc') // bm.command['cmd2'].output.columns.count === 0"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"아이템 유효성 검사","url":"guide/features/shared-column-properties.html#아이템-유효성-검사","text":"아이템 유효성 검사 checkSelector()는 지정한 컬렉션 내 selector 속성의 유효성을 검사합니다. ts declare function checkSelector ( collection ?: PropertyCollection = this .items, isLog : boolean = false ): string []; checkSelector() : 대상 컬렉션의 selector 속성을 검사합니다. collection : 검사 대상 컬렉션 (기본값: this.items ) isLog : true로 설정 시, 유효성 검사 실패 항목을 콘솔에 출력합니다. Tip collection은 다음의 대상을 설정할 수 있습니다: ['테이블명'].columns, items, columns, valid.columns , bind.columns , output.columns js const bm = new BindModel (); // 아이템 추가 bm. items . add ( 'aa' , { selector : { key : '#user_name' , type : 'value' }}); bm. items . add ( 'bb' , { selector : { key : '.sub_name' , type : 'text' }}); bm. items . add ( 'cc' , { selector : { key : 'input[name=man]' , type : 'none' }}); // 유효성 검사 bm. checkSelector (); // 빈 배열 반환: 검사 성공 // bm.items.count === 3 Tip 서비스객체 주입 시 DOM 유효성 검사는 preCheck 콜백 함수에서 처리할 수 있습니다. 유효성 검사는 지정된 컬렉션 내의 selector 속성에 대해 수행됩니다. js const bm = new BindModel (); // 컬럼 추가 bm. addColumnValue ( 'aa' , { selector : { key : '#user_name' , type : 'value' }}); bm. addColumnValue ( 'bb' , { selector : { key : '.sub_name' , type : 'text' }}); bm. addColumnValue ( 'cc' , { selector : { key : 'input[name=man]' , type : 'none' }}); // 유효성 검사 bm. checkSelector (bm. columns ); // 빈 배열 반환: 검사 성공 // bm.columns.count === 3"},{"title":"공통 컬럼 속성","group":"기능 가이드","section":"selector 조회하기","url":"guide/features/shared-column-properties.html#selector-조회하기","text":"selector 조회하기 getSelector()를 사용해 컬렉션 내 selector 속성의 목록을 가져올 수 있습니다. ts type KeyType = 'none' | 'value' | 'text' | 'html' | 'prop' | 'attr' | 'css' ; type SelectorType = { key : string , type : KeyType }; declare function getSelector ( collection ?: PropertyCollection = this .items ): SelectorType []; collection : 조회할 컬렉션 (기본값: this.items ) js const bm = new BindModel (); // 컬럼 추가 bm. columns . add ( 'item1' , { selector : { key : '#ID1' , type : 'value' }}); bm. columns . add ( 'item2' , { selector : { key : '#ID2' , type : 'text' }}); // `selector` 목록 조회 bm. getSelector (); // 반환 값 : [ { key:'#ID1', type: 'value' }, { key:'#ID2', type: 'text' } ] Tip 컬렉션을 인자로 전달하면, 해당 컬렉션에 포함된 selector 목록을 가져올 수 있습니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 컬럼 관리 다음 문서 흐름 제어"},{"title":"흐름 제어","group":"기능 가이드","section":"흐름 제어","url":"guide/features/flow-control.html","text":"문서 기능 가이드 기능 가이드 02 흐름 제어 콜백 라이프사이클과 오류 처리로 실행 흐름을 제어합니다. 한국어 문서 약 13분"},{"title":"흐름 제어","group":"기능 가이드","section":"콜백 라이프 사이클","url":"guide/features/flow-control.html#콜백-라이프-사이클","text":"콜백 라이프 사이클 다음은 BindCommand 실행 시의 콜백 함수 라이프사이클 을 도식화한 것입니다. 각 단계에서 호출되는 콜백 함수와 관련 동작이 나열되어 있습니다. graph TD E1(\"1.onExecute 이벤트\") --> C1(\"2.cbBegin\") subgraph client_area C2(\"3.cbValid\") --> V1(\"4.valid:유효성검사\") end C1 --> C2 C1 --> |cbValid 없을경우| V1 V1 --> C3(\"6.cbBind\") client_area --> |논리적 실패| F1(\"5.cbFail\") subgraph callback_area C3 --> V2(\"7.bind:서버전송\") V2 --> C4(\"8.cbResult\") C4 --> |outOpt > 0| V3(\"9.output:바인딩\") V3 --> C5(\"10.cbOutput\") end callback_area --> |오류| F2(\"11.cbError\") C5 --> C6(\"12.cbEnd\") C4 --> |outOpt == 0| C6 F1 --> C6 F2 --> C6 C6 --> E2(\"13.onExecuted 이벤트\") style C1 fill:gray,color:#fff style C2 fill:gray,color:#fff style C3 fill:gray,color:#fff style C4 fill:gray,color:#fff style C5 fill:gray,color:#fff style C6 fill:gray,color:#fff style E1 fill:green,color:#fff style E2 fill:green,color:#fff style F1 fill:orange,color:#fff style F2 fill:orange,color:#fff 구조와 흐름을 설명하는 다이어그램 onExecute 이벤트 명령 실행 시작 시 발생하는 이벤트입니다. cbBegin 실행 시작 콜백. 초기 설정이나 검증 전에 호출됩니다. cbValid 유효성 검사를 위한 콜백. valid: MetaView에 설정된 조건을 확인합니다. cbValid가 없을 경우, 바로 유효성 검사로 넘어갑니다. valid: MetaView 유효성 검사 컬럼의 제약조건(required, constraints)을 검사합니다. cbFail 유효성 검사 실패 시 호출되는 콜백함수를 호출합니다. cbBind 서버 요청 전 데이터를 호출되는 콜백함수를 호출합니다. bind: MetaView 요청 서버 요청을 실행합니다. cbResult 서버 응답 데이터를 처리하는 콜백함수를 호출합니다. output: MetaView 바인딩 outputOption.option = 'SEND' 가 아닌 경우 응답 데이터를 output: MetaView에 바인딩합니다. cbOutput output: MetaView에 데이터를 바인딩한 후 호출되는 콜백입니다. cbError 실행 중 오류가 발생하면 호출되는 콜백함수를 호출합니다. cbEnd 명령 실행이 완료된 후 호출되는 콜백함수를 호출합니다. onExecuted 이벤트 명령 실행 종료 시 발생하는 이벤트입니다."},{"title":"흐름 제어","group":"기능 가이드","section":"실패 및 에러 처리","url":"guide/features/flow-control.html#실패-및-에러-처리","text":"실패 및 에러 처리 cbError 와 cbFail 콜백함수는 기본값을 제공합니다. 필요에 따라 커스터마이징하여 사용할 수 있습니다. js cbFail = function ( msg, valid ) { console . warn ( 'Failed. Err:' + msg); }; cbError = function ( msg, status, response ) { console . error ( 'An error has occurred. : ' + msg); };"},{"title":"흐름 제어","group":"기능 가이드","section":"오류  콜백(cbError)","url":"guide/features/flow-control.html#오류-콜백cberror","text":"오류 콜백(cbError) execute() 실행 중에 발생한 모든 오류를 처리합니다. ts type cbError = ( msg : string , status : number , response : object ) => void ; msg : 에러 메세지 status : 에러 번호 response : 응답 객체 예제 : 유효성 검사 실패시 경고창을 표시합니다. js bm. cbError = function ( msg, status, res ) { alert ( 'Err: ' + msg); }; Tip execute()는 내부적으로 try 문으로 감싸져 있어 예외를 던지지 않습니다. 예외 처리를 위해서는 cbError 에서 직접 구현해야 합니다."},{"title":"흐름 제어","group":"기능 가이드","section":"실패 콜백","url":"guide/features/flow-control.html#실패-콜백","text":"실패 콜백 execute() 실행 중 유효성 검사가 실패했을 때 호출됩니다. ts type cbFail = ( msg : string , valid : MetaView ) => void ; msg : 실패 메세지 valid : 유효성 검사 대상 MetaView 예제 : 유효성 검사 실패시 경고창을 표시합니다. js bm. cbFail = function ( msg, valid ) { alert ( 'Failed: ' + msg); };"},{"title":"흐름 제어","group":"기능 가이드","section":"콜백 함수 호출 순서","url":"guide/features/flow-control.html#콜백-함수-호출-순서","text":"콜백 함수 호출 순서 명령(BindCommand)의 execute() 호출 시 단계별로 실행되는 콜백 함수는 다음과 같습니다. 구분 기본콜백 <br>(BindModel) 명령콜백 <br>(BindCommand) 설명 시작 cbBaseBegin cbBegin 명령 실행 시작 시 호출됩니다. 유효성 검사 cbBaseValid cbValid valid: MetaView 유효성 검사 전에 호출됩니다. 서버 요청 cbBaseBind cbBind bind: MetaView 요청 전에 호출됩니다. 응답 결과 cbBaseResult cbResult 서버 응답 데이터를 처리한 후 호출됩니다. 결과 출력 cbBaseOutput cbOutput output: MetaView에 데이터 매핑 후 호출됩니다. 종료 cbBaseEnd cbEnd 명령 실행 종료 시 호출됩니다. 명령 콜백 이 정의된 경우, 기본 콜백 은 무시됩니다. 예를 들어, cbBegin 콜백함수가 정의되어 있으면 cbBaseBegin 콜백함수는 실행되지 않습니다."},{"title":"흐름 제어","group":"기능 가이드","section":"1. 시작 콜백","url":"guide/features/flow-control.html#1-시작-콜백","text":"1. 시작 콜백 execute() 호출 시 가장 먼저 실행되는 콜백입니다. cbBaseBegin 은 모델(BindModel)의 기본 콜백함수이며, cbBegin 은 각 명령(BindCommand)의 콜백함수입니다. ts type BeginType = ( model : BindModel , cmd : BindCommand ) => void ; type cbBaseBegin = BeginType ; type cbBegin = BeginType ; model : 현재 모델(BindModel) 객체 입니다. cmd : 실행 대상 명령(BindCommand) 객체입니다. 예제 : 기본 시작 콜백과, list 명령(BindCommand) 시작 콜백을 설정 js bm. cbBaseBegin = function ( model, cmd ) { cmd. url = '/member/1' ; }; bm. command [ 'list' ]. cbBegin = function ( model, cmd ) { cmd. url = '/member/1' ; }; Tip 시작 콜백은 동적으로 서버 요청 경로를 설정하거나 초기화를 수행하는 데 유용합니다."},{"title":"흐름 제어","group":"기능 가이드","section":"2. 유효성 검사 콜백","url":"guide/features/flow-control.html#2-유효성-검사-콜백","text":"2. 유효성 검사 콜백 execute() 호출시 valid(MetaView)에 대한 유효성 검사 전에 호출됩니다. cbBaseValid 은 모델(BindModel)의 기본 콜백함수이며, cbValid 는 각 명령(BindCommand)의 콜백함수입니다. ts type ValidType = ( valid : MetaView , cmd : BindCommand , model : BindModel ) => boolean | undefined ; type cbBaseValid = ValidType ; type cbValid = ValidType ; valid : 유효성 검사 대상 MetaView cmd : 실행 대상 명령(BindCommand) model : 현재 모델(BindModel) 객체 입니다. return true : 유효성 검사를 통과하고 다음 단계를 진행합니다. false : 유효성 검사가 실패하며, cbFail 콜백함수가 호출됩니다. undefined : 유효성 검사가 실패하지만 cbFail 콜백함수가 호출되지 않습니다 Tip 유효성 검사 콜백에서 return 값으로 undefined 를 반환하면, 오류 메시지 출력 등의 처리를 콜백 내부에서 직접 수행하며, 별도로 cbFail 콜백 함수를 호출하지 않습니다. 예제 : 기본 유효성 검사 콜백과, list 명령(BindCommand) 유효성 검사 콜백을 설정 js bm. cbBaseValid = function ( valid, cmd, model ) { if (valid. colums . count > 0 ) return true ; alert ( 'valid(MetaView) 컬럼이 없습니다.' ); }; bm. command [ 'list' ]. cbValid = function ( valid, cmd, model ) { return confirm ( '삭제하시겠습니까?' ); }; cbBaseValid : 실패 시 undefined 를 반환하여 cbFail 콜백함수가 호출되지 않습니다. cbValid : confirm 결과가 false 면 cbFail 콜백함수가 호출됩니다. Tip 유효성 검사 콜백은 선택창 확인이나 추가 검증 로직에 주로 활용됩니다."},{"title":"흐름 제어","group":"기능 가이드","section":"3. 서버 요청 콜백","url":"guide/features/flow-control.html#3-서버-요청-콜백","text":"3. 서버 요청 콜백 execute() 호출시 bind(MetaView) 컬럼값을 서버로 요청하기 전에 호출됩니다. cbBaseBind 은 모델(BindModel)의 기본 콜백이며, cbBind 는 각 명령(BindCommand) 콜백함수입니다. ts type BindType = ( bind : MetaView , cmd : BindCommand , config : object ) => void ; type cbBaseBind = BindType ; type cbBind = BindType ; bind : 요청할 데이터가 포함된 MetaView cmd : 실행 대상 명령(BindCommand) config : axios 설정 객체 Tip 서버 요청 콜백은 전송 데이터 타입 설정, 인증 토큰 추가, 암호화 처리 등에 활용됩니다."},{"title":"흐름 제어","group":"기능 가이드","section":"4. 응답 처리 콜백","url":"guide/features/flow-control.html#4-응답-처리-콜백","text":"4. 응답 처리 콜백 execute() 호출시 서버에서 응답을 받은 후에 호출됩니다. cbBaseResult 은 모델(BindModel)의 기본 콜백이며, cbResult 는 각 명령(BindCommand) 콜백함수입니다. ts type ResultType = ( data : object , cmd : BindCommand , response : object ) => object ; type cbBaseResult = ResultType ; type cbResult = ResultType ; data : 서버 응답 데이터 cmd : 실행 대상 명령(BindCommand) response : axios 응답 객체 return : 반환 데이터 ( return 값이 없으면 data 객체로 대체 됩니다) 예제 : 기본 응답 결과 콜백과, list 명령(BindCommand) 응답 결과 콜백을 설정 js // data = { aa: 1, bb: 2 } bm. cbBaseResult = function ( data ) { return { rows : data }; }; bm. command [ 'list' ]. cbResult = function ( data ) { return { rows : data }; }; Tip 서버 응답 데이터를 스키마 구조로 변환하는 데 주로 활용됩니다. #참조"},{"title":"흐름 제어","group":"기능 가이드","section":"5. 출력 콜백","url":"guide/features/flow-control.html#5-출력-콜백","text":"5. 출력 콜백 execute() 호출시 응답 데이터를 output(MetaView)에 매핑한 후 호출됩니다. cbBaseOutput 은 모델(BindModel)의 기본 콜백이며, cbOutput 는 각 명령(BindCommand)의 콜백함수입니다. Tip 명령(BindCommand)의 outputOption 이 0 일 경우에는 출력 콜백은 무시됩니다. ts type OutputType = ( outputs : MetaViewColleciton , cmd : BindCommand , response : object ) => void ; type cbBaseOutput = OutputType ; type cbOutput = OutputType ; outputs : MetaView 컬렉션. ( output === _outputs[0] ) cmd : 실행 대상 명령(BindCommand). response : axios 응답 객체. Tip output(MetaView) 는 _outputs[0] 컬렉션 을 참조합니다. 여러개의 출력 결과를 받을때 addOutput() 을 사용하여 추가할 수 있습니다. #참조 json // SERVER DATA [ { \"u_name\" : \"Neo\" , \"gender\" : \"M\" } , { \"u_name\" : \"Jane\" , \"gender\" : \"W\" } , ] 예제 : list 명령(BindCommand) 출력 콜백을 설정 js bm. command [ 'list' ]. cbOutput = function ( outputs ) { outputs[ 0 ]. rows . forEach ( ( row, i ) => { console . log (i, row[ 'name' ], row[ 'gender' ]); }); }; // 0 Neo M // 1 Jane W Tip 출력 콜백은 데이터를 화면에 출력하거나 추가 처리를 수행할 때 유용합니다."},{"title":"흐름 제어","group":"기능 가이드","section":"6. 종료 콜백","url":"guide/features/flow-control.html#6-종료-콜백","text":"6. 종료 콜백 execute() 호출시 실행이 완료된 후 호출됩니다. cbBaseEnd 은 모델(BindModel)의 기본 콜백이며, cbEnd 는 각 명령(BindCommand) 콜백함수입니다. ts type EndType = ( status : number , cmd : BindCommand , response : object ) => void ; type cbBaseEnid = EndType ; type cbEnd = EndType ; status : 응답 상태 코드. cmd : 실행 대상 명령(BindCommand). response : axios 응답 객체. 예제 : 기본 종료 콜백과, list 명령(BindCommand) 종료 콜백함수를 설정 js bm. cbBaseEnd = function ( status, cmd, res ) { alert ( '처리가 완료되었습니다.' ); }; bm. command [ 'list' ]. cbEnd = function ( status, cmd, res ) { bm. command [ 'read' ]. execute (); // // 'read' 명령 실행 (체이닝) } Tip 종료 콜백은 결과 메시지 표시, 리다이렉트, 명령 체인 실행 등에 활용됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 공통 컬럼 속성 다음 문서 서비스 객체 주입"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"서비스 객체 주입","url":"guide/features/service-injection.html","text":"문서 기능 가이드 기능 가이드 02 서비스 객체 주입 설정과 비즈니스 로직을 서비스 객체로 모아 재사용합니다. 한국어 문서 약 24분"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"서비스 객체 구성","url":"guide/features/service-injection.html#서비스-객체-구성","text":"서비스 객체 구성 서비스 객체를 주입하여 모델(BindModel) 객체를 간편하게 생성할 수 있습니다. 서비스 객체는 다음과 같은 영역으로 구성됩니다: 기본 영역 기본 서버 설정, 공통 콜백 함수, 이벤트, 테이블 설정을 정의합니다. 아이템 영역 모델(BindModel)에서 공통 컬럼 속성을 관리합니다. 명령 영역 명령(BindCommand)을 정의하고, 실행 흐름과 관련된 설정을 구성합니다. 매핑 영역 아이템을 테이블이나 명령의 뷰(MetaView)와 매핑하여 데이터 흐름을 제어합니다. 함수 영역 사용자 정의 함수로 비즈니스 로직을 캡슐화하여 외부에서 쉽게 호출할 수 있도록 구성합니다. 전처리 영역 모델 init() 초기화 시 호출되는 전처리 함수로 초기 설정 및 유효성 검사 등의 작업을 처리합니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"기본 영역","url":"guide/features/service-injection.html#기본-영역","text":"기본 영역 기본 영역에는 기본서버설정, 기본 콜백함수, 전역 이벤트, 테이블 확장 을 구성합니다. ts type ServiceType = { // 기본 서버 설정 url ?: string , // 기본 axios config baseConfig ?: axiosConfig, // 추가할 테이블 tables ?: string [], // 기본 콜백 함수 cbBaseBegin ?: ( model : BindModel , cmd : BindCommand ) => void ; cbBaseValid ?: ( view : MetaView , cmd : BindCommand , model : BindModel ) => boolean , cbBaseBind ?: ( view : MetaView , cmd : BindCommand , cfg : object ) => void , cbBaseResult ?: ( data : object , cmd : BindCommand , res : object ) => object , cbBaseOutput ?: ( outs : MetaViewCollection , cmd : BindCommand , res : object ) => void , cbBaseEnd ?: ( status : number , cmd : BindCommand , res : object ) => void , // 공통 이벤트 onExecute ?: ( bm : BindModel , bc : BindCommand ) => void , onExecuted ?: ( bm : BindModel , bc : BindCommand ) => void , }; URL 설정 url 속성은 서버 요청에 사용되는 기본 경로입니다. js const bm = new BindModel ({ url : '/user' }); Tip url 속성은 baseConfig.url 의 참조합니다. baseConfig 설정 axios 모듈의 config 설정을 구성하는 기본 객체를 지정합니다. 명령(BindCommand)에서 config 를 따로 설정하지 않으면, baseConfig 값이 사용됩니다. js const bm = new BindModel ({ baseConfig : { method : 'post' , url : '/user' , baseUrl : 'https://bindmodel.com' , responseType : 'json' , headers : { 'X-Requested-With' : 'XMLHttpRequest' }, timeout : 1000 , // 기본값은 `0` (타임아웃 없음) auth : { username : 'janedoe' , password : 's00pers3cret' }, // ... 기타 axios 설정 참조 } }); baseConfig.url 속성은 url 속성과 동일한 값을 참조합니다. 참조 : axios > 요청 Config 기본 콜백함수 설정 기본 콜백 함수는 모든 명령(BindCommand)에 적용됩니다. 명령에 특정 콜백 함수가 없을 경우, 해당 기본 콜백 함수가 호출됩니다. js const bm = new BindModel ({ cbBaseBegin : function ( model, cmd ) { console . log ( '기본 시작 콜백' ); }, cbBaseValid : function ( view, cmd, model ) { console . log ( '기본 유효성 검사 콜백' ); return true ; }, cbBaseBind : function ( view, cmd, cfg ) { console . log ( '기본 서버 요청 콜백' ); }, cbBaseResult : function ( data, cmd, res ) { console . log ( '기본 서버 응답 콜백' ); return data; }, cbBaseOutput : function ( view, cmd, res ) { console . log ( '기본 응답 출력 콜백' ); }, cbBaseEnd : function ( status, cmd, res ) { console . log ( '기본 종료 콜백' ); } }); 참조 : 흐름 제어 모델 이벤트 설정 모델(BindModel)의 execute() 호출 시 발생하는 이벤트를 처리합니다. js const bm = new BindModel ({ onExecute : function ( bModel, bCommand ) { console . log ( '실행 시작 이벤트' ); }, onExecuted : function ( bModel, bCommand ) { console . log ( '실행 종료 이벤트' ); } }); Tip 이벤트는 여러 개를 등록할 수 있으며, 콜백 함수는 하나만 설정 가능합니다. 참조 : 이벤트 설정 > 모델 실행 이벤트 , 흐름 제어"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"아이템 영역","url":"guide/features/service-injection.html#아이템-영역","text":"아이템 영역 아이템 영역은 컬럼의 공통 속성값을 정의하는데 사용됩니다. Tip 서비스 객체를 주입하면 BindModel 의 items 컬렉션에 키-값 형식으로 등록됩니다. 이후, 이 컬렉션은 컬럼 등록 및 매핑에 활용됩니다. 참조 : 공통 컬럼 속성 ts type KeyType = 'none' | 'value' | 'text' | 'html' | 'prop' | 'attr' | 'css' ; type ValType = string | number | boolean ; type RegExpType = { reg : RegExp , msg : string , match ?: boolean }; type FuncType = ( value : any ) => boolean ; type ConstraintType = RegExpType | FuncType ; type ColumnType = { columnName ?: string , selector ?: { key : string , type : KeyType }, getter ?: () => any , setter ?: ( val : any ) => any , getFilter ?: () => any , setFilter ?: ( val : any ) => any , default ?: string | number | boolean | null , value ?: ValType , alias ?: string , caption ?: string , constraints ?: ConstraintType | ConstraintType [], required ?: boolean | false , }; type serviceType = { items ?: { [ key : string ]: ColumnType | ValType } }; 컬럼 등록 시, items 의 속성값이 기본형(string, number, boolean)이면 초기값으로 설정되며, 객체일 경우 해당 객체가 컬럼 설정값으로 사용됩니다. 이 예제는 아이템 영역을 설정하는 방법과 다양한 속성값을 활용하여 컬럼 속성을 정의하는 데 유용합니다. 이를 통해 컬럼의 기본값, 제약 조건, 셀렉터, getter/setter 등을 효율적으로 관리할 수 있습니다. js const bm = new BindModel ({ // 아이템 items : { aa : 'Cat' , // 기본값이 'Cat'인 컬럼 bb : 10 , // 기본값이 10 인 컬럼 cc : true , // 기본값이 true 인 컬럼 dd : { selector : { key : '#U_ID' , type : 'value' }, // 셀렉터 설정 setter : ( val ) => { /*외부에 설정 영역*/ }, // setter 설정 getter : () => { return '외부값' ; }, // getter 설정 }, ee : { required : true , // 필수 값 설정 setFilter : ( val ) => { /*외부에 설정영역*/ }, // 값 설정 필터 getFilter : () => { return '외부값' ; }, // 값 가져오기 필터 }, ff : { constraints : { reg : /abc/ , msg : '매칭 실패!' } // 제약조건 설정 } } });"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"명령 영역","url":"guide/features/service-injection.html#명령-영역","text":"명령 영역 명령(BindCommand) 객체를 구성합니다. ts type OptionType = 'SEND' | 'VIEW' | 'ALL' | 'PICK' ; // default 'SEND' type SchemaType = 'AUTO' | 'DATA' | 'ENTITY' ; // default 'AUTO' type IndexType = number | number []; // // default 0 type OutOptType = { option : OptionType , schema : SchemaType , index : IndexType } type CmdPropType = { outputOption ?: OutOptType | OptionType | SchemaType | IndexType , views ?: string [], // 추가할 뷰(MetaView) 목록 config ?: object , // axios 설정 객체 url ?: string , // 서버 요청 URL // 명령 콜백 함수 cbBegin ?: ( model : BindModel , cmd : BindCommand ) => void , cbValid ?: ( view : MetaView , cmd : BindCommand , model : BindModel ) => boolean , cbBind ?: ( view : MetaView , cmd : BindCommand , cfg : object ) => void , cbResult ?: ( data : object , cmd : BindCommand , res : object ) => object , cbOutput ?: ( views : MetaViewCollection , cmd : BindCommand , res : object ) => void , cbEnd ?: ( status : number , cmd : BindCommand , res : object ) => void , // 명령 이벤트 onExecute ?: ( model : BindModel , cmd : BindCommand ) => void , onExecuted ?: ( model : BindModel , cmd : BindCommand ) => void , }; type CommandType = { [ key : string ]: CmdPropType | {} }; type ServiceType = { command ?: CommandType ; }; 서비스 객체를 주입하면 모델(BindModel)의 command 컬렉션에 키와 명령(BindCommand) 객체가 등록됩니다. js const bm = new BindModel ({ command : { create : {}, read : { outputOption : 'VIEW' , // 데이터를 컬럼값에 설정 (지정된 컬럼) config : { method : 'GET' }, // GET 요청 설정 cbEnd : function ( ) { // 처리 완료 후 콜백 함수 alert ( '정상처리되었습니다.' ); } }, update : { views : [ 'two' ], // 'two' 뷰를 추가 url : '/user' // 요청할 URL 경로 } } }); // bm.cmd['create'] : BindCommand // bm.cmd['read'] : BindCommand // bm.cmd['update'] : BindCommand 참조 : 명령 구성 outputOption 설정 서버 응답 데이터를 처리하는 방식 지정 SEND : 출력하지 않음 (기본값) VIEW : 정의된 컬럼 데이터 + 특정 인덱스 데이터를 컬럼값으로 설정 ALL : 모든 데이터를 가져옴 PICK : 정의된 컬럼과 매칭되는 데이터만 가져옴 서버 응답 데이터 형식 지정 AUTO : JSON 데이터 검사 후 엔티티로 변환 DATA : JSON 데이터를 rows 속성에 강제 변환 ENTITY : JSON 데이터를 엔티티 형식의 데이터로 취급 참조 : 명령 구성 > 출력 옵션의 종류 , JSON 스키마 가이드 views 설정 명령에 추가로 사용할 출력 뷰(MetaView)를 정의 js update : { views : [ 'customView' ] } config 설정 axios 요청 설정: js ({ read : { config : { method : 'POST' , timeout : 1000 } } }); 참조 : axios > 요청 Config 명령 콜백 함수 설정 명령의 특정 단계에서 동작을 정의: js ({ read : { cbEnd : function ( cmd ) { console . log ( `명령 ' ${cmd.name} ' 실행 완료` ); } } }); 참조 : 흐름 제어"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"매핑 영역","url":"guide/features/service-injection.html#매핑-영역","text":"매핑 영역 아이템에 등록된 컬럼 속성을 지정한 명령(BindCommand)의 선택된 뷰(MetaView)에 매핑합니다. ts type CommandName = '$all' | string ; // 명령 이름 ('$all'은 모든 명령을 의미) type ViewName = 'valid' | 'bind' | 'output' | '$all' | string ; // 뷰 이름 type MappingType = { [ key : ColumnName ]: { [ key : CommandName ]: ViewName | ViewName [] // 명령 이름과 매핑된 뷰 목록 } }; type ServiceType = { mapping ?: MappingType }; Tip 아이템 이름 규칙 : [테이블명 . ]컬럼명 매핑시 아이템명은 [테이블명.]아이템명 형식으로 지정할 수 있습니다. 매핑할 컬럼명과 동일한 이름의 아이템이 존재할 경우 아이템의 속성을 사용하여 컬럼을 등록합니다. 테이블명이 생략되면 기본 테이블( _baseTable == first )에 컬럼이 추가되며, 지정된 테이블이 존재하지 않으면 자동으로 생성됩니다. 지정한 명령에 개별적으로 매핑할 수 있습니다. 특정 명령(BindCommand)이 존재하지 않으면 자동으로 생성됩니다. Tip 매핑 가능한 뷰는 기본 제공되는 valid , bind , output , misc 에 한정됩니다. 이 외의 출력 뷰에 매핑하려면, 먼저 해당 뷰를 사전에 추가해야 합니다. js const bm = new BindModel ({ mapping : { 'aa' : { $all : [ 'valid' ] }, // 모든 명령의 'valid' 뷰에 'aa' 등록 'bb' : { cmd1 : [ 'bind' ] }, // 'cmd1' 명령의 'bind' 뷰에 'bb' 등록 'second.cc' : { cmd2 : [ 'output' ] } // 'cmd2' 명령의 'output' 뷰에 'cc' 등록 } }); // bm.items.count == 4 ('aa','bb','cc','dd') // bm.first.columns.count == 2 ('aa','bb') // bm.second.columns.count == 1 ('cc') // bm.cmd['cmd1'].valid.columns.count == 1 ('aa') // bm.cmd['cmd1'].bind.columns.count == 1 ('bb') // bm.cmd['cmd1'].output.columns.count == 0 // bm.cmd['cmd2'].valid.columns.count == 1 ('aa') // bm.cmd['cmd2'].bind.columns.count == 0 // bm.cmd['cmd2'].output.columns.count == 1 ('cc') Tip 객체 생성 후에는 setMapping() 메서드를 사용하여 매핑을 설정할 수 있습니다. '$all' : 전체 매핑 모든 명령(BindCommand)을 대상으로 매핑합니다. js aa : { $all : [ 'valid' ] } 모든 뷰(valid, bind, output, misc)를 대상으로 매핑합니다. js aa : { cmd1 : '$all' } 명령에 기본 뷰 외의 추가 뷰가 포함되어 있을 경우, 해당 뷰는 '$all' 옵션의 매핑 대상에 포함됩니다. 명시적 테이블명 지정 특정 테이블 컬럼을 명시적으로 매핑: js ({ 'second.cc' : { cmd2 : [ 'output' ] } }); 'second' 테이블의 'cc' 컬럼이 'cmd2' 명령의 'output' 뷰에 매핑됩니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"함수 영역","url":"guide/features/service-injection.html#함수-영역","text":"함수 영역 모델(BindModel)의 fn 속성 컬렉션은 사용자 정의 함수를 등록하고 활용할 수 있는 영역입니다. 이 영역을 사용하면 반복적인 작업을 캡슐화하거나, 콜백 함수와 연계하여 효과적으로 로직을 실행할 수 있습니다. ts type fnType = { [ key : string ]: Function }; type ServiceType = { fn ?: fnType }; fn 속성에 사용자 함수를 정의하고, 모델 내부 및 외부에서 호출할 수 있습니다. js const bm = new BindModel ({ // 기본 시작 콜백에서 사용자 함수 호출 cbBaseBegin : function ( model, cmd ) { model. fn . execCreate (); // 명령(model)에서 접근 this . bindModel . fn . sum ( 1 , 1 ); // 모델(this.bindModel) 객체에서 접근 }, // 명령 종료 시 사용자 함수 호출 command : { create : { cbEnd : function ( ) { this . bindModel . fn . sum ( 1 , 2 ); } }, }, // 사용자 함수 정의 fn : { sum : function ( a, b ) { return a + b}, execCreate : function ( ) { this . bindModel . command [ 'read' ]. execute (); } } }); 콜백 함수 내에서 this.bindModel 은 현재 BindModel 객체를 참조합니다. 외부에서 사용자 함수를 호출할 수 있습니다. js var bm = new BindModel (); //.... // 버튼 클릭 이벤트와 사용자 함수 연결 $( '#btn_create' ). click ( function ( ) { bm. fn . execCreate (); }); 함수이름 규칙 함수 이름을 명확하게 정의하여 내부와 외부에서 쉽게 식별할 수 있도록 관리합니다. Tip 서비스 객체에서 this.bindModel 은 항상 현재 모델 객체를 참조하므로, 객체 간의 종속성을 효과적으로 관리할 수 있습니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"전처리 영역","url":"guide/features/service-injection.html#전처리-영역","text":"전처리 영역 모델(BindModel) 객체에서 init()을 호출하면 아래 전처리 함수들이 순차적으로 실행됩니다. 이는 주로 서비스 객체의 유효성 검사 및 초기화에 활용됩니다. ts type ServiceType = { preRegister ?: ( bindModel ) => void , preCheck ?: ( bindModel ) => boolean , preReady ?: ( bindModel ) => void }; preRegister() : 전처리 단계에서 가장 먼저 호출되며, 초기화 또는 등록을 구현합니다. preCheck() : 유효성 검사를 수행하며, 검사 성공 시 true 를 반환되어야 다음 단계로 진행됩니다. preReady() : preCheck()에서 true를 반환한 경우 호출되며, 최종 준비 완료 로직을 구현합니다. Tip 전처리 함수에서 첫 번째 인자로 전달되는 bindModel 은 현재 모델(BindModel) 객체를 참조합니다. js const bm = new BindModel ({ preRegister : function ( bindModel ) { console . log ( '1. 전처리: 초기화 또는 등록' ); }, preCheck : function ( bindModel ) { console . log ( '2. 전처리: 유효성 검사' ); // Selector 검사 후 성공 여부 반환 if (bindModel. checkSelector (). length === 0 ) return true ; }, preReady : function ( bindModel ) { console . log ( '3. 전처리: 준비 완료' ); // 준비 완료 후 특정 명령 실행 bindModel. command [ 'test' ]. execute (); }, }); // DOM이 준비되면 초기화 수행 $( document ). ready ( function ( ) { bm. init (); }); init() 호출하면 전처리 함수는 preRegister() >> preCheck() >> preReady() 순차적으로 실행합니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"서비스 객체 설정","url":"guide/features/service-injection.html#서비스-객체-설정","text":"서비스 객체 설정 서비스 객체는 BindModel 생성자 또는 setService() 메서드를 사용하여 주입할 수 있습니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"생성자로 설정","url":"guide/features/service-injection.html#생성자로-설정","text":"생성자로 설정 모델(BindModel) 객체를 생성할 때, 서비스 객체를 인자로 전달합니다. ts declare function BindModel ( service ?: ServiceType ); js let service = { tables : [ 'second' ] // etc config ... }; const bm = new BindModel (service); // bm.second instanceof MetaTable : true 서비스 객체를 통해 ‘second’ 테이블 이 추가되었습니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"메소드로 설정","url":"guide/features/service-injection.html#메소드로-설정","text":"메소드로 설정 모델(BindModel) 객체를 생성한 후, setService() 메서드를 호출하여 서비스 객체를 주입합니다. js let service = { tables : [ 'second' ] // etc config ... }; const bm = new BindModel (); bm. setService (service); // bm.second instanceof MetaTable : true Tip setService() 메서드를 사용하면 서비스 객체를 여러 번 주입할 수 있습니다. 이를 통해 동적으로 필요한 설정을 추가하거나 변경할 수 있습니다. js let secondService = { tables : [ 'second' ] }; let threeService = { tables : [ 'three' ] }; bm. setService (secondService); bm. setService (threeService); // bm.second instanceof MetaTable : true // bm.three instanceof MetaTable : true"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"서비스 객체 관리","url":"guide/features/service-injection.html#서비스-객체-관리","text":"서비스 객체 관리 서비스 객체를 클래스로 정의하면 재사용성을 높이고, 일관된 구조로 관리할 수 있습니다. 사용 목적에 따라 클래스를 다양한 방식으로 구성할 수 있습니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"클래스 정의","url":"guide/features/service-injection.html#클래스-정의","text":"클래스 정의 서비스 객체는 공통 기능을 포함한 클래스로 정의할 수 있으며, 해당 클래스로부터 객체를 생성한 후 사용자 환경에 맞게 수정하여 재사용할 수 있습니다. js // common-service.js export class CommonService { cbFail = function ( msg, valid ) { console . warn ( \"user failure handling:\" + msg); }; cbError = function ( msg, status, response ) { console . error ( \"User error handling\" + msg) }; } js import { BindModel } from 'logic-bind-model' ; import { CommonService } from 'common-service.js' ; const svc = new CommonService (); const bm = new BindModel (svc);"},{"title":"서비스 객체 주입","group":"기능 가이드","section":"상속을 통한 재사용성","url":"guide/features/service-injection.html#상속을-통한-재사용성","text":"상속을 통한 재사용성 서비스 객체의 공통 부분을 부모 클래스로 정의하면 재사용성을 높일 수 있습니다. 자식 클래스는 부모 클래스의 기능을 확장하거나 재정의할 수 있습니다. js // member-service.js import { CommonService } from 'common-service.js' ; export class MemberService extends CommonService { constructor ( suffix ) { super (); this . items = { idx : 10 , user_no : { selector : { key : '#user_no' + suffix, type : 'value' } }, u_name : { selector : { key : '#u_name' + suffix, type : 'value' } }, }; this . command = { create : {}, // 명시적으로 지정 read : { outputOption : 3 , cbEnd : ( status, cmd, res ) => { alert ( 'Normal Processed' ); } } }; this . mapping = { idx : { read : [ 'valid' , 'bind' ] }, u_name : { create : [ 'valid' , 'bind' ], read : [ 'output' ] }, user_no : { create : [ 'bind' ], read : [ 'output' ], } }; } preCheck ( bindModel ) { if (bm. checkSelector (). length === 0 ) return true ; } }; 객체클래스 정의시 suffix 인자를 지정하여, selector 이름의 중복을 피할 수 있습니다. create: {} 명시적으로 지정한 경우이며, 지정하지 않아도 매핑 시 자동으로 생성됩니다. js import { BindModel } from 'logic-bind-model' ; import { MemberService } from 'member-service.js' ; const svc = new CommonService (); const bm = new BindModel (svc); bm. url = \"/user\" ; // bm 객체 사용자화 클래스에서 생성한 객체를 모델(BindModel)에 주입하고, 모델객체를 추가 설정하여 사용합니다."},{"title":"서비스 객체 주입","group":"기능 가이드","section":"클래스 정의 가이드","url":"guide/features/service-injection.html#클래스-정의-가이드","text":"클래스 정의 가이드 BindModel 에서 자주 사용하는 클래스를 정의하고, 이를 상속하여 확장하는 과정을 단계별로 안내합니다. 1단계 : 공통 정의 - 'cbFail', 'cbError' 및 기본 콜백함수를 정의 - 중복 코드 제거를 목표로 공통 기능 구현 2단계 : 독립적인 items 구성 - 공통된 속성을 정의하고, 각 클래스에서 세부적으로 재정의 가능 3단계 : tables , command , mapping 의 연계 구성 - tables , command , mapping 은 상호 연관성이 높아 계층적으로 함께 설계하는 것이 효율적 4단계 : 전처리 및 초기값 설정 - preCheck 와 같은 전처리 과정을 정의하여 폼 유효성 검사 및 초기값 설정에 활용 5단계 : 객체 생성 후 사용자화 - 서버 경로, 환경 설정 등을 객체 생성 후 수정하여 사용자 요구에 맞게 설정 클래스 설계는 사용 목적과요구사항에 맞게 유연하게 변경될 수 있습니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 흐름 제어 다음 문서 JSON 스키마 가이드"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"JSON 스키마 가이드","url":"guide/features/json-schema.html","text":"문서 기능 가이드 기능 가이드 02 JSON 스키마 가이드 AUTO, DATA, ENTITY 모드로 서버 응답의 구조를 다룹니다. 한국어 문서 약 9분 JSON 데이터를 처리하는 과정에서 구조 해석을 자동화하기 위한 스키마 변환 정책에 대해 설명합니다. 기본 모드는 AUTO 이며, 대부분의 일반 데이터는 별도 설정 없이 자동으로 처리됩니다. 복잡하거나 구조 충돌이 우려되는 경우에만 DATA 또는 ENTITY 모드를 명시적으로 지정합니다."},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"엔티티 스키마","url":"guide/features/json-schema.html#엔티티-스키마","text":"엔티티 스키마 엔티티란? MetaTable 또는 MetaView 로 데이터로 가져오거나, 내보낼때의 스키마 구조입니다. ts type DataType = string | number | boolean ; type SingleEntity = { rows : Record < string , DataType > | Record < string , DataType >[], columns ?: Record < string , ColumnType > }; type MultiEntity = SingleEntity []; ColumnType 타입은 문서를 하세요. 참조 : 컬럼 타입 명령(BindCommand) 객체의 outputOption 속성을 직접 설정할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. addCommand ( 'cmd3' ); // outputOption 속성 설정 bm. command [ 'cmd1' ]. outputOption = 'DATA' ; bm. command [ 'cmd2' ]. outputOption . schema = 'ENTITY' ; bm. command [ 'cmd3' ]. outputOption = { schema : 'AUTO' , index : 1 }; // bm.cmd['cmd1'].outOpt === { option: 'SEND', index: 0, schema: 'DATA' } // bm.cmd['cmd2'].outOpt === { option: 'SEND', index: 0, schema: 'ENTITY' } // bm.cmd['cmd3'].outOpt === { option: 'SEND', index: 1, schema: 'AUTO' } outOpt 속성은 outputOption 의 별칭입니다. 명령(BindCommand)을 추가할 때, 매개변수를 통해 설정할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' , 'DATA' ); bm. addCommand ( 'cmd2' , 'ENTITY' ); bm. addCommand ( 'cmd3' , { schema : 'AUTO' , index : 1 }); // bm.cmd['cmd1'].outOpt === { option: 'SEND', index: 0, schema: 'DATA' } // bm.cmd['cmd2'].outOpt === { option: 'SEND', index: 0, schema: 'ENTITY' } // bm.cmd['cmd3'].outOpt === { option: 'SEND', index: 1, schema: 'AUTO' } execute() 메서드를 호출할 때, 매개변수를 통해 설정할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' , 'VIEW' ); bm. addCommand ( 'cmd2' , 'VIEW' ); bm. addCommand ( 'cmd3' , 'VIEW' ); bm. cmd [ 'cmd1' ]. execute ( 'cmd1' , 'DATA' ); bm. cmd [ 'cmd2' ]. execute ( 'cmd2' , 'ENTITY' ); bm. cmd [ 'cmd3' ]. execute ( 'cmd3' , { schema : 'AUTO' , index : 1 }); // bm.cmd['cmd1'].outOpt === { option: 'VIEW', index: 0, schema: 'DATA' } // bm.cmd['cmd2'].outOpt === { option: 'VIEW', index: 0, schema: 'ENTITY' } // bm.cmd['cmd3'].outOpt === { option: 'VIEW', index: 1, schema: 'AUTO' }"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"스키마 모드 요약","url":"guide/features/json-schema.html#스키마-모드-요약","text":"스키마 모드 요약 모드 용도 특징 'AUTO' 기본값 데이터를 검사 후 변환 'DATA' 항상 { rows: [...] } 로 래핑 데이터(rows) 속성으로 강제 변환 'ENTITY' 엔티티 스키마 명시적 지정 배열은 복수의 엔티티로 변환"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"각  모드의 처리 방식","url":"guide/features/json-schema.html#각-모드의-처리-방식","text":"각 모드의 처리 방식"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"AUTO 모드","url":"guide/features/json-schema.html#auto-모드","text":"AUTO 모드 AUTO 모드는 대상 객체의 구조를 확인하여 자동으로 DATA 구조로 변환합니다. (기본값) 대상이 객체 일 경우: rows 속성이 없으면, 해당 객체를 rows 속성으로 래핑함 대상이 배열 일 경우: 배열을 빈 객체의 rows 속성에 할당함 단일 객체 데이터 json { \"aa\" : 10 } json // 변환 결과 { \"rows\" : { \"aa\" : 10 } } 배열 객체 데이터 json [ { \"aa\" : 10 } , { \"aa\" : 20 } ] json // 변환 결과 { \"rows\" : [ { \"aa\" : 10 } , { \"aa\" : 20 } ] } 엔티티 구조 데이터 엔티티 스키마 구조를 갖는 객체는 기존 데이터를 유지합니다. json { \"rows\" : { \"aa\" : 10 } }"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"DATA 모드","url":"guide/features/json-schema.html#data-모드","text":"DATA 모드 DATA 모드는 대상 객체를 무조건 데이터( rows )로 변환하는 강제 변환 모드입니다. 대상이 객체 일 경우: 무조건 rows 속성으로 래핑함 대상이 배열일 경우: 빈 객체에 rows 속성으로 등록함 단, 배열의 요소가 객체가 아닐 경우 오류가 발생 함 단일 객체 데이터 AUTO 로 지정하여도 같은 같은 결과를 확인할 수 있습니다. json { \"aa\" : 10 } json // 변환 결과 { \"rows\" : { \"aa\" : 10 } } 배열 객체 데이터 AUTO 로 지정하여도 같은 같은 결과를 확인할 수 있습니다. json [ { \"aa\" : 10 } , { \"aa\" : 20 } ] json // 변환 결과 { \"rows\" : [ { \"aa\" : 10 } , { \"aa\" : 20 } ] } 'rows', 'columns' 속성명을 사용할 때 'rows', 'columns' 이름의 속성명을 사용하고 할때는 DATA 모드를 지정하면 강제로 rows 래핑하여 'rows', 'columns' 을 데이터로 이용할 수 있습니다. json { \"rows\" : 10 , \"columns\" : 20 } json // 변환 결과 { \"rows\" : { \"rows\" : 10 , \"columns\" : 20 } }"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"ENTITY 모드","url":"guide/features/json-schema.html#entity-모드","text":"ENTITY 모드 ENTITY 모드는 대상 객체를 스키마로 해석하지 않고 독립된 엔티티로 유지합니다. 대상이 객체 일 경우: rows 속성이 없으면, 해당 객체를 rows 속성으로 래핑함 대상이 배열 일 경우: 각 배열 요소에 rows 속성이 있으면 유지 rows 속성이 없을 경우, 해당 요소를 rows 속성으로 래핑함 단, 배열의 요소가 객체가 아닐 경우 오류가 발생 함 객체 데이터 json { \"aa\" : 10 } json // 변환 결과 { \"rows\" : { \"aa\" : 10 } } 엔티티 구조 데이터 엔티티 구조를 갖는 객체는 기존의 구조를 유지합니다. json { \"rows\" : { \"aa\" : 10 } } 배열 객체 데이터 ENTITY 모드에서 배열 객체 데이터는 독립된 엔티티로 변환합니다. json [ { \"aa\" : 10 } , { \"bb\" : 20 } ] json // 변환 결과 [ { \"rows\" : { \"aa\" : 10 } } , { \"rows\" : { \"bb\" : 20 } } ] 복수 배열 객체 데이터 json [ { \"rows\" : { \"aa\" : 10 } } , { \"rows\" : { \"bb\" : 20 } } ] 엔티티 배열 구조를 유지합니다. Tip { \"rows\": { key: vlaue} } 는 { \"rows\": [ { key: vlaue} ]} 로 내부적으로 변환되므로, \"rows\" 속성값으로 객체 또는 배열로 표현할 수 있습니다."},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"스키마 변환표","url":"guide/features/json-schema.html#스키마-변환표","text":"스키마 변환표 JSON 데이터에 따라 적합한 스카마 모드로 지정하여 엔티티로 변환 할 수 있습니다. JSON 구분 AUTO DATA ENTITY { ... } 데이터 객체 확인 후 변환 강제 변환 확인 후 변환 { rows: {...} } 엔티티 객체 유지 실패 유지 [ {...}, ...] 객체 요소 복수 데이터로 변환 복수 데이터로 변환 복수 엔티티로 변환 [ { rows: {...} }, ...] 엔티티 요소 실패 실패 유지 입력된 데이터는 엔티티 데이터 형식 {rows: {...}} 으로 변환되어야 합니다. 엔티티 데이터를 'DATA' 모드로 지정하면, rows 속성으로 강제 래핑하여, 가져오기가 실패합니다. 엔티티 배열 데이터는 'AUTO' 모드로 지정하면, rows 속성으로 래핑하여, 가져오기가 실패합니다. 데이터의 의미에 맞게 적합한 모드를 선택해서 엔티티로 스키타 타입으로 변환할 수 있 수 있습니다. 그 외의 데이터는 cbResult 콜백함수에서 데이터를 변환합니다. 참조 : 흐름 제어 > cbResult"},{"title":"JSON 스키마 가이드","group":"기능 가이드","section":"모드를 쉽게 선택하기","url":"guide/features/json-schema.html#모드를-쉽게-선택하기","text":"모드를 쉽게 선택하기 데이터가 복수 엔티티일 경우에 'entity' 모드 사용합니다. 데이터에 특수한 컬럼(rows, columns) 를 사용할 경우에 'data' 모드 사용합니다. 그 외 기본 'auto' 모드 사용합니다. 즉, 대부분의 기본값인 auto 모드로 사용하면 됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 서비스 객체 주입 다음 문서 컬럼값 호출 구조"},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"컬럼값 호출 구조","url":"advanced/column-value-flow.html","text":"문서 고급 기능 고급 기능 03 컬럼값 호출 구조 값을 읽고 쓸 때 getter, setter, selector가 작동하는 구조를 살펴봅니다. 한국어 문서 약 19분 1.1.13에서 필터를 사용할 때 이 배포 버전에서는 getFilter 로 값을 읽을 때 selector 설정이 필요합니다. DOM을 읽지 않는 필터에는 selector: { key: '#example', type: 'none' } 을 함께 설정하세요. key 는 실제 사용하는 요소에 맞춰 지정합니다. 컬럼의 value 값을 조회하거나 설정할 때 다양한 설정 방식을 활용하여 유연하게 구성할 수 있습니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"컬럼값(value) 조회","url":"advanced/column-value-flow.html#컬럼값value-조회","text":"컬럼값(value) 조회 컬럼값 조회 시, 다음과 같은 우선순위에 따라 적합한 값을 선택합니다. getter : 값 조회 시 우선적으로 실행되는 사용자 정의 함수입니다. getFilter : getter 가 없을 경우, 값을 변환하기 위한 필터 함수입니다. selector : DOM 요소에서 값을 가져옵니다. 내부값 : 컬럼에 저장된 내부 value 값입니다. 기본값(default) : value 나 다른 설정이 없을 경우 반환되는 기본값입니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"조회 내부 구조","url":"advanced/column-value-flow.html#조회-내부-구조","text":"조회 내부 구조 graph BT BB(\"getter():val\") --> |1.getter 있을 경우|AA[let title = column.value] CC{선택} --> AA DD --> |값을 인자로 전달|EE(\"getFilter(selectorValue): val\") DOM -.-> DD EE --> |2.getFilter 있을 경우|CC DD[selector 조회] --> |3.selector 있을 경우|CC FF[[inner value]] --> |4.설정 없는 경우|AA style AA fill:navy,color:#fff style DOM fill:orange,color:#fff style BB fill:green,color:#fff style DD fill:green,color:#fff style EE fill:green,color:#fff style FF fill:green,color:#fff 구조와 흐름을 설명하는 다이어그램"},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"컬럼값 조회 단계","url":"advanced/column-value-flow.html#컬럼값-조회-단계","text":"컬럼값 조회 단계 getter 확인 getter 함수가 설정되어 있으면, 이를 호출하여 반환된 값을 사용합니다. getFilter 확인 getter가 없을 경우, getFilter가 설정되어 있으면 이를 통해 값을 변환합니다. 만약 selector 가 동시에 있으면 selector 로 값을 가져온 후 getFilter 를 거쳐 반환합니다. selector 확인 getter 와 getFilter 가 없고, selector 가 설정되어 있으면 selector 의 type 에 따라 값을 가져옵니다. 내부값 확인 getter , getFilter , selector 가 모두 없으면 컬럼에 저장된 내부 값을 반환합니다. getter , getFilter , selector 에서 반환값이 null, undefined 이면 내부값을 반환합니다. Note 값 조회 시에는 우선순위에 따라 적절한 값이 선택됩니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"컬럼값(value) 설정","url":"advanced/column-value-flow.html#컬럼값value-설정","text":"컬럼값(value) 설정 컬럼값을 설정할 때, 아래 속성에 따라 병렬로 값을 저장하며, 각 단계는 독립적으로 실행됩니다. 즉, setter , setFilter , selector 가 모두 설정되어 있으면 각각에 값을 저장합니다. 컬럼값 설정 시, 다음과 같은 순위에 따라 값을 설정합니다. setter : 값 설정 시 우선적으로 실행되는 사용자 정의 함수입니다. 내부값 : 컬럼에 저장된 내부 value 값에 저장합니다. setFilter : 값을 변환하여 설정하기 위한 필터 함수입니다. selector : DOM 요소에서 값을 설정합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"설정 내부 구조","url":"advanced/column-value-flow.html#설정-내부-구조","text":"설정 내부 구조 graph TD A[title.value = 'title ...'] --> B(\"1.setter(val) : val?\") B --> |리턴 존재시|C[[2.inner value]] A --> |setter 없는 경우| C C --> |setFilter 있을 경우| D(\"3.setFilter(val) : val?\") D -->|return 값과 selector 있을 경우|E(\"4.selector 설정\") D -.-> |DOM Element 설정|DOM C -->|selector 있는 경우|E E -.->|type='none' 아닌 경우| DOM style A fill:navy,color:#fff style B fill:green,color:#fff style C fill:green,color:#fff style D fill:green,color:#fff style E fill:green,color:#fff style DOM fill:orange,color:#fff 구조와 흐름을 설명하는 다이어그램"},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"컬럼값 설정 단계","url":"advanced/column-value-flow.html#컬럼값-설정-단계","text":"컬럼값 설정 단계 setter 호출 setter 함수가 설정되어 있으면, 이를 호출하여 값을 처리합니다. setter 함수가 값을 리턴하는 경우, 리턴값이 내부값으로 저장됩니다. 내부값 저장 설정된 값은 내부값으로 저장됩니다. 만약 setter 가 값을 리턴하면, 리턴값이 내부값으로 저장됩니다. setFilter 호출 setFilter 가 설정되어 있으면, 설정된 함수가 호출되어 값이 변환됩니다. selector 설정 selector 가 설정되어 있으면, type 에 따라 DOM 요소에 값을 설정합니다. setFilter 함수가 값을 리턴하는 경우, 리턴값이 selector 에 값으로 저장됩니다. type이 none 이면 무시됩니다. Note 값을 설정할 때는 정의된 순서에 따라 순차적으로 적용되며, 일부 항목은 병렬로 처리될 수 있습니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"컬럼값 구성 빈도","url":"advanced/column-value-flow.html#컬럼값-구성-빈도","text":"컬럼값 구성 빈도 컬럼값은 다양한 환경과 요구에 따라 조회와 설정을 위한 속성이 다르게 구성됩니다. 아래는 컬럼값을 설정하거나 조회할 때 사용되는 속성의 빈도와 주요 사용 예를 설명합니다. 빈도 setter setFilter selector getFilter getter 설명 89% 사용 - DOM 요소에 직접 연결 <br>- 단일 HTML 요소와 연동 <br>- 예시> 태그 p, input, select, css 3% 사용 사용 - 외부 변수나 객체를 참조<br>- page_count 등 비 DOM 데이터 3% 사용 사용 사용 - 외부 객체와 DOM을 동시 제어<br>- 예시> page_size <br>(HTML select 값과 연동) 3% 사용 사용 - 복합 DOM 요소를 제어 <br>- 예시> 라디오 버튼, 내부값과 화면값이 다른 경우 1% 사용 사용 - HTML 표현값을 가공하는 경우<br>- 예시> 숫자를 통화 형식으로 표시 1% 사용 - HTML 표현과 상관없이 내부적으로만 변환 <br>- 예시> 코드 값 변환, 선택값 표시 샘플 : 쇼핑몰, DB Table 36EA 기준 Note 값의 성격에 따라 setter , getter , setFilter , getFilter , selector를 적절히 조합함으로써, 다양한 조건에 대응하는 컬럼 구성을 할 수 있습니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"selector 를 사용한 경우","url":"advanced/column-value-flow.html#selector-를-사용한-경우","text":"selector 를 사용한 경우 selector 는 DOM 요소와 직접 연결하여 값을 가져오거나 설정합니다. html < div id = \"idx\" > < p style = \"color:red;\" > 10 </ p > </ div > < input id = \"title\" type = \"text\" value = \"AA\" /> < input id = \"chk_yn\" type = \"checkbox\" checked /> < a href = \"http://google.com\" > google.com </ a > js var bm = new BindModel (); bm. addSelector ( 'aa' , { key : '#idx' , type : 'html' }); bm. addSelector ( 'bb' , { key : '#idx' , type : 'text' }); bm. addSelector ( 'cc' , { key : 'title' , type : 'value' }); bm. addSelector ( 'dd' , { key : '#chk_yn' , type : 'prop.checked' }); bm. addSelector ( 'ee' , { key : 'a' , type : 'attr.href' }); bm. addSelector ( 'ff' , { key : 'p' , type : 'css.color' }); // bb.columns['aa'].value == '<p style=\"color:red;\">10</p>' // bb.columns['bb'].value == '10' // bb.columns['cc'].value == 'AA' // bb.columns['dd'].value == true // bb.columns['ee'].value == 'http://google.com' // bb.columns['ff'].value == 'red' 셀렉터에 문자열 키를 지정하면, 해당 DOM 요소를 검사하여 value , text , html 중 적절한 타입이 자동으로 지정됩니다. Tip selector 지정한 값이 여러개 존재하면, 첫번째 값을 가져오거나, 설정합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"setter, getter 을 사용한 경우","url":"advanced/column-value-flow.html#setter-getter-을-사용한-경우","text":"setter, getter 을 사용한 경우 외부 변수와 컬럼을 연동할 때 사용합니다. js const bm = new BindModel (); let page_size = 10 ; bm. addColumnValue ( 'aa' , { getter : function ( ) { return page_size }, setter : function ( nVal ) { page_size = nVal } }); // bm.columns['aa'].value === 10 Tip 단방향으로 외부값을 읽기전용으로 사용할려면 getter 함수만 정의합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"selector, setter, getter 를 조합한 경우","url":"advanced/column-value-flow.html#selector-setter-getter-를-조합한-경우","text":"selector, setter, getter 를 조합한 경우 HTML 요소와 외부 변수를 동시에 제어합니다. html < select id = \"page_size\" > < option value = \"10\" > 10EA </ option > < option value = \"20\" > 20EA </ option > < option value = \"30\" > 30EA </ option > </ select > js const bm = new BindModel (); let page_size = 10 ; bm. addColumnValue ( 'aa' , { getter : function ( ) { return page_size }, setter : function ( nVal ) { page_size = nVal }, selector : { key : '#page_size' , type : 'value' } }); // bm.columns['aa'].value === 10 // jQuery를 이용하여 DOM 값 변경 $( \"#page_size\" ). val ( \"20\" ); // bm.columns['aa'].value === 20 // 컬럼 value 값 변경 bm. columns [ 'aa' ]. value = 30 ; // bm.columns['aa'].value === 30 // page_size === 30 // $(\"#page_size\").val() == '30' 값을 가져올 때는 우선순우가 높은 getter 을 호출하여 값을 가져옵니다. 값을 설정할 때는 setter 와 selector 두곳에 값을 설정합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"setFilter, getFilter 을 사용한 경우","url":"advanced/column-value-flow.html#setfilter-getfilter-을-사용한-경우","text":"setFilter, getFilter 을 사용한 경우 컬럼 값이 여러 요소와 연관되어 있을 경우에는 setFilter 와 getFilter 를 사용하여 값을 변환하거나 가공할 수 있습니다. html < input type = \"radio\" name = \"gender\" value = \"woman\" /> < input type = \"radio\" name = \"gender\" value = \"man\" /> js const bm = new BindModel (); bm. addColumnValue ( 'aa' , { getFilter : function ( ) { return $( 'input[name=gender]:checked' ). val (); }, setFilter : function ( nVal ) { $( 'input[name=gender][value=' + newVal + ']' ). prop ( 'checked' , true ); } }); // bm.columns['aa'].value == '' $( 'input[name=gender][value=man]' ). prop ( 'checked' , true ); // radio choice // bm.columns['aa'].value == 'man' 내부 값과 표시 값이 다를 경우, getFilter 와 setFilter 를 사용해 숫자를 통화 형식 등으로 변환할 수 있습니다. html < p id = \"sum\" > </ p > js const bm = new BindModel (); bm. columns . addValue ( 'price' , { setFilter : ( val ) => { const formatted = Number (val). toLocaleString (); $( \"#sum\" ). text (formatted); }, getFilter : () => { return parseInt ($( \"#sum\" ). text (). replace ( /,/g , \"\" )); } }); // 값 설정 및 표시 bm. columns [ 'price' ]. value = 10000 ; // DOM 값 확인 console . log ($( \"#sum\" ). text ()); // \"10,000\" // 값 조회 console . log (bm. columns [ 'price' ]. value ); // 10000 내부적으로는 10000 값으로 저장되고, 화면에는 콤마가 포함된 10,000 으로 표시됩니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"selector 객체","url":"advanced/column-value-flow.html#selector-객체","text":"selector 객체 selector 객체는 컬럼값을 DOM 요소의 값을 참조하여 설정하거나 가져오는 데 사용됩니다. 이 객체를 사용하면 HTML 요소와 모델 간의 데이터를 동기화할 수 있습니다. type 설명 비고 'value' | 'val' DOM 요소의 value 값을 가르킵니다. 'val' 은 축약어 'text' 지정한 위치의 text 값을 가르킵니다. 태그 제외 'html' 지정한 위치의 html 태그값을 가르킵니다. 'attr.*' HTML 속성명의 값을 가르킵니다. 예> 'attr.value', 'attr.type' 'prop.*' DOM 객체의 속성명의 값을 가르킵니다. 예> 'prop.checked' 'css.*' css 속성값을 가르킵니다 jquery(셀렉터).css(속성명) 사용 'none' 값을 사용하지 않습니다. 유효성 검사 등에서 활용"},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"value 타입","url":"advanced/column-value-flow.html#value-타입","text":"value 타입 DOM 요소의 value 값을 참조합니다. <input> 또는 <select> 요소에 주로 사용됩니다. html < input type = \"text\" id = \"user_name\" value = \"mike\" /> < select id = \"color_name\" > < option value = \"red\" selected > Red </ option > < option value = \"green\" > Blue </ option > < option value = \"blue\" > Green </ option > </ select > 컬럼 등록시 설정할 경우 js bm. addSelector ( 'aa' , { key : '#user_name' , type : 'value' }); bm. addSelector ( 'bb' , { key : '#color_name' , type : 'value' }); // bm.columns['aa'].value = 'Mike' // bm.columns['bb'].value = 'red' 기존 컬럼에 설정할 경우 js bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' ); bm. columns [ 'aa' ]. selector = { key : '#user_name' , type : 'value' }; bm. columns [ 'bb' ]. selector = { key : '#color_name' , type : 'value' }; // bm.columns['aa'].value = 'Mike' // bm.columns['bb'].value = 'red' Tip jQuery(셀렉터).val()과 동일한 결과를 반환합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"text 타입","url":"advanced/column-value-flow.html#text-타입","text":"text 타입 태그를 제외한 순수 텍스트를 가져오거나 설정합니다. html < div id = 'area_name' > < p id = 'user_name' > mike </ p > < p id = 'user_no' > 1000 </ p > </ div > 컬럼 등록시 설정할 경우 js bm. addSelector ( 'aa' , { key : '#user_name' , type : 'text' }); bm. addSelector ( 'bb' , { key : '#user_no' , type : 'text' }); // bm.columns['aa'].value = 'mike' // bm.columns['bb'].value = 'mike1000' 기존 컬럼에 설정할 경우 js bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' ); bm. columns [ 'aa' ]. selector = { key : '#user_name' , type : 'text' }; bm. columns [ 'bb' ]. selector = { key : '#user_no' , type : 'text' }; // bm.columns['aa'].value = 'mike' // bm.columns['bb'].value = 'mike1000' Tip jQuery(셀렉터).text()와 동일한 결과를 반환합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"html 타입","url":"advanced/column-value-flow.html#html-타입","text":"html 타입 HTML 태그를 포함한 내용을 가져오거나 설정합니다. html < div id = \"content\" > < p style = \"color:red;\" > Hello </ p > </ div > 컬럼 등록시 설정할 경우 js bm. addSelector ( 'aa' , { key : '#content' , type : 'html' }); // bm.columns['aa'].value === '<p style=\"color:red;\">Hello</p>' 기존 컬럼에 설정할 경우 js bm. addColumn ( 'aa' ); bm. columns [ 'aa' ]. selector = { key : '#content' , type : 'html' }; // bm.columns['aa'].value === '<p style=\"color:red;\">Hello</p>' Tip jQuery(셀렉터).html()과 동일한 결과를 반환합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"attr 타입","url":"advanced/column-value-flow.html#attr-타입","text":"attr 타입 HTML 속성 값을 참조합니다. html < input id = \"user_name\" type = \"text\" flag = \"OK\" /> js bm. addSelector ( 'aa' , { key : '#user_name' , type : 'attr.flag' }); // bm.columns['aa'].value === 'OK' Tip jQuery(셀렉터).attr(속성명)과 동일한 결과를 반환합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"prop 타입","url":"advanced/column-value-flow.html#prop-타입","text":"prop 타입 DOM 객체의 속성 값을 참조합니다. html < input id = 'agree' type = \"checkbox\" class = \"item\" value = \"Y\" /> js bm. addSelector ( 'aa' , { key : '#agree' , type : 'prop.checked' }); // bm.columns['aa'].value === false $( '#agree' ). prop ( 'checked' , true ); // checkbox choice // bm.columns['aa'].value === true Tip jQuery(셀렉터).prop(속성명)과 동일한 결과를 반환합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"css 타입","url":"advanced/column-value-flow.html#css-타입","text":"css 타입 CSS 속성 값을 참조합니다. html < div id = \"title\" style = \"color: black; padding: 10px;\" > Text Content </ div > js bm. addSelector ( 'aa' , { key : '#title' , type : 'css.color' }); bm. addSelector ( 'bb' , { key : '#title' , type : 'css.padding' }); // bm.columns['aa'].value === 'black' // bm.columns['bb'].value === '10px' Tip jQuery(셀렉터).css(속성명) 을 사용한 결과와 동일합니다."},{"title":"컬럼값 호출 구조","group":"고급 기능","section":"none 타입","url":"advanced/column-value-flow.html#none-타입","text":"none 타입 type을 'none'으로 설정하면 값을 사용하지 않습니다. 유효성 검사와 같은 검증 작업에 활용됩니다. html < input id = \"memo\" type = \"text\" value = \"Not Used\" /> js bm. addSelector ( 'aa' , { key : '#memo' , type : 'none' }); // bm.columns['aa'].value === undefined Tip 값 조작 및 검증 none 타입은 UI 값이 아닌 상태만 검증하거나 이벤트 트리거에 활용할 수 있습니다. DOM 동기화 value, text, html 타입은 데이터와 UI 동기화를 쉽게 관리할 수 있습니다. 속성 및 스타일 제어 attr, prop, css 타입은 DOM 속성과 스타일을 효과적으로 제어합니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 JSON 스키마 가이드 다음 문서 테이블 관리"},{"title":"테이블 관리","group":"고급 기능","section":"테이블 관리","url":"advanced/tables.html","text":"문서 고급 기능 고급 기능 03 테이블 관리 복수의 테이블로 데이터를 나누고 기본 테이블을 설정합니다. 한국어 문서 약 16분 모델(BindModel)은 기본적으로 first 속성의 기본 테이블 (MetaTable)을 제공합니다. js bm. first === bm. _tables [ 'first' ] === bm. _tables [ 0 ]; first 속성은 _tables['first'] 의 참조값입니다. 추가 테이블은 _tables 컬렉션에 저장되며, 테이블 이름 이 BindModel 객체에 속성으로 추가됩니다. js const bm = new BindModel (); // 테이블 추가 bm. addTable ( 'second' ); bm. addTable ( 'third' ); // bm._tables['second'] === bm.second // bm._tables['third'] === bm.third"},{"title":"테이블 관리","group":"고급 기능","section":"테이블 추가하기","url":"advanced/tables.html#테이블-추가하기","text":"테이블 추가하기 테이블을 추가하면 컬럼명 중복 문제를 해결 하고 데이터를 논리적으로 분리 할 수 있습니다. ts declare function addTable ( tableName : string , isBaseTable ?: boolean ): MetaTable ; isBaseTable 을 true 로 지정하면, 해당 테이블이 기본 테이블( _baseTable )로 설정됩니다. addTable() 메소드를 사용하여 새로운 테이블을 추가합니다. 추가된 테이블은 _tables 컬렉션에 등록되며, 해당 테이블은 BindModel 객체의 속성으로 자동 추가되어 사용할 수 있습니다. js const bm = new BindModel (); // 'second' 및 'three' 테이블 추가 bm. addTable ( 'second' ); bm. addTable ( 'three' ); // bm.second === _tables['second'] === _tables[1] // bm.three === _tables['three'] === _tables[2] Tip 테이블 이름은 모델(BindModel)의 키값 과 중복되지 않아야 합니다. 예약어 목록 : _tables, _baseTable, _columnType, items, fn, command, cmd, columns, '$service', 'baseConfig', 'url', '_guid', '_type', '$event', '$KEYWORD'"},{"title":"테이블 관리","group":"고급 기능","section":"컬럼 중복 문제 해결","url":"advanced/tables.html#컬럼-중복-문제-해결","text":"컬럼 중복 문제 해결 서버 데이터에서 동일한 컬럼명이 여러 번 등장할 경우, 다른 테이블에 분리 하여 관리할 수 있습니다. js bm. addTable ( 'second' ); bm. addTable ( 'three' ); bm. second . columns . add ( 'age' ); // 'second' 테이블에 'age' 컬럼 추가 bm. three . columns . add ( 'age' ); // 'three' 테이블에 'age' 컬럼 추가 Tip 전송하거나 수신하는 데이터의 이름이 중복될 경우, 컬럼 별칭(alias)을 통해 충돌을 피할 수 있습니다."},{"title":"테이블 관리","group":"고급 기능","section":"기본 테이블 변경","url":"advanced/tables.html#기본-테이블-변경","text":"기본 테이블 변경 _baseTable 은 모델(BindModel)의 기본 테이블 을 가리킵니다. 기본 테이블은 컬럼(HTMLColumn)이나 명령(BindCommand)을 추가할 때, 특정 테이블이 지정되지 않으면 자동으로 선택되는 테이블 입니다. columns 속성은 기본 테이블의 컬럼 컬렉션을 참조합니다. js bm. _baseTable === bm. _tables [ 'first' ] === bm. first ; bm. columns === bm. _baseTable . columns ; addTable() 메서드로 테이블을 추가할 때, 매개변수를 지정하여 해당 테이블을 기본 테이블로 설정할 수 있습니다. js const bm = new BindModel (); bm. addTable ( 'second' , true ); // bm._baseTable === bm.second // bm.columns === bm.second.columns === bm._baseTable.columns _baseTable 값을 변경하면 columns 참조도 변경 됩니다. _baseTable 속성을 설정하면 기본 테이블을 변경할 수 있습니다. js const bm = new BindModel (); bm. addTable ( 'second' , true ); // 기본 테이블 변경 bm. _baseTable = bm. second ; // bm._baseTable === bm.second // bm.columns === bm.second.columns === bm._baseTable.columns"},{"title":"테이블 관리","group":"고급 기능","section":"명령에 기본 테이블 설정","url":"advanced/tables.html#명령에-기본-테이블-설정","text":"명령에 기본 테이블 설정 명령(BindCommand)을 추가할 때, 특정 테이블을 명령의 기본 테이블로 지정 할 수 있습니다. 이 기본 테이블은 해당 명령 내에서 컬럼을 추가하거나 참조할 때 사용됩니다. Note 모델(BindModel)과 명령(BindCommand) 객체는 각각 _baseTable 속성을 가지고 있습니다. BindModel의 _baseTable은 공통 컬럼 등록 및 명령의 기본 테이블 로 사용되며, BindCommand의 _baseTable 은 해당 명령 전용의 기본 테이블 로 사용됩니다. js bm. addCommand ( 'cmd1' , 'SEND' , 'second' ); // bm.command['cmd1']._baseTable === bm.second 명령(BindCommand)에서 컬럼을 추가하면 _baseTable 로 지정된 테이블에 추가됩니다. Tip 명령(BindCommand) 추가할 때 기본테이블이 생략되면, 모델의 기본테이블이 기본값으로 설정됩니다. js const bm = new BindModel (); bm. addTable ( 'second' ); // 'second' 테이블 추가 bm. addCommand ( 'create' , 'VIEW' , 'second' ); // 명령 추가 // 컬럼 추가 bm. command [ 'create' ]. addColumn ( 'age' ); // 'second' 테이블에 'age' 컬럼 생성 bm. command [ 'create' ]. addColumn ( 'tel' ); // 'second' 테이블에 'tel' 컬럼 생성 명령(BindCommand)의 _baseTable 을 변경하면, 이후 생성하는 컬럼은 변경된 기본 테이블 을 기준으로 추가됩니다. js const bm = new BindModel (); bm. addTable ( 'second' ); // 'second' 테이블 추가 bm. addCommand ( 'create' ); // 명령 추가 // 컬럼 추가 bm. command [ 'create' ]. addColumn ( 'age' ); // 'first' 테이블에 'age' 컬럼 생성 // 명령의 기본 테이블 변경 bm. command [ 'create' ]. _baseTable = 'second' ; // 컬럼 추가 bm. command [ 'create' ]. addColumn ( 'tel' ); // 'second' 테이블에 'tel' 컬럼 생성"},{"title":"테이블 관리","group":"고급 기능","section":"테이블 컬럼 추가 및 매핑","url":"advanced/tables.html#테이블-컬럼-추가-및-매핑","text":"테이블 컬럼 추가 및 매핑 Tip 컬럼명 이름 규칙 : [테이블명 . ]컬럼명 테이블명이 생략 되면 기본테이블에 등록됩니다."},{"title":"테이블 관리","group":"고급 기능","section":"컬럼 추가하기","url":"advanced/tables.html#컬럼-추가하기","text":"컬럼 추가하기 기본 테이블에 추가 기본테이블에 컬럼을 추가합니다. js bm. addColumn ( 'aa' ); bm. addColumnValue ( 'bb' , 10 ); bm. addSelector ( 'cc' , '#tel' ); // bm.first.columns['aa'] instanceof MetaColumn : true // bm.first.columns['bb'] instanceof MetaColumn : true // bm.first.columns['cc'] instanceof MetaColumn : true 지정한 테이블에 추가 지정한 테이블에 컬럼을 추가합니다. js // 'second' 테이블에 컬럼 추가 bm. addColumn ( 'aa' , null , null , 'second' ); bm. addColumn ( 'bb' , null , null , bm. second ); 컬럼을 추가하면서 초기값을 설정합니다. js bm. addColumnValue ( 'cc' , 10 , null , null , 'second' ); bm. addColumnValue ( 'dd' , 'B' , null , null , bm. second ); // bm.second.columns.count == 2 // bm.second.columns['cc'].value == 10 // bm.second.columns['dd'].value == 'B' 컬럼을 추가하면서 셀렉터 값을 설정합니다. js bm. addSelector ( 'cc' , '#age' , null , null , 'second' ); bm. addSelector ( 'dd' , '#tel' , null , null , bm. second ); // bm.second.columns.count == 2 추가된 테이블의 컬렉션을 직접 사용하여 컬럼을 추가할 수도 있습니다. js bm. second . columns . add ( 'aa' ); bm. second . columns . addValue ( 'bb' , 10 ); // bm.second.columns.count == 2 // bm.second.columns['aa'].value == null // bm.second.columns['bb'].value == 10"},{"title":"테이블 관리","group":"고급 기능","section":"컬럼 추가 및 매핑하기","url":"advanced/tables.html#컬럼-추가-및-매핑하기","text":"컬럼 추가 및 매핑하기 빈 컬럼 추가 특정 테이블에 컬럼을 추가하고, 명령(BindCommand)의 전체 뷰 (valid, bind, output, misc)에 매핑합니다. Tip 뷰를 생략하면 전체 뷰($all)에 매핑됩니다. js bm. addColumn ( 'aa' , 'cmd1' , '$all' , 'second' ); // bm['second'].columns.count == 1 ('aa') // bm.command['cmd1'].valid.columns.count == 1 ('aa') // bm.command['cmd1'].bind.columns.count == 1 ('aa') // bm.command['cmd1'].output.columns.count == 1 ('aa') 특정 명령과 뷰(MetaView)에 매핑합니다. js bm. addColumn ( 'bb' , [ 'cmd2' , 'cmd3' ], [ 'valid' , 'bind' ], 'second' ); // bm['second'].columns.count == 1 ('bb') // bm.command['cmd2'].valid.columns.count == 1 ('bb') // bm.command['cmd2'].bind.columns.count == 1 ('bb') // bm.command['cmd2'].output.columns.count == 0 // bm.command['cmd3'].valid.columns.count == 1 ('bb') // bm.command['cmd3'].bind.columns.count == 1 ('bb') // bm.command['cmd3'].output.columns.count == 0 모든 명령($all)과 특정 뷰(MetaView)에 매핑합니다. js // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); // 컬럼 추가 및 매핑 bm. addColumn ( 'cc' , '$all' , 'output' , 'second' ); // bm['second'].columns.count == 1 ('cc') // bm.command['cmd1'].output.columns.count == 2 ('cc') // bm.command['cmd2'].output.columns.count == 1 ('cc') '$all' 지시자는 모든 명령(BindCommand)객체가 선택됩니다. : cmd1, cmd2 초기값으로 컬럼 추가 특정한 테이블에 컬럼을 추가하면서 초기값을 설정하고, 명령(BindCommand)의 뷰(MetaView)에 매핑합니다. js const bm = new BindModel (); // 테이블 추가 bm. addTable ( 'second' ); // 초기값이 있는 컬럼 추가 및 매핑 bm. addColumnValue ( 'aa' , 10 , 'cmd1' , '$all' , 'second' ); // bm['second'].columns.count == 1 ('aa') // bm.second.columns['aa'].value == 10 // bm.command['cmd1'].valid.columns.count == 1 ('aa') // bm.command['cmd1'].bind.columns.count == 1 ('aa') // bm.command['cmd1'].output.columns.count == 1 ('aa') 특정한 테이블에 컬럼을 추가하면서 초기값을 설정하고, 선택된 명령(BindCommand)의 지정한 뷰(MetaView)에 매핑합니다. js const bm = new BindModel (); // 테이블 추가 bm. addTable ( 'second' ); // 초기값이 있는 컬럼 추가 및 매핑 bm. addColumnValue ( 'bb' , 'B' , [ 'cmd1' , 'cmd2' ], [ 'valid' , 'bind' ], 'second' ); // bm.second.columns.count == 1 ('bb') // bm.second.columns['bb'].value == 'B' // bm.command['cmd1'].valid.columns.count == 1 ('bb') // bm.command['cmd1'].bind.columns.count == 1 ('bb') // bm.command['cmd1'].output.columns.count == 0 // bm.command['cmd2'].valid.columns.count == 1 ('bb') // bm.command['cmd2'].bind.columns.count == 1 ('bb') // bm.command['cmd2'].output.columns.count == 0 컬럼을 추가할 때, 명령과 뷰를 함께 지정하여 등록할 수 있습니다. Tip addColumnValue() 메서드는 addColumn()에 초기값 설정 기능 이 추가된 메서드입니다."},{"title":"테이블 관리","group":"고급 기능","section":"명령에서 컬럼 추가하기","url":"advanced/tables.html#명령에서-컬럼-추가하기","text":"명령에서 컬럼 추가하기 명령(BindCommand)에서 컬럼을 추가하려면, 먼저 명령 과 특정 테이블 을 추가합니다. js const bm = new BindModel (); bm. addTable ( 'second' ); // 'second' 테이블 추가 bm. addCommand ( 'cmd1' ); // 'cmd1' 명령 추가 명령(BindCommand)에 특정 뷰(valid)와 테이블 을 지정하여 컬럼을 추가합니다. js bm. command [ 'cmd1' ]. addColumn ( 'aa' , 'valid' , bm. second ); // bm['second'].columns.count == 1 ('aa') // bm.command['cmd1'].valid.columns.count == 1 ('aa') // bm.command['cmd1'].bind.columns.count == 0 // bm.command['cmd1'].output.columns.count == 0 명령(BindCommand)에 특정 뷰(bind, output)와 테이블 을 지정하여 컬럼을 추가합니다. js bm. command [ 'cmd1' ]. addColumn ( 'bb' , [ 'bind' , 'output' ], 'second' ); // bm.command['cmd1'].valid.columns.count == 0 // bm.command['cmd1'].bind.columns.count == 1 ('bb') // bm.command['cmd1'].output.columns.count == 1 ('bb') 명령(BindCommand)에 모든 뷰(valid, bind, output)와 테이블 을 지정하여 컬럼을 추가합니다. js bm. command [ 'cmd1' ]. addColumn ( 'cc' , '$all' , 'second' ); // bm.command['cmd1'].valid.columns.count == 2 ('cc') // bm.command['cmd1'].bind.columns.count == 2 ('cc') // bm.command['cmd1'].output.columns.count == 2 ('cc')"},{"title":"테이블 관리","group":"고급 기능","section":"기존 컬럼 등록하기","url":"advanced/tables.html#기존-컬럼-등록하기","text":"기존 컬럼 등록하기 모델(BindModel) 객체에 테이블과 기본 컬럼을 추가하고, 명령(BindCommand) 객체의 특정 뷰(MetaView)에 컬럼을 참조로 등록합니다. 모델을 생성하고 테이블과 컬럼을 생성하는 예제입니다. js const bm = new BindModel (); // 'second' 테이블 추가 bm. addTable ( 'second' ); // 기본 테이블에 컬럼 추가 bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' ); // 'second' 테이블에 컬럼 추가 bm. second . columns . add ( 'cc' ); bm. second . columns . add ( 'dd' ); // bm.first.columms.count == 2 ('aa', 'bb') // bm.second.columms.count == 2 ('cc', 'dd') 'aa', 'bb' 컬럼은 기본테이블에 추가됩니다. 'cc', 'dd' 컬럼은 'second' 테이블에 추가됩니다. 명령을 추가하고 지정한 뷰(valid)에 기본테이블(first)의 컬럼을 설정하는 예제입니다. js bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. setColumn ( 'aa' , 'valid' ); // bm.command['cmd1'].valid.columns.count == 1 ('aa') // bm.command['cmd1'].bind.columns.count == 0 // bm.command['cmd1'].output.columns.count == 0 명령을 추가하고 지정한 뷰(bind)에 기본테이블(first)과 추가테이블(second)의 컬럼을 설정하는 예제입니다. js bm. addCommand ( 'cmd2' ); bm. command [ 'cmd2' ]. setColumn ([ 'bb' , 'second.cc' ], 'bind' ); // bm.command['cmd2'].valid.columns.count == 0 // bm.command['cmd2'].bind.columns.count == 2 ('bb', 'dd') // bm.command['cmd2'].output.columns.count == 0 명령을 추가하고 전체 뷰(valid, bind, output, misc)에 추가테이블(second)의 컬럼을 설정하는 예제입니다. js bm. addCommand ( 'cmd3' ); bm. command [ 'cmd3' ]. setColumn ( 'second.dd' , '$all' ); // bm.command['cmd3'].valid.columns.count == 1 ('dd') // bm.command['cmd3'].bind.columns.count == 1 ('dd') // bm.command['cmd3'].output.columns.count == 1 ('dd') 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 컬럼값 호출 구조 다음 문서 명령 복수 출력 구성"},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"명령 복수 출력 구성","url":"advanced/multiple-outputs.html","text":"문서 고급 기능 고급 기능 03 명령 복수 출력 구성 하나의 명령에서 여러 출력 뷰를 구성하고 응답을 처리합니다. 한국어 문서 약 13분 서버에서 다중 엔티티(테이블) 데이터를 응답받을 경우, 명령(BindCommand) 객체에서 복수의 출력 뷰(MetaView)를 구성하여 데이터를 처리할 수 있습니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"_outputs 컬렉션의 구조","url":"advanced/multiple-outputs.html#_outputs-컬렉션의-구조","text":"_outputs 컬렉션의 구조 명령(BindCommand) 객체는 _outputs 컬렉션을 통해 여러 출력 뷰(MetaView)를 관리합니다. 기본 출력 뷰는 output 속성을 통해 접근할 수 있으며, 이는 _outputs['output1'] 를 참조합니다. 추가 출력 뷰는 newOutput() 메서드를 통해 생성되며, _outputs 컬렉션에 등록됩니다. classDiagram BindCommand o--> MetaView : valid BindCommand o--> MetaView : bind BindCommand o--> MetaView : output == _outputs['output1'] BindCommand *--> MetaViewCollection : _outputs MetaViewCollection ..> MetaView : outputs1 class BindCommand { - _outputs: MetaViewCollection + outputOption + valid: MetaView + bind: MetaView + output = _outputs['output1'] + newOutput(outputName) + removeOutput(outputName) } class MetaViewCollection { + output1: MetaView + .... } class MetaView { } 구조와 흐름을 설명하는 다이어그램"},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"출력 뷰(MetaView) 추가","url":"advanced/multiple-outputs.html#출력-뷰metaview-추가","text":"출력 뷰(MetaView) 추가 newOutput() 메서드를 사용하여 명령(BindCommand) 객체에 출력 뷰를 추가할 수 있습니다. ts declare function newOutput ( outputName ?: string ): void ; outputName : 새롭게 추가할 출력 뷰의 이름입니다. 이름을 지정하지 않은 경우, 기본 이름 규칙 ('output' + 숫자) 에 따라 출력 뷰가 자동으로 추가됩니다. Tip 명령(BindCommand) 객체에는 output 과 output1 속성이 기본으로 제공되며, 두 속성은 동일한 값을 참조합니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"기본 출력 뷰 추가","url":"advanced/multiple-outputs.html#기본-출력-뷰-추가","text":"기본 출력 뷰 추가 아무 이름도 지정하지 않을 경우, 기본 이름 규칙( 'output' + number )에 따라 출력 뷰가 추가됩니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 출력 뷰 추가 bm. cmd [ 'cmd1' ]. newOutput (); // bm.command['cmd1'].output2 instanceof MetaView // bm.command['cmd1'].output2 === bm.command['cmd1']._outputs['output2'] Tip 기본 출력 뷰 이름은 output2 , output3 , … 순으로 자동 생성됩니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"사용자 지정 출력 뷰 추가","url":"advanced/multiple-outputs.html#사용자-지정-출력-뷰-추가","text":"사용자 지정 출력 뷰 추가 사용자 정의 이름을 사용하면 기본 출력 뷰와 사용자 정의 이름으로 출력 뷰가 추가됩니다. js bm. cmd [ 'cmd1' ]. newOutput ( 'three' ); // bm.command['cmd1'].output3 instanceof MetaView // bm.command['cmd1'].three instanceof MetaView // bm.command['cmd1'].output3 === bm.command['cmd1'].three Tip 출력 뷰 이름이 명령(BindCommand)의 키값 과 중복되지 않아야 합니다. 예약어 목록 : config, url, _outputs, _model, _baseTable, valid, bind, output, output1, misc, outputOption, outOpt, cbBind, cbValid, cbBind, cbResult, cbOutput, cbEnd, _guid, _type"},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"출력 뷰(MetaView) 제거","url":"advanced/multiple-outputs.html#출력-뷰metaview-제거","text":"출력 뷰(MetaView) 제거 명령(BindCommand) 객체에서 추가한 출력 뷰(MetaView)를 제거할 수 있습니다. ts declare function removeOutput ( outputName : string ): void ; outputName : 제거할 출력 뷰(MetaView)의 이름입니다. 출력 뷰를 제거할 때, 기본적으로 생성된 'output' + 숫자 형식 의 자동 속성명도 함께 제거됩니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // bm.cmd['cmd1']._outputs.count == 1 // 기본 출력 뷰 생성 bm. cmd [ 'cmd1' ]. newOutput (); // output2 생성 // bm.cmd['cmd1']._outputs.count == 2 // 제거 bm. cmd [ 'cmd1' ]. removeOutput ( 'output2' ); // bm.cmd['cmd1']._outputs.count == 1 사용자 정의 이름을 사용해 추가한 출력 뷰를 제거합니다. js bm. cmd [ 'cmd1' ]. newOutput ( 'three' ); // bm.cmd['cmd1']._outputs.count == 2 // bm.command['cmd1'].output2 == MetaView // bm.command['cmd1'].three == MetaView // Remove bm. cmd [ 'cmd1' ]. removeOutput ( 'three' ); // bm.cmd['cmd1']._outputs.count == 1 Tip 기본 뷰인 output 또는 output1 속성은 제거할 수 없습니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"출력 뷰 가져오기","url":"advanced/multiple-outputs.html#출력-뷰-가져오기","text":"출력 뷰 가져오기 서버 응답 데이터가 여러 엔티티로 구성된 경우, 출력 뷰(MetaView)를 활용하여 데이터를 가져올 수 있습니다. 출력 옵션(opt)에 따라 데이터 처리 방식이 달라집니다. json // SERVER DATA [ { \"rows\" : [ { \"aa\" : 10 , \"bb\" , 20 , \"cc\" : 30 } , { \"aa\" : 11 , \"bb\" , 21 , \"cc\" : 31 } ] } , { \"rows\" : [ { \"dd\" : 40 , \"ee\" , 50 } ] } ] Tip 서버 응답 형식이 다를 경우, cbResult 및 cbBaseResult 콜백을 사용하여 데이터를 변환할 수 있습니다. 서버 응답 데이터가 다수의 엔티티로 구성되어 있을 경우, 출력 뷰(MetaView)는 생성된 출력 뷰의 개수만큼 데이터를 가져옵니다. 참조 : 흐름 제어 > 응답 처리 콜백 , JSON 스키마 가이드 > ENTITY 모드"},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"모든 데이터 가져오기 (outOpt = 'ALL')","url":"advanced/multiple-outputs.html#모든-데이터-가져오기-outopt-all","text":"모든 데이터 가져오기 (outOpt = 'ALL') 서버의 모든 데이터를 출력 뷰(MetaView)에 매핑합니다. js const bm = new BindModel (); // 출력 옵션 'ALL'으로 명령 추가 bm. addCommand ( 'cmd1' , 'ALL' ); // 'output2' 추가 bm. cmd [ 'cmd1' ]. newOutput (); // 명령 실행 bm. cmd [ 'cmd1' ]. execute (); // bm.columns.count == 5 // bm.columns['cmd1'].output.rows[0]['aa'] == 10 // bm.columns['cmd1'].output.rows[0]['bb'] == 20 // bm.columns['cmd1'].output.rows[0]['cc'] == 30 // bm.columns['cmd1'].output.rows[1]['aa'] == 11 // bm.columns['cmd1'].output.rows[1]['bb'] == 21 // bm.columns['cmd1'].output.rows[1]['cc'] == 31 // bm.columns['cmd1'].output2.rows[0]['dd'] == 40 // bm.columns['cmd1'].output2.rows[0]['ee'] == 50 모든 데이터를 출력 뷰에 가져옵니다. Tip 서버 데이터를 가져올 때, 출력 뷰(MetaView)에 미리 컬럼 정의가 되어 있다면, 해당 정의를 그대로 사용합니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"지정 데이터 가져오기 (outOpt ='PICK')","url":"advanced/multiple-outputs.html#지정-데이터-가져오기-outopt-pick","text":"지정 데이터 가져오기 (outOpt ='PICK') 서버에서 지정한 컬럼명을 가져와 출력 뷰에 매핑합니다. js const bm = new BindModel (); // 출력 옵션 'PICK'으로 명령 추가 bm. addCommand ( 'cmd1' , 'PICK' ); // 'output2' 추가 bm. cmd [ 'cmd1' ]. newOutput (); // 컬럼 추가 및 출력 뷰에 매핑 bm. cmd [ 'cmd1' ]. addColumn ( 'aa' , 'output' ); bm. cmd [ 'cmd1' ]. addColumn ( 'bb' , 'output' ); bm. cmd [ 'cmd1' ]. addColumn ( 'dd' , 'output2' ); bm. cmd [ 'cmd1' ]. addColumn ( 'ee' , 'output2' ); bm. cmd [ 'cmd1' ]. execute (); // bm.columns.count == 4 ('aa', 'bb', 'dd', 'ee') // bm.columns['cmd1'].output.rows[0]['aa'] == 10 // bm.columns['cmd1'].output.rows[0]['bb'] == 20 // bm.columns['cmd1'].output.rows[1]['aa'] == 11 // bm.columns['cmd1'].output.rows[1]['bb'] == 21 // bm.columns['cmd1'].output2.rows[0]['dd'] == 40 // bm.columns['cmd1'].output2.rows[0]['ee'] == 50 지정된 컬럼명만 출력 뷰에 매핑 합니다. 각 출력 뷰의 컬럼 개수는 지정된 컬럼으로 제한됩니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"지정 데이터 가져와서 컬럼 설정 (outOpt ='VIEW')","url":"advanced/multiple-outputs.html#지정-데이터-가져와서-컬럼-설정-outopt-view","text":"지정 데이터 가져와서 컬럼 설정 (outOpt ='VIEW') 서버에서 지정한 컬럼 데이터를 출력 뷰에 매핑하고, index 위치의 rows 데이터를 컬럼값으로 설정합니다. js const bm = new BindModel (); // 출력 옵션 'VIEW'으로 명령 추가 bm. addCommand ( 'cmd1' , 'VIEW' ); // 'output2' 추가 bm. cmd [ 'cmd1' ]. newOutput (); // 컬럼 추가 및 출력 뷰에 매핑 bm. cmd [ 'cmd1' ]. addColumn ( 'aa' , 'output' ); bm. cmd [ 'cmd1' ]. addColumn ( 'bb' , 'output' ); bm. cmd [ 'cmd1' ]. addColumn ( 'dd' , 'output2' ); bm. cmd [ 'cmd1' ]. addColumn ( 'ee' , 'output2' ); bm. cmd [ 'cmd1' ]. execute (); // bm.columns.count == 4 ('aa', 'bb', 'dd', 'ee') // bm.columns['aa'].value == 10 // bm.columns['bb'].value == 20 // bm.columns['dd'].value == 40 // bm.columns['ee'].value == 50 1단계 : 지정된 컬럼 데이터를 출력 뷰에 매핑 합니다. 2단계 : index 위치의 rows 데이터 값을 컬럼의 값( value )으로 설정합니다. Tip outputOption.index 는 rows 에서 설정할 위치를 의미하며, 기본값은 0 입니다."},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"복수 출력 인덱스","url":"advanced/multiple-outputs.html#복수-출력-인덱스","text":"복수 출력 인덱스"},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"복수 출력 인덱스 설정하기","url":"advanced/multiple-outputs.html#복수-출력-인덱스-설정하기","text":"복수 출력 인덱스 설정하기 명령(BindCommand) 객체의 outputOption.index 속성을 사용하여 출력 데이터를 가져올 인덱스를 배열 또는 단일 숫자로 지정할 수 있습니다. Tip 인덱스 설정은 outputOption = 'VIEW' 인 경우에만 유효하며, 기본 인덱스 값은 0입니다. ts type OptionType = 'SEND' | 'VIEW' | 'ALL' | 'PICK' ; // default 'SEND' type SchemaType = 'AUTO' | 'DATA' | 'ENTITY' ; // default 'AUTO' type IndexType = number | number []; // // default 0 type OutOptType = { option : OptionType , schema : SchemaType , index : IndexType } type outputOption = OutOptType | OptionType | SchemaType | IndexType ; type outOpt = outputOption; // outputOption의 별칭 명령(BindCommand)의 index 값을 배열 또는 숫자로 지정합니다. js bm. command [ 'cmd1' ]. outputOption . index = [ 1 , 2 ]; bm. command [ 'cmd2' ]. outputOption . index = 1 ; bm. command [ 'cmd3' ]. outputOption = { index : [ 1 , 2 ] }; bm. command [ 'cmd4' ]. outOpt . index = [ 1 , 2 ]; 'cmd1' 은 첫 번째 엔티티 index = 1 , 두 번째 엔티티 index = 2 'cmd2' 은 모든 엔티티 index = 1 'cmd3' 은 첫 번째 엔티티 index = 1 , 두 번째 엔티티 index = 2 'cmd4' 은 첫 번째 엔티티 index = 1 , 두 번째 엔티티 index = 2"},{"title":"명령 복수 출력 구성","group":"고급 기능","section":"복수 출력 인덱스 가져오기","url":"advanced/multiple-outputs.html#복수-출력-인덱스-가져오기","text":"복수 출력 인덱스 가져오기 서버 응답 데이터가 여러 엔티티로 구성되어 있을 때, 각 엔티티에 대해 가져올 컬럼값 인덱스 를 지정할 수 있습니다. json // SERVER DATA [ { \"rows\" : [ { \"aa\" : 10 , \"bb\" , 20 , \"cc\" : 30 } , { \"aa\" : 11 , \"bb\" , 21 , \"cc\" : 31 } ] } , { \"rows\" : [ { \"dd\" : 40 , \"ee\" , 50 } , { \"dd\" : 41 , \"ee\" , 51 } , { \"dd\" : 42 , \"ee\" , 52 } ] } ] 복수 엔티티에 대해 index 는 배열로 지정합니다. Tip index 는 배열과 같이 0 부터 시작합니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' , 'VIEW' ); // 'output2' 추가 bm. cmd [ 'cmd1' ]. newOutput (); // 첫 번째 엔티티: index 1, 두 번째 엔티티: index 2 bm. cmd [ 'cmd1' ]. outputOption . index = [ 1 , 2 ]; // 컬럼 추가 및 출력 뷰 매핑 bm. cmd [ 'cmd1' ]. addColumn ( 'aa' , 'output' ); bm. cmd [ 'cmd1' ]. addColumn ( 'bb' , 'output' ); bm. cmd [ 'cmd1' ]. addColumn ( 'dd' , 'output2' ); bm. cmd [ 'cmd1' ]. addColumn ( 'ee' , 'output2' ); bm. cmd [ 'cmd1' ]. execute (); // bm.columns.count == 4 // bm.columns['aa'].value == 11 // bm.columns['bb'].value == 21 // bm.columns['dd'].value == 42 // bm.columns['ee'].value == 52 첫번째 엔티티에서 index = 1 의 rows 값을 가져옵니다. 두번째 엔티티에서 index = 2 의 rows 값을 가져옵니다. Tip 엔티티 개수보다 index 배열 길이가 작으면 , 부족한 인덱스는 기본값 0으로 설정됩니다. 엔티티 개수보다 index 배열 길이가 크면 , 초과된 값은 무시됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 테이블 관리 다음 문서 실행 및 동기화"},{"title":"실행 및 동기화","group":"고급 기능","section":"실행 및 동기화","url":"advanced/execution.html","text":"문서 고급 기능 고급 기능 03 실행 및 동기화 Promise와 async/await로 명령을 순차 또는 병렬 실행합니다. 한국어 문서 약 7분 BindCommand 객체의 execute() 메소드는 Promise 를 반환합니다. 이를 통해 async 및 await 키워드를 사용하여 비동기 작업을 동기적으로 처리할 수 있습니다. ts declare function execute ( ): Promise < void >; • 명령(BindCommand)는 비동기 적으로 작동합니다. • execute() 메소드는 서버 요청을 수행하며, 응답을 받을 때까지 기다릴 수 있습니다. • Promise 의 특성을 활용하여 체인 호출(then) 또는 async/await 문법으로 동기적인 흐름을 구현할 수 있습니다."},{"title":"실행 및 동기화","group":"고급 기능","section":"명령 실행 및 동기화","url":"advanced/execution.html#명령-실행-및-동기화","text":"명령 실행 및 동기화 BindCommand 객체의 execute() 메소드는 Promise 를 반환합니다. 이를 활용해 명령을 동기적 으로 실행하거나 병렬 로 실행할 수 있습니다. ts type OptionType = 'SEND' | 'VIEW' | 'ALL' | 'PICK' ; // default 'SEND' type SchemaType = 'AUTO' | 'DATA' | 'ENTITY' ; // default 'AUTO' type IndexType = number | number []; // // default 0 type OutOptType = { option : OptionType , schema : SchemaType , index : IndexType } declare function execute ( outputOption ?: OutOptType | OptionType | SchemaType | IndexType , config ?: object | string ): Promise < void >; declare const exec : typeof execute; outputOption : 출력 옵션 설정 { option: 'VIEW', schema: 'DATA', index: 0} 와 같은 객체 형태로 지정하거나, 'SEND' , 'VIEW' , 'ALL' , 'PICK' 문자열로 option 을 지정할 수 있습니다. config : axios 설정 객체 또는 요청 URL 객체로 지정하면 axios 의 설정 객체로 사용되며, 문자열로 지정하면 요청할 URL 경로로 처리됩니다. exec() 는 execute() 메소드의 별칭입니다. Tip execute() 실행 시 전달되는 outputOption 과 config 는 내부에 저장되지 않으며, 호출 시점에만 일회성으로 사용됩니다."},{"title":"실행 및 동기화","group":"고급 기능","section":"명령 실행시 옵션 지정","url":"advanced/execution.html#명령-실행시-옵션-지정","text":"명령 실행시 옵션 지정 execute() 실행시 outputOption 을 지정할 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. addCommand ( 'cmd3' ); bm. addCommand ( 'cmd4' ); bm. command [ 'cmd1' ]. execute ( 'VIEW' ); bm. command [ 'cmd2' ]. execute ( 'DATA' ); bm. command [ 'cmd3' ]. execute ({ option : 'PICK' , schema : 'ENTITY' }); bm. command [ 'cmd4' ]. execute ({}, '/user' ); cmd1 명령은 option = 'VIEW' 으로 실행합니다. cmd2 명령은 schema = 'DATA' 으로 실행합니다. cmd3 명령은 option = 'PICK', schema = 'ENTITY' 으로 실행합니다. cmd4 명령은 url 이 '/user' 으로 실행합니다."},{"title":"실행 및 동기화","group":"고급 기능","section":"독립된 함수로 정의","url":"advanced/execution.html#독립된-함수로-정의","text":"독립된 함수로 정의 async await 문을 사용하여 execute() 를 순차적으로 실행합니다. CJS 환경 js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); async function executeCommands ( ) { await bm. command [ 'cmd1' ]. execute (); console . log ( 'Command 1 executed.' ); await bm. command [ 'cmd2' ]. execute (); console . log ( 'Command 2 executed.' ); } // 호출 executeCommands (); ESM 환경 js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); await bm. command [ 'cmd1' ]. execute (); console . log ( 'Command 1 executed.' ); await bm. command [ 'cmd2' ]. execute (); console . log ( 'Command 2 executed.' ); 사용자 함수를 fn 에 추가할 수 있습니다. tip execute() 내부에 try 문으로 구성되어 있어서 오류발생시 cbError 콜백함수가 호출됩니다."},{"title":"실행 및 동기화","group":"고급 기능","section":"콜백함수를 이용한 동기화","url":"advanced/execution.html#콜백함수를-이용한-동기화","text":"콜백함수를 이용한 동기화 Promise 의 then 메소드를 사용해 동기적인 실행 흐름을 구현할 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. command [ 'cmd1' ]. execute () . then ( () => { console . log ( 'Command 1 executed.' ); return bm. command [ 'cmd2' ]. execute (); }) . then ( () => { console . log ( 'Command 2 executed.' ); }) . catch ( ( err ) => { console . error ( 'Error executing commands:' , err); });"},{"title":"실행 및 동기화","group":"고급 기능","section":"사용자 정의 함수에 추가","url":"advanced/execution.html#사용자-정의-함수에-추가","text":"사용자 정의 함수에 추가 fn 컬렉션에 사용자 정의 동기화 함수를 추가하여 재사용성을 높일 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. fn . add ( 'syncCommands' , async function ( ) { await bm. command [ 'cmd1' ]. execute (); await bm. command [ 'cmd2' ]. execute (); }); // 호출 bm. fn . syncCommands ();"},{"title":"실행 및 동기화","group":"고급 기능","section":"비동기 명령 동시 실행","url":"advanced/execution.html#비동기-명령-동시-실행","text":"비동기 명령 동시 실행 Promise.all 을 사용하여 여러 명령(BindCommand)을 동시에 실행할 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. addCommand ( 'cmd3' ); async function executeConcurrently ( ) { await Promise . all ([ bm. command [ 'cmd1' ]. execute (), bm. command [ 'cmd2' ]. execute () ]); console . log ( 'Command 1 and Command 2 executed concurrently.' ); await bm. command [ 'cmd3' ]. execute (); console . log ( 'Command 3 executed.' ); } // 호출 executeConcurrently (); 'cmd1', 'cmd2' 을 동시에 실행이 완료되면 'cmd3'이 실행됩니다. Tip Promise.all 은 하나라도 실패하면 전체가 실패하므로, 에러 처리를 위해 try/catch 를 사용하세요."},{"title":"실행 및 동기화","group":"고급 기능","section":"실행 에러 처리","url":"advanced/execution.html#실행-에러-처리","text":"실행 에러 처리 execute()는 내부적으로 try 문으로 보호되어 있어, 실패 시 cbError 콜백이 호출됩니다. 에러 처리는 catch 문에서 처리하거나 cbError 콜백을 활용합니다. 에러 처리는 기본 적으로 cbError 콜백 함수를 호출합니다. js bm. cbError = function ( msg ) { console . error ( 'Global error handler:' , msg); }; catch 문에서 처리하여 에러를 처리합니다. js bm. command [ 'cmd1' ]. execute () . catch ( ( err ) => { console . error ( 'Error:' , err); }); 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 명령 복수 출력 구성 다음 문서 이벤트 설정"},{"title":"이벤트 설정","group":"고급 기능","section":"이벤트 설정","url":"advanced/events.html","text":"문서 고급 기능 고급 기능 03 이벤트 설정 명령 실행, 데이터 변경, 컬렉션 변경 이벤트에 반응합니다. 한국어 문서 약 8분 모델(BindModel)은 실행 이벤트, 변경 이벤트, 컬렉션 이벤트 등 다양한 상황에서 이벤트를 설정할 수 있습니다."},{"title":"이벤트 설정","group":"고급 기능","section":"실행 이벤트","url":"advanced/events.html#실행-이벤트","text":"실행 이벤트 모델(BindModel)과 명령(BindCommand) 실행 전 후에 이벤트를 설정할 수 있습니다. ts type onExecute = ( bModel : BindModel , bCommand : BindCommand ) => void ; type onExecuted = ( bModel : BindModel , bCommand : BindCommand ) => void ; bModel : 대상의 모델(BindModel)객체 bCommand : 대상의 명령(BindCommand)객체"},{"title":"이벤트 설정","group":"고급 기능","section":"모델 실행 이벤트","url":"advanced/events.html#모델-실행-이벤트","text":"모델 실행 이벤트 모델(BindModel)에서 실행 전(onExecute)과 실행 후(onExecuted) 이벤트를 설정합니다. 이는 모든 명령에 적용됩니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. onExecute = function ( bModel, bCommand ) { console . log ( 'Model: Before execute' ); }; bm. onExecuted = function ( bModel, bCommand ) { console . log ( 'Model: After execute' ); }; bm. command [ 'cmd1' ]. execute (); // 출력: // Model: Before execute // Model: After execute"},{"title":"이벤트 설정","group":"고급 기능","section":"명령 실행 이벤트","url":"advanced/events.html#명령-실행-이벤트","text":"명령 실행 이벤트 특정 명령(BindCommand)에만 실행 전(onExecute)과 실행 후(onExecuted) 이벤트를 설정합니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. onExecute = function ( bModel, bCommand ) { console . log ( 'Command: Before execute' ); }; bm. command [ 'cmd1' ]. onExecuted = function ( bModel, bCommand ) { console . log ( 'Command: After execute' ); }; bm. command [ 'cmd1' ]. execute (); // 출력: // Command: Before execute // Command: After execute"},{"title":"이벤트 설정","group":"고급 기능","section":"변경 이벤트","url":"advanced/events.html#변경-이벤트","text":"변경 이벤트"},{"title":"이벤트 설정","group":"고급 기능","section":"컬럼 변경 이벤트","url":"advanced/events.html#컬럼-변경-이벤트","text":"컬럼 변경 이벤트 컬럼값이 변경된 후 이벤트가 발생합니다. ts type onChanged = ( nVal : ValueType , oVal : ValueType , _this : this ) => void ; nVal : 새로운 컬럼값 oVal : 이전 컬럼값 js const bm = new BindModel (); bm. columns . addValue ( 'aa' , 10 ); bm. columns [ 'aa' ]. onChanged = function ( nVal, oVal, _this ) { console . log ( `New Value: ${nVal} , Old Value: ${oVal} ` ); }; bm. columns [ 'aa' ]. value = 20 ; // 출력: // New Value: 20, Old Value: 10 Tip 뷰(MetaView)의 컬럼(HTMLColumn) 속성은 대부분 테이블(MetaTable)을 참조합니다. 따라서 컬럼 변경 이벤트를 설정할 때 테이블의 컬럼에 정의하는 것이 더욱 직관적이며 관리에 용이합니다."},{"title":"이벤트 설정","group":"고급 기능","section":"로우 데이터 변경 이벤트","url":"advanced/events.html#로우-데이터-변경-이벤트","text":"로우 데이터 변경 이벤트 테이블(MetaTable) 또는 뷰(MetaView)의 MetaRow 데이터 변경 시 발생합니다. ts type onChanging = ( idx : number , nVal : any , oVal : any , _this : this ) => void ; type onChanged = ( idx : number , nVal : any , oVal : any , _this : this ) => void ; idx : 변경된 데이터의 인덱스 nVal : 새로운 값 oVal : 이전 값 js const bm = new BindModel (); bm. addColumnValue ( 'aa' , 10 , 'cmd1' , 'valid' ); bm. addColumnValue ( 'bb' , 20 , 'cmd1' , 'valid' ); const v1 = bm. command [ 'cmd1' ]. valid ; v1. rows . add (v1. getRow ()); v1. rows [ 0 ]. onChanging = function ( idx, nVal, oVal, _this ) { console . log ( `Before Change - Index: ${idx} , New: ${nVal} , Old: ${oVal} ` ); }; v1. rows [ 0 ]. onChanged = function ( idx, nVal, oVal, _this ) { console . log ( `After Change - Index: ${idx} , New: ${nVal} , Old: ${oVal} ` ); }; v1. rows [ 0 ][ 'aa' ] = 11 ; // 출력: // Before Change - Index: 0, New: 11, Old: 10 // After Change - Index: 0, New: 11, Old: 10 Tip 로우(MetaRow)는 테이블(MetaTable)과 뷰(MetaView)에서 독립적으로 존재 합니다. 따라서 로우 이벤트는 해당 뷰(MetaView)의 row 에 정의하는 것이 더 직관적이고 효율적 입니다."},{"title":"이벤트 설정","group":"고급 기능","section":"컬렉션 이벤트","url":"advanced/events.html#컬렉션-이벤트","text":"컬렉션 이벤트 컬렉션 관련 작업 시 발생하는 공통 이벤트입니다. 다양한 컬렉션 작업(추가, 삭제, 초기화 등)에 대해 대응할 수 있습니다. 모델(BindModel)의 컬렉션 - _tables : 테이블 컬렉션 - columns : 기본 테이블( _baseTable )의 컬럼 컬렉션 - items : 공통 컬럼 속성 컬렉션 - command : 명령(BindCommand) 객체 컬렉션 - fn : 사용자 함수 컬렉션 명령(BindCommand)의 컬렉션 - _outputs : 출력 뷰(MetaView) 컬렉션 - valid.columns, valid,rows : 유효성 검사 뷰(MetaView)의 컬럼 및 로우 컬렉션 - bind.columns, bind.rows : 서버 요청 뷰(MetaView)의 컬럼 및 로우 컬렉션 - output.columns, output.rows : 서버 응답 기본 뷰(MetaView)의 컬럼 및 로우 컬렉션 - misc.columns, misc.rows : 기타 뷰(MetaView)의 컬럼 및 로우 컬렉션"},{"title":"이벤트 설정","group":"고급 기능","section":"컬렉션 추가 이벤트","url":"advanced/events.html#컬렉션-추가-이벤트","text":"컬렉션 추가 이벤트 컬렉션에 요소를 추가할 때 발생하는 이벤트 입니다. ts type onAdd = ( idx : number , elem : any , _this : object ) => void ; type onAdded = ( idx : number , elem : any , _this : object ) => void ; idx : 추가할 요소의 인덱스 elem : 추가할 요소 js const bm = new BindModel (); bm. columns . onAdd = function ( idx, elem, _this ) { console . log ( `before : idx = ${idx} , elem = ${elem._name} ` ); }; bm. columns . onAdded = function ( idx, elem, _this ) { console . log ( `after : idx = ${idx} , elem = ${elem._name} ` ); }; bm. addColumn ( 'aa' ); // before : idx = 0, elem = aa // after : idx = 0, elem = aa"},{"title":"이벤트 설정","group":"고급 기능","section":"컬렉션 삭제 이벤트","url":"advanced/events.html#컬렉션-삭제-이벤트","text":"컬렉션 삭제 이벤트 컬렉션에 요소를 삭제할 때 발생하는 이벤트 입니다. ts type onRemove = ( idx : number , elem : any , _this : object ) => void ; type onRemoved = ( idx : number , elem : any , _this : object ) => void ; idx : 삭제할 요소의 인덱스 elem : 삭제할 요소 js const bm = new BindModel (); bm. columns . onRemove = function ( idx, elem, _this ) { console . log ( `before : idx = ${idx} , elem = ${elem._name} ` ); }; bm. columns . onRemoved = function ( idx, elem, _this ) { console . log ( `after : idx = ${idx} , elem = ${elem._name} ` ); }; bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' ); bm. columns . remove ( 'bb' ); // before : idx = 0, elem = bb // after : idx = 0, elem = bb"},{"title":"이벤트 설정","group":"고급 기능","section":"컬렉션 초기화 이벤트","url":"advanced/events.html#컬렉션-초기화-이벤트","text":"컬렉션 초기화 이벤트 컬렉션을 초기화 할 때 발생하는 이벤트 입니다. ts type onClear = ( _this : object ) => {}; type onCleared = ( _this : object ) => {}; js const bm = new BindModel (); bm. columns . onClear = function ( _this ) { console . log ( `before : clear` ); }; bm. columns . onCleared = function ( _this ) { console . log ( `after : clear` ); }; bm. addColumn ( 'aa' ); bm. columns . clear (); // before : clear // after : clear 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 실행 및 동기화 다음 문서 객체 구성 방법"},{"title":"객체 구성 방법","group":"고급 기능","section":"객체 구성 방법","url":"advanced/composition.html","text":"문서 고급 기능 고급 기능 03 객체 구성 방법 서비스 객체, 모델, 명령을 활용한 구성 방법을 비교합니다. 한국어 문서 약 11분 모델(BindModel)은 사용자의 다양한 요구에 맞게 여러 가지 생성 방식을 제공합니다. 각 방식의 특징과 장단점을 이해하고, 요구사항에 적합한 방법을 선택하여 사용할 수 있습니다."},{"title":"객체 구성 방법","group":"고급 기능","section":"서비스객체로 구성","url":"advanced/composition.html#서비스객체로-구성","text":"서비스객체로 구성 서비스 객체를 별도로 정의하여 관리하면, BindModel 객체를 한 번에 구성할 수 있습니다. 이 방식은 유지보수성과 재사용성을 높이는 데 효과적입니다. js const bm = new BindModel ({ // 추가 테이블 설정 tables : [ 'second' ], // 아이템 설정 items : { 'aa' : 'Cat' , 'second.bb' : 10 , // 'second' 테이블의 컬럼 설정 'second.cc' : true , // 'second' 테이블의 컬럼 설정 'dd' : { selector : { key : '#U_ID' , type : 'value' }, // 컬럼의 selector 설정 setter : ( val ) => { /*외부에 설정 영역*/ }, // 컬럼의 setter 설정 getter : () => { return '외부값' ; }, // 컬럼의 getter 설정 }, 'ee' : { required : true , // 컬럼의 required 설정 setFilter : ( val ) => { /*외부에 설정영역*/ }, // 컬럼의 setFilter 설정 getFilter : () => { return '외부값' ; }, // 컬럼의 getFilter 설정 }, 'ff' : { constraints : { reg : /abc/ , msg : '매칭되지 실패!' } // 컬럼의 제약조건 설정 } }, // 명령(BindCommand) 설정 command : { create : {}, // 기본 명령 설정 read : { outputOption : 'ALL' , // 데이터를 지정한 컬럼값에 설정 config : { method : 'GET' }, // GET 요청 설정 cbEnd : function ( ) { alert ( '정상처리되었습니다.' ); } // 처리 완료 후 콜백 함수 }, update : { views : [ 'two' ], // 'two' 뷰를 추가 url : '/user' // 요청할 URL 경로 } } }); setService(service) 메서드를 통해 필요한 시점에 서비스를 주입하며, 단계적으로 객체 구성을 완성할 수 있습니다. Tip 서비스 객체를 생성하는 클래스를 정의하면, 재사용성과 관리 효율성을 높일 수 있습니다. 이를 통해 공통 로직을 캡슐화하고, 각 모델에서 필요한 맞춤 설정만 추가하여 사용할 수 있습니다. 참조 : 서비스 객체 주입"},{"title":"객체 구성 방법","group":"고급 기능","section":"모델에서 구성","url":"advanced/composition.html#모델에서-구성","text":"모델에서 구성 모델(BindModel) 객체를 점진적으로 확장하거나, 컬럼을 여러 명령(BindCommand)에서 공통으로 사용해야 할 경우에 유용합니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'create' ); bm. addCommand ( 'read' , 3 ); // 'aa' 컬럼을 'create' 명령의 'valid' 뷰에 등록 bm. addColumn ( 'aa' , 'create' , 'valid' ); // 'bb' 컬럼을 'read' 명령의 'bind' 뷰에 등록 bm. addColumn ( 'bb' , 'read' , 'bind' ); // 'cc' 컬럼을 모든 명령의 'output' 뷰에 등록 bm. addColumn ( 'cc' , '$all' , 'output' ); // bm.command['create'].valid.columns.count == 1 ('aa') // bm.command['create'].bind.columns.count == 0 // bm.command['create'].output.columns.count == 1 ('cc') // bm.command['read'].valid.columns.count == 0 // bm.command['read'].bind.columns.count == 1 ('bb') // bm.command['read'].output.columns.count == 1 ('cc') // bm.columns.count // 3 'aa','bb' Tip '$all' 을 사용하면 모든 명령에 공통적으로 적용됩니다. 참조 : 모델 구성"},{"title":"객체 구성 방법","group":"고급 기능","section":"명령에서 구성","url":"advanced/composition.html#명령에서-구성","text":"명령에서 구성 각 명령(BindCommand) 객체를 독립적으로 구성하는 방식입니다. 명령 단위로 컬럼이 독립적이거나, 특정 명령에만 컬럼을 설정할 경우 유용합니다."},{"title":"객체 구성 방법","group":"고급 기능","section":"명령에 컬럼 등록","url":"advanced/composition.html#명령에-컬럼-등록","text":"명령에 컬럼 등록 명령(BindCommand)을 추가하고, 해당 명령에 컬럼을 설정합니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 명령 설정 bm. command [ 'cmd1' ]. url = '/user' // 명령에 컬럼 추가 bm. command [ 'cmd1' ]. addColumn ( 'aa' , 'valid' ); bm. command [ 'cmd1' ]. addColumn ( 'bb' , [ 'bind' , 'output' ]); bm. command [ 'cmd1' ]. addColumn ( 'cc' , '$all' ); bm. command [ 'cmd1' ]. addColumn ( 'dd' ); // bm['first'].columns.count == 4 ('aa', 'bb', 'cc', 'dd') // bm.command['cmd1'].valid.columns.count == 3 ('aa', 'cc', 'dd') // bm.command['cmd1'].bind.columns.count == 3 ('bb', 'cc', 'dd') // bm.command['cmd1'].output.columns.count == 3 ('bb', 'cc', 'dd')"},{"title":"객체 구성 방법","group":"고급 기능","section":"명령에 컬럼 참조 설정","url":"advanced/composition.html#명령에-컬럼-참조-설정","text":"명령에 컬럼 참조 설정 공유 컬럼을 명령에 따라 뷰(MetaView)에 등록하는 방식입니다. 명령 단위로 컬럼을 공유해야 할 때 유용합니다. js const bm = new BindModel (); // 컬럼 추가 bm. addColumn ( 'aa' ); bm. addColumn ( 'bb' ); bm. addColumn ( 'cc' , '$all' ); bm. addColumn ( 'dd' ); // 명령 추가 bm. addCommand ( 'cmd1' ); // 명령에 컬럼 참조 설정 bm. command [ 'cmd1' ]. setColumn ( 'aa' , 'valid' ); bm. command [ 'cmd1' ]. setColumn ( 'bb' , [ 'bind' , 'output' ]); bm. command [ 'cmd1' ]. setColumn ( 'cc' , '$all' ); bm. command [ 'cmd1' ]. setColumn ( 'dd' ); // bm['first'].columns.count == 4 ('aa', 'bb', 'cc', 'dd') // bm.command['cmd1'].valid.columns.count == 3 ('aa', 'cc', 'dd') // bm.command['cmd1'].bind.columns.count == 3 ('bb', 'cc', 'dd') // bm.command['cmd1'].output.columns.count == 3 ('bb', 'cc', 'dd') Tip 사용하는 조건에 맞게 객체 생성방식을 자유롭게 조합해서 사용할 수 있습니다. 참조 : 명령 구성"},{"title":"객체 구성 방법","group":"고급 기능","section":"객체 구성 비교","url":"advanced/composition.html#객체-구성-비교","text":"객체 구성 비교 아래 예제는 'bb' 속성을 공유하며 공통 컬럼 아이템을 사용하는 방식으로 동일한 객체를 다양한 방법으로 구성한 예입니다. 방식 특징 비고 서비스 객체로 구성 전체적인 구조를 한 번에 정의하고 관리할 때 적합 모델에서 컬럼 구성 공통 컬럼이 여러 명령에서 공유될 때 적합 명령에서 컬럼 구성 명령마다 컬럼이나 설정이 독립적일 때 적합 Tip 필요에 따라 위 방식을 혼합하여 사용할 수도 있습니다."},{"title":"객체 구성 방법","group":"고급 기능","section":"서비스 객체로 구성","url":"advanced/composition.html#서비스-객체로-구성","text":"서비스 객체로 구성 서비스 객체를 통해 모델(BindModel)을 한 번에 구성합니다. js const bm = new BindModel (); bm. setService ({ // 추가 테이블 tables : 'second' , // 아이템 items : { aa : 'AA' , bb : 10 , cc : true , dd : { required : true }, }, // 명령 command : { cmd1 : {}, cmd2 : { outputOption : 'ALL' , // 데이터를 컬럼값에 설정하기 (지정한 컬럼) config : { method : 'GET' }, // GET 요청 설정 cbEnd : () => { alert ( '정상처리되었습니다.' ) } // 처리 완료 후 콜백 함수 }, cmd3 : { views : [ 'two' ], // 'two' 뷰를 추가 url : '/user' // 요청할 URL 경로 } }, // 매핑 mapping : { 'aa' : { cmd1 : 'valid' }, 'bb' : { cmd2 : [ 'valid' , 'bind' ], cmd3 : 'output' }, 'second.cc' : { cmd3 : 'output' }, 'second.dd' : { cmd3 : '$all' } } }); Tip 서비스 객체를 사용하면 초기 설정 및 구성이 간편하며, 한눈에 객체 구조를 파악할 수 있습니다."},{"title":"객체 구성 방법","group":"고급 기능","section":"명령에서 컬럼 구성","url":"advanced/composition.html#명령에서-컬럼-구성","text":"명령에서 컬럼 구성 명령(BindCommand) 중심으로 객체를 구성하며, 단계별로 컬럼을 추가하고 매핑합니다. js const bm = new BindModel (); // 추가 테이블 bm. addTable ( 'second' ); // 아이템 추가 bm. items . add ( 'aa' , AA ); bm. items . add ( 'bb' , 10 ); bm. items . add ( 'cc' , true ); bm. items . add ( 'dd' , { required : true }); // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' , 3 ); bm. addCommand ( 'cmd3' ); // 명령 설정 bm. commmand [ 'cmd2' ]. config . method = 'GET' ; bm. commmand [ 'cmd2' ]. cbEnd = () => { alert ( '정상처리되었습니다.' ) }; bm. commmand [ 'cmd3' ]. newOutput ( 'two' ); bm. commmand [ 'cmd3' ]. url = '/user' ; // 컬럼 추가 및 매핑 bm. commmand [ 'cmd1' ]. addColumn ( 'aa' , 'valid' ); bm. commmand [ 'cmd2' ]. addColumn ( 'bb' , [ 'valid' , 'bind' ]); bm. commmand [ 'cmd3' ]. addColumn ( 'bb' , 'output' ); bm. commmand [ 'cmd3' ]. addColumn ( 'cc' , 'output' , 'second' ); bm. commmand [ 'cmd3' ]. addColumn ( 'dd' , '$all' , 'second' ); Tip 명령에서 컬럼을 개별적으로 설정하면 명령 단위로 유연하게 구성할 수 있습니다."},{"title":"객체 구성 방법","group":"고급 기능","section":"모델에서 컬럼 구성","url":"advanced/composition.html#모델에서-컬럼-구성","text":"모델에서 컬럼 구성 모델(BindModel) 중심으로 테이블, 아이템, 컬럼을 먼저 등록한 뒤 명령에 매핑합니다. js const bm = new BindModel (); // 추가 테이블 bm. addTable ( 'second' ); // 아이템 추가 bm. items . add ( 'aa' , AA ); bm. items . add ( 'bb' , 10 ); bm. items . add ( 'cc' , true ); bm. items . add ( 'dd' , { required : true }); // 컬럼 추가 및 매핑 bm. addColumn ( 'aa' , 'cmd1' , 'valid' ); bm. addColumn ( 'bb' , 'cmd2' , [ 'valid' , 'bind' ]); bm. addColumn ( 'bb' , 'cmd3' , 'output' ); bm. addColumn ( 'cc' , 'cmd3' , 'output' , 'second' ); bm. addColumn ( 'dd' , 'cmd3' , '$all' , 'second' ); // 명령 설정 bm. commmand [ 'cmd2' ]. outputOption = 'ALL' ; bm. commmand [ 'cmd2' ]. config . method = 'GET' ; bm. commmand [ 'cmd2' ]. cbEnd = () => { alert ( '정상처리되었습니다.' ) }; bm. commmand [ 'cmd3' ]. newOutput ( 'two' ); bm. commmand [ 'cmd3' ]. url = '/user' ; Tip 모델 중심 구성은 공통 컬럼을 여러 명령에서 사용해야 할 때 적합하며, 컬럼과 명령을 명시적으로 관리할 수 있습니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 이벤트 설정 다음 문서 CRUD + List 구현하기"},{"title":"CRUD + List 구현하기","group":"예제","section":"CRUD + List 구현하기","url":"examples/crudl.html","text":"문서 예제 예제 04 CRUD + List 구현하기 목록 조회, 등록, 수정, 삭제를 연결하며 하나의 화면을 완성합니다. 한국어 문서 약 24분 코드로 따라 하는 CRUD 예제 이 문서는 화면과 서비스 객체를 구성하는 튜토리얼입니다. 등록·수정·삭제를 저장하려면 별도의 서버 API가 필요합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"1단계 : 화면 구성","url":"examples/crudl.html#1단계-화면-구성","text":"1단계 : 화면 구성 목록과 등록, 수정을 한 화면에 구성하는 구조 + 부트스트립트 + JQuery 로 구성되어 있습니다. 화면 영역 은 목록 테이블과 보임과 숨김을 제어하기 위해 수정 폼 영역(class-form) : ntx_idx, title, content, create_dt, top_yn, active_cd 수정 폼 버튼 영역(edit-button) : btn_Update, btn_Delete, btn_List 저장 폼 버튼 영역(create-button) : btn_Reset, btn_Save, btn_Cancel 등록 폼 버튼 영역(form-button) : btn_Create 으로 구성되어 있습니다. html <!DOCTYPE html > < html lang = \"en\" > < head > < title > BindModel Example </ title > < meta charset = \"utf-8\" > < meta name = \"viewport\" content = \"width=device-width, initial-scale=1\" > < link href = \"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel = \"stylesheet\" > < script src = \"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\" > </ script > < script src = \"https://cdnjs.cloudflare.com/ajax/libs/handlebars.js/4.7.8/handlebars.min.js\" > </ script > < script src = \"https://code.jquery.com/jquery-3.7.1.slim.min.js\" > </ script > < script src = \"main.js\" type = \"module\" > </ script > </ head > < body > < div class = \"container mt-3\" > < h2 > Notice Admin Page </ h2 > < h5 > Key Features: List inquiry/modification/deletion </ h5 > < p > Data is transmitted when modified or deleted from the test page, but it is not actually processed. </ p > < table class = \"table\" > < thead > < tr > < th > Title </ th > < th > Status </ th > < th > Date </ th > </ tr > </ thead > < tbody id = \"area-tbody\" > < tr > < td colspan = \"3\" > There is no content. </ td > </ tr > </ tbody > </ table > < div id = \"class-form\" class = \"d-none\" > < form id = \"notice-form\" > <!-- form element --> < div id = \"edit-button\" class = \"d-none\" > <!-- edit button --> </ div > < div id = \"create-button\" class = \"d-none\" > <!-- create button --> </ div > </ form > </ div > < div id = \"form-button\" > < button type = \"button\" class = \"btn btn-primary mt-3\" id = \"btn_From\" > Create </ button > </ div > </ div > </ body > </ html >"},{"title":"CRUD + List 구현하기","group":"예제","section":"2 단계 : 서버 데이터 샘플","url":"examples/crudl.html#2-단계-서버-데이터-샘플","text":"2 단계 : 서버 데이터 샘플 서버 경로 /notice/data/list.json 에 샘플데이터를 제작 합니다. json [ { \"ntc_idx\" : 1 , \"title\" : \"This is the first notice post.\" , \"top_yn\" : \"Y\" , \"active_cd\" : \"A\" , \"create_dt\" : \"2014-01-01\" , \"contents\" : \"This is the content of the first post....\" } , { \"ntc_idx\" : 2 , \"title\" : \"This is the second notice post.\" , \"top_yn\" : \"N\" , \"active_cd\" : \"H\" , \"create_dt\" : \"2014-01-02\" , \"contents\" : \"This is the content of the second post...\" } ]"},{"title":"CRUD + List 구현하기","group":"예제","section":"3단계 : main.js 구성","url":"examples/crudl.html#3단계-mainjs-구성","text":"3단계 : main.js 구성 <script src=\"main.js\" type=\"module\"></script> esm 모듈방식으로 파일을 제작합니다. BindModel 객체를 생성할때 인자로 서비스 객체를 생성하여 주입합니다. 모든 서버 경로는 '/notice/data/list.json' 로 지정합니다. js import BindModel from 'https://unpkg.com/logic-bind-model/dist/bind-model.esm.js' ; import NoticeAdminService from './service/notice-admin-svc.js' var bm = new BindModel ( new NoticeAdminService ()); bm. url = '/notice/data/list.json' ; // base url"},{"title":"CRUD + List 구현하기","group":"예제","section":"4단계 :  서비스객체  구성","url":"examples/crudl.html#4단계-서비스객체-구성","text":"4단계 : 서비스객체 구성 notice-admin-svc.js 경로에 서비스 객체는 이후 재사용성을 위하여 class 형식으로 지정하면 상속 등 활용하여 재사용 유리합니다. 인자로 전달되는 _SUFF 는 selector 에 id 등 지정시 중복방지에 활용할 수 있습니다. js class NoticeAdminService { constructor ( _SUFF = '' ) { //..... } } export { NoticeAdminService as default , NoticeAdminService }"},{"title":"CRUD + List 구현하기","group":"예제","section":"5-1단계 : 명령(list) 서비스 객체 구성","url":"examples/crudl.html#5-1단계-명령list-서비스-객체-구성","text":"5-1단계 : 명령(list) 서비스 객체 구성 조회된 데이트를 확인 가능하게 목록 명령에 대한 명칭을 list 로 지정하고 서비스 객체를 구상합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"items 서비스 객체 구성","url":"examples/crudl.html#items-서비스-객체-구성","text":"items 서비스 객체 구성 아이템 대상이 되는 항목을 정의합니다. 서버로 전송하거나 받을 항목 제어가 필요한 위치를 아이템으로 구성합니다. 각 항목은 _area_temp 은 목록을 handlebars 템플릿을 사용할 양식입니다. <script id=\"area-temp\" type=\"text/x-handlebars-template\"> _area_tbody 템플릿으로 생성된 코드를 추가할 위치를 가르킵니다. <tbody id=\"area-tbody\"> _area_form 은 읽기/수정/등록에 사용할 폼 양식들이 있는 영역을 가르킵니다. _area_btn_edit 은 읽기/수정에 사용할 버튼(update, deate, list) 영역을 가르킵니다. _area_btn_create 은 신규 등록에 사용할 버튼(reset, save, cacel) 영역을 가르킵니다. _area_btn_form 은 신규 등록시 폼양식 을 보이게 하는 버튼이 구성된 영역을 가르킵니다. selector 속성의 key 는 셀렉터 값을 의미하고 type 셀렉터에 대한 타입을 지정합니다. type='html' 는 html 태그를 가르킵니다. type='attr.*' 는 지정한 요소의 정적 속성에 대한 값을 가르킵니다. type='attr.class' 지정한 요소의 <div class='d-none'> 값 부트스트립트에 d-none 값은 style=\"display:none;\" 와 같은 기능입니다. js this . items = { _area_temp : { selector : { key : `#area-temp ${_SUFF} ` , type : 'html' } }, _area_tbody : { selector : { key : `#area-tbody ${_SUFF} ` , type : 'html' } }, _area_form : { selector : { key : `#class-form ${_SUFF} ` , type : 'attr.class' } }, _area_btn_edit : { selector : { key : `#edit-button ${_SUFF} ` , type : 'attr.class' } }, _area_btn_create : { selector : { key : `#create-button ${_SUFF} ` , type : 'attr.class' } }, _area_btn_form : { selector : { key : `#form-button ${_SUFF} ` , type : 'attr.class' } }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"fn 서비스 객체 구성","url":"examples/crudl.html#fn-서비스-객체-구성","text":"fn 서비스 객체 구성 목록에서 내용을 선택하면 처리할 기능을 fn 영역에 추가합니다. js this . fn = { procRead ( index ) { _this. bindModel . items . _index = index; _this. bindModel . command [ 'read' ]. execute (); }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"command 서비스 객체 구성","url":"examples/crudl.html#command-서비스-객체-구성","text":"command 서비스 객체 구성 서버 경로에서 모든 데이터를 가져오기 위해서 outputOption: 'ALL' 로 지정하였습니다. (기본값은 'SEND' 서버에 데이터를 전송 후 데이터는 받지 않습니다.) 처음으로 실행되는 cbBegin 콜백함수에 폼영역은 숨기고, 신규 등록시 폼양식은 보이도록 설정합니다. cbOutput 콜백함수에 서버에서 전송받은 데이터를 MetaView 에 저장이후에, 화면 출력과 관련된 부분을 정의합니다. Handlebars 템플릿에 translateActive 헬퍼를 등록합니다. (코드를 값으로 변환) _template 템플릿 양식을 컴파일하여 템플릿 객체를 생성합니다. _template(outs[0].rows) 템플릿 객체에 데이터를 전달하여, 파싱 결과를 _area_tbody 에 붙임 outs 인자는 출력뷰의 컬렉션을 가르키면 outs[0].rows 는 첫번째 MetaView 을 rows 데이터를 가르킵니다. 목록에 대한 이벤트를 등록합니다. document.getElementById('area-tbody').addEventListener('click', ...) js this . command = { list : { outputOption : 'ALL' , cbBegin ( model, cmd ) { model. columns [ '_area_form' ]. value = 'd-none' ; model. columns [ '_area_button' ]. value = '' ; }, cbOutput ( outs, cmd, res ) { Handlebars . registerHelper ( 'translateActive' , function ( code ) { if (code === 'S' ) return 'Standby' ; if (code === 'A' ) return 'Activation' ; if (code === 'H' ) return 'hidden' ; return '' ; }); if (_template === null ) { _template = Handlebars . compile ( _this. bindModel . columns [ '_area_temp' ]. value ); } _this. bindModel . columns [ '_area_tbody' ]. value = _template (outs[ 0 ]. rows ); document . getElementById ( 'area-tbody' ). addEventListener ( 'click' , function ( e ) { const target = e. target . closest ( '.btnNormal' ); if (target && target. dataset . index ) { const index = parseInt (target. dataset . index , 10 ); if (! isNaN (index)) cmd. _model . fn . procRead (index); } }); } } }; 목록 템플릿 양식으로 본문에 추가합니다. {{#each this}} 블럭은 배열갯수 만큼 반복하여 파싱합니다. html < script id = \"area-temp\" type = \"text/x-handlebars-template\" > {{#each this }} <tr> < td > < a href = \"#\" class = \"btnNormal\" data-index = \"{{@index}}\" > {{title}} </ a > </ td > < td > {{translateActive active_cd}} </ td > < td > {{create_dt}} </ td > </tr> {{/each}} </ script >"},{"title":"CRUD + List 구현하기","group":"예제","section":"mapping 서비스 객체 구성","url":"examples/crudl.html#mapping-서비스-객체-구성","text":"mapping 서비스 객체 구성 items 에서 정의한 아이템을 별도의 뷰(misc) 에 지정합니다. misc 는 서버에 전송과 수신과정에 관여하지 않습니다. 단지 매핑을 위해 임시로 지정한 뷰입니다. 각각 아이템에 대한 'list' 명령의 'misc' 뷰에 매핑입니다. js this . mapping = { _area_temp : { list : 'misc' }, _area_tbody : { list : 'misc' }, _area_form : { list : 'misc' }, _area_btn_edit : { list : 'misc' }, _area_btn_create : { list : 'misc' }, _area_btn_form : { list : 'misc' }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"main.js 실행 및 테스트","url":"examples/crudl.html#mainjs-실행-및-테스트","text":"main.js 실행 및 테스트 초기에 실행할 명령(list) 을 지정하고, 결과를 확인합니다. js $( document ). ready ( function ( ) { bm. command [ 'list' ]. execute (); });"},{"title":"CRUD + List 구현하기","group":"예제","section":"5-2 단계 : 명령(create) 서비스 객체 구성","url":"examples/crudl.html#5-2-단계-명령create-서비스-객체-구성","text":"5-2 단계 : 명령(create) 서비스 객체 구성 입력폼 양식에서 데이터를 입력받아 서버로 전송합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"html 구성","url":"examples/crudl.html#html-구성","text":"html 구성 html < form id = \"notice-form\" > < input type = \"hidden\" id = \"ntc_idx\" > < div class = \"form-group\" > < label for = \"title\" > 날짜 </ label > < p id = \"create_dt\" > </ p > </ div > < div class = \"form-group\" > < label for = \"title\" > Title </ label > < input type = \"text\" class = \"form-control\" id = \"title\" > </ div > < div class = \"form-group\" > < label for = \"contents\" > Content </ label > < textarea class = \"form-control\" id = \"contents\" rows = \"3\" > </ textarea > </ div > < div class = \"row\" > < div class = \"col\" > < div class = \"form-check\" > < input type = \"checkbox\" class = \"form-check-input\" id = \"check1\" name = \"top_yn\" value = \"Y\" > < label class = \"form-check-label\" for = \"check1\" > top notice </ label > </ div > </ div > < div class = \"col\" > < div class = \"form-check\" > < input type = \"radio\" class = \"form-check-input\" id = \"radio1\" name = \"active_cd\" value = \"D\" checked > < label class = \"form-check-label\" for = \"radio1\" > Standby </ label > </ div > < div class = \"form-check\" > < input type = \"radio\" class = \"form-check-input\" id = \"radio2\" name = \"active_cd\" value = \"A\" > < label class = \"form-check-label\" for = \"radio2\" > Activation </ label > </ div > < div class = \"form-check\" > < input type = \"radio\" class = \"form-check-input\" id = \"radio3\" name = \"active_cd\" value = \"H\" > < label class = \"form-check-label\" for = \"radio3\" > Hidden </ label > </ div > </ div > </ div > < div id = \"edit-button\" class = \"d-none\" > <!-- edit button --> < button type = \"button\" class = \"btn btn-primary mt-3\" id = \"btn_Update\" > Update </ button > < button type = \"button\" class = \"btn btn-primary mt-3\" id = \"btn_Delete\" > Delete </ button > < button type = \"button\" class = \"btn btn-primary mt-3\" id = \"btn_List\" > List </ button > </ div > < div id = \"create-button\" class = \"d-none\" > <!-- create button --> < button type = \"reset\" class = \"btn btn-primary mt-3\" id = \"btn_Reset\" > Reset </ button > < button type = \"button\" class = \"btn btn-primary mt-3\" id = \"btn_Save\" > Save </ button > < button type = \"button\" class = \"btn btn-primary mt-3\" id = \"btn_Cancel\" > Cancel </ button > </ div > </ form >"},{"title":"CRUD + List 구현하기","group":"예제","section":"items 서비스 객체 구성","url":"examples/crudl.html#items-서비스-객체-구성-2","text":"items 서비스 객체 구성 아이템 대상이 되는 항목을 정의합니다. 서버로 전송하거나 받을 항목 제어가 필요한 위치를 아이템으로 구성합니다. 각 아이템 ntc_idx 는 hidden 값으로 지정합니다. title 은 필수 조건으로 지정합니다. (required = true) top_yn , active_cd 은 setFilter , getFilter 를 설정하여 지정합니다. Tip 아니의 아이템이 복수의 요소를 제어하거나, 실제 값과 표현되는 값이 다를 경우 getFilter, setFilter 를 활용합니다. js this . items = { ntc_idx : { selector : { key : `#ntc_idx ${_SUFF} ` , type : 'value' } }, title : { selector : { key : `#title ${_SUFF} ` , type : 'value' }, required : true , }, contents : { selector : { key : `#contents ${_SUFF} ` , type : 'value' } }, top_yn : { selector : { key : `input[name=top_yn ${_SUFF} ]` , type : 'none' }, setFilter ( val ) { $( `input[name=top_yn ${_SUFF} ]` ). prop ( 'checked' , val == 'Y' ? true : false ); }, getFilter ( val ) { return $( `input[name=top_yn ${_SUFF} ]:checked` ). val () || 'N' ; } }, active_cd : { selector : { key : `input[name=active_cd ${_SUFF} ][type=radio]` , type : 'none' }, setFilter ( val ) { $( `input[name=active_cd ${_SUFF} ][value= ${val} ]` ). prop ( 'checked' , true ); }, getFilter ( val ) { return $( `input[name=active_cd ${_SUFF} ]:checked` ). val (); } } };"},{"title":"CRUD + List 구현하기","group":"예제","section":"command 서비스 객체 구성","url":"examples/crudl.html#command-서비스-객체-구성-2","text":"command 서비스 객체 구성 cbEnd 콜백함수를 설정하여 등록 완료 후에 사용자에게 메세지를 표시합니다. _this 객체는 서비스 클래스 정의시 자신을 가르키는 속성입니다. cmd 인자를 사용하여 cmd._model.cmd['list'].execute() 으로 지정할 수도 있습니다. js this . command = { create : { cbEnd ( status, cmd, res ) { if (res) { alert ( 'The post has been created.' ); _this. bindModel . cmd [ 'list' ]. execute (); } } }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"mapping 서비스 객체 구성","url":"examples/crudl.html#mapping-서비스-객체-구성-2","text":"mapping 서비스 객체 구성 title 은 valid 뷰에 지정하여 유효성 검사에 포함 시킵니다. bind 뷰에 지정된 아이템은 명령 실행시 서버로 전송되는 데이터입니다. js this . mapping = { title : { create : [ 'valid' , 'bind' ] }, contents : { create : 'bind' }, top_yn : { create : 'bind' }, active_cd : { create : 'bind' }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"fn 서비스 객체 구성","url":"examples/crudl.html#fn-서비스-객체-구성-2","text":"fn 서비스 객체 구성 등록 버튼을 선택시 폼을 초기화 하고, 폼양식을 화면에 보여줌니다. selector 속성에 type: 'attr.class' 값으로 숨김/보기 기능을 설정합니다. (부트스트립트) js this . fn = { createFrom ( form ) { document . getElementById (form). reset (); _this. bindModel . columns [ '_area_form' ]. value = '' ; _this. bindModel . columns [ '_area_create' ]. value = '' ; _this. bindModel . columns [ '_area_edit' ]. value = 'd-none' ; _this. bindModel . columns [ '_area_button' ]. value = 'd-none' ; } };"},{"title":"CRUD + List 구현하기","group":"예제","section":"main.js 이벤트 등록","url":"examples/crudl.html#mainjs-이벤트-등록","text":"main.js 이벤트 등록 등록 폼 보기 버튼과, 저장, 취소 버튼에 대한 이벤트를 연결합니다. js // create button event handlers $( '#btn_From' ). click ( ()=> bm. fn . createFrom ( 'notice-form' )); $( '#btn_Save' ). click ( ()=> bm. command [ 'create' ]. execute ()); $( '#btn_Cancel' ). click ( ()=> bm. command [ 'list' ]. execute ());"},{"title":"CRUD + List 구현하기","group":"예제","section":"5-3 단계 : 명령(read) 서비스 객체 구성","url":"examples/crudl.html#5-3-단계-명령read-서비스-객체-구성","text":"5-3 단계 : 명령(read) 서비스 객체 구성 지정한 서버 데이터를 각 폼 요소에 가져옵니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"items 서비스 객체 구성","url":"examples/crudl.html#items-서비스-객체-구성-3","text":"items 서비스 객체 구성 _index 는 정적 JSON 을 샘플로 가져오므로 임시로 데이터를 가져오는데 활용하였습니다. 등록일 아이템 create_dt 을 추가합니다. js this . items = { _index : 0 , create_dt : { selector : { key : `#create_dt ${_SUFF} ` , type : 'text' } } };"},{"title":"CRUD + List 구현하기","group":"예제","section":"command 서비스 객체 구성","url":"examples/crudl.html#command-서비스-객체-구성-3","text":"command 서비스 객체 구성 서버 경로에서 데이터를 가져오기 지정된 index 에 데이터를 value 을 가져오기 위해 outputOption: 'VIEW' 로 지정하였습니다. 처음으로 실행되는 cbBegin 콜백함수에 폼 추가 버튼 영역은 숨기고, 폼양식은 보이도록 설정합니다. 정적 JSON 데이터를 가져오기 위해서 임으로 _index 을 임으로 지정하여 값을 가져올 수 있게 합니다. js this . command = { read : { outputOption : 'VIEW' , cbBegin ( model, cmd ) { cmd. outputOption . index = Number (cmd. _model . items . _index ); model. columns [ '_area_form' ]. value = '' ; // form show model. columns [ '_area_edit' ]. value = '' ; // button show model. columns [ '_area_create' ]. value = 'd-none' ; model. columns [ '_area_button' ]. value = 'd-none' ; }, }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"mapping 서비스 객체 구성","url":"examples/crudl.html#mapping-서비스-객체-구성-3","text":"mapping 서비스 객체 구성 ntc_idx 을 서버에 전송하고, 모든 아이템을 output 으로 지정하여 출력뷰에 가져올 수 있게 지정합니다. js this . mapping = { ntc_idx : { read : [ 'bind' , 'output' ] }, title : { read : 'output' }, contents : { read : 'output' }, top_yn : { read : 'output' }, active_cd : { read : 'output' }, create_dt : { read : 'output' }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"main.js 이벤트 등록","url":"examples/crudl.html#mainjs-이벤트-등록-2","text":"main.js 이벤트 등록 목록 보기 버튼 이벤트를 연결합니다. js // read/update button event handlers $( '#btn_List' ). click ( ()=> bm. command [ 'list' ]. execute ());"},{"title":"CRUD + List 구현하기","group":"예제","section":"5-4 단계 : 명령(update) 서비스 객체 구성","url":"examples/crudl.html#5-4-단계-명령update-서비스-객체-구성","text":"5-4 단계 : 명령(update) 서비스 객체 구성 수정 처리 완료후 처리 결과를 alert() 메세지로 출력합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"items 서비스 객체 구성","url":"examples/crudl.html#items-서비스-객체-구성-4","text":"items 서비스 객체 구성 기존의 items 사용합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"command 서비스 객체 구성","url":"examples/crudl.html#command-서비스-객체-구성-4","text":"command 서비스 객체 구성 cbEnd 콜백함수를 지정하여 수정 완료후 결과를 메세지로 표시합니다. js this . command = { update : { cbEnd ( status, cmd, res ) { if (res) alert ( 'It has been modified.' ); } }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"mapping 서비스 객체 구성","url":"examples/crudl.html#mapping-서비스-객체-구성-4","text":"mapping 서비스 객체 구성 ntc_idx, title, top_yn, active_cd 아이템을 valid 뷰에 지정하여 유효성을 검사합니다. 유효성 검사가 성공하면 bind 뷰에 지정되 아이템은 서버로 전송됩니다. js this . mapping = { ntc_idx : { update : [ 'valid' , 'bind' ] }, title : { update : [ 'valid' , 'bind' ] }, contents : { update : 'bind' }, top_yn : { update : [ 'valid' , 'bind' ] }, active_cd : { update : [ 'valid' , 'bind' ] }, };"},{"title":"CRUD + List 구현하기","group":"예제","section":"main.js 이벤트 등록","url":"examples/crudl.html#mainjs-이벤트-등록-3","text":"main.js 이벤트 등록 수정 버튼에 이벤트를 등록합니다. js // read/update button event handlers $( '#btn_Update' ). click ( ()=> bm. command [ 'update' ]. execute ());"},{"title":"CRUD + List 구현하기","group":"예제","section":"5-5 단계 : 명령(delete) 서비스 객체 구성","url":"examples/crudl.html#5-5-단계-명령delete-서비스-객체-구성","text":"5-5 단계 : 명령(delete) 서비스 객체 구성 삭제 버튼을 클릭하면 사용자에게 confirm() 확인 삭제 처리 후에 목록 보기로 이동합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"items 서비스 객체 구성","url":"examples/crudl.html#items-서비스-객체-구성-5","text":"items 서비스 객체 구성 기존의 items 사용합니다."},{"title":"CRUD + List 구현하기","group":"예제","section":"command 서비스 객체 구성","url":"examples/crudl.html#command-서비스-객체-구성-5","text":"command 서비스 객체 구성 cbValid 콜백함수를 활용해서 사용자에 삭제유무를 확인하도록 추가합니다. cbEnd 콜백함수를 지정하여 삭제 처리 결과를 메세지로 표시합니다. js this . command = { delete : { cbValid ( valid, cmd ) { if ( confirm ( 'Are you sure you want to delete it?' )) return true ; }, cbEnd ( status, cmd, res ) { if (res) { alert ( 'The post has been deleted.' ); cmd. _model . command [ 'list' ]. execute (); } } } };"},{"title":"CRUD + List 구현하기","group":"예제","section":"mapping 서비스 객체 구성","url":"examples/crudl.html#mapping-서비스-객체-구성-5","text":"mapping 서비스 객체 구성 ntc_idx 아이템을 유효성 검사후 서버에 전송합니다. js this . mapping = { ntc_idx : { delete : [ 'valid' , 'bind' ] } };"},{"title":"CRUD + List 구현하기","group":"예제","section":"main.js 이벤트 등록","url":"examples/crudl.html#mainjs-이벤트-등록-4","text":"main.js 이벤트 등록 삭제 버튼에 이벤트를 등록합니다. js // read/update button event handlers $( '#btn_Delete' ). click ( ()=> bm. command [ 'delete' ]. execute ()); 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 객체 구성 방법 다음 문서 BindModel"},{"title":"BindModel","group":"API 레퍼런스","section":"BindModel","url":"api/bind-model.html","text":"문서 API 레퍼런스 API 레퍼런스 05 BindModel 모델의 속성, 메서드, 이벤트를 찾아보세요. 한국어 문서 약 59분 BindModel은 데이터 처리 및 바인딩 작업을 수행하기 위한 핵심 클래스입니다. 이 클래스는 데이터 테이블 관리, 명령 정의, 콜백 처리 등 다양한 기능을 제공합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"구성 요소","url":"api/bind-model.html#구성-요소","text":"구성 요소"},{"title":"BindModel","group":"API 레퍼런스","section":"속성","url":"api/bind-model.html#속성","text":"속성 항목 설명 _columnType 생성될 컬럼의 기본 타입입니다. _baseTable BindModel 객체의 기본 테이블입니다. _tables 관리되는 모든 테이블의 컬렉션입니다. baseConfig 서버 요청에 필요한 기본 설정입니다. url 기본 요청 경로를 정의합니다. first 기본적으로 제공되는 MetaTable 입니다. columns 기본 테이블의 컬럼 컬렉션을 참조합니다. items 컬럼의 공통 속성을 관리하는 컬렉션입니다. fn 사용자 정의 함수를 관리하는 컬렉션입니다. command 명령(BindCommand) 객체를 관리하는 컬렉션입니다. cbFail 명령 실행 시 유효성 검사에 실패했을 때 호출되는 콜백 함수입니다. cbError 명령 실행 중 오류가 발생했을 때 호출되는 콜백 함수입니다. cbBaseBegin 명령 실행 흐름에서 첫 번째로 호출되는 기본 콜백 함수입니다. cbBaseValid 유효성 검사 전에 호출되는 기본 콜백 함수입니다. cbBaseBind 명령 실행 시 데이터를 서버로 전송하기 전에 호출되는 기본 콜백 함수입니다. cbBaseResult 전송받은 서버 응답 데이터를 처리하는 기본 콜백 함수입니다. cbBaseOutput 서버 응답 데이터를 화면에 출력하는 기본 콜백 함수입니다. cbBaseEnd 명령 실행이 완료된 후 호출되는 기본 콜백 함수입니다. preRegister init() 메소드를 실행할 때 처음으로 호출되는 콜백함수입니다. preCheck init() 메소드를 실행할 때 전처리 검사를 수행하는 콜백 함수입니다. preReady init() 메소드를 실행할 때 전처리 검사(preCheck) 이후에 수행하는 콜백함수입니다."},{"title":"BindModel","group":"API 레퍼런스","section":"메소드","url":"api/bind-model.html#메소드","text":"메소드 항목 설명 addTable() 새로운 테이블(MetaTable)을 추가합니다. addCommand() 새로운 명령(BindCommand)을 추가합니다. addColumn() 테이블에 새로운 컬럼을 추가합니다. addColumnValue() 테이블에 컬럼을 추가하면서 해당 컬럼의 기본값을 설정합니다. setService() 서비스 객체를 주입하여 BindModel 객체를 구성합니다. setMapping() 지정된 명령(BindCommand)의 뷰에 컬럼을 매핑합니다. init() BindModel 객체를 초기화하는 메서드입니다. checkSelector() selector 속성을 검사하여 유효하지 않은 항목을 반환합니다. getSelector() 대상 컬렉션에 설정된 selector 객체를 반환합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"이벤트","url":"api/bind-model.html#이벤트","text":"이벤트 항목 설명 onExecute 명령(BindCommand)이 실행되기 전에 호출되는 전역 이벤트 입니다. onExecuted 명령(BindCommand)이 실행된 후 호출되는 전역 이벤트 입니다."},{"title":"BindModel","group":"API 레퍼런스","section":"주요 속성","url":"api/bind-model.html#주요-속성","text":"주요 속성"},{"title":"BindModel","group":"API 레퍼런스","section":"_columnType","url":"api/bind-model.html#_columntype","text":"_columnType 생성될 컬럼의 기본 타입 속성입니다. ts type _columnType = HTMLColumn | MetaColumn | CustomColumn ; HTMLColumn : HTML 요소와 연동 가능한 컬럼 타입 MetaColumn : MetaTable 의 기본 컬럼 타입 CustomColumn : 사용자 정의 컬럼 타입 _columnType 속성은 새로운 컬럼을 추가할 때 적용되는 기본 타입입니다. 객체 생성 시 HTMLColumn 으로 초기화됩니다. (기본값) MetaColumn을 상속하여 사용자 정의 타입을 구현할 수 있습니다. 유의점: _columnType 속성을 변경하면 이후 추가되는 컬럼부터 적용됩니다. 기본값 확인 및 변경 예제 js const bm = new BindModel (); console . log (bm. _columnType ); // [Class HTMLColumn] // 컬럼 타입 변경 bm. _columnType = MetaColumn ; console . log (bm. _columnType ); // [Class MetaColumn] _columnType 을 MetaColumn으로 변경하고 변경된 값을 확인합니다. 컬럼 생성 시 _columnType 적용 예제 js const bm = new BindModel (); // 기본 컬럼 타입으로 컬럼 추가 bm. addColumn ( 'username' ); console . log (bm. columns [ 'username' ]); // [Object HTMLColumn] // _columnType 변경 후 컬럼 추가 bm. _columnType = MetaColumn ; bm. addColumn ( 'age' ); console . log (bm. columns [ 'age' ]); // [Object MetaColumn] _columnType 을 변경 후 새로운 컬럼을 추가하면 변경된 타입으로 추가됩니다. #이슈 별도로 테이블의 columns.baseType 을 임의 로 지정한 경우 설정 이후에 테이블을 추가한 경우"},{"title":"BindModel","group":"API 레퍼런스","section":"_baseTable","url":"api/bind-model.html#_basetable","text":"_baseTable BindModel 객체의 기본 테이블 속성입니다. ts type _baseTable = MetaTable ; MetaTable : BindModel의 기본 테이블 힌트 first === _tables[0] === _tables['frist'] _baseTable 속성은 데이터를 관리하는 기본 테이블로, 명령과 컬럼 매핑의 중심 역할을 수행합니다. 컬럼 추가 및 명령 실행 시 기본적으로 적용되는 테이블입니다. 객체 생성 시 초기값으로 _tables['first'] 객체가 _baseTable 로 설정됩니다. (초기값) columns 속성은 항상 _baseTable.columns 을 참조합니다. Tip : 관련 메소드 addCommand() : 명령 생성 시 기본 테이블로 사용됩니다. addColumn() : 컬럼을 추가할 때 기본테이블로 사용됩니다. addColumnValue() : 초기값을 포함된 컬럼을 추가할 때 기본 테이블로 사용됩니다. setMapping() : 컬럼 매핑 작업에서 기본 테이블로 사용됩니다. 기본테이블 변경 예제 js const bm = new BindModel (); // 새로운 테이블 추가 bm. addTable ( 'second' ); // 기본 테이블 변경 bm. _baseTable = bm. second ; // 변경된 기본 테이블에 컬럼 추가 bm. addColumn ( 'username' ); console . log (bm. second . columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. columns [ 'username' ]); // [Object HTMLColumn] _baseTable 을 second 테이블로 변경하여 이후의 모든 데이터 작업이 이를 기준으로 수행됩니다. addColumn('username') 을 호출하면, 변경된 _baseTable 인 second 테이블에 컬럼이 추가됩니다. bm.columns 는 항상 _baseTable.columns 을 참조하므로, 변경된 기본 테이블의 컬럼과 동일한 결과를 출력합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"_tables","url":"api/bind-model.html#_tables","text":"_tables 관리되는 모든 테이블의 컬렉션 속성입니다. ts type _tables = MetaTableCollection ; MetaTableCollection : 테이블 객체의 컬렉션 _tables 속성은 복수의 테이블을 관리하는 컬렉션으로 사용됩니다. BindModel 객체 생성 시 기본 테이블로 _tables['first'] 가 자동으로 생성됩니다. addTable() 메서드를 사용하여 새로운 테이블을 추가할 수 있습니다. 테이블명 또는 인덱스를 통해 각 테이블에 접근할 수 있습니다. _tables 컬렉션의 다른 테이블로 _baseTable 속성을 변경할 수 있습니다. 참조 : first === _tables['first'] === _tables[0] js const bm = new BindModel (); // 테이블 추가 bm. addTable ( 'second' ); bm. addTable ( 'three' ); // 테이블 이름으로 접근 console . log (bm. _tables [ 'first' ]); // [Object MetaTable \"first\"] *기본 테이블* console . log (bm. _tables [ 'second' ]); // [Object MetaTable \"second\"] console . log (bm. _tables [ 'three' ]); // [Object MetaTable \"three\"] // 테이블 인덱스로 접근 console . log (bm. _tables [ 0 ]); // [Object MetaTable \"first\"] *기본 테이블* console . log (bm. _tables [ 1 ]); // [Object MetaTable \"second\"] console . log (bm. _tables [ 2 ]); // [Object MetaTable \"three\"] addTable() 메서드를 사용해 추가 테이블을 생성합니다. 각 테이블은 _tables 컬렉션에 저장되며, 테이블명이나 인덱스를 통해 접근할 수 있습니다. _tables['first'] 는 초기에 기본 테이블이며, 추가된 테이블은 순서대로 인덱스를 가집니다."},{"title":"BindModel","group":"API 레퍼런스","section":"baseConfig","url":"api/bind-model.html#baseconfig","text":"baseConfig 서버 요청에 필요한 기본 설정 속성입니다. ts type baseConfig = { method : 'GET' | 'POST' | 'PUT' | 'DELETE' , url ?: string , baseUrl ?: string , responseType ?: 'json' | 'text' | 'blob' }; method : HTTP 요청 방식 (기본값 'GET') url : 요청 경로 baseUrl : url 과 결합되는 기본 경로(도메인) responseType : 서버 응답 데이터 형식 (기본값 'json') 참조 : 추가 속성에 대한 자세한 내용은 Axios의 config 문서를 참조하세요. baseConfig 속성은 서버 요청의 기본 설정을 관리합니다. 명령별로 config 설정을 하지 않으면 baseConfig 설정이 사용됩니다. baseConfig 속성은 axios 설정(config)의 역활을 수행하며 URL, HTTP 메서드, 응답 데이터 형식 등 주요 설정 값을 지정합니다. Tip : basConfig 를 활용하여 인증 토큰 추가, 요청 데이터 포맷 지정, 서버와의 세부 통신 방식을 효율적으로 관리할 수 있습니다. js const bm = new BindModel (); bm. baseConfig = { url : '/api/data' , method : 'POST' , responseType : 'json' , headers : { Authorization : 'Bearer token' } }; baseConfig 속성에 서버 요청 URL, HTTP 메서드, 응답 형식, 헤더를 설정합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"url","url":"api/bind-model.html#url","text":"url 기본 요청 경로를 정의하는 속성입니다. ts type url = string ; url : 서버 요청 경로 url 속성은 서버 요청의 기본 경로의 역할을 합니다. url 속성은 baseConfig.url 속성의 참조값입니다. 각 명령(BindCommand)에서 url 속성을 설정하면 BindModel의 url 속성은 무시됩니다. baseConfig.baseUrl 속성과 조합하여 전체 URL을 구성할 수 있습니다. (도메인) 기본 url 설정 예제 js const bm = new BindModel (); bm. url = '/api/users' ; console . log (bm. baseConfig ); // Out: { url: '/api/users' } 설정된 URL은 baseConfig 속성에 반영되어 명령에서 기본 설정으로 사용됩니다. 명령에서 url 사용시 예제 js const bm = new BindModel (); bm. url = '/users' ; // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); // 경로 설정 bm. command [ 'cmd2' ]. url = '/api' ; // 명령 실행 bm. command [ 'cmd1' ]. execute (); // 요청 경로 : '/users' bm. command [ 'cmd2' ]. execute (); // 요청 경로 : '/api' cmd1 명령은 기본 URL을 사용하고, cmd2 명령는 개별적으로 설정된 URL을 사용하여 실행합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"first","url":"api/bind-model.html#first","text":"first 기본적으로 제공되는 MetaTable 속성입니다. ts type first = MetaTable ; MetaTable : 모델에서 생성한 테이블 Tip : first ==== _baseTable === _tables['first'] === _tables[0] first 속성은 BindModel 객체에서 기본 테이블( _baseTable )을 참조합니다. BindModel 객체가 생성되면 자동으로 first 테이블이 생성됩니다. _baseTable 속성은 초기값으로 _tables['first'] 를 가리킵니다. first 테이블은 _tables['first'] , _tables[0] 과 동일합니다. js const bm = new BindModel (); // 테이블에 컬럼 추가 bm. first . columns . add ( 'id' ); bm. first . columns . add ( 'username' ); console . log (bm. first . columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. _baseTable . columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. _tables [ 'first' ]. columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. columns [ 'username' ]); // [Object HTMLColumn] first 속성을 사용하여 기본 테이블에 컬럼과 데이터를 추가합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"columns 또는 cols","url":"api/bind-model.html#columns-또는-cols","text":"columns 또는 cols 기본 테이블의 컬럼 컬렉션을 참조하는 속성입니다. 별칭으로 cols 참조 속성을 제공합니다. ts type columns = MetaTableColumnCollection ; MetaTableColumnCollection : MetaTable 의 컬럼 컬렉션 columns 속성은 기본 테이블의 컬럼 컬렉션( _baseTable.columns )을 가르킵니다. _baseTable 속성이 변경되면, columns 속성의 참조값도 변경됩니다. Tip : 자주 사용되는 기본 테이블의 컬렉션에 쉽게 접근할 수 있습니다. 컬럼 컬렉션에서 컬럼 추가 예제 js const bm = new BindModel (); bm. columns . add ( 'username' ); console . log (bm. columns [ 'username' ]); // [Object HTMLColumn] columns 속성을 사용해 기본 테이블에 컬럼을 추가합니다. 기본 테이블 변경 시 컬럼 추가 예제 js const bm = new BindModel (); // 기본 테이블에 컬럼 추가 bm. columns . add ( 'email' ); // 기본 테이블 변경 bm. _baseTable = bm. addTable ( 'second' ); // 새로운 테이블에 컬럼 추가 bm. columns . add ( 'age' ); console . log (bm. first . columns [ 'email' ]); // [Object HTMLColumn] console . log (bm. second . columns [ 'age' ]); // [Object HTMLColumn] console . log (bm. columns [ 'age' ]); // [Object HTMLColumn] _baseTable 속성이 변경되면 columns 속성이 새로운 테이블의 컬럼 컬렉션을 참조하게 됩니다. bm.columns['age'] === bm.second.columns['age'] 동일합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"items","url":"api/bind-model.html#items","text":"items 컬럼의 공통 속성을 관리하는 컬렉션 속성입니다. ts type items = PropertyCollection ; PropertyCollection : 키-값 쌍으로 구성된 컬렉션 items 속성은 컬럼의 공통 속성을 관리하는 컬렉션입니다. 서비스 객체를 구성할 때 컬럼을 공통 속성으로 등록하고 사용합니다. Tip : items 속성은 복수의 테이블에 동일한 컬럼을 등록하는데 유용합니다. items 속성에 추가 예제 js const bm = new BindModel (); // items 추가 bm. items . add ( 'username' , 'Alice' ); bm. items . add ( 'id' , { value : 3 , default : 0 }); // 속성 조회 console . log (bm. items [ 'username' ]); // Out: 'Alice' console . log (bm. items [ 'id' ]); // Out: { value: 3, default: 0 } items 컬렉션에 속성을 추가하고 키로 조회하여 값을 확인합니다. items 값이 string, number, boolean 타입이면 컬럼의 value 속성으로 지정되고, 객체인 경우 각 속성에 매칭됩니다. items 속성과 테이블 매핑 예제 js const bm = new BindModel (); // 새로운 테이블 추가 bm. addTable ( 'second' ); // items 추가 bm. items . add ( 'aa' , 10 ); bm. items . add ( 'bb' , 20 ); // 테이블 매핑 설정 bm. setMapping ({ 'aa' : {}, 'first.bb' : {}, 'second.bb' : {} }); // 속성 및 컬럼 상태 확인 console . log (bm. items . count ); // Out: 2 console . log (bm. first . columns . count ); // Out: 2 console . log (bm. second . columns . count ); // Out: 1 console . log (bm. first . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. first . columns [ 'bb' ]. value ); // Out: 20 console . log (bm. second . columns [ 'bb' ]. value ); // Out: 20 '테이블명 . 아이템' 형식으로 지정하면 해당 테이블에 등록됩니다. '아이템명' 형식으로 테이블명을 생략하면 기본 테이블에 등록됩니다. first 테이블에는 aa, bb 컬럼이 추가되고, second 테이블에는 bb 컬럼이 추가됩니다. 참조 : setMaping 메소드"},{"title":"BindModel","group":"API 레퍼런스","section":"fn","url":"api/bind-model.html#fn","text":"fn 사용자 정의 함수를 관리하는 컬렉션 속성입니다. ts type fn = PropertyCollection ; PropertyCollection : 키-값 쌍으로 구성된 컬렉션 fn 속성은 사용자 정의 함수를 관리하는 컬렉션입니다. Tip : 콜백함수에서 호출되는 함수를 fn 컬렉션에 정의하여 BindModel을 캡슐화할 수 있습니다. js const bm = new BindModel (); // 사용자 정의 함수 추가 bm. fn . add ( 'calculateSum' , ( a, b ) => a + b); // 콜백함수에서 호출 bm. cbBaseBegin = function ( model, cmd ) { bm. fn . calculateSum ( 5 , 10 ); }; console . log (bm. fn [ 'calculateSum' ]( 5 , 10 )); // Out: 15 콜백함수 또는 외부에서 fn 함수를 호출할 수 있습니다."},{"title":"BindModel","group":"API 레퍼런스","section":"command 또는 cmd","url":"api/bind-model.html#command-또는-cmd","text":"command 또는 cmd 명령(BindCommand) 객체를 관리하는 컬렉션 속성입니다. 별칭으로 cmd 참조 속성을 제공합니다. ts type command = PropertyCollection ; PropertyCollection : 키-값 쌍으로 구성된 컬렉션 command 속성은 명령(BindCommand) 객체를 관리하는 컬렉션입니다. command['명령 이름'] 또는 command[인덱스] 경로를 통해 접근할 수 있습니다. addCommand() 메서드를 사용하여 새로운 명령(BindCommand)을 추가할 수 있습니다. 참조 : addCommand() 메소드 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 명령 실행 bm. command [ 'cmd1' ]. execute (); bm. cmd [ 'cmd1' ]. execute (); bm. cmd [ 0 ]. execute (); command['cmd1'], cmd['cmd1'], cmd[0] 을 통해 명령 객체에 접근할 수 있습니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbFail","url":"api/bind-model.html#cbfail","text":"cbFail 명령 실행 시 유효성 검사에 실패했을 때 호출되는 콜백 함수입니다. ts type cbFail = ( msg : string , valid : MetaView ) => void ; msg : 유효성 검사 실패와 관련된 메시지 valid : 실패한 유효성 검사가 적용된 MetaView 객체 cbFail 속성은 명령 실행 중 유효성 검사 실패를 처리하기 위한 콜백 함수입니다. 유효성 검사가 실패하면 cbFail 함수가 호출됩니다. 사용 환경에 맞게 cbFail 함수를 재정의하여 사용할 수 있습니다. 기본 콜백함수에서 콘솔 출력을 제공합니다. (기본값) js const bm = new BindModel (); bm. cbFail = function ( msg, view ) { console . warn ( `failed: ${msg} ` ); }; cbFail 함수를 설정하여 유효성 검사 실패 시 경고 메시지를 출력합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbError","url":"api/bind-model.html#cberror","text":"cbError 명령 실행 중 오류가 발생했을 때 호출되는 콜백 함수입니다. ts type cbError = ( msg : string , status ?: number , response ?: object ) => void ; msg : 오류 메시지 status(선택) : HTTP 상태 코드 또는 오류 상태를 나타내는 숫자 값 response(선택) : 서버에서 반환된 응답 객체 cbError 속성은 명령 실행 중 발생하는 모든 예외 상황을 처리하기 위한 콜백함수입니다. 사용자에게 오류 메시지를 제공하거나 로그를 출력하여 문제를 확인할 수 있습니다. 사용 환경에 맞게 cbError 을 재정의하여 사용할 수 있습니다. 기본 콜백함수에서 콘솔 출력을 제공합니다. Tip : execute() 메서드는 try 문으로 구성되어 있으며, catch 블럭에서 cbError 콜백 함수가 호출됩니다. 전역 오류 처리 예제 js const bm = new BindModel (); bm. cbError = function ( msg, status, response ) { console . error ( `Error occurred: ${msg} ` ); if (status) console . log ( `Status: ${status} ` ); if (response) console . log ( `Response:` , response); }; // 명령 실행 중 오류가 발생하면 cbError가 호출됩니다. 오류발생 시 오류 메시지와 상태, 응답 데이터를 로그로 출력합니다. 사용자 정의 오류 처리 예제 js const bm = new BindModel (); bm. cbError = function ( msg, status, response ) { alert ( `An error occurred: ${msg} ` ); }; // 명령 실행 중 오류가 발생하면 사용자에게 알림 메시지를 표시합니다. cbError 를 재정의하여 오류 발생 시 알림 창이 표시됩니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbBaseBegin","url":"api/bind-model.html#cbbasebegin","text":"cbBaseBegin 명령 실행 흐름에서 첫 번째로 호출되는 기본 콜백 함수 입니다. ts type cbBaseBegin = ( model : BindModel , cmd : BindCommand ) => void ; model : 현재 모델(BindModel) 객체 입니다. cmd : 실행 중인 명령(BindCommand) 객체 cbBaseBegin 은 명령 실행 흐름에서 첫 번째로 호출되는 콜백 함수입니다. 명령 실행 전에 필요한 설정을 동적으로 설정할 수 있습니다. 명령별로 cbBegin 콜백 함수가 없으면 cbBaseBegin 콜백 함수가 호출됩니다. js const bm = new BindModel (); bm. cbBaseBegin = function ( model, cmd ) { console . log ( `Command is about to execute.` ); // Out: `Command \"XXX\" is about to execute.` }; cbBaseBegin 함수를 설정하여 명령 실행 전 로그 메시지를 출력합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbBaseValid","url":"api/bind-model.html#cbbasevalid","text":"cbBaseValid 유효성 검사 전에 호출되는 기본 콜백 함수 입니다. ts type cbBaseValid = ( valid : MetaView , cmd : BindCommand , model : BindModel ) => boolean | undefined ; view : 유효성 검사 대상인 MetaView 객체 cmd : 실행 중인 명령(BindCommand) 객체 model : 현재 모델(BindModel) 객체 입니다. 반환값: true : 유효성 검사를 통과하고 다음 단계로 진행합니다. false : 유효성 검사가 실패하며, cbFail 함수가 호출됩니다. undefined : 유효성 검사가 실패하지만, cbFail 함수는 호출되지 않습니다. cbBaseValid 는 명령 실행 중 데이터의 유효성을 검사하기 전에 호출됩니다. 명령별로 cbValid 콜백 함수가 없으면 cbBaseValid 콜백 함수가 호출됩니다. Tip : 기본 유효성 검사 로직 외에 추가적인 검증 로직을 적용할 수 있습니다. 유효성 검사 예제 js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addColumn ( 'username' , 'cmd1' , 'valid' ); // 콜백 함수 설정 bm. cbBaseValid = function ( view, cmd, model ) { const username = view. columns [ 'username' ]. value ; if (!username || username. length < 3 ) { alert ( '사용자 이름은 3자 이상이어야 합니다.' ); return false ; } return true ; }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); 유효성 검사를 통해 username 값이 3자 이상인지 확인합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbBaseBind","url":"api/bind-model.html#cbbasebind","text":"cbBaseBind 명령 실행 시 데이터를 서버로 전송하기 전에 호출되는 기본 콜백 함수 입니다. ts type cbBaseBind = ( bind : MetaView , cmd : BindCommand , config : object ) => void ; bind : 서버로 전송할 데이터를 포함하는 MetaView 객체 cmd : 실행 중인 명령(BindCommand) 객체 config : axios 요청 설정 객체 cbBaseBind 는 명령 실행 중 서버 요청 데이터를 준비하기 위해 호출됩니다. 서버로 데이터를 전송하기 전에 요청 설정을 동적으로 설정할 수 있습니다. 명령별로 cbBind 콜백 함수가 없으면 cbBaseBind 콜백 함수가 호출됩니다. Tip : 전송할 데이터의 암호화 또는 토큰 추가 등 데이터 포멧 변환에 활용할 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'sendData' ); // 콜백 함수 설정 bm. cbBaseBind = function ( bind, cmd, config ) { config. headers = { Authorization : 'Bearer token' }; }; // 명령 실행 bm. command [ 'sendData' ]. execute (); 실행 시점에서 서버 요청 헤더에 인증 토큰을 동적으로 추가합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbBaseResult","url":"api/bind-model.html#cbbaseresult","text":"cbBaseResult 전송받은 서버 응답 데이터를 처리하는 기본 콜백 함수 입니다. ts type cbBaseResult = ( data : object , cmd : BindCommand , response : object ) => object ; data : 서버 응답 데이터 cmd : 실행된 명령(BindCommand) 객체 response : 서버에서 반환된 전체 응답 객체 반환값: 처리된 데이터를 반환하며, 이 데이터는 이후 작업에 사용됩니다. cbBaseResult 는 서버에서 반환된 데이터를 검증하거나 변환하는 데 사용됩니다. 서버 응답 데이터를 MetaView 스키마 형식으로 변환하는데 사용됩니다. 내부적으로 반환된 데이터는 MetaView(output)의 read(data) 메소드에 전달됩니다. 명령별로 cbResult 콜백 함수가 없으면 cbBaseResult 콜백 함수가 호출됩니다. 참조 : MetaView 의 read() js const bm = new BindModel (); bm. addCommand ( 'cmd1' , 1 ); // 콜백 함수 설정 bm. cbBaseResult = function ( data, cmd, response ) { return { rows : data. rows . filter ( product => product. inStock ) }; }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); 서버 응답 데이터에서 inStock 값이 참인 상품만 필터링하여 반환합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbBaseOutput","url":"api/bind-model.html#cbbaseoutput","text":"cbBaseOutput 서버 응답 데이터를 화면에 출력하는 기본 콜백 함수 입니다. ts type cbBaseOutput = ( outputs : MetaViewCollection , cmd : BindCommand , response : object ) => object ; outputs : 매핑된 데이터를 포함하는 MetaViewCollection 객체 outputs[0] 은 output 속성을 가르킵니다. outputs[뷰 이름] 또는 outputs[인덱스] 을 통해서 뷰에 접근합니다. cmd : 현재 실행 중인 BindCommand 객체 response : axios 응답 객체 cbBaseOutput 는 명령 실행 시 output 뷰에 데이터를 매핑한 뒤 호출됩니다. outputOption 이 1, 2, 3 일 경우에만 호출됩니다. 응답 데이터를 기반으로 화면에 출력하거나 로그를 기록할 수 있습니다. 명령별로 cbOutput 콜백 함수가 없으면 cbBaseOutput 콜백 함수가 호출됩니다. 참조 : 명령 복수 출력 구성 js const bm = new BindModel (); bm. addCommand ( 'cmd1' , 1 ); // 모든 컬럼의 데이터 가져옴 // 콜백 함수 설정 bm. cbBaseOutput = function ( outputs, cmd, response ) { const output = outputs[ 0 ]; // 첫번째 기본 MetaView 선택 output. rows . forEach ( product => { console . log ( `Product ID: ${product.id} , Name: ${product.name} ` ); }); }; bm. command [ 'cmd1' ]. execute (); // Product ID: XXX , Name: XXX // ... 명령 실행 후 첫 번째 MetaView 에서 데이터를 가져와 각 제품의 ID와 이름을 출력합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"cbBaseEnd","url":"api/bind-model.html#cbbaseend","text":"cbBaseEnd 명령 실행이 완료된 후 호출되는 기본 콜백 함수 입니다. ts type cbBaseEnd = ( status : number , cmd : BindCommand , response : object ) => void ; status : 명령 실행 결과를 나타내는 상태 코드 cmd : 현재 실행된 BindCommand 객체 response : 서버에서 반환된 응답 객체 cbBaseEnd 는 명령 실행 후 호출되어 최종 결과를 처리하는 콜백 함수입니다. 명령 실행 후 후속 작업을 수행할 수 있습니다. 명령별로 cbEnd 콜백 함수가 없으면 cbBaseEnd 콜백 함수가 호출됩니다. js const bm = new BindModel (); bm. addCommand ( 'saveData' ); // 콜백 함수 설정 bm. cbBaseEnd = function ( status, cmd, response ) { if (status > 0 ) alert ( '데이터 저장이 완료되었습니다.' ); else alert ( '데이터 저장 중 오류가 발생했습니다.' ); }; bm. command [ 'saveData' ]. execute (); 성공 여부에 따라 후속 작업이나 오류 처리를 수행할 수 있습니다."},{"title":"BindModel","group":"API 레퍼런스","section":"preRegister","url":"api/bind-model.html#preregister","text":"preRegister init() 메소드를 실행할 때 처음으로 호출되는 콜백함수 입니다. ts type preRegister = ( model : BindModel ) => void ; model : 현재 실행되는 BindModel 객체 Tip : init() 메소드를 필요에 따라 선택적으로 사용할 수 있습니다. preRegister 콜백함수는 BindModel 객체의 초기화 과정에서 처음으로 호출되며, 기본적으로 필요한 컬럼, 명령 등을 등록하거나 설정합니다. js const bm = new BindModel (); bm. preRegister = function ( model ) { console . log ( 'Registering the model...' ); }; bm. init (); // Out: 'Registering the model...' init() 메서드를 호출하면 preRegister 함수가 실행되며, 초기화 작업의 시작을 확인할 수 있습니다"},{"title":"BindModel","group":"API 레퍼런스","section":"preCheck","url":"api/bind-model.html#precheck","text":"preCheck init() 메소드를 실행할 때 전처리 검사를 수행하는 콜백 함수 입니다. ts type preReady = ( model : BindModel ) => boolean ; model : 현재 실행되는 BindModel 객체 반환값: true 이면 유효성 검사를 통과하고 초기화가 계속 진행됩니다. false 이면 초기화가 중단됩니다. Tip : init() 메소드를 필요에 따라 선택적으로 사용할 수 있습니다. preCheck 콜백함수는 BindModel 객체 초기화 과정에서 preRegister 이후 실행되며, 전처리 검사를 수행한 결과에 따라 다음 단계로 진행 여부를 결정합니다. 객체 상태 및 실행 환경에 관련된 검사를 수행합니다. Tip : items 또는 columns 의 selector 속성의 HTML 유효성 검사 활용할 수 있습니다. js const bm = new BindModel (); bm. preCheck = function ( model ) { const result = model. checkSelector (); // selector 속성의 유효성 검사 if (result. length > 0 ) console . error ( 'selector fail...' ); return true ; }; bm. init (); // Out: 'selector fail...' preCheck 콜백을 설정하여 초기화 전에 selector 속성의 유효성을 검사합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"preReady","url":"api/bind-model.html#preready","text":"preReady init() 메소드를 실행할 때 전처리 검사(preCheck) 이후에 수행하는 콜백함수 입니다. ts type preReady = ( model : BindModel ) => void ; model : 현재 실행되는 BindModel 객체 Tip : init() 메소드를 필요에 따라 선택적으로 사용할 수 있습니다. preReady 콜백함수는 BindModel 객체의 전처리(preCheck) 검사가 성공한 경우 실행됩니다. 초기화가 완료된 후, 필요한 이벤트 연결 등 후속 작업을 수행합니다. Tip : 전처리 과정은 preRegister 와 유사하지만, 논리적으로 preCheck 검사를 통과한 이후에 실행됩니다. js const bm = new BindModel (); bm. preReady = function ( model ) { console . log ( 'ready...' ); }; bm. init (); // Out: 'read...' preReady 함수를 설정하여 초기화가 완료된 후 콘솔에 출력합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"주요 메소드","url":"api/bind-model.html#주요-메소드","text":"주요 메소드"},{"title":"BindModel","group":"API 레퍼런스","section":"addTable()","url":"api/bind-model.html#addtable","text":"addTable() 새로운 테이블(MetaTable)을 추가하는 메서드입니다. ts declare function addTable ( name : string ): MetaTable ; name : 새로 추가될 테이블의 이름 반환값: 생성된 MetaTable 객체를 반환합니다. addTable() 메서드는 다음과 같은 역할과 특징을 가지고 있습니다: 지정한 이름으로 새로운 MetaTable 객체를 생성하여 _tables 컬렉션에 추가합니다. 테이블 이름은 BindModel 객체의 속성으로 추가되며, 예약어와 중복되지 않아야 합니다. 새로 추가된 테이블은 필요에 따라 기본테이블( _baseTable )로 설정할 수 있습니다. Tip : 예약어 목록 _tables , _baseTable , _columnType , items , fn , command , cmd , columns , $service , baseConfig , url , _guid , _type , $event , $KEYWORD js const bm = new BindModel (); bm. addTable ( 'second' ); bm. _tables [ 'first' ] === bm. first // true bm. _tables [ 'second' ] === bm. second // true addTable() 메서드를 사용하여 second 테이블을 추가합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"addCommand()","url":"api/bind-model.html#addcommand","text":"addCommand() 새로운 명령(BindCommand)을 추가하는 메서드입니다. ts declare function addCommand ( cmdName : string , outputOption ?: number = 0 , bTable ?: string | MetaTable ): BindCommand ; cmdName : 명령 이름 문자열 outputOption(선택) : 서버 응답 데이터를 출력 뷰에 바인딩하는 방식 0 : 바인딩하지 않음. (기본값) 1 : 응답 데이터를 모든 컬럼과 행으로 가져옴 2 : output.columns 컬렉션에 정의된 컬럼과 매칭되는 데이터를 가져옴 3 : 옵션 2 처리 후, 지정한 인덱스 데이터(rows)를 컬럼값(value)으로 설정 bTable(선택) : 명령의 기본 테이블( _baseTable )로 사용할 테이블 (기본값 : 모델의 _baseTable ) 반환값: 생성된 BindCommand 객체를 반환합니다. addCommand() 메소드는 명령(BindCommand) 객체를 생성하고, 이를 command 컬렉션에 등록합니다. outputOption 값을 지정하여 서버 응답 데이터를 출력 뷰 output(MetaView)에 바인딩하는 방식을 설정할 수 있습니다. 참조 : BindModel 클래스의 outputOpion 속성 명령 추가 예제 js const bm = new BindModel (); bm. addCommand ( 'create' ); bm. addCommand ( 'read' , 3 ); console . log (bm. command [ 'create' ]. outputOption ); // { option: 0, index: 0 } console . log (bm. command [ 'read' ]. outputOption ); // { option: 3, index: 0 } create 와 read 명령을 추가하며, 각각 기본 옵션(0)과 출력 옵션(3)으로 설정합니다. 테이블 지정 명령 추가 예제 js const bm = new BindModel (); bm. addTable ( 'second' ); bm. addCommand ( 'create' , 0 , 'second' ); console . log (bm. command [ 'create' ]); // [Object BindCommand] console . log (bm. command [ 'create' ]. outputOption ); // { option: 0, index: 0 } console . log (bm. command [ 'create' ]. _baseTable ); // [Object MetaTable \"second\"] 명령 추가 시 옵션을 0으로 지정하고, 기본 테이블을 second 테이블로 설정하였습니다."},{"title":"BindModel","group":"API 레퍼런스","section":"addColumn()","url":"api/bind-model.html#addcolumn","text":"addColumn() 테이블에 새로운 컬럼을 추가하는 메서드입니다. ts type ViewType = '$all' | 'valid' | 'bind' | 'output' | 'misc' | string ; declare function addColumn ( column : string | MetaColumn , cmds ?: string | string [] | '$all' , views ?: ViewType | ViewType [], bTable ?: MetaTable | string ): void ; column : 추가할 컬럼의 이름(문자열) 또는 MetaColumn 객체 cmds(선택) : 컬럼을 연계할 명령의 이름 또는 이름 배열 views(선택) : 컬럼을 매핑할 뷰를 이름 또는 이름 배열 '$all' : 모든 뷰 (기본값) 'valid' : 유효성 검사를 위한 뷰 'bind' : 서버 요청 데이터를 위한 뷰 'output' : 응답 데이터를 매핑하는 뷰 'misc' : 추가적인 뷰 string : 사용자 정의 출력 뷰 bTable(선택) : 컬럼을 추가할 MetaTable 객체 (기본값은 _baseTable ) Tip : column 인자만 지정하면 뷰에 매핑은 하지 않고 기본테이블에 컬럼만 추가됩니다. addColumn() 메서드는 컬럼을 추가하고, 명령(cmd)과 뷰(views)를 지정하여 참조값을 등록할 수 있습니다. column 인자만 지정하여 컬럼을 테이블에 추가할 수 있습니다. cmd 와 views 인자를 지정하여 명령(BindCommand)의 뷰에 컬럼을 매핑할 수 있습니다. views 인자는 기본적으로 전체 뷰가 지정되어 있습니다. (기본값 '$all') 컬럼 추가 예제 js const bm = new BindModel (); // 컬럼 추가 bm. addColumn ( 'gender' ); console . log (bm. columns [ 'gender' ]); // [Object HTMLColumn] console . log (bm. first . columns [ 'gender' ]); // [Object HTMLColumn] console . log (bm. _tables [ 'first' ]. columns [ 'gender' ]); // [Object HTMLColumn] gender 컬럼이 _baseTable 에 등록되고, columns 속성과 first 속성으로 확인할 수 있습니다. 컬럼 추가 및 모든 뷰에 매핑 예제 js // 명령 등록 bm. addCommand ( 'cmd1' ); // 컬럼 추가 및 명령에 매핑 bm. addColumn ( 'username' , 'cmd1' ); console . log (bm. cmd [ 'cmd1' ]. valid . columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. cmd [ 'cmd1' ]. bind . columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. cmd [ 'cmd1' ]. output . columns [ 'username' ]); // [Object HTMLColumn] console . log (bm. cmd [ 'cmd1' ]. misc . columns [ 'username' ]); // [Object HTMLColumn] username 컬럼을 모든 뷰( valid , bind , output , misc )에 참조값이 등록됩니다. 컬럼 추가 및 특정 뷰에 매핑 예제 js // 컬럼 추가 및 명령에 매핑 bm. addColumn ( 'email' , 'cmd1' , 'valid' ); bm. addColumn ( 'phone' , 'cmd1' , [ 'bind' , 'output' ]); console . log (bm. command [ 'cmd1' ]. valid . columns [ 'email' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. bind . columns [ 'phone' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. output . columns [ 'phone' ]); // [Object HTMLColumn] email 컬럼을 valid 뷰에만 매핑되고, phone 컬럼은 bind 와 output 뷰에 매핑됩니다. 사용자 정의 출력 뷰에 추가 예제 js // 출력 뷰 추가 bm. command [ 'cmd1' ]. newOutput ( 'out2' ); // 컬럼 추가 및 명령에 매핑 bm. addColumn ( 'address' , 'cmd1' , 'out2' ); console . log (bm. command [ 'cmd1' ]. out2 . columns [ 'address' ]); // [Object HTMLColumn] 추가된 출력 뷰( out2 )에 address 컬럼이 매핑됩니다."},{"title":"BindModel","group":"API 레퍼런스","section":"addColumnValue()","url":"api/bind-model.html#addcolumnvalue","text":"addColumnValue() 테이블에 컬럼을 추가하면서 해당 컬럼의 기본값을 설정하는 메서드입니다. ts declare function addColumnValue ( columnName : string , value : string | number | boolean | object , cmds ?: string | string [], views ?: '$all' | 'valid' | 'bind' | 'output' | 'misc' | string [], bTable ?: string | MetaTable ): void ; columnName : 추가할 컬럼의 이름 value : 초기값으로 설정할 데이터 cmds(선택) : 컬럼을 연계할 명령의 이름 또는 이름 배열 views(선택) : 컬럼을 매핑할 뷰를 이름 또는 이름 배열 '$all' : 모든 뷰 (기본값) 'valid' : 유효성 검사를 위한 뷰 'bind' : 서버 요청 데이터를 위한 뷰 'output' : 응답 데이터를 매핑하는 뷰 'misc' : 추가적인 뷰 string[] : 사용자 정의 출력 뷰 bTable(선택) : 컬럼을 추가할 MetaTable 객체 (기본값은 _baseTable ) addColumnValue() 메서드는 컬럼을 추가하면서 초기값을 설정하고, 명령(cmd)과 뷰(views)를 지정하여 참조값을 등록할 수 있습니다. 컬럼을 추가하면서 초기값을 함께 지정할 수 있습니다. cmd 와 views 매개변수를 지정하여 명령(BindCommand)의 뷰에 컬럼을 매핑할 수 있습니다. views 매개변수는 기본적으로 전체 뷰가 지정되어 있습니다. (기본값 '$all') 컬럼 추가 예제 js const bm = new BindModel (); // 컬럼 추가 bm. addColumnValue ( 'gender' , 'Man' ); console . log (bm. columns [ 'gender' ]. value ); // Out: 'Man' console . log (bm. first . columns [ 'gender' ]. value ); // Out: 'Man' console . log (bm. _tables [ 'first' ]. columns [ 'gender' ]. value ); // Out: 'Man' gender 컬럼이 _baseTable 에 등록되고, columns 속성과 first 속성으로 확인할 수 있습니다. 컬럼 추가 및 모든 뷰에 매핑 예제 js // 명령 등록 bm. addCommand ( 'cmd1' ); // 컬럼 추가 및 명령에 매핑 bm. addColumnValue ( 'username' , 'Jane' , 'cmd1' ); console . log (bm. cmd [ 'cmd1' ]. valid . columns [ 'username' ]. value ); // Out: 'Jane' console . log (bm. cmd [ 'cmd1' ]. bind . columns [ 'username' ]. value ); // Out: 'Jane' console . log (bm. cmd [ 'cmd1' ]. output . columns [ 'username' ]. value ); // Out: 'Jane' console . log (bm. cmd [ 'cmd1' ]. misc . columns [ 'username' ]. value ); // Out: 'Jane' username 컬럼을 모든 뷰( valid , bind , output , misc )에 참조값이 등록됩니다. 컬럼 추가 및 특정 뷰에 매핑 예제 js // 컬럼 추가 및 명령에 매핑 bm. addColumnValue ( 'email' , 'abc@gmail.com' , 'cmd1' , 'valid' ); bm. addColumnValue ( 'phone' , '010-1234' , 'cmd1' , [ 'bind' , 'output' ]); console . log (bm. cmd [ 'cmd1' ]. valid . cols [ 'email' ]. value ); // Out: 'abc@gmail.com' console . log (bm. cmd [ 'cmd1' ]. bind . cols [ 'phone' ]. value ); // Out: '010-1234' console . log (bm. cmd [ 'cmd1' ]. output . cols [ 'phone' ]. value ); // Out: '010-1234' email 컬럼을 valid 뷰에만 매핑되고, phone 컬럼은 bind 와 output 뷰에 매핑됩니다. 사용자 정의 출력 뷰에 추가 예제 js // 출력 뷰 및 컬럼 추가 bm. command [ 'cmd1' ]. newOutput ( 'out2' ); bm. addColumnValue ( 'address' , 'USA' , 'cmd1' , 'out2' ); console . log (bm. command [ 'cmd1' ]. out2 . columns [ 'address' ]. value ); // Out: 'USA' 추가된 출력 뷰( out2 )에 address 컬럼이 매핑됩니다."},{"title":"BindModel","group":"API 레퍼런스","section":"setService()","url":"api/bind-model.html#setservice","text":"setService() 서비스 객체를 주입하여 BindModel 객체를 구성하는 메서드입니다. ts declare function setService ( service : ServiceType , chkPass ?: boolean ) : void ; service : BindModel과 주입할 서비스 객체 chkPass(선택) : 타입 검사를 생략할지 여부 (기본값 false ) true 로 설정하면 타입 검사를 생략하고 서비스를 등록할 수 있습니다. setService() 메서드는 서비스 객체를 주입하여 BindModel 객체를 구성합니다. Tip : 비즈니스 로직을 분리하여 코드의 재사용성과 유지보수성을 높이는데 활용할 수 있습니다. 서비스객체 타입 ts // 공통 컬럼 속성 타입 (items) type KeyType = 'none' | 'value' | 'text' | 'html' | 'prop' | 'attr' | 'css' ; type SelectorType = { key : string , type : KeyType }; type RegExpType = { reg : RegExp , msg : string , return ?: boolean }; type FuncType = ( value : any ) => boolean ; type ConstraintType = RegExpType | FuncType ; type ColumnType = { selector ?: SelectorType , getter ?: () => any , setter ?: ( val : any ) => any , getFilter ?: () => any , setFilter ?: ( val : any ) => any , default ?: string | number | boolean | null , value ?: any , alias ?: string , caption ?: string , constraints ?: ConstraintType [] | ConstraintType , required ?: boolean | false , columnName ?: string }; type ItemType = ColumnType | string | number | boolean ; // 명령 타입 type CmdPropType = { outputOption ?: 0 | 1 | 2 | 3 , // 데이터 출력 옵션 views ?: string [], // 추가할 뷰(MetaView) 목록 config ?: object , // axios 설정 객체 url ?: string , // 서버 요청 URL // 명령 콜백 함수 cbBegin ?: ( model : BindModel , cmd : BindCommand ) => void , cbValid ?: ( view : MetaView , cmd : BindCommand , model : BindModel ) => boolean , cbBind ?: ( view : MetaView , cmd : BindCommand , cfg : object ) => void , cbResult ?: ( data : object , cmd : BindCommand , res : object ) => object , cbOutput ?: ( views : MetaViewCollection , cmd : BindCommand , res : object ) => void , cbEnd ?: ( status : number , cmd : BindCommand , res : object ) => void , // 명령 이벤트 onExecute ?: ( model : BindModel , cmd : BindCommand ) => void , onExecuted ?: ( model : BindModel , cmd : BindCommand ) => void , }; type CommandType = { [ key : string ]: CmdPropType }; // 매핑 타입 type CommandName = '$all' | string ; // 명령 이름 ('$all'은 모든 명령을 의미) type ViewName = 'valid' | 'bind' | 'output' | '$all' | string ; // 뷰 이름 type MappingType = { [ key : ColumnName ]: { [ key : CommandName ]: ViewName | ViewName [] // 명령 이름과 매핑된 뷰 목록 } }; // 서비스 타입 type ServiceType = { // 기본 서버 설정 url ?: string , baseConfig ?: axiosConfig, // 추가할 테이블 tables ?: string [], // 기본 콜백 함수 cbBaseBegin ?: ( model : BindModel , cmd : BindCommand ) => void ; cbBaseValid ?: ( view : MetaView , cmd : BindCommand , model : BindModel ) => boolean , cbBaseBind ?: ( view : MetaView , cmd : BindCommand , cfg : object ) => void , cbBaseResult ?: ( data : object , cmd : BindCommand , res : object ) => object , cbBaseOutput ?: ( outs : MetaViewCollection , cmd : BindCommand , res : object ) => void , cbBaseEnd ?: ( status : number , cmd : BindCommand , res : object ) => void , preRegister ?: ( bindModel ) => void , preCheck ?: ( bindModel ) => boolean , preReady ?: ( bindModel ) => void , // 공통 이벤트 onExecute ?: ( bm : BindModel , bc : BindCommand ) => void , onExecuted ?: ( bm : BindModel , bc : BindCommand ) => void , // 공통 속성 타입 (items) items ?: { [ key : string ]: ItemType }, // 명령 타입 command ?: CommandType , // 매핑 타입 mapping ?: MappingType , // 함수 타입 fn ?: { [ key : string ]: Function } }; 서비스 객체 주입 예제 js const bm = new BindModel (); const svc = { tables : [ 'second' ] }; // 서비스 객체 주입 bm. setService (svc); console . log (bm. second ); // [Object MetaTable \"second\"] 참조 : 서비스 객체 주입"},{"title":"BindModel","group":"API 레퍼런스","section":"setMapping()","url":"api/bind-model.html#setmapping","text":"setMapping() 지정된 명령(BindCommand)의 뷰(MetaView)에 컬럼을 매핑하는 메서드입니다. ts type CommandName = '$all' | string ; // 명령 이름 ('$all'은 모든 명령을 의미) type ViewName = 'valid' | 'bind' | 'output' | '$all' | string ; // 뷰 이름 type MappingType = { [ key : ColumnName ]: { [ key : CommandName ]: ViewName | ViewName [] // 명령 이름과 매핑된 뷰 목록 } }; declare function setMapping ( mapping : MappingType | PropertyCollection , baseTable ?: string | MetaTable ): void ; MappingType : 매핑 설정 객체 ColumnName : 매핑할 컬럼 이름 CommandName : 매핑할 명령 이름 ViewName : 매핑할 뷰 이름 ('$all', 'valid', 'bind', 'output', '추가한 뷰이름') PropertyCollection : 키(컬럼명)와 값(명령별 뷰 설정)의 컬렉션 baseTable(선택) : 매핑 작업을 수행할 기본 테이블 (기본값 _baseTable ) setMapping() 메서드는 컬럼을 지정한 명령의 뷰에 매핑하며, 이는 여러 컬럼의 매핑 작업을 일괄적으로 처리할 수 있습니다. 명령과 연계된 매핑 예제 js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. setMapping ({ 'username' : { cmd1 : 'valid' }, 'password' : { cmd1 : 'valid' , cmd2 : [ 'valid' , 'bind' ] } }); console . log (bm. command [ 'cmd1' ]. valid . cols [ 'username' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. valid . cols [ 'password' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd2' ]. valid . cols [ 'password' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd2' ]. bind . cols [ 'password' ]); // [Object HTMLColumn] cmd1 명령의 valid 뷰에 username 과 password 컬럼을 매핑합니다. cmd2 명령에서는 password 컬럼을 valid 와 bind 뷰에 매핑합니다. 두번째 테이블과 명령 매핑 js const bm = new BindModel (); bm. addTable ( 'second' ); bm. addCommand ( 'read1' ); bm. addCommand ( 'read2' ); bm. setMapping ({ aa : { $all : 'valid' }, bb : { $all : 'bind' }, 'second.cc' : { $all : 'output' } }); console . log (bm. first . columns . count ); // 2 console . log (bm. second . columns . count ); // 1 console . log (bm. command [ 'read1' ]. valid . cols [ 'aa' ]); // [Object HTMLColumn] console . log (bm. command [ 'read1' ]. bind . cols [ 'bb' ]); // [Object HTMLColumn] console . log (bm. command [ 'read1' ]. output . cols [ 'cc' ]); // [Object HTMLColumn] console . log (bm. command [ 'read2' ]. valid . cols [ 'aa' ]); // [Object HTMLColumn] console . log (bm. command [ 'read2' ]. bind . cols [ 'bb' ]); // [Object HTMLColumn] console . log (bm. command [ 'read2' ]. output . cols [ 'cc' ]); // [Object HTMLColumn] setMapping 메서드를 사용하여 두 개의 명령과 두 개의 테이블에 컬럼을 매핑합니다. 기본 테이블의 aa 와 bb 컬럼은 각각 valid 와 bind 뷰에 매핑됩니다. 두 번째 테이블의 cc 컬럼은 output 뷰에 매핑됩니다."},{"title":"BindModel","group":"API 레퍼런스","section":"init()","url":"api/bind-model.html#init","text":"init() BindModel 객체를 초기화하는 메서드입니다. ts declare function init ( ): void ; init() 메서드는 BindModel 객체를 초기화하는 데 사용됩니다. 초기화 과정에서 preRegister , preCheck , preReady 의 콜백 함수가 순차적으로 호출됩니다. preRegister 함수를 통해 필요한 명령 또는 컬럼 등을 추가하거나 설정합니다. preCheck 함수를 통해 초기화 전에 데이터와 실행환경의 유효성을 확인합니다. preReady 함수를 호출하여 초기화 완료 후의 후속 작업을 처리합니다. Tip : 초기화 과정은 필요에 따라 생략할 수 있으며, 서비스 객체를 주입하여 자동 검사할 때 사용됩니다. js const bm = new BindModel (); bm. preRegister = function ( model ) { console . log ( 'Registering the model...' ); }; bm. preCheck = function ( model ) { console . log ( 'Checking the model...' ); return true ; }; bm. preReady = function ( model ) { console . log ( 'Model is ready...' ); }; bm. init (); // Out: // 'Registering the model...' // 'Checking the model...' // 'Model is ready...' preRegister , preCheck , preReady 함수로 초기화 과정의 각 단계를 설정합니다. Tip : init()은 서비스 객체를 주입하여 자동화를 수행할 때 유용합니다."},{"title":"BindModel","group":"API 레퍼런스","section":"checkSelector()","url":"api/bind-model.html#checkselector","text":"checkSelector() selector 속성을 검사하여 유효하지 않은 항목을 반환하는 메서드입니다. ts type SelectorType = { key : string , type : string }; declare function checkSelector ( collection ?: ViewColumnCollection | TableColumnCollection , viewLog ?: boolean ): SelectorType []; collection(선택) : 유효성을 검사할 컬렉션 객체 (기본값 items ) viewLog(선택) : 검사 결과를 로그로 출력할지 여부 (기본값 false ) 반환값: 유효성 검사를 통과하지 못한 항목의 목록을 반환합니다. checkSelector() 메서드는 selector 속성의 유효성을 검사하여 올바르게 설정되지 않은 항목을 식별하는 데 사용됩니다. 기본 검사 대상으로 items 컬렉션을 검사합니다. selector 속성이 존재할 경우 key 에 대한 type 이 유효한지 검사합니다. 사용자가 지정한 컬렉션(예: columns)의 유효성을 검사할 수 있습니다. 참조 : HTMLColum 클래스 selector 속성 유효하지 않은 항목 확인 예제 js const bm = new BindModel (); // 아이템에 selector 객체 추가 bm. items . add ( 'username' , { selector : { key : 'input#username' , type : 'value' }}) // 검사 const failList = bm. checkSelector (); console . log (failList); // { key: 'input#username', type: 'value' } items 에 selector 속성이 포함된 username 의 유효성을 검사합니다. Tip : preCheck 콜백 함수를 사용하여 DOM 검사를 수행할 수 있습니다."},{"title":"BindModel","group":"API 레퍼런스","section":"getSelector()","url":"api/bind-model.html#getselector","text":"getSelector() 대상 컬렉션에 설정된 selector 객체를 반환하는 메서드입니다. ts type SelectorType = { key : string , type : string }; declare function getSelector ( collection ?: PropertyCollection ): SelectorType []; collection(선택) : selector 정보를 가져올 PropertyCollection 객체 (기본값 items ) 반환값: SelectorType 객체 배열을 반환합니다. getSelector() 메서드는 지정된 컬렉션에 설정된 selector 객체를 배열로 반환합니다. js const bm = new BindModel (); // 아이템 추가 bm. items . add ( 'u_name' , { selector : { key : 'input#u_name' , type : 'value' }}) bm. items . add ( 'passwd' , { selector : { key : 'input#passwd' , type : 'value' }}) // 조회 const list = bm. getSelector (); console . log (list); // Out: // [ // { selector: { key: 'input#u_name', type: 'value' }}, // { selector: { key: 'input#passwd', type: 'value' }} // ] getSelector() 메서드를 호출하여 설정된 모든 selector 객체를 배열 형태로 반환 받습니다."},{"title":"BindModel","group":"API 레퍼런스","section":"이벤트","url":"api/bind-model.html#이벤트-2","text":"이벤트"},{"title":"BindModel","group":"API 레퍼런스","section":"onExecute","url":"api/bind-model.html#onexecute","text":"onExecute 명령(BindCommand)이 실행되기 전에 호출되는 전역 이벤트 속성입니다. ts type onExecute = ( model : BindModel , cmd : BindCommand ) => void ; model : 실행 중인 BindModel 객체 cmd : 실행 중인 BindCommand 객체 onExecute 는 명령이 실행되기 전에 호출되는 전역 이벤트로, 모든 명령 실행 시 항상 작동합니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const bm = new BindModel (); // 이벤트 등록 bm. onExecute = function ( model, cmd ) { console . log ( 'Execute start...' ); }; // 명령 추가 및 실행 bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. execute (); 모든 명령(BindCommand) 실행 전에 콘솔에 'Execute start...' 메시지가 출력됩니다."},{"title":"BindModel","group":"API 레퍼런스","section":"onExecuted","url":"api/bind-model.html#onexecuted","text":"onExecuted 명령(BindCommand)이 실행된 후 호출되는 전역 이벤트 속성입니다. ts type onExecute = ( model : BindModel , cmd : BindCommand ) => void ; model : 실행 중인 BindModel 객체 cmd : 실행 중인 BindCommand 객체 onExecuted 는 명령이 성공적으로 실행된 후 호출되는 전역 이벤트로, 모든 명령 실행시 항상 작동합니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const bm = new BindModel (); // 이벤트 등록 bm. onExecuted = function ( model, cmd ) { console . log ( 'Execute End...' ); }; // 명령 추가 및 실행 bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. execute (); 모든 명령 실행 후에 콘솔에 'Execute End...' 메시지가 출력됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 CRUD + List 구현하기 다음 문서 BindCommand"},{"title":"BindCommand","group":"API 레퍼런스","section":"BindCommand","url":"api/bind-command.html","text":"문서 API 레퍼런스 API 레퍼런스 05 BindCommand 명령의 실행, 출력 옵션, 콜백과 뷰를 살펴봅니다. 한국어 문서 약 48분 각 명령에 대한 객체 역활을 수행하며 MetaView 와 콜백(hooking)함수로 구성되어 있으며 execute() 메서드 호출을 통해 실행됩니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"구성 요소","url":"api/bind-command.html#구성-요소","text":"구성 요소"},{"title":"BindCommand","group":"API 레퍼런스","section":"속성","url":"api/bind-command.html#속성","text":"속성 항목 설명 _baseTable BindCommand 객체의 기본 테이블입니다. _outputs 명령 실행 후 결과 데이터를 담고 있는 MetaView 컬렉션입니다. _model 명령(BindCommand) 객체가 속한 BindModel 객체를 가르킵니다. config 서버 요청에 필요한 정보를 설정합니다 (axios 설정) url 요청 경로를 정의합니다. outputOption 서버 응답 데이터를 처리하는 방식을 정의합니다. (기본값 = 0)<br>- 'SEND' : 안가져옴<br>- 'ALL' : 모든 column 및 rows 가져오기<br>- 'PICK' : 존재하는 column 의 rows 가져오기 <br>- 'VIEW' : 존재하는 column 의 rows 가져오기 + row값 value 설정 valid 데이터 유효성을 검사하는 데 사용되는 MetaView 입니다. bind 서버 요청 데이터를 정의하는 MetaView 입니다. output 서버 응답 데이터를 저장하는 MetaView 입니다. misc 기타 MetaView 입니다. (컬럼 그룹화에 활용) cbBegin 명령 실행 시 가장 먼저 호출되는 콜백 함수입니다. cbValid 유효성 검사 전에 호출되는 콜백 함수입니다. cbBind 명령 실행 시 데이터를 서버로 전송하기 전에 호출되는 콜백 함수입니다. cbResult 전송받은 서버 응답 데이터를 처리하는 콜백 함수입니다. cbOutput 명령 실행 후 서버 응답 데이터를 화면에 출력하는 콜백 함수입니다. cbEnd 명령 실행이 완료된 후 호출되는 콜백 함수입니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"메소드","url":"api/bind-command.html#메소드","text":"메소드 항목 설명 execute() 유효성 검사, 데이터 전송, 응답 처리를 수행합니다. addColumn() 테이블에 컬럼을 추가하고 뷰에 참조값을 등록합니다. addColumnValue() 테이블에 초기값과 함께 컬럼을 추가하고, 뷰에 참조값을 등록합니다. setColumn() 기존에 정의된 컬럼을 지정된 뷰에 설정합니다. release() 지정된 뷰에서 컬럼 설정을 해제합니다. newOutput() 새로운 출력 뷰를 생성합니다. removeOutput() 특정 출력 뷰를 삭제합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"이벤트","url":"api/bind-command.html#이벤트","text":"이벤트 항목 설명 onExecute 명령(BindCommand)이 실행되기 전에 호출되는 이벤트입니다. onExecuted 명령(BindCommand)이 실행된 후 호출되는 이벤트입니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"주요 속성","url":"api/bind-command.html#주요-속성","text":"주요 속성"},{"title":"BindCommand","group":"API 레퍼런스","section":"_baseTable","url":"api/bind-command.html#_basetable","text":"_baseTable BindCommand 객체의 기본 테이블 속성입니다. ts type _baseTable = MetaTable ; MetaTable : BindCommand의 기본 테이블 _baseTable 속성은 데이터를 관리하는 기본 테이블로, 명령과 컬럼 매핑의 중심 역할을 수행합니다. 컬럼 추가 및 설정 시 기본적으로 참조되는 테이블을 나타냅니다. 명령(BindCommand)이 속한 BindModel 객체의 테이블을 가르킵니다. 명령(BindCommand) 생성시 지정하거나, _baseTable 속성을 직접 변경할 수 있습니다. Tip : 관련 메소드 addColumn() : 컬럼 추가할 때 기본 테이블로 사용됩니다. addColumnValue() : 초기값을 포함된 컬럼을 추가할 때 기본 테이블로 사용됩니다. setColumn() : 컬럼 매핑 작업에서 기본 테이블로 사용됩니다. js const bm = new BindModel (); console . log (bm. _baseTable === bm. first ); // true console . log (bm. _baseTable === bm. _tables [ 'first' ]); // true console . log (bm. _baseTable === bm. _tables [ 0 ]); // true"},{"title":"BindCommand","group":"API 레퍼런스","section":"_outputs","url":"api/bind-command.html#_outputs","text":"_outputs 명령 실행 후 결과 데이터를 담고 있는 MetaView 컬렉션 속성입니다. ts type _outputs = MetaViewCollection ; MetaViewCollection : MetaView 객체 컬렉션 Tip : 복수 출력 뷰(MetaView)를 처리할 때 _outputs 를 사용하여 분리하여 관리할 수 있습니다. _outputs 속성은 명령 실행 결과 데이터를 저장하는 컬렉션입니다. _outputs[0] 은 항상 output 속성과 동일합니다. newOutput() 메서드를 사용하여 추가적인 출력 뷰를 생성할 수 있습니다. 참조 : addOutput() 메소드 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'list' ); // 출력 뷰 추가 bm. command [ 'list' ]. newOutput (); // 명령 실행 bm. command [ 'list' ]. execute (); console . log (bm. command [ 'list' ]. _outputs [ 0 ]); // [Object MetaView] *기본* console . log (bm. command [ 'list' ]. _outputs [ 1 ]); // [Object MetaView] *추가* _outputs[0] : 명령 실행 후 서버 응답 데이터를 가져오는 첫번째 MetaView입니다. _outputs[1] : newOutput() 으로 추가된 MetaView입니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"_model","url":"api/bind-command.html#_model","text":"_model 명령(BindCommand) 객체가 속한 BindModel 객체를 가르키는 속성입니다. ts type _model = BindModel ; BindModel : 명령이 속한 모델 객체 _model 속성은 명령 객체(BindCommand)가 속한 BindModel 객체를 참조합니다. Tip : _model 을 통해 BindModel 객체의 columns , command , _tables 속성에 접근할 수 있습니다. js const bm = new BindModel (); bm. addColumnValue ( 'u_id' , 'abc' ); bm. addCommand ( 'list' ); bm. command [ 'list' ]. cbBegin = function ( model, cmd ) { console . log (model. columns [ 'u_id' ]. value ); // Out: 'abc' }; model : 현재 명령이 속한 BindModel 객체를 참조합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"config","url":"api/bind-command.html#config","text":"config 서버 요청에 필요한 정보를 설정하는 속성입니다. ts type config = { method ?: 'GET' | 'POST' | 'PUT' | 'DELETE' , url ?: string , baseUrl ?: string , responseType ?: 'json' | 'text' | 'blob' }; method(선택) : HTTP 요청 방식 (기본값 'GET') url(선택) : 요청 경로 baseUrl(선택) : url 과 결합되는 기본 경로 (도메인) responseType(선택) : 서버 응답 데이터 형식 (기본값 'json') 추가 속성에 대한 자세한 내용은 Axios의 config 문서를 참조하세요. config 속성은 서버 요청의 설정을 관리하는 속성입니다. config 속성이 설정되지 않으면 BindModel 객체의 baseConfig 속성이 기본값으로 사용됩니다. config 속성은 axios 설정(config)의 역활을 수행하며 URL, HTTP 메서드, 응답 데이터 형식 등 주요 설정 값을 지정합니다. Tip : config 속성을 활용하여 인증 토큰 추가, 요청 데이터 포맷 지정, 서버와의 세부 통신 방식을 효율적으로 관리할 수 있습니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // 명령의 서버 요청 설정 bm. command [ 'cmd1' ]. config = { method : 'GET' , url : '/api/users' , headers : { Authorization : 'Bearer token123' }, timeout : 5000 }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); method : HTTP 메서드로 'GET'을 설정했습니다. url : 서버 요청 URL을 /api/users 로 설정했습니다. headers : 인증 토큰을 포함한 헤더를 설정했습니다. timeout : 요청 제한 시간을 5000ms로 설정했습니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"url","url":"api/bind-command.html#url","text":"url 요청 경로를 정의하는 속성입니다. ts type url = string ; string : 서버 요청 경로 url 속성은 서버 요청 경로의 역할을 합니다. url 은 config.url 속성의 참조값입니다. url 값을 설정하지 않으면 BindModel 객체의 url 속성이 기본값으로 사용됩니다. config.baseUrl 속성과 조합하여 전체 URL을 구성할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // URL 설정 bm. command [ 'cmd1' ]. url = '/api/data' ; bm. command [ 'cmd1' ]. execute (); execute() 실행시 /api/data 경로로 서버에 요청을 보냅니다. 동적 url 설정 예제 js const bm = new BindModel (); // 명령 및 컬럼 추가 bm. addCommand ( 'cmd1' ); bm. addColumnValue ( 'u_id' , 10 ); // 동적 URL 설정 bm. command [ 'cmd1' ]. cbBegin = function ( model, cmd ) { const userId = model. columns [ 'u_id' ]. value ; cmd. url = `/api/users/ ${userId} ` ; }; bm. command [ 'cmd1' ]. execute (); execute() 실행 시 동적으로 설정된 요청 경로로 서버에 요청을 보냅니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"outputOption 또는 outOpt","url":"api/bind-command.html#outputoption-또는-outopt","text":"outputOption 또는 outOpt 서버 응답 데이터를 처리하는 방식을 정의하는 속성입니다. 별칭으로 outOpt 참조 속성을 제공합니다. ts type outputOption = { option : 0 | 1 | 2 | 3 , index ?: number } | number ; option : 출력 데이터 처리 방식 0 : 데이터를 바인딩하지 않습니다. 1 : 모든 데이터를 가져옵니다. 2 : 정의된 컬럼과 매칭되는 데이터(row)만 가져옵니다. 3 : 특정 인덱스 데이터를 컬럼 값으로 설정합니다. index(선택) : option: 3 일 때, 값을 가져올 데이터의 인덱스 (기본값 0 ) number : outputOption.option 값을 설정 (0 ~ 3) outputOption 속성은 서버에서 반환된 데이터를 처리하는 방식을 설정하며, 데이터 바인딩 및 컬럼 값 설정을 제어할 수 있습니다. 인자값이 option = 0 이면, 데이터 바인딩이 비활성화됩니다. (기본값) 인자값이 option = 3 이면, index 에 지정한 데이터가 컬럼 value 값으로 설정됩니다. outputOption 직접 설정 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. addCommand ( 'cmd3' ); bm. addCommand ( 'cmd4' ); // 및 outputOption 설정 bm. command [ 'cmd2' ]. outputOption = 1 ; bm. command [ 'cmd3' ]. outOpt = { option : 2 } bm. command [ 'cmd4' ]. outputOption = { option : 3 , index : 2 }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); // option = 0, index = 0 bm. command [ 'cmd2' ]. execute (); // option = 1, index = 0 bm. command [ 'cmd3' ]. execute (); // option = 2, index = 0 bm. command [ 'cmd4' ]. execute (); // option = 3, index = 2 명령 추가시 outputOption 설정 예제 js const bm = new BindModel (); // 명령 추가 및 outputOption 설정 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' , 1 ); bm. addCommand ( 'cmd3' , { option : 2 }); bm. addCommand ( 'cmd4' , { option : 3 , index : 2 }); // 명령 실행 bm. command [ 'cmd1' ]. execute (); // option = 0, index = 0 bm. command [ 'cmd2' ]. execute (); // option = 1, index = 0 bm. command [ 'cmd3' ]. execute (); // option = 2, index = 0 bm. command [ 'cmd4' ]. execute (); // option = 3, index = 2 cmd1 명령: 기본값으로 설정되어 데이터 바인딩을 비활성화합니다 ( option: 0 ) cmd2 명령: 서버 응답의 모든 데이터를 가져옵니다 ( option: 1 ) cmd3 명령: 정의된 컬럼과 매칭되는 데이터만 가져옵니다 ( option: 2 ) cmd4 명령: 특정 인덱스(2)의 데이터(row)를 컬럼 값으로 설정합니다 ( option: 3 , index: 2 )"},{"title":"BindCommand","group":"API 레퍼런스","section":"valid","url":"api/bind-command.html#valid","text":"valid 데이터 유효성을 검사하는 데 사용되는 MetaView 속성입니다. ts type valid = MetaView ; MetaView : 데이터 유효성 뷰 참조 HTMLColumn 클래스 requred 속성 HTMLColumn 클래스 constraints 속성 HTMLColumn 클래스 valid() 메소드 valid(MetaView) 속성에 정의된 컬럼들의 제약조건(constraints)과 필수(required) 여부를 확인하여 데이터(value)의 유효성을 검사합니다. 서버 전송 전에 컬럼의 제약 조건( constraints )과 필수 조건( required )을 검사합니다. 유효성 검사에 실패한 경우, cbFail 콜백함수가 호출됩니다. Tip : 유효성 검사는 명령 실행시 첫단계에서 수행되며, 데이터 무결성을 보장합니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // 컬럼 추가 bm. command [ 'cmd1' ]. valid . columns . add ( 'u_id' ); bm. command [ 'cmd1' ]. valid . columns . add ( 'phone' ); // 위와 동일 // bm.command['cmd1'].addColumn('u_id', 'valid'); // bm.command['cmd1'].addColumn('phone', 'valid'); // 제약 조건 설정 bm. columns [ 'u_id' ]. required = true ; bm. columns [ 'phone' ]. constraints = { regex : /^\\d{10,11}$/ , msg : '전화번호는 10~11자리 숫자여야 합니다.' }; bm. command [ 'cmd1' ]. execute (); 명령 실행시 valid 속성에 정의된 컬럼의 유효성을 검사합니다. 컬럼의 required 속성과 constraints 속성을 기반으로 검증을 수행합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"bind","url":"api/bind-command.html#bind","text":"bind 서버 요청 데이터를 정의하는 MetaView 속성입니다. ts type bind = MetaView ; MetaView : 서버 요청 뷰 bind 속성은 명령 실행 시 서버로 데이터를 전송하는 데 사용됩니다. MetaView 에 설정된 컬럼과 value 값으로 요청 데이터를 구성하여 전송합니다. Tip: bind 는 서버와의 통신에서 데이터 전송의 핵심 역할을 하며, RESTful API 요청에 유용합니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // 컬럼 추가 bm. command [ 'cmd1' ]. bind . columns . add ( 'u_id' ); bm. command [ 'cmd1' ]. bind . columns . add ( 'email' ); bm. command [ 'cmd1' ]. bind . columns [ 'u_id' ]. value = 101 ; bm. command [ 'cmd1' ]. bind . columns [ 'email' ]. value = 'abc@gmail.com' ; // 위와 동일 // bm.command['cmd1'].addColumnValue('u_id', 101, 'bind'); // bm.command['cmd1'].addColumnValue('email', 'abc@gmail.com', 'bind'); bm. command [ 'cmd1' ]. execute (); bind 속성은 서버 요청 데이터를 관리하며, 명령 실행 시 전송 데이터를 구성합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"output","url":"api/bind-command.html#output","text":"output 서버 응답 데이터를 저장하는 MetaView 속성입니다. ts type output = MetaView ; MetaView : 서버 응답 데이터 뷰 output 속성은 서버 응답 데이터를 저장하는 MetaView 이며, 화면 표시나 데이터 처리를 위해 사용됩니다. outputOption 속성이 0 이면 경우에는 output 속성에 데이터를 가져오지 않습니다. cbOutput 콜백함수에서 output 데이터를 화면에 표시하는 후속 작업을 처리합니다. Tip : 복수의 출력을 처리하기 위해서는 newOuput() 메소드를 활용하여 처리합니다. 참조 : cbOutput 속성, newOutput() 메소드 js const bm = new BindModel (); // 명령 추가 : 첫번째 데이터(row)를 컬럼값에 설정 bm. addCommand ( 'cmd1' , 3 ); // 응답 데이터를 처리할 컬럼 추가 bm. command [ 'cmd1' ]. output . columns . add ( 'u_id' ); bm. command [ 'cmd1' ]. output . columns . add ( 'u_name' ); // 위와 동일 // bm.command['cmd1'].addColumn('u_id', 'output'); // bm.command['cmd1'].addColumn('u_name', 'output'); // 명령 실행 bm. command [ 'cmd1' ]. execute (); console . log (bm. columns [ 'u_id' ]); // [Object HTMLColumn] console . log (bm. command [ 'u_name' ]); // [Object HTMLColumn] cmd1 명령은 outputOption = 3 으로 설정하여 첫 번째 데이터를 컬럼값으로 저장합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"cbBegin","url":"api/bind-command.html#cbbegin","text":"cbBegin 명령 실행 시 가장 먼저 호출되는 콜백 함수 입니다. ts type cbBegin = ( model : BindModel , cmd : BindCommand ) => void ; model : 현재 모델(BindModel) 객체 입니다. cmd : 실행 중인 명령(BindCommand) 객체 cbBegin 속성은 명령 실행 흐름에서 첫 번째로 호출되는 콜백 함수입니다. 명령 실행 전에 필요한 설정을 동적으로 설정할 수 있습니다. (동적 경로 지정) 명령별로 cbBegin 콜백 함수가 없으면 cbBaseBegin 콜백 함수가 호출됩니다. js const bm = new BindModel (); // 명령 추가 및 컬럼 값 설정 bm. addCommand ( 'cmd1' ); bm. addColumnValue ( 'u_id' , 100 ); // 콜백 함수 설정 bm. command [ 'cmd1' ]. cbBegin = function ( model, cmd ) { const userId = model. columns [ 'u_id' ]. value ; cmd. url = `/api/users/ ${userId} ` ; }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); cbBegin 콜백함수에서 서버 전송 전에 u_id 컬럼값을 기반으로 URL을 동적으로 설정합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"cbValid","url":"api/bind-command.html#cbvalid","text":"cbValid 유효성 검사 전에 호출되는 콜백 함수 입니다. ts type cbValid = ( valid : MetaView , cmd : BindCommand , model : BindModel ) => boolean | undefined ; view : 유효성 검사를 수행할 대상인 MetaView 객체 cmd : 실행 중인 명령(BindCommand) 객체 model : 현재 모델(BindModel) 객체 입니다. 반환값: true : 유효성 검사를 통과하고 다음 단계로 진행합니다. false : 유효성 검사가 실패하며, cbFail 콜백이 호출됩니다. undefined : 유효성 검사가 실패하지만, cbFail 은 호출되지 않습니다. cbValid 속성은 명령 실행 중 데이터의 유효성을 검사하기 전에 호출되는 콜백함수입니다. 기본 유효성 검사 로직 외에 추가적인 검증 로직을 적용할 수 있습니다. 명령별로 cbValid 콜백 함수가 없으면 cbBaseValid 콜백 함수가 호출됩니다. 유효성 실패를 개별로 처리할 경우 cbValid 함수에 처리하고 undefined 를 반환합니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 컬럼 추가 및 뷰 매핑 bm. addColumnValue ( 'u_name' , 'John' , 'cmd1' , 'valid' ); // 콜백 함수 설정 bm. command [ 'cmd1' ]. cbValid = function ( view, cmd, model ) { const username = view. columns [ 'u_name' ]. value ; if (username. length < 5 ) { console . log ( '사용자 이름은 5자 이상이어야 합니다.' ); return false ; } return true ; }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); cbValid 콜백함수에서 valid 유효성 검사 전에 u_name 컬럼값을 검사합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"cbBind","url":"api/bind-command.html#cbbind","text":"cbBind 명령 실행 시 데이터를 서버로 전송하기 전에 호출되는 콜백 함수 입니다. ts type cbBind = ( bind : MetaView , cmd : BindCommand , config : object ) => void ; bind : 서버로 전송할 데이터를 포함하는 MetaView 객체 cmd : 실행 중인 명령(BindCommand) 객체 config : axios 요청 설정 객체 cbBind 속성은 명령 실행 중 서버 요청 데이터를 준비하기 위해 호출되는 콜백함수입니다. 서버로 데이터를 전송하기 전에 요청 설정을 동적으로 설정할 수 있습니다. 명령별로 cbBind 콜백 함수가 없으면 cbBaseBind 콜백 함수가 호출됩니다. Tip : 전송할 데이터의 암호화 또는 토큰 추가 등 데이터 포멧 변환에 활용할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'upload' ); // 컬럼 추가 및 뷰 매핑 bm. addColumnValue ( 'file_name' , 'file.txt' , 'upload' , 'bind' ); bm. addColumnValue ( 'file_size' , 2048 , 'upload' , 'bind' ); // 콜백 함수 설정 bm. command [ 'upload' ]. cbBind = function ( bind, cmd, config ) { config. headers = { 'Content-Type' : 'application/json' }; }; // 명령 실행 bm. command [ 'upload' ]. execute (); cbBind 콜백함수에서 서버 요청 데이터에 header 정보를 추가합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"cbResult","url":"api/bind-command.html#cbresult","text":"cbResult 전송받은 서버 응답 데이터를 처리하는 콜백 함수 입니다. ts type cbResult = ( data : object , cmd : BindCommand , response : object ) => object ; data : 서버에서 반환된 데이터 cmd : 실행 중인 명령(BindCommand) 객체 response : 원본 axios 응답 객체 반환값: 변환된 데이터를 반환하며, 이후 단계에서 사용되거나 cbOutput 에 전달됩니다. cbResult 속성은 서버에서 반환된 데이터를 MetaView 스키마 형식으로 변환할 때 사용되는 콜백 함수입니다. 내부적으로 반환된 데이터는 output 뷰의 read(data) 메서드로 전달됩니다. 명령별로 cbResult 콜백 함수가 없으면 cbBaseResult 콜백 함수가 호출됩니다. 참조 : MetaView 의 스키마 데이터 읽기 메소드, read() js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' , 1 ); // 콜백 함수 설정 bm. command [ 'cmd1' ]. cbResult = function ( data, cmd, response ) { return { rows : data. rows . filter ( product => product. inStock ) }; }; // 명령 실행 bm. command [ 'cmd1' ]. execute (); cbResult 콜백 함수에서 서버 응답 데이터를 변환하는 작업을 수행합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"cbOutput","url":"api/bind-command.html#cboutput","text":"cbOutput 명령 실행 후 서버 응답 데이터를 화면에 출력하는 콜백 함수 입니다. ts type cbOutput = ( outputs : MetaViewCollection , cmd : BindCommand , response : object ) => object ; outputs : 매핑된 데이터를 포함하는 MetaViewCollection 객체 outputs[0] 은 output 속성을 가르킵니다. outputs[뷰 이름] 또는 outputs[인덱스] 을 통해서 뷰에 접근합니다. cmd : 현재 실행 중인 BindCommand 객체 response : axios 응답 객체 cbOutput 속성는 명령 실행 시 output 뷰에 데이터를 매핑한 뒤 호출되는 콜백함수입니다. outputOption 속성이 1, 2, 3 일 경우에만 호출됩니다. 응답 데이터를 기반으로 화면에 출력하거나 로그를 기록합니다. 명령별로 cbOutput 콜백 함수가 없으면 cbBaseOutput 콜백 함수가 호출됩니다. Tip : newOutput('뷰이름') 메소드로 뷰를 추가할 수 있습니다. 참조 : 명령 복수 출력 구성 js const bm = new BindModel (); // 명령 추가 (1: 모든 데이터 가져오기) bm. addCommand ( 'cmd1' , 1 ); // 콜백 함수 설정 bm. command [ 'cmd1' ]. cbOutput = function ( outputs, cmd, response ) { const output = outputs[ 0 ]; // 첫번째 기본 MetaView output. rows . forEach ( product => { console . log ( `Product ID: ${product.u_id} , Name: ${product.name} ` ); }); }; bm. command [ 'cmd1' ]. execute (); // Product ID: ...., Name: .... cbOutput 콜백함수에서 매핑된 데이터 outputs[0] 뷰의 행(rows)을 출력합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"cbEnd","url":"api/bind-command.html#cbend","text":"cbEnd 명령 실행이 완료된 후 호출되는 콜백 함수 입니다. ts type cbEnd = ( status ?: number , cmd ?: BindCommand , response ?: object ) => void ; status(선택) : 명령 실행 결과를 나타내는 상태 코드 cmd(선택) : 현재 실행된 BindCommand 객체 response(선택) : 서버에서 반환된 응답 객체 cbEnd 속성은 명령 실행 후 최종 결과를 처리하는 콜백 함수입니다. 명령별로 cbEnd 콜백 함수가 없으면 cbBaseEnd 콜백 함수가 호출됩니다. Tip : 명령 실행 후 후속 작업을 수행하는데 활용할 수 있습니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 콜백 함수 설정 bm. command [ 'cmd1' ]. cbEnd = function ( status, cmd, response ) { if (status > 0 ) console . log ( '데이터 저장이 완료되었습니다.' ); else console . log ( '데이터 저장 중 오류가 발생했습니다.' ); }; bm. command [ 'cmd1' ]. execute (); cbEnd 콜백함수는 명령 실행 후 마지막으로 호출되어, 최종 상태를 처리합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"주요 메소드","url":"api/bind-command.html#주요-메소드","text":"주요 메소드"},{"title":"BindCommand","group":"API 레퍼런스","section":"exectue()  또는 exec()","url":"api/bind-command.html#exectue-또는-exec","text":"exectue() 또는 exec() 유효성 검사, 데이터 전송, 응답 처리를 수행하는 메서드입니다. 별칭으로 exec() 참조 메서드를 제공합니다. ts declare function execute ( ): Promise < void >; 반환값: Promise<void> . 명령 실행이 비동기 작업으로 처리되며, 완료 시 아무 값도 반환하지 않습니다. Promise 기반: 명령 실행 흐름을 비동기로 관리할 수 있어, 실행 완료 후 추가 작업을 체인으로 연결할 수 있습니다. execute() 메소드는 BindCommand 객체를 실행하는 메서드로, 다음과 같은 흐름으로 동작합니다: valid MetaView 속성을 기반으로 데이터의 유효성을 확인합니다. bind MetaView 속성을 사용하여 서버로 데이터를 전송합니다. 서버에서 반환된 데이터를 output MetaView에 매핑합니다. 단계별 콜백 함수를 호출합니다. (cbBegin, cbValid, cbBind, cbResult, cbOutput, cbEnd) Tip : execute() 메서드는 try 문으로 구성되어 있으며, catch 블럭에서 cbError 콜백 함수가 호출됩니다. 참조 : 5. 흐름 제어, 4. 실행 및 동기화 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 유효성 검사 및 서버 요청 추가 bm. command [ 'cmd1' ]. addColumn ( 'u_name' , [ 'valid' , 'bind' ]); // 값 및 제약 조건 설정 bm. columns [ 'u_name' ]. require = true ; bm. columns [ 'u_name' ]. value = 'John' ; // 명령 실행 bm. command [ 'cmd1' ]. execute (); u_name 컬럼은 유효성 검사( valid )와 서버 전송( bind ) 대상으로 설정합니다. 명령을 실행하여 유효성 검사, 데이터 전송, 응답 처리를 순차적으로 수행합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"addColumn()","url":"api/bind-command.html#addcolumn","text":"addColumn() 테이블에 컬럼을 추가하고 뷰에 참조값을 등록하는 메서드입니다. ts type ViewType = '$all' | 'valid' | 'bind' | 'output' | 'misc' | string ; declare function addColumn ( column : string | MetaColumn , views ?: ViewType | ViewType [], table ?: MetaTable | string ): void ; column : 추가할 컬럼의 이름(문자열) 또는 MetaColumn 객체 views(선택) : 컬럼을 매핑할 뷰를 이름 또는 이름 배열 '$all' : 모든 뷰 (기본값) 'valid' : 유효성 검사를 위한 뷰 'bind' : 서버 요청 데이터를 위한 뷰 'output' : 응답 데이터를 매핑하는 뷰 'misc' : 추가적인 뷰 string : 사용자 정의 출력 뷰 bTable(선택) : 컬럼을 추가할 MetaTable 객체 (기본값은 _baseTable ) addColumn() 메서드는 모델에 컬럼을 추가하고, 지정한 뷰에 참조값을 등록합니다. views 인자는 기본적으로 전체 뷰가 지정되어 있습니다. (기본값 $all ) 모든 뷰에 컬럼 추가 예제 js const bm = new BindModel (); // 명령 및 컬럼 추가 bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. addColumn ( 'u_name' ); // 위와 동일 // bm.command['cmd1'].addColumn('u_name', '$all'); console . log (bm. command [ 'cmd1' ]. valid . columns [ 'u_name' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. bind . columns [ 'u_name' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. output . columns [ 'u_name' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. misc . columns [ 'u_name' ]); // [Object HTMLColumn] u_name 컬럼은 모든 뷰( valid , bind , output , misc )에 참조값이 등록됩니다. 특정 뷰에만 컬럼 등록 예제 js // 컬럼 추가 및 뷰에 참조 등록 bm. command [ 'cmd1' ]. addColumn ( 'email' , 'valid' ); bm. command [ 'cmd1' ]. addColumn ( 'phone' , [ 'bind' , 'output' ]); console . log (bm. command [ 'cmd1' ]. valid . columns [ 'email' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. bind . columns [ 'phone' ]); // [Object HTMLColumn] console . log (bm. command [ 'cmd1' ]. output . columns [ 'phone' ]); // [Object HTMLColumn] email 컬럼을 valid 뷰에만 매핑하고, phone 컬럼은 bind 와 output 뷰에 매핑합니다. 사용자 정의 출력 뷰에 추가 예제 js // 출력 뷰 추가 bm. command [ 'cmd1' ]. newOutput ( 'out2' ); // 컬럼 추가 및 추가 출력 뷰에 참조 등록 bm. command [ 'cmd1' ]. addColumn ( 'address' , 'out2' ); console . log (bm. command [ 'cmd1' ]. out2 . columns [ 'address' ]); // [Object HTMLColumn] 추가된 출력 뷰( out2 )에 address 컬럼이 매핑됩니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"addColumnValue()","url":"api/bind-command.html#addcolumnvalue","text":"addColumnValue() 테이블에 초기값과 함께 컬럼을 추가하고, 뷰에 참조값을 등록하는 메서드입니다. ts type ViewType = '$all' | 'valid' | 'bind' | 'output' | 'misc' | string ; declare function addColumnValue ( columnName : string , value : any , views ?: ViewType | ViewType [], table ?: MetaTable | string ): void ; columnName : 추가할 컬럼의 이름 value : 초기값으로 설정할 데이터 views(선택) : 컬럼을 매핑할 뷰를 이름 또는 이름 배열 '$all' : 모든 뷰 (기본값) 'valid' : 유효성 검사를 위한 뷰 'bind' : 서버 요청 데이터를 위한 뷰 'output' : 응답 데이터를 매핑하는 뷰 'misc' : 추가적인 뷰 string[] : 사용자 정의 출력 뷰 bTable(선택) : 컬럼을 추가할 MetaTable 객체 (기본값은 _baseTable ) addColumn() 메서드는 컬럼을 추가하면서 초기값을 설정하고, 지정된 뷰에 참조값을 등록합니다. 컬럼을 추가하면서 초기값을 함께 지정할 수 있습니다. views 인자를 통해 컬럼이 어떤 뷰에서 매핑할지 지정할 수 있습니다. 모든 뷰에 컬럼 추가 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 컬럼 초기값으로 등록 bm. command [ 'cmd1' ]. addColumnValue ( 'u_name' , 'John' , [ '$all' ]); console . log (bm. command [ 'cmd1' ]. valid . columns [ 'u_name' ]. value ); // Out: 'John' console . log (bm. command [ 'cmd1' ]. bind . columns [ 'u_name' ]. value ); // Out: 'John' console . log (bm. command [ 'cmd1' ]. output . columns [ 'u_name' ]. value ); // Out: 'John' username 컬럼은 모든 뷰( valid , bind , output , misc )에 참조값이 등록됩니다. 특정 뷰에만 컬럼 등록 예제 js // 컬럼 추가 및 뷰에 매핑 bm. command [ 'cmd1' ]. addColumnValue ( 'email' , 'abc@gmail.com' , 'valid' ); bm. command [ 'cmd1' ]. addColumnValue ( 'phone' , '12345' , [ 'bind' , 'output' ]); console . log (bm. cmd [ 'cmd1' ]. valid . columns [ 'email' ]. value ); // Out: 'abc@gmail.com' console . log (bm. cmd [ 'cmd1' ]. bind . columns [ 'phone' ]. value ); // Out: 12345 console . log (bm. cmd [ 'cmd1' ]. output . columns [ 'phone' ]. value ); // Out: 12345 email 컬럼을 valid 뷰에만 매핑되고, phone 컬럼은 bind 와 output 뷰에 매핑됩니다. 사용자 정의 출력 뷰에 추가 예제 js // 출력 뷰 추가 bm. command [ 'cmd1' ]. newOutput ( 'out2' ); // 컬럼 추가 및 뷰에 매핑 bm. command [ 'cmd1' ]. addColumnValue ( 'address' , 'Home' , 'out2' ); console . log (bm. command [ 'cmd1' ]. out2 . columns [ 'address' ]. value ); // Out: 'Home' 추가된 출력 뷰( out2 )에 address 컬럼이 매핑됩니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"setColumn()","url":"api/bind-command.html#setcolumn","text":"setColumn() 기존에 정의된 컬럼을 지정된 뷰에 설정하는 메서드입니다. ts type ViewType = '$all' | 'valid' | 'bind' | 'output' | 'misc' | string ; declare function setColumn ( columnNames : string | string [], views : ViewType | ViewType [], table ?: MetaTable | string ): void ; columnNames : 설정할 컬럼의 이름 또는 이름 배열 views : 컬럼을 매핑할 뷰를 이름 또는 이름 배열 '$all' : 모든 뷰 (기본값) 'valid' : 유효성 검사를 위한 뷰 'bind' : 서버 요청 데이터를 위한 뷰 'output' : 응답 데이터를 매핑하는 뷰 'misc' : 추가적인 뷰 string[] : 사용자 정의 출력 뷰 bTable(선택) : 컬럼을 추가할 MetaTable 객체 (기본값은 _baseTable ) setColumn() 메서드는 기존에 정의된 컬럼을 지정한 뷰에 설정하는 메서드입니다. 특정 컬럼을 하나 이상의 뷰에 매핑합니다. (컬럼 참조값 등록) 다수의 컬럼을 동시에 설정할 수 있어 반복 작업을 줄일 수 있습니다. Tip : setColumn() 을 사용하면 데이터 처리 로직을 유연하게 구성할 수 있습니다. 단일 컬럼 설정 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); bm. addCommand ( 'cmd2' ); bm. addCommand ( 'cmd3' ); // 컬럼 추가 bm. columns . addValue ( 'aa' , 10 ); bm. columns . addValue ( 'bb' , 20 ); bm. columns . addValue ( 'cc' , 30 ); // 컬럼 참조 설정 bm. command [ 'cmd1' ]. setColumn ( 'aa' , 'output' ); console . log (bm. command [ 'cmd1' ]. output . columns [ 'aa' ]. value ); // Out: 10 컬럼 aa 를 output 뷰에 설정하고 값을 확인합니다. js // 컬럼 참조 설정 bm. command [ 'cmd2' ]. setColumn ([ 'bb' , 'cc' ], [ 'valid' , 'bind' ]); console . log (bm. command [ 'cmd2' ]. valid . columns [ 'bb' ]. value ); // Out: 20 console . log (bm. command [ 'cmd2' ]. bind . columns [ 'cc' ]. value ); // Out: 30 console . log (bm. command [ 'cmd2' ]. valid . columns [ 'bb' ]. value ); // Out: 20 console . log (bm. command [ 'cmd2' ]. bind . columns [ 'cc' ]. value ); // Out: 30 컬럼 bb 와 cc 를 각각 valid 와 bind 뷰에 설정합니다. js // 컬럼 참조 설정 bm. command [ 'cmd3' ]. setColumn ( 'aa' , '$all' ); // views 기본값 : '$all' console . log (bm. command [ 'cmd3' ]. valid . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. command [ 'cmd3' ]. bind . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. command [ 'cmd3' ]. output . columns [ 'aa' ]. value ); // Out: 10 컬럼 aa 를 모든 뷰( $all )에 설정합니다. 테이블 설정 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 테이블 추가 bm. addTable ( 'second' ); // 컬럼 추가 bm. columns . addValue ( 'aa' , 10 ); // 위와 동일 // bm.first.columns.addValue('aa', 10); bm. second . columns . addValue ( 'bb' , 20 ); // 컬럼 참조 설정 bm. command [ 'cmd1' ]. setColumn ([ 'aa' , 'second.bb' ], 'valid' ); console . log (bm. command [ 'cmd1' ]. valid . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. command [ 'cmd1' ]. valid . columns [ 'bb' ]. value ); // Out: 20 bm. cmd [ 'cmd1' ]. valid . columns [ 'aa' ] === bm. first . columns [ 'aa' ] // true bm. cmd [ 'cmd1' ]. valid . columns [ 'bb' ] === bm. second . columns [ 'bb' ] // true 첫 번째 테이블의 컬럼 aa 와 두 번째 테이블의 컬럼 bb 를 valid 뷰에 설정합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"release()","url":"api/bind-command.html#release","text":"release() 지정된 뷰에서 컬럼 설정을 해제하는 메서드입니다. ts type ViewType = '$all' | 'valid' | 'bind' | 'output' | 'misc' | string ; declare function release ( columnNames : string | string [], views : ViewType | ViewType [] ): void ; columnNames : 매핑을 해제할 컬럼의 이름 또는 이름 배열습니다. views : 매핑을 해제할 뷰 이름 또는 이름 배열 '$all' : 모든 뷰 'valid' : 유효성 검사를 위한 뷰 'bind' : 서버 요청 데이터를 위한 뷰 'output' : 응답 데이터를 매핑하는 뷰 'misc' : 추가적인 뷰 string[] : 사용자 정의 출력 뷰 release() 메서드는 컬럼 설정을 해제하는 메서드로, 지정된 뷰 또는 모든 뷰에 설정을 해제합니다. 한 번의 호출로 여러 컬럼의 매핑을 동시에 해제할 수 있습니다. Tip : release() 메서드는 뷰에서 참조된 컬럼을 간소화하여 해제하는 데 유용합니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 컬럼 추가 bm. columns . addValue ( 'aa' , 10 ); // 컬럼 매핑 bm. command [ 'cmd1' ]. setColumn ( 'aa' , '$all' ); console . log (bm. command [ 'cmd1' ]. valid . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. command [ 'cmd1' ]. bind . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. command [ 'cmd1' ]. output . columns [ 'aa' ]. value ); // Out: 10 console . log (bm. command [ 'cmd1' ]. misc . columns [ 'aa' ]. value ); // Out: 10 일부 컬럼 해제 예제 js // 컬럼 해제 bm. command [ 'cmd1' ]. release ( 'aa' , [ 'valid' , 'bind' ]); console . log (bm. command [ 'cmd1' ]. output . columns [ 'aa' ]. value ); // 10 특정 뷰( valid 와 bind )에서 컬럼 aa 의 참조값을 제거합니다. 모든 컬럼 해제 예제 js // 컬럼 해제 bm. command [ 'cmd1' ]. release ( 'aa' ); // 위와 동일 // bm.command['cmd1'].release('aa', '$all'); console . log (bm. command [ 'cmd1' ]. valid . columns . count ); // Out: 0 console . log (bm. command [ 'cmd1' ]. bind . columns . count ); // Out: 0 console . log (bm. command [ 'cmd1' ]. output . columns . count ); // Out: 0 console . log (bm. command [ 'cmd1' ]. misc . columns . count ); // Out: 0 모든 뷰에서 컬럼 aa 의 참조값을 해제합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"newOutput()","url":"api/bind-command.html#newoutput","text":"newOutput() 새로운 출력 뷰를 생성하는 메서드입니다. ts declare function newOutput ( viewName ?: string ): void ; viewName(선택) : 생성할 출력 뷰의 이름 newOutput() 메서드는 기본 출력 뷰 외에 추가적인 출력 뷰를 생성합니다. 출력 뷰의 저장 위치는 _outputs 컬렉션입니다. 기본 이름( 'output' + 순서 )이 할당되며, 선택적으로 이름을 추가할 수 있습니다. 뷰 이름은 현재 객체에 속성으로 추가되며, 예약어와 중복되지 않아야 합니다. Tip : 응답 데이터를 분리하여 각 뷰에서 개별적으로 관리할 수 있습니다. Tip : 예약어 목록 _baseTable , _output , _model , config , url , _guid , _type , $event , $KEYWORD , valid , bind , output , output1 , misc 기본뷰 뷰 추가 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); bm. command [ 'cmd1' ]. output === bm. command [ 'cmd1' ]. output1 // true 기본 출력 뷰( output )와 output1 는 동일한 뷰입니다. 지정한 이름으로 뷰 추가 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 출력 뷰 추가 bm. command [ 'cmd1' ]. newOutput ( 'info' ); bm. cmd [ 'cmd1' ]. output2 === bm. cmd [ 'cmd1' ]. info // true console . log (bm. command [ 'cmd1' ]. info ); // [Object MetaView] console . log (bm. command [ 'cmd1' ]. output2 ); // [Object MetaView] 출력 뷰를 추가하고, output2 와 custormView 뷰를 확인합니다. 빈 이름으로 뷰 추가 예제 js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 출력 뷰 추가 bm. command [ 'cmd1' ]. newOutput (); console . log (bm. command [ 'cmd1' ]. output2 ); // [Object MetaView] 이름을 지정하지 않고 출력 뷰를 추가하면, output3 속성의 뷰만 할당됩니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"removeOutput()","url":"api/bind-command.html#removeoutput","text":"removeOutput() 특정 출력 뷰를 삭제하는 메서드입니다. ts declare function removeOutput ( viewName : string ): boolean ; viewName : 제거할 출력 뷰의 이름 removeOutput() 메서드는 명령에서 생성된 특정 출력 뷰를 제거합니다. 지정이름과 함께 추가된 기본 이름은 같이 삭제됩니다. js const bm = new BindModel (); // 명령 추가 bm. addCommand ( 'cmd1' ); // 출력 뷰 추가 bm. command [ 'cmd1' ]. newOutput ( 'customView' ); console . log (bm. command [ 'cmd1' ]. customView ); // [Object MetaView] console . log (bm. command [ 'cmd1' ]. output2 ); // [Object MetaView] // 출력 뷰 제거 bm. command [ 'cmd1' ]. removeOutput ( 'customView' ); console . log (bm. command [ 'cmd1' ]. customView ); // Out: undefined console . log (bm. command [ 'cmd1' ]. output2 ); // Out: undefined 출력 뷰 customView 를 생성한 후 제거하여 해당 뷰가 삭제되었는지 확인합니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"이벤트","url":"api/bind-command.html#이벤트-2","text":"이벤트"},{"title":"BindCommand","group":"API 레퍼런스","section":"onExecute","url":"api/bind-command.html#onexecute","text":"onExecute 명령(BindCommand)이 실행되기 전에 호출되는 이벤트 속성입니다. ts type onExecute = ( model : BindModel , cmd : BindCommand ) => void ; model : 실행 중인 BindModel 객체 cmd : 실행 중인 BindCommand 객체 onExecute 는 명령이 실행되기 전에 호출되며, 실행 전 필요한 작업을 수행하는 이벤트입니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // 이벤트 등록 bm. command [ 'cmd1' ]. onExecute = function ( model, cmd ) { console . log ( 'Execute start...' ); }; bm. command [ 'cmd1' ]. execute (); 명령 실행 전에 콘솔에 'Execute...start' 메시지가 출력됩니다."},{"title":"BindCommand","group":"API 레퍼런스","section":"onExecuted","url":"api/bind-command.html#onexecuted","text":"onExecuted 명령(BindCommand)이 실행된 후 호출되는 이벤트 속성입니다. ts type onExecute = ( model : BindModel , cmd : BindCommand ) => void ; model : 실행 중인 BindModel 객체 cmd : 실행 중인 BindCommand 객체 onExecuted 는 명령이 성공적으로 실행된 후 호출되며, 실행 후 작업을 수행하는 이벤트입니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const bm = new BindModel (); bm. addCommand ( 'cmd1' ); // 이벤트 등록 bm. command [ 'cmd1' ]. onExecuted = function ( model, cmd ) { console . log ( 'Execute End...' ); }; bm. command [ 'cmd1' ]. execute (); 명령 실행 후 콘솔에 'Execute End...' 메시지가 출력됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 BindModel 다음 문서 MetaView"},{"title":"MetaView","group":"API 레퍼런스","section":"MetaView","url":"api/meta-view.html","text":"문서 API 레퍼런스 API 레퍼런스 05 MetaView 참조 컬럼으로 데이터를 구성하고 입출력을 관리합니다. 한국어 문서 약 49분 MetaView는 데이터를 컬럼(column) 과 행(row) 으로 구성하는 객체입니다. 명령(BindCommand) 객체의 valid, bind, output, misc 속성에서 사용됩니다."},{"title":"MetaView","group":"API 레퍼런스","section":"MetaView와 MetaTable 과의 차이점","url":"api/meta-view.html#metaview와-metatable-과의-차이점","text":"MetaView와 MetaTable 과의 차이점 MetaTable은 독립 데이터 관리 에 초점을 맞춘 구조로 설계되었습니다. 데이터 변경을 효과적으로 처리하기 위해 트랜잭션 관련 메서드(acceptChanges(), rejectChanges(), getChanges())를 제공하여 데이터의 상태를 추적하고 변경 사항을 관리할 수 있습니다. 반면, MetaView는 참조 관리 가 가능한 구조적 차별점을 가지고 있습니다. columns 컬렉션에 컬럼의 참조값을 등록할 수 있어 동일한 데이터를 여러 뷰에서 공유하거나, 필요에 따라 독립적으로 처리할 수 있는 유연성을 제공합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"구성 요소","url":"api/meta-view.html#구성-요소","text":"구성 요소"},{"title":"MetaView","group":"API 레퍼런스","section":"속성","url":"api/meta-view.html#속성","text":"속성 항목 설명 _baseEntity 컬럼을 추가 시 기준이 될 엔티티를 지정합니다. viewName MetaView 이름을 나타냅니다. columns 컬럼을 정의하는 컬렉션입니다. rows 데이터를 행(Row) 단위로 관리하는 컬렉션입니다."},{"title":"MetaView","group":"API 레퍼런스","section":"메소드","url":"api/meta-view.html#메소드","text":"메소드 항목 설명 clone() 객체를 복제하여 새로운 객체를 생성합니다. copy() 특정 조건에 만족하는 컬럼 구조의 데이터를 복사합니다. clear() rows 컬렉션의 데이터를 초기화합니다. reset() columns 컬렉션과 rows 컬렉션을 초기화합니다. newRow() 컬럼 구조에 맞는 새로운 데이터 행(row)을 생성합니다. getValue() 현재 컬럼값(value)을 기반으로 데이터(row)를 반환합니다. setValue() 컬럼 값(value)을 지정된 데이터(row)로 설정합니다. merge() 다른 MetaView 객체의 데이터를 현재 객체에 병합합니다. select() 조건에 맞는 행을 필터링하거나 특정 컬럼 데이터를 반환합니다. output() 데이터를 직렬화된 문자열 또는 특정 형식으로 내보냅니다. load() 직렬화된 객체를 로드하여 컬럼과 행 데이터를 구성합니다. write() 현재 객체를 스키마 타입의 객체로 변환하여 반환합니다. writeSchema() 현재 객체의 컬럼 정보를 스키마 타입의 객체로 변환하여 반환합니다. writeData() 현재 객체의 행(데이터)을 스키마 타입의 객체로 변환하여 반환합니다. read() MetaView 스키마 타입 객체를 읽어옵니다. readSchema() MetaView 스키마 타입 객체의 컬럼(구조) 정보를 읽어옵니다. readData() MetaView 스키마 타입 객체의 행(데이터) 정보를 읽어옵니다."},{"title":"MetaView","group":"API 레퍼런스","section":"데이터 입출력 메서드 정리","url":"api/meta-view.html#데이터-입출력-메서드-정리","text":"데이터 입출력 메서드 정리 InPut 설명 OutPut 설명 load(str) 직렬화(문자열) 불러오기 output(): str 직렬화(문자열) 내보내기 read(obj) 읽기 (스키마 + 데이터) write(): obj 쓰기 (스키마 + 데이터) readSchema(obj) 스키마 읽기 writeSchema(): obj 스키마 쓰기 readData(obj) 데이터 읽기 writeData(): obj 데이터 쓰기"},{"title":"MetaView","group":"API 레퍼런스","section":"주요 속성","url":"api/meta-view.html#주요-속성","text":"주요 속성"},{"title":"MetaView","group":"API 레퍼런스","section":"_baseEntity","url":"api/meta-view.html#_baseentity","text":"_baseEntity 컬럼을 추가 시 기준이 될 엔티티를 지정하는 속성입니다. ts type _baseEntity = MetaTable | MetaView ; _baseEntity 속성을 설정한 후 컬럼을 추가하면, 지정된 엔티티에 컬럼이 등록되며, 현재 객체에는 해당 컬럼을 참조하는 컬럼이 등록됩니다. 참조 컬럼 방식: _baseEntity 을 지정한 경우, 추가된 컬럼은 참조값이 등록됩니다. 독립 컬럼 방식: _baseEntity 을 지정하지 않으면, 컬럼이 뷰에 독립적으로 생성됩니다. 전체 참조 예제 js const table1 = new MetaTable ( 't1' ); const view1 = new MetaView ( 'v1' ); // 기본 엔티티 설정 view1. _baseEntity = table1; view1. columns . add ( 'u_id' ); view1. columns . add ( 'addr' ); view1. columns [ 'u_id' ] === table1. columns [ 'u_id' ] // true view1. columns [ 'addr' ] === table1. columns [ 'addr' ] // true view1 추가된 컬럼( id , addr )은 table1 에 컬럼이 추가되고, 참조값이 view1 에 등록됩니다. 특정 컬럼만 참조 예제 js const table1 = new MetaTable ( 't1' ); const view1 = new MetaView ( 'v1' ); view1. columns . add ( 'u_id' , table1. columns ); // 컬럼 추가 시 컬렉션 지정 view1. columns . add ( 'addr' ); view1. columns [ 'u_id' ] === table1. columns [ 'u_id' ] // true console . log (view1. columns [ 'addr' ]); // [Object MetaColumn] view1 에 u_id 컬럼은 참조로 등록되고, addr 컬럼은 독립적으로 추가됩니다. HTMLColumn 은 MetaColumn 의 자식 클래스 입니다. 독립 사용 예제 js const view1 = new MetaView ( 'v1' ); view1. columns . addValue ( 'addr' , 'USA' ); console . log (view1. columns [ 'addr' ]. value ); // Out: 'USA' view1 에 addr 컬럼을 독립적으로 추가합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"viewName","url":"api/meta-view.html#viewname","text":"viewName MetaView 이름을 나타내는 속성입니다. ts type viewName = string ; string : 뷰 이름 문자열 Tip : _name 속성과 동일한 값을 가집니다. viewName 속성은 MetaView의 이름을 나타내며, 이를 통해 객체를 식별하고 관리할 수 있습니다. viewName 속성을 변경하면 상위 속성인 _name 도 함께 변경됩니다. js const view1 = new MetaView ( 'v1' ); console . log (view1. viewName ); // Out: 'v1' console . log (view1. _name ); // Out: 'v1' view1. viewName = 'v2' ; // 이름 변경 console . log (view1. viewName ); // Out: 'v2' console . log (view1. _name ); // Out: 'v2' viewName 속성을 업데이트합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"columns 또는 cols","url":"api/meta-view.html#columns-또는-cols","text":"columns 또는 cols 컬럼을 정의하는 컬렉션 속성입니다. 별칭으로 cols 속성을 제공합니다. ts type columns = MetaViewColumnCollection ; MetaViewColumnCollection : MetaColumn 객체 컬렉션 참조 : MetaViewColumnCollection API columns 속성은 컬럼을 정의하는 컬렉션으로, add() 메서드를 사용하여 컬럼을 등록하거나 컬렉션을 제어할 수 있습니다. 정의된 컬럼에 따라 행(row)의 구조가 결정됩니다. 등록되는 컬럼은 독립적으로 생성되거나 참조값을 가질 수 있습니다. 컬럼 추가 예제 js const view1 = new MetaView ( 'v1' ); // 빈 컬럼 추가 view1. columns . add ( 'u_id' ); // 초기값이 있는 컬럼 추가 view1. columns . addValue ( 'addr' , 'USA' ); console . log (view1. columns [ 'u_id' ]); // [Object MetaColumn] console . log (view1. columns [ 'addr' ]. value ); // 'USA' add() 메서드를 사용하여 빈 컬럼을 추가합니다. addValue() 메서드를 사용하여 초기값이 있는 컬럼을 추가합니다. BindModel 에서 컬럼 추가 예제 js const bm = new BindModel (); // 기본 컬렉션에서 컬럼 추가 bm. columns . add ( 'gender' ); bm. columns . addValue ( 'addr' , 'USA' ); // 모델에서 컬럼 추가 bm. addColumn ( 'memo' ); bm. addColumnValue ( 'age' , 20 ); console . log (view1. columns [ 'gender' ]); // [Object MetaColumn] console . log (view1. columns [ 'addr' ]. value ); // Out: 'USA' console . log (view1. columns [ 'memo' ]); // [Object MetaColumn] console . log (view1. columns [ 'age' ]. value ); // Out: 20 columns 컬렉션을 사용하거나 addColumn() addColumnValue() 메소드를 통해 컬럼을 추가할 수 있습니다. 컬럼 참조 사용 예제 js const table1 = new MetaTable ( 't1' ); const view1 = new MetaView ( 'v1' ); view1. columns . add ( 'u_name' , table1. columns ); // 컬럼 추가 시 컬렉션 지정 view1. columns . add ( 'addr' ); view1. columns [ 'u_name' ] === table1. columns [ 'u_name' ] // true console . log (view1. columns [ 'addr' ]); // [Object MetaColumn] view1 에 u_name 컬럼은 참조로 등록되고, addr 컬럼은 독립적으로 추가됩니다. 참조 : HTMLColumn API"},{"title":"MetaView","group":"API 레퍼런스","section":"rows","url":"api/meta-view.html#rows","text":"rows 데이터를 행(Row) 단위로 관리하는 컬렉션 속성입니다. ts type rows = MetaRowCollection ; MetaRowCollection : 행 객체들의 컬렉션 rows 컬렉션은 뷰의 데이터를 관리하는 데 사용되며, 각 행은 개별 컬럼 데이터를 포함합니다. 컬렉션의 add() 메소드를 사용하여 행(row)을 추가할 수 있습니다. 행(row)을 추가한 후에는 컬럼을 추가하거나 제거할 수 없습니다. (제약조건) js const view1 = new MetaView ( 'v1' ); // 컬럼 추가 view1. columns . add ( 'u_name' ); view1. columns . add ( 'age' ); // 행 추가 const row = view1. newRow (); row[ 'u_name' ] = 'John' ; row[ 'age' ] = 20 ; view1. rows . add (row); console . log (view1. rows [ 0 ][ 'u_name' ]); // Out: 'John' console . log (view1. rows [ 0 ][ 'age' ]); // Out: 20 newRow() 메서드를 사용하여 새로운 행을 생성하고, 데이터를 설정합니다. 생성된 행을 rows 컬렉션에 add() 메서드를 통해 추가합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"주요 메소드","url":"api/meta-view.html#주요-메소드","text":"주요 메소드"},{"title":"MetaView","group":"API 레퍼런스","section":"clone()","url":"api/meta-view.html#clone","text":"clone() 객체를 복제하여 새로운 객체를 생성하는 메서드입니다. ts declare function clone ( ): MetaView ; 반환값: 복제된 새로운 MetaView 객체 clone() 메서드는 객체의 현재 상태를 그대로 복제하여 새로운 MetaView 객체를 생성합니다. 복제된 객체는 원본과 독립적으로 동작하며, 동일한 속성을 유지합니다. js const view1 = new MetaView ( 'v1' ); view1. columns . addValue ( 'age' , 20 ); // 뷰 복제 const clone = view1. clone (); consol. log (clone. viewName ); // Out: 'v1' clone. columns [ 'age' ] === view1. columns [ 'age' ] // false clone. columns [ 'age' ]. value === view1. columns [ 'age' ]. value // true 복제된 객체는 원본과 독립적으로 동작하며, 동일한 구조와 속성을 가집니다."},{"title":"MetaView","group":"API 레퍼런스","section":"copy()","url":"api/meta-view.html#copy","text":"copy() 특정 조건에 만족하는 컬럼 구조의 데이터를 복사하는 메서드입니다. ts declare function copy ( filter : (row, idx, view) => boolean | string [] | arguments < string >, colNames ?: string [] | arguments < string > ): MetaView ; filter : 필터 콜백함수 또는 대상 컬럼명 함수 : 행( row ), 인덱스( idx ), 원본 뷰( view )를 매개변수로 받아 boolean 타입을 반환합니다. string[] : 특정 컬럼명만 복사합니다. arguments<string> : 매개변수 형태로 전달된 컬럼명을 복사합니다. colNames(선택) : 복사 대상의 컬럼명 또는 컬럼 문자열 배열 또는 arguments<string> 형태 반환값: 데이터를 복사한 새로운 MetaView 객체를 반환합니다. copy() 메서드는 현재 객체에서 특정 조건에 만족하는 컬럼과 데이터를 복사하여 새로운 객체로 반환합니다. 컬럼명을 배열 또는 인자로 전달하여 복사할 대상 컬럼을 지정할 수 있습니다. filter 함수를 사용하여 조건에 만족하는 행(row)을 선택할 수 있습니다. js const view1 = new MetaView ( 'view1' ); // 컬럼 추가 view1. columns . add ( 'c1' ); view1. columns . add ( 'c2' ); view1. columns . add ( 'c3' ); // 행 추가 view1. rows . add (view1. newRow ()); view1. rows [ 0 ][ 'c1' ] = 1 ; view1. rows [ 0 ][ 'c2' ] = 2 ; view1. rows [ 0 ][ 'c3' ] = 3 ; view1. rows . add (view1. newRow ()); view1. rows [ 1 ][ 'c1' ] = 10 ; view1. rows [ 1 ][ 'c2' ] = 20 ; view1. rows [ 1 ][ 'c3' ] = 30 ; // 첫번째 복사 const copy1 = view1. copy ( row => row[ 'c1' ] < 10 , [ 'c1' ]); console . log (copy1. rows . count ); // Out: 1 console . log (copy1. rows [ 0 ][ 'c1' ]); // Out: 1 // 두번째 복사 const copy2 = view1. copy ([ 'c1' , 'c2' ]); console . log (copy2. rows [ 0 ][ 'c1' ]); // Out: 1 console . log (copy2. rows [ 0 ][ 'c2' ]); // Out: 2 console . log (copy2. rows [ 1 ][ 'c1' ]); // Out: 10 console . log (copy2. rows [ 1 ][ 'c2' ]); // Out: 20 첫번째 copy1 뷰에는 c1 값이 10 보다 작은 특정 컬럼( 'c1'] )만 복사합니다. 두번째 copy2 뷰에는 특정 컬럼( ['c1', 'c2'] )만 복사합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"clear()","url":"api/meta-view.html#clear","text":"clear() rows 컬렉션의 데이터를 초기화하는 메서드입니다. ts declare function clear ( ): void ; • 반환값: 없음 clear() 메서드는 모든 행(row) 데이터를 초기화하며, 컬럼 정의는 유지합니다. js const view = new MetaView ( 'v1' ); // 컬럼 추가 view. columns . add ( 'age' ); view. columns . add ( 'u_name' ); // 데이터(행) 추가 view. rows . add (view. newRow ()); view. rows [ 0 ]. age = 10 ; view. rows [ 0 ]. u_name = 'Alice' ; view. rows . add (view. newRow ()); view. rows [ 1 ]. age = 20 ; view. rows [ 1 ]. u_name = 'Bob' ; console . log (view. rows . count ); // Out: 2 // 데이터 초기화 view. clear (); console . log (view. rows . count ); // Out: 0 console . log (view. columns . count ); // Out: 2 clear()를 호출하면 컬럼 정의는 유지되며, 모든 데이터만 초기화됩니다."},{"title":"MetaView","group":"API 레퍼런스","section":"reset()","url":"api/meta-view.html#reset","text":"reset() columns 컬렉션과 rows 컬렉션을 초기화하는 메서드입니다. ts declare function reset ( ): void ; reset() 메서드는 MetaView 객체의 컬럼과 데이터 행(row)을 초기 상태로 재설정하여 구조와 데이터를 모두 삭제합니다. js const view = new MetaView ( 'v1' ); // 컬럼 추가 view. columns . add ( 'age' ); view. columns . add ( 'u_name' ); // 데이터(행) 추가 view. rows . add (view. newRow ()); view. rows [ 0 ]. age = 10 ; view. rows [ 0 ]. u_name = 'Alice' ; // 전체 초기화 view. reset (); console . log (view. viewName ); // Out: 'v1' console . log (view. rows . count ); // Out: 0 console . log (view. columns . count ); // Out: 0 reset() 메서드를 호출하여 컬럼 정의와 데이터 행( rows )을 모두 초기화합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"newRow()","url":"api/meta-view.html#newrow","text":"newRow() 컬럼 구조에 맞는 새로운 데이터 행(row)을 생성하는 메서드입니다. ts declare function newRow ( ): MetaRow ; 반환값: 생성된 빈 데이터 행( MetaRow ) 객체 newRow() 메서드는 MetaView 객체의 컬럼 정의를 기반으로 초기화된 새로운 데이터 행을 반환합니다. 각 행의 초기값은 개별 컬럼의 default 속성값을 가집니다. (초기값) 컬럼에 alias 속성이 지정되어 있으면, 별칭이 행(row)의 키로 구성됩니다. js const view = new MetaView ( 'v1' ); // 컬럼 추가 view. columns . add ( 'id' ); view. columns . add ( 'name' ); // 데이터(행) 추가 const row = view. newRow (); row[ 'age' ] = 20 ; row[ 'u_name' ] = 'Alice' ; view. rows . add (row); console . log (view. rows [ 0 ][ 'age' ]); // Out: 20 console . log (view. rows [ 0 ][ 'u_name' ]); // Out: 'Alice' newRow() 메서드로 생성된 행은 컬럼 이름을 키로 가지며, default 값으로 초기화됩니다. 생성된 데이터 행(row)은 rows 컬렉션에 추가할 수 있습니다."},{"title":"MetaView","group":"API 레퍼런스","section":"getValue()","url":"api/meta-view.html#getvalue","text":"getValue() 현재 컬럼값(value)을 기반으로 데이터(row)를 반환하는 메서드입니다. ts declare function getValue ( ): MetaRow ; 반환값: 현재 컬럼 값이 포함된 데이터 행( MetaRow ) 객체 getValue() 메서드는 모든 컬럼 값(value)을 포함하는 하나의 데이터 행(row)을 반환합니다. 컬럼에 alias 속성이 지정되어 있으면, 별칭이 행의 키로 구성되어 value 속성값을 포함합니다. 컬럼값(value)이 설정되지 않은 경우, default 속성값을 가집니다. Tip : setValue() 메소드를 사용하여 데이터(row)를 컬럼 값(value)으로 설정할 수 있습니다. js const view = new MetaView ( 'v1' ); // 컬럼 추가 view. columns . addValue ( 'age' , 20 ); view. columns . add ( 'u_name' ); const row = view. getValue (); console . log (row[ 'age' ]); // Out: 20 console . log (row[ 'u_name' ]); // Out: '' getValue() 메서드는 현재 컬럼 값(value)으로 구성된 데이터 행을 반환합니다. 설정되지 않은 u_name 컬럼은 default 속성값을 가집니다. (default 기본값은 공백)"},{"title":"MetaView","group":"API 레퍼런스","section":"setValue()","url":"api/meta-view.html#setvalue","text":"setValue() 컬럼 값(value)을 지정된 데이터(row)로 설정하는 메서드입니다. ts declare function setValue ( row : MetaRow ): void ; row : 설정할 데이터가 포함된 MetaRow 객체 setValue() 메서드는 데이터 행(row)을 사용하여 컬럼 값(value)을 설정합니다. 행(row)의 키는 컬럼 이름에 매칭하여, alias 속성이 설정된 경우 이를 우선적으로 적용합니다. 다른 엔티티의 행(row)인 경우에도 컬럼명 매칭 기준에 따라 컬럼 값을 가져올 수 있습니다. js const view = new MetaView ( 'v1' ); // 컬럼 추가 view. columns . add ( 'age' ); view. columns . add ( 'u_name' ); view. columns [ 'u_name' ]. alias = 'r_name' ; // 별칭 설정 // 행 생성 const row = view. newRow (); row[ 'age' ] = 20 ; row[ 'r_name' ] = 'Alice' ; // 컬럼값 설정 view. setValue (row); // 행 추가 view. rows . add (row); console . log (view. columns [ 'age' ]. value ); // Out: 20 console . log (view. columns [ 'u_name' ]. value ); // Out: 'Alice' console . log (view. rows [ 0 ][ 'age' ]); // Out: 20 console . log (view. rows [ 0 ][ 'r_name' ]); // Out: 'Alice' setValue() 메서드를 사용하여 행( row ) 데이터를 설정하며, alias 속성이 설정된 경우 해당 alias 속성을 기준으로 값을 설정합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"merge()","url":"api/meta-view.html#merge","text":"merge() 다른 MetaView 객체의 데이터를 현재 객체에 병합하는 메서드입니다. ts declare function merge ( target : MetaTable | MetaView , option : number , matchType ?: boolean ): void ; target : 병합할 데이터를 포함한 원본 MetaTable 또는 MetaView 객체 option : 병합 방식을 지정하는 숫자형 옵션 0 : 로우( idx ) 기준 병합, 초과 컬럼은 무시됩니다. 1 : 컬럼( key ) 기준 병합, 초과 로우는 무시됩니다. 2 : 로우( idx ) 기준 병합, 초과 컬럼은 채워집니다. 3 : 컬럼( key ) 기준 병합, 초과 로우는 채워집니다. matchType(선택) : 행 유효성 검사 여부 (기본값 false ) merge() 메서드는 두 데이터 구조를 병합하며, 병합 방식과 유효성 검사 옵션을 조합하여 다양한 데이터를 처리할 수 있습니다. 병합 방식은 옵션( option )을 통해 로우( idx ) 또는 컬럼( key ) 기준으로 동작합니다. matchType 을 활성화하면 컬럼 제약 조건을 확인 후 데이터 병합을 수행하며, 실패 시 예외를 발생시킵니다. 데이터 병합 중 초과된 컬럼 또는 로우를 무시하거나 채우는 동작은 옵션 값에 따라 결정됩니다. 병합 옵션 0 - 로우 기준 병합, 초과 컬럼 무시 컬럼 매칭 예제 js const view1 = new MetaView ( 'v1' ); const view2 = new MetaView ( 'v2' ); // 데이터 행(row) 읽기 : read opt = 3 view1. read ({ rows : [{ c1 : 'R1' , c2 : 'R2' }] }, 3 ); view2. read ({ rows : [{ c1 : 'R10' , c2 : 'R20' }] }, 3 ); // 병합 opt = 0 view1. merge (view2, 0 ); console . log (view1. columns . count ); // Out: 2 console . log (view1. rows . count ); // Out: 2 console . log (view1. rows [ 0 ][ 'c1' ]); // Out: 'R1' console . log (view1. rows [ 0 ][ 'c2' ]); // Out: 'R2' console . log (view1. rows [ 1 ][ 'c1' ]); // Out: 'R10' console . log (view1. rows [ 1 ][ 'c2' ]); // Out: 'R20' option = 0 으로 설정하면, 행(row) 기준으로 매칭되는 컬럼만 병합됩니다. 컬럼 일부 매칭 예제 js const view1 = new MetaView ( 'v1' ); const view2 = new MetaView ( 'v2' ); // 데이터 행(row) 읽기 : read opt = 3 view1. read ({ rows : [{ c1 : 'R1' , c2 : 'R2' }] }, 3 ); view2. read ({ rows : [{ c1 : 'R10' , c3 : 'R30' }] }, 3 ); // 병합 opt = 0 view1. merge (view2, 0 ); console . log (view1. columns . count ); // Out: 2 console . log (view1. rows . count ); // Out: 2 console . log (view1. rows [ 0 ][ 'c1' ]); // Out: 'R1' console . log (view1. rows [ 0 ][ 'c2' ]); // Out: 'R2' console . log (view1. rows [ 1 ][ 'c1' ]); // Out: 'R10' console . log (view1. rows [ 1 ][ 'c2' ]); // Out: '' view2 에서 매칭되지 않은 c2 컬럼은 빈 값( '' )으로 병합됩니다. 병합 옵션 1 - 컬럼 기준 병합, 초과 로우 무시 컬럼 전부 비매칭 예제 js const view1 = new MetaView ( 'v1' ); const view2 = new MetaView ( 'v2' ); // 데이터 행(row) 읽기 : read opt = 3 view1. read ({ rows : [{ c1 : 'R1' , c2 : 'R2' }] }, 3 ); view2. read ({ rows : [{ c3 : 'R3' , c4 : 'R4' }, { c3 : 'R30' , c4 : 'R40' }] }, 3 ); // 병합 opt = 1 view1. merge (view2, 1 ); console . log (view1. columns . count ); // Out: 4 console . log (view1. rows . count ); // Out: 1 console . log (view1. rows [ 0 ][ 'c1' ]); // Out: 'R1' console . log (view1. rows [ 0 ][ 'c2' ]); // Out: 'R2' console . log (view1. rows [ 0 ][ 'c3' ]); // Out: 'R3' console . log (view1. rows [ 0 ][ 'c4' ]); // Out: 'R4' option = 1 으로 설정하면, 컬럼 기준으로 매칭되어 병합되며, 컬럼 개수가 증가합니다. 컬럼명이 중복되면, 예외가 발생합니다. 대상의 행(row)이 원본보다 많으면 무시되고, 적으면 공백으로 채워집니다. 병합 옵션 2 - 로우 기준 병합, 초과 컬럼 채움 컬럼 일부 매칭 예제 js const view1 = new MetaView ( 'view1' ); const view2 = new MetaView ( 'view2' ); // 데이터 행(row) 읽기 view1. read ({ rows : [{ c1 : 'R1' , c2 : 'R2' }] }, 3 ); view2. read ({ rows : [{ c1 : 'R10' , c3 : 'R30' }] }, 3 ); // 병합 opt = 2 view1. merge (view2, 2 ); console . log (view1. columns . count ); // Out: 3 console . log (view1. rows . count ); // Out: 2 console . log (view1. rows [ 0 ][ 'c1' ]); // Out: 'R1' console . log (view1. rows [ 0 ][ 'c2' ]); // Out: 'R2' console . log (view1. rows [ 0 ][ 'c3' ]); // Out: '' console . log (view1. rows [ 1 ][ 'c1' ]); // Out: 'R10' console . log (view1. rows [ 1 ][ 'c2' ]); // Out: '' console . log (view1. rows [ 1 ][ 'c3' ]); // Out: 'R30' option = 2 으로 설정하면, 행(row) 기준으로 매칭되는 컬럼만 병합됩니다. 원본 view1 에 채워진 c3 컬럼은 빈 값( '' )으로 채워집니다. 대상 view2 에 매칭되지 않은 c2 컬럼은 빈 값( '' )으로 채워집니다. 병합 옵션 3 - 컬럼 기준 병합, 초과 로우 채움 컬럼 전부 비매칭 예제 js const view1 = new MetaView ( 'view1' ); const view2 = new MetaView ( 'view2' ); // 데이터 행(row) 읽기 view1. read ({ rows : [{ c1 : 'R1' , c2 : 'R2' }] }, 3 ); view2. read ({ rows : [{ c3 : 'R3' , c4 : 'R4' }, { c3 : 'R30' , c4 : 'R40' }] }, 3 ); // 병합 opt = 3 view1. merge (view2, 3 ); console . log (view1. columns . count ); // Out: 4 console . log (view1. rows . count ); // Out: 2 console . log (view1. rows [ 0 ][ 'c1' ]); // Out: 'R1' console . log (view1. rows [ 0 ][ 'c2' ]); // Out: 'R2' console . log (view1. rows [ 0 ][ 'c3' ]); // Out: 'R3' console . log (view1. rows [ 0 ][ 'c4' ]); // Out: 'R4' console . log (view1. rows [ 1 ][ 'c1' ]); // Out: '' console . log (view1. rows [ 1 ][ 'c2' ]); // Out: '' console . log (view1. rows [ 1 ][ 'c3' ]); // Out: 'R30' console . log (view1. rows [ 1 ][ 'c4' ]); // Out: 'R40' option = 3 으로 설정하면, 컬럼 기준으로 매칭되어 병합되며, 컬럼 개수가 증가합니다. 컬럼명이 중복되면, 예외가 발생합니다. 대상의 행(row)이 원본보다 갯수가 크면 공백으로 채워지고, 작으면 예외가 발생합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"select()","url":"api/meta-view.html#select","text":"select() 조건에 맞는 행(row)을 필터링하거나 특정 컬럼 데이터를 반환하는 메서드입니다. ts declare function select ( filter : (row, idx, view) => boolean | string [] | arguments < string >, colNames ?: string [] | arguments < string > ): MetaRow []; filter : 필터 콜백함수 또는 대상 컬럼명 함수 : 행( row ), 인덱스( idx ), 원본 뷰( view )를 매개변수로 받아 boolean 타입을 반환합니다. string[] : 특정 컬럼명만 복사합니다. arguments<string> : 매개변수 형태로 전달된 컬럼명을 복사합니다. colNames(선택) : 복사 대상의 컬럼명 또는 컬럼 문자열 배열 또는 arguments<string> 형태 반환값: 조건에 맞는 행 데이터( MetaRow[] ) 배열. select() 메서드는 MetaView 객체의 행 데이터를 조건에 따라 필터링하거나 특정 컬럼 데이터를 선택하여 배열 형태로 반환합니다. 컬럼명을 배열 또는 인자로 전달하여 복사할 대상 컬럼을 지정할 수 있습니다. filter 함수를 사용하여 조건에 만족하는 행(row)을 선택할 수 있습니다. 선택된 데이터는 새로운 배열로 생성되므로, 원본 데이터와 독립적으로 사용할 수 있습니다. 필터 함수로 데이터 선택 예제 js const view1 = new MetaView ( 'v1' ); // 데이터 행(row) 읽기 view1. read ({ rows : [{ c1 : 10 , c2 : 'R2' }, { c1 : 20 , c2 : 'R20' }]}, 3 ); // rows 선택 const rows = view1. select ( row => row[ 'c1' ] > 10 ); console . log (rows. length ); // Out: 1 console . log (rows[ 0 ][ 'c1' ]); // Out: 20 console . log (rows[ 0 ][ 'c2' ]); // Out: 'R20' select() 메서드를 호출하여 c1 값이 10보다 큰 행만 선택합니다. 선택된 행(row) 데이터는 배열로 반환합니다. 특정 컬럼 선택 예제 js const view1 = new MetaView ( 'V1' ); // 데이터 행(row) 읽기 view1. read ({ rows : [{ c1 : 10 , c2 : 'R2' }, { c1 : 20 , c2 : 'R20' }]}, 3 ); // rows 선택 const rows = view1. select ([ 'c1' ]); console . log (rows. length ); // Out: 2 console . log (rows[ 0 ][ 'c1' ]); // Out: 10 console . log (rows[ 1 ][ 'c1' ]); // Out: 20 select() 메서드를 호출하여 c1 컬럼 데이터만 포함된 행(row) 배열을 반환합니다. Tip : 필터함수와 대상컬럼을 조합하여 다양한 방식으로 데이터 조회에 활용할 수 있습니다."},{"title":"MetaView","group":"API 레퍼런스","section":"output()","url":"api/meta-view.html#output","text":"output() 현재 객체를 직렬화된 문자열로 내보내는 메서드입니다. ts declare function output ( vOpt ?: number , stringify ?: Function , space ?: string ): string ; vOpt(선택) : 직렬화 옵션 (기본값 0 ) 0 : guid 참조 구조를 유지합니다 ( _guid: 예 , $ref: 예 ) 1 : guid 중복 구조로 출력합니다 ( _guid: 예 , $ref: 예 ) 2 : 비참조 구조로 출력합니다 ( _guid: 아니오 , $ref: 아니오 ). stringify(선택) : (선택) 사용자 정의 파서 출력 함수 space(선택) : 출력 문자열의 들여쓰기 설정 반환값: 직렬화된 데이터 문자열 output() 메서드는 MetaView 객체의 데이터를 JSON 문자열 또는 사용자 정의 형식으로 직렬화하여 반환합니다. vOpt 를 사용하여 참조 구조, 중복 구조, 비참조 구조를 선택적으로 설정할 수 있습니다. stringify 함수는 데이터를 직렬화하는 데 사용되며, 사용자 정의 파서를 지정할 수 있습니다. space 매개변수를 통해 직렬화된 출력의 가독성을 높이기 위해 들여쓰기 설정을 추가할 수 있습니다. Tip : 반환된 데이터는 외부로 전달하거나 다른 MetaView 객체로 로드할 때 사용됩니다. vOpt 에 대하여 opt = 0 과 opt = 1 은 동일하게 작동하지만, opt = 1 은 MetaView 의 참조 컬럼을 독립적인 객체로 직렬화합니다. 이 경우 객체에 참조값은 _guid 값이 중복되어 구성됩니다. opt = 2 는 객체의 참조를 제거하여 독립적인 구조로 출력할 때 사용됩니다. js const view1 = new MetaView ( 'v1' ); const view2 = new MetaView ( 'v2' ); // 컬럼 추가 view1. columns . addValue ( 'c1' , 10 ); // 문자열로 내보내기 : opt = 0 const data1 = view1. output (); // 문자열로 가져오기 view2. load (data1); console . log (view1. viewName ); // Out: 'v1' console . log (view1. columns [ 'c1' ]. value ); // Out: 10 console . log (view2. viewName ); // Out: 'v1' console . log (view2. columns [ 'c1' ]. value ); // Out: 10 output() 메서드를 사용하여 view1 데이터를 JSON 문자열로 변환합니다. view2 는 view1 과 동일한 구조를 가집니다."},{"title":"MetaView","group":"API 레퍼런스","section":"load()","url":"api/meta-view.html#load","text":"load() 직렬화된 객체를 불러와서 컬럼과 행 데이터를 구성하는 메서드입니다. ts declare function load ( data : object | string , parse ?: (data: string ) => object ): void ; data : 로드할 데이터 객체 또는 JSON 문자열 객체: getObject() 메서드를 통해 직렬화된 객체 문자열: output() 메서드를 통해 직렬화된 객체의 JSON 문자열 parse(선택) : (선택) JSON 문자열을 객체로 변환하는 사용자 정의 파서 함수 함수가 제공되지 않으면 기본 JSON 파서를 사용합니다 load() 메서드는 직렬화된 객체 또는 JSON 문자열 데이터를 MetaView 객체에 로드하여 컬럼과 행 데이터를 구성합니다. parse 함수를 사용하여 사용자 정의 방식으로 데이터를 처리할 수 있습니다. load() 메서드를 실행하면, 기존 데이터는 초기화됩니다. js const view1 = new MetaView ( 'v1' ); const view2 = new MetaView ( 'v2' ); const view3 = new MetaView ( 'v3' ); // 컬럼 추가 view1. columns . addValue ( 'c1' , 10 ); // 문자열로 내보내기 const data1 = view1. output (); // 객체로 내보내기 const data2 = view1. getObject (); // 문자열 불러오기 view2. load (data1); // 객체 불러오기 view3. load (data2); console . log (view1. viewName ); // Out: 'v1' console . log (view2. viewName ); // Out: 'v1' console . log (view3. viewName ); // Out: 'v1' console . log (view1. columns [ 'c1' ]. value ); // Out: 10 console . log (view2. columns [ 'c1' ]. value ); // Out: 10 console . log (view3. columns [ 'c1' ]. value ); // Out: 10 data1 과 data2 를 load() 메서드를 사용하여 view2 와 view3 에 로드합니다. 모든 MetaView 객체는 동일한 컬럼과 데이터를 갖습니다."},{"title":"MetaView","group":"API 레퍼런스","section":"write()","url":"api/meta-view.html#write","text":"write() 현재 객체를 MetaView 스키마 타입의 객체로 변환하여 반환하는 메서드입니다. ts declare function write ( vOpt ?: number ): object ; vOpt(선택) (number, 선택) : 직렬화 옵션 (기본값 0 ) 0 : guid 참조 구조를 유지합니다 ( _guid: 예 , $ref: 예 ) 1 : guid 중복 구조로 출력합니다 ( _guid: 예 , $ref: 예 ) 2 : 비참조 구조로 출력합니다 ( _guid: 아니오 , $ref: 아니오 ) 반환값: MetaView 스키마 타입 객체 write() 메서드는 컬럼(구조)과 행(데이터)을 MetaView 스키마 타입의 객체로 반환합니다. Tip : 반환된 데이터는 외부 시스템으로 전달하거나 저장하는 데 활용됩니다. MetaView 스키마 타입 ts type ConstraintType = { regex : RegExp , // 검사할 정규식 msg : string , // 조건 미충족 시 출력할 메시지 code ?: string , // 조건 미충족 시 반환할 코드 (선택적) condition ?: boolean // true: 매칭 조건, false: 비매칭 조건 (기본값: true) }; type GuidType = { $ref : string } | string ; type EntitySchema = { _guid ?: string , _baseEntity ?: GuidType , columns ?: { [ key : string ]: { _entity ?: GuidType , _guid ?: string , default ?: number | string | boolean , caption ?: string , required ?: boolean , constraints ?: ConstraintType [], getter ?: () => any , setter ?: ( value : string | number | boolean ) => void | any , $alias?: string , value ?: string }, $key?: string [] // 컬럼의 순서 }, rows ?: { [ key : number ]: { [ key : string ]: number | string | boolean ; } } }; rows 에 boolean 타입에 대한 이슈? #REVIEW 기본 참조 구조 직렬화 예제 js const view = new MetaView ( 'v1' ); const c1 = new HTMLColumn ( 'u_id' , view, { default : 0 , required : true }); const c2 = new HTMLColumn ( 'name' , view, { caption : 'Full Name' }); // 컬럼 추가 view. columns . add (c1); view. columns . add (c2); // 행 추가 view. rows . add (view. newRow ()); view. rows [ 0 ][ 'u_id' ] = 1 ; view. rows [ 0 ][ 'name' ] = 'Alice' ; view. rows . add (view. newRow ()); view. rows [ 1 ][ 'id' ] = 2 ; view. rows [ 1 ][ 'name' ] = 'Bob' ; // MetaView 스키마 쓰기 : opt = 2 const schema = view. write ( 2 ); console . log (schema); // Out: // { // \"columns\": { // \"u_id\": { // \"default\": 0, // \"required\": true // }, // \"name\": { // \"caption\": \"Full Name\" // }, // \"$key\": [\"u_id\", \"name\"] // }, // \"rows\": [ // { \"u_id\": 1, \"name\": \"Alice\" }, // { \"u_id\": 2, \"name\": \"Bob\" } // ] // } write(2) : 컬럼과 행 데이터를 비참조 구조로 직렬화하여 반환합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"writeSchema()","url":"api/meta-view.html#writeschema","text":"writeSchema() 현재 객체의 컬럼(구조) 정보를 MetaView 스키마 타입의 객체로 변환하여 반환하는 메서드입니다. ts declare function writeSchema ( vOpt ?: number ): object ; vOpt(선택) : (선택) 직렬화 옵션 (기본값 0 ) 0 : guid 참조 구조를 유지합니다 ( _guid: 예 , $ref: 예 ) 1 : guid 중복 구조로 출력합니다 ( _guid: 예 , $ref: 예 ) 2 : 비참조 구조로 출력합니다 ( _guid: 아니오 , $ref: 아니오 ) 반환값: MetaView 스키마 타입 객체 writeSchema() 메서드는 MetaView 객체의 컬럼 정의를 추출하여 스키마 형태로 반환합니다. 반환된 객체는 컬럼 이름, 기본값, 캡션, 필수 여부 등 컬럼의 메타데이터를 포함합니다. Tip : 데이터를 제외한 구조 정보를 관리하거나 저장할 때 유용합니다. 구조 스키마 타입 ts type ConstraintType = { regex : RegExp , // 검사할 정규식 msg : string , // 조건 미충족 시 출력할 메시지 code ?: string , // 조건 미충족 시 반환할 코드 (선택적) condition ?: boolean // true: 매칭 조건, false: 비매칭 조건 (기본값: true) }; type GuidType = { $ref : string } | string ; type EntitySchema = { _guid ?: string , _baseEntity ?: GuidType , columns ?: { [ key : string ]: { _entity ?: GuidType , _guid ?: string , default ?: number | string | boolean , caption ?: string , required ?: boolean , constraints ?: ConstraintType [], getter ?: () => any , setter ?: ( value : string | number | boolean ) => void | any , $alias?: string , value ?: string }, $key?: string [] // 컬럼의 순서 } }; MetaView 컬럼 구조 쓰기 예제 js const view = new MetaView ( 'v1' ); const c1 = new HTMLColumn ( 'u_id' , view, { default : 0 , required : true }); const c2 = new HTMLColumn ( 'name' , view, { caption : 'Full Name' }); // 컬럼 추가 view. columns . add (c1); view. columns . add (c2); // 행 추가 view. rows . add (view. newRow ()); view. rows [ 0 ][ 'u_id' ] = 1 ; view. rows [ 0 ][ 'name' ] = 'Alice' ; // 스키마 쓰기 const schema = view. writeSchema ( 2 ); console . log (schema); // Out: // { // \"columns\": { // \"u_id\": { // \"default\": 0, // \"required\": true // }, // \"name\": { // \"caption\": \"Full Name\" // }, // \"$key\": [\"u_id\", \"name\"] // }, // } writeSchema() 메서드를 호출하여 컬럼 정의를 직렬화된 스키마 객체로 반환합니다. 반환된 객체는 컬럼 이름과 메타데이터를 포함하며, 컬럼 순서 정보( $key )를 제공합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"writeData()","url":"api/meta-view.html#writedata","text":"writeData() 현재 객체의 행(row)을 스키마 타입의 객체로 변환하여 반환하는 메서드입니다. ts declare function writeData ( vOpt ?: number ) : object ; vOpt(선택) : 직렬화 옵션 (기본값 0 ) 0 : guid 참조 구조를 유지합니다 ( _guid: 예 , $ref: 예 ) 1 : guid 중복 구조로 출력합니다 ( _guid: 예 , $ref: 예 ) 2 : 비참조 구조로 출력합니다 ( _guid: 아니오 , $ref: 아니오 ). 반환값: MetaView 스키마 타입 객체 writeData() 메서드는 MetaView 객체의 행(데이터)를 추출하여 스키마 형태로 반환합니다. 컬럼 구조를 제외한 데이터를 관리하거나 저장할 때 유용합니다. Tip : readSchema() 메서드에서 옵션을 지정하여 행(row)을 기준으로 컬럼을 가져올 수 있습니다. 데이터 스키마 타입 ts type DataSchema = { rows ?: { [ key : number ]: { [ key : string ]: number | string | boolean ; } } }; MetaView 행(row) 쓰기 예제 js const view = new MetaView ( 'v1' ); // 컬럼 추가 view. columns . add ( 'u_id' ); view. columns . add ( 'name' ); view. rows . add ({ u_id : 1 , name : 'Alice' }); view. rows . add ({ u_id : 2 , name : 'Bob' }); // 데이터 쓰기 : opt = 2 const data = view. writeData ( 2 ); console . log (data); // Out: // { // \"rows\": [ // { \"u_id\": 1, \"name\": \"Alice\" }, // { \"u_id\": 2, \"name\": \"Bob\" } // ] // } writeData() 메서드를 호출하여 행 데이터를 직렬화된 객체 배열로 반환합니다."},{"title":"MetaView","group":"API 레퍼런스","section":"read()","url":"api/meta-view.html#read","text":"read() MetaView 스키마 타입 객체를 읽어오는 메서드입니다. ts declare function read ( source : object | MetaView | string , option ?: number ): void ; source : 읽어올 데이터 소스 객체 : 스키마 또는 데이터 구조 MetaView : 기존 MetaView 객체 문자열 : JSON 형식의 직렬화된 데이터 option(선택) : 읽기 동작 옵션 (기본값 3 ) 1 : 컬럼(구조)만 읽기 2 : 로우(데이터)만 읽기 3 : 컬럼과 로우 모두 읽기 read() 메서드는 MetaView 객체 또는 직렬화 객체 또는 스키마 객체를 읽어와 MetaView 객체를 구성합니다. 기존에 설정된 정보는 유지되며, 병합과 유사한 역활을 합니다. option 값에 따라 컬럼(columns)과 로우(rows) 데이터를 선택적으로 읽어올 수 있습니다. Tip : getObject() 메서드로 MetaView 의 직렬화 객체를 얻을 수 있으며, wrtie() 메서드로 MetaView 의 스키마 객체를 얻을 수 있습니다. MetaView 스키마 타입 ts type ConstraintType = { regex : RegExp , // 검사할 정규식 msg : string , // 조건 미충족 시 출력할 메시지 code ?: string , // 조건 미충족 시 반환할 코드 (선택적) condition ?: boolean // true: 매칭 조건, false: 비매칭 조건 (기본값: true) }; type GuidType = { $ref : string } | string ; type EntitySchema = { _guid ?: string , _baseEntity ?: GuidType , columns ?: { [ key : string ]: { _entity ?: GuidType , _guid ?: string , default ?: number | string | boolean , caption ?: string , required ?: boolean , constraints ?: ConstraintType [], getter ?: () => any , setter ?: ( value : string | number | boolean ) => void | any , $alias?: string , value ?: string }, $key?: string [] // 컬럼의 순서 }, rows ?: { [ key : number ]: { [ key : string ]: number | string | boolean ; } } }; MetaView 객체에서 읽기 예제 js const view1 = new MetaView ( 'v1' ); const view2 = new MetaView ( 'v2' , view1); // 전체 참조 뷰 const view3 = new MetaView ( 'v3' ); // 컬럼 추가 view1. columns . add ( 'c1' ); view2. columns . add ( 'c2' ); view3. columns . add ( 'c3' , view2. columns ); // 컬럼 일부 참조 // 스키마를 읽을 뷰 생성 const v1 = new MetaView ( 'view1' ); const v2 = new MetaView ( 'view2' ); const v3 = new MetaView ( 'view3' ); // 컬럼 및 데이터 읽기 : opt = 3 v1. read (view1); v2. read (view2); v3. read (view3); console . log (v1. columns . count ); // Out: 3 console . log (v2. columns . count ); // Out: 2 console . log (v3. columns . count ); // Out: 1 MetaView 객체에서 컬럼과 행 데이터를 읽어옵니다. 스키마 객체 읽기 예제 js const view = new MetaView ( 'v1' ); const schema = { columns : { c1 : 'D1' , c2 : 'D2' }, rows : [{ c1 : 'R1' , c2 : 'R2' }] }; // 컬럼 및 데이터 읽기 : opt = 3 view. read (schema); console . log (view. columns . count ); // Out: 2 console . log (view. rows . count ); // Out: 1 스키마 타입의 컬럼과 행 데이터를 읽어옵니다."},{"title":"MetaView","group":"API 레퍼런스","section":"readSchema()","url":"api/meta-view.html#readschema","text":"readSchema() MetaView 스키마 타입 객체의 컬럼(구조) 정보를 읽어오는 메서드입니다. ts declare function readSchema ( schema : object , isReadRow ?: boolean ): void ; schema : 읽어올 스키마 객체 isReadRow(선택) : 로우 키를 읽어서 컬럼 등록 여부 (기본값 false ) true 이면 row[0] 을 기준으로 컬럼을 추가합니다. readSchema() 메서드는 MetaView 스키마 타입 객체에서 컬럼 정보를 읽어오는 메서드입니다. isReadRow = true 인자를 설정하면, 첫번째 행(row)정보를 사용하여 기본 컬럼을 구성합니다. 컬럼 스키마 타입 ts type ConstraintType = { regex : RegExp , // 검사할 정규식 msg : string , // 조건 미충족 시 출력할 메시지 code ?: string , // 조건 미충족 시 반환할 코드 (선택적) condition ?: boolean // true: 매칭 조건, false: 비매칭 조건 (기본값: true) }; type GuidType = { $ref : string } | string ; type EntitySchema = { _guid ?: string , _baseEntity ?: GuidType , columns ?: { [ key : string ]: { _entity ?: GuidType , _guid ?: string , default ?: number | string | boolean , caption ?: string , required ?: boolean , constraints ?: ConstraintType [], getter ?: () => any , setter ?: ( value : string | number | boolean ) => void | any , $alias?: string , value ?: string }, $key?: string [] // 컬럼의 순서 } }; 컬럼 정보 읽기 예제 js const view = new MetaView ( 'v1' ); const schema = { columns : { c1 : 'D1' , c2 : 'D2' } }; // 컬럼 읽기 view. readSchema (schema); console . log (view. columns . count ); // Out: 2 console . log (view. columns [ 'c1' ]. value ); // Out: 'D1' console . log (view. columns [ 'c2' ]. value ); // Out: 'D2' 스키마 타입의 컬럼을 읽어옵니다. 읽기 순서 변경 예제 js const view = new MetaView ( 't1' ); const schema = { columns : { $key : [ 'c2' , 'c1' ], // 키 위치 변경 c1 : { caption : 'Column1' }, c2 : { caption : 'Column2' } } }; view. readSchema (schema); console . log (view. columns . count ); // Out: 2 console . log (view. columns [ 'c1' ]. caption ); // Out: 'Column1' console . log (view. columns [ 'c2' ]. caption ); // Out: 'Column2' console . log (view. columns [ 0 ]. caption ); // Out: 'Column2' console . log (view. columns [ 1 ]. caption ); // Out: 'Column1' $key 속성을 사용하여 컬럼의 순서를 조정할 수 있습니다."},{"title":"MetaView","group":"API 레퍼런스","section":"readData()","url":"api/meta-view.html#readdata","text":"readData() MetaView 스키마 타입 객체의 행(데이터) 정보를 읽어오는 메서드입니다. ts declare function readData ( data : object ): void ; data : 읽어올 데이터 객체 readData() 메서드는 데이터 객체에서 rows 속성에 존재하는 컬럼의 행(row) 데이터만 읽습니다. 행(row)의 키는 컬럼명과 같으며, alias 속성이 설정되어 있으면 우선합니다. 행 스키마 타입 ts type DataSchema = { rows ?: { [ key : number ]: { [ key : string ]: number | string | boolean ; } } }; 행 데이터 읽기 예제 js const view = new MetaView ( 'T1' ); const data = { rows : [{ c1 : 'R1' , c2 : 'R2' }, { c1 : 'R3' , c2 : 'R4' }] }; // 컬럼 추가 view. columns . add ( 'c1' ); view. columns . add ( 'c2' ); // 행(row) 데이터 읽기 view. readData (data); console . log (view. rows . count ); // Out: 2 console . log (view. rows [ 0 ][ 'c1' ]); // Out: 'R1' console . log (view. rows [ 0 ][ 'c2' ]); // Out: 'R2' console . log (view. rows [ 1 ][ 'c1' ]); // Out: 'R3' console . log (view. rows [ 1 ][ 'c2' ]); // Out: 'R4' readData() 메서드를 사용하여 data 객체의 행 읽어옵니다. 컬럼없는 데이터 읽기 예제 js const view = new MetaView ( 'T1' ); const data = { rows : [{ c1 : 'R1' , c2 : 'R2' }, { c1 : 'R3' , c2 : 'R4' }] }; view. readData (data); console . log (view. rows . count ); // Out: 0 readData() 메서드는 컬럼이 없는 경우 데이터를 로드하지 않습니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 BindCommand 다음 문서 HTMLColumn"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"HTMLColumn","url":"api/html-column.html","text":"문서 API 레퍼런스 API 레퍼런스 05 HTMLColumn 값, 유효성 검사, DOM 연결에 사용하는 컬럼 API입니다. 한국어 문서 약 25분 1.1.13에서 필터를 사용할 때 이 배포 버전에서는 getFilter 로 값을 읽을 때 selector 설정이 필요합니다. DOM을 읽지 않는 필터에는 selector: { key: '#example', type: 'none' } 을 함께 설정하세요. key 는 실제 사용하는 요소에 맞춰 지정합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"구성 요소","url":"api/html-column.html#구성-요소","text":"구성 요소"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"속성","url":"api/html-column.html#속성","text":"속성 항목 설명 _valueTypes 컬럼값(value)으로 가능한 타입을 제한합니다. _entity 컬럼이 속한 엔티티(MetaTable 또는 MetaView)를 가르킵니다. value 컬럼의 현재값을 나타냅니다. default 컬럼의 초기값을 지정합니다. getter 컬럼의 값(value)를 조회할 때 실행되는 사용자 정의 함수입니다. setter 컬럼의 값(value)를 설정할 때 실행되는 사용자 정의 함수입니다. getFilter 값(value)를 가져올 때 필터를 적용하는 함수입니다. setFilter 값(value)를 설정할 때 필터를 적용하는 함수입니다. selector 컬럼과 HTML 요소 간의 동기화를 정의합니다. required 컬럼 값이 필수인지 여부를 정의합니다. constraints 컬럼 값의 제약 조건을 정의합니다. columnName 컬럼의 고유 이름을 정의합니다. alias 컬럼의 별칭입니다. caption 컬럼의 설명이나 라벨로 사용됩니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"메소드","url":"api/html-column.html#메소드","text":"메소드 항목 설명 addConstraint() 컬럼에 제약 조건(constraints)을 추가합니다. valid() 컬럼값(value)이 제약 조건을 충족하는지 확인합니다. clone() 컬럼을 복제하여 새로운 인스턴스를 생성합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"이벤트","url":"api/html-column.html#이벤트","text":"이벤트 항목 설명 onChanged 컬럼 값이 변경될 때 호출되는 이벤트 입니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"주요 속성","url":"api/html-column.html#주요-속성","text":"주요 속성"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"_valueTypes","url":"api/html-column.html#_valuetypes","text":"_valueTypes 컬럼값(value)으로 가능한 타입을 제한하는 속성입니다. ts type _valueTypes = any []; any[] : 컬럼에 value 으로 등록을 제한할 타입 추후 동적타입관리에 대한 정보가 제공될 예정입니다. _valueTypes 속성은 컬럼값(value) 타입을 제한합니다. 특정 규칙에 따라 값을 제한할 때 유용합니다. js const c1 = new HTMLColumn ( 'aa' ); // 타입 재정의 c1. _valueTypes = [ String ]; c1. value = 'Mike' ; // 값 등록 성공 c1. value = 10 ; // 제약조건으로 예외 발생!! console . log (c1. _valueTypes ); // Out: [String] _valueTypes 에 String 타입을 추가하여 이 컬럼에서 문자열만 허용되도록 설정합니다. 10 은 String 타입이 아니므로 제약조건이 위반되어 예외가 발생합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"_entity","url":"api/html-column.html#_entity","text":"_entity 컬럼이 속한 엔티티(MetaTable 또는 MetaView)를 가르키는 속성입니다. ts type _entity = MetaTable | MetaView ; _entity 속성은 컬럼이 속한 테이블(MetaTable)이나 뷰(MetaView)를 가르킵니다. 컬럼과 테이블 간의 연결 관계를 확인할 수 있습니다. Tip : 동일한 엔티티에 소속된 컬럼을 찾을 때 유용합니다. ( _entity.columns['컬럼명'] ) js const table = new MetaView ( 'users' ); table. columns . add ( 'name' ); console . log (table. columns [ 'name' ]. _entity . viewName ); // Out: 'users' _entity 속성을 사용하여 name 컬럼이 속한 테이블의 이름을 확인합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"value","url":"api/html-column.html#value","text":"value 컬럼의 현재값을 나타내는 속성입니다. ts type value = string | number | boolean ; value 속성은 컬럼의 현재값을 나타내며, 컬럼값을 설정하거나 조회할 수 있습니다. 값(value)의 특성을 다양한 방식으로 지정할 수 있습니다. getter / setter : 값 조회 및 설정 시 사용자 정의 함수 설정 getFilter / setFilter : 값 변환을 위해 필터 함수 설정 selector : UI 와 동기화하기 위한 선택자 설정 참조 : 컬럼값 호출 구조 js const column = new HTMLColumn ( 'age' ); // 기본값 설정 column. default = 15 ; // getter / setter 정의 column. getter = () => column. default * 2 ; column. setter = ( val ) => { if (val > 0 ) column. default = val; }; console . log (column. value ); // Out: 30 (getter를 통해 값 조회) column. value = 30 ; // setter를 통해 값 설정 console . log (column. value ); // Out: 60 (getter를 통해 값 조회) default 속성을 통해 초기값을 설정하고, setter 를 사용해 조건부로 값을 변경합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"default","url":"api/html-column.html#default","text":"default 컬럼의 초기값을 지정하는 속성입니다. ts type DefaultValue = string | number | boolean | '' ; 초기값 : 빈공백 default 속성은 컬럼의 value 값이 지정되지 않았을 때 사용하는 기본값입니다. 초기 데이터를 제공하고, 데이터가 누락된 경우에도 일관성을 유지하게 합니다. value 값이 null 이면 default 속성 값을 반환합니다. newRow(), getValue() 메소드에서 value 값이 없으면 default 속성 값으로 대체됩니다. js const column = new HTMLColumn ( 'status' ); // 기본값 설정 column. default = 'active' ; // 값 설정 후 확인 column. value = 'inactive' ; console . log (column. value ); // Out: 'inactive' // 기본값 반환 column. value = null ; console . log (column. value ); // Out: 'active' 값이 설정되지 않은 경우, default 속성을 통해 기본값을 반환합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"getter","url":"api/html-column.html#getter","text":"getter 컬럼의 값(value)를 조회할 때 실행되는 사용자 정의 함수입니다. ts type getter = () => any ; 함수로 정의되며, 반환값이 컬럼의 현재값으로 간주됩니다. getter 속성은 컬럼 값(value)을 조회할 때 실행되는 함수로, 추가 가공이나 조건부 처리를 수행할 수 있습니다. 가장 높은 우선순위를 가지며, 이후 단계는 무시됩니다. 이후단계 : getFilter 함수 호출 > selector 조회 > 내부값 조회 참조 : 컬럼값 호출 구조 js const column = new HTMLColumn ( 'price' ); // getter 정의 column. getter = () => { return column. default + 50 ; }; // 기본값 설정 column. default = 100 ; // 값 조회 console . log (column. value ); // Out: 150 getter 정의: getter 함수를 통해 기본값에 50 을 더한 값을 반환하도록 설정합니다. 값 조회: value 속성을 호출할 때 getter 함수가 실행되어 가공된 값이 반환됩니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"setter","url":"api/html-column.html#setter","text":"setter 컬럼의 값(value)를 설정할 때 실행되는 사용자 정의 함수입니다. ts type setter = ( value : string | number | boolean ) => void | any ; value : 설정하려는 값 반환값: void 또는 추가 로직에서 사용할 값을 반환할 수 있습니다. setter 속성은 값이 설정될 때 실행되며, 유효성 검사, 변환, 추가 처리를 수행하는 함수입니다. 가장 높은 우선순위로 실행되며, 순차적으로 다음 단계가 처리됩니다. 반환값이 존재하면 이후 단계에서 설정 값으로 사용됩니다. 이후단계 : 내부값 저장 > setFilter 함수 호출 > selector 설정 참조 : 컬럼값 호출 구조 js const column = new HTMLColumn ( 'discount' ); // setter 설정 column. setter = ( value ) => { if ( typeof value !== 'number' || value < 0 || value > 100 ) { throw new Error ( 'Discount must be a number from 0 to 100.' ); } return value; // 내부에 저장됨 }; // 값 설정 column. value = 20 ; console . log (column. value ); // Out: 20 try { column. value = 150 ; // 유효성 검사 실패!! } catch (e) { console . error (e. message ); // Out: 'Discount must be a number from 0 to 100.' } 입력값이 0 ~ 100 사이의 숫자인지 확인하며, 조건을 만족하지 않으면 예외가 발생합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"getFilter","url":"api/html-column.html#getfilter","text":"getFilter 값(value)를 가져올 때 필터를 적용하는 함수입니다. ts type getFilter = ( selectorValue ?: any ) => any ; selectorValue(선택) : selector 에 의해 전달된 값 반환값: 필터링된 결과로 반환될 값입니다. getFilter 속성은 컬럼 값에 사용자 정의 필터를 적용하여 데이터를 변환하거나 가공된 값을 반환합니다. getter 함수가 정의되지 않은 경우 호출됩니다. selector 속성과 함께 동작하여 UI에서 가져온 데이터를 처리할 수 있습니다. 참조 : 컬럼값 호출 구조 js const column = new HTMLColumn ( 'price' ); // getFilter 설정 column. getFilter = ( selectorValue ) => { return `$ ${selectorValue.toFixed( 2 )} ` ; }; // selector 설정 column. selector = { key : '#price-input' , type : 'value' }; // DOM 에 값 입력 document . querySelector ( '#price-input' ). value = 123.456 ; console . log (column. value ); // Out: '$123.45' selector 속성을 통해 입력된 값을 getFilter 함수에서 가공하여 반환합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"setFilter","url":"api/html-column.html#setfilter","text":"setFilter 값(value)를 설정할 때 필터를 적용하는 함수입니다. ts type setFilter = ( innerValue : any ) => void | any ; innerValue : setter 이후 전달된 내부값 또는 설정값 반환값: 선택적으로 반환값이 있고, selector 속성이 존재하면 해당 값이 UI에 설정됩니다. setFilter 속성는 내부값을 입력받아 이를 변환하거나 추가 처리를 수행합니다. 반환값이 존재하고 selector 속성이 정의된 경우, 해당 반환값이 selector 속성 위치에 동기화 됩니다. Tip : setFilter 반환값이 존재하지 않고, selector 속성이 지정된 경우 각각 독립적으로 처리됩니다. 참조 : 컬럼값 호출 구조 js const column = new HTMLColumn ( 'price' ); // setFilter 설정 column. setFilter = ( innerValue ) => { return `$ ${innerValue.toFixed( 2 )} ` ; // 통화 형식으로 변환 }; // selector 설정 column. selector = { key : '#price-input' , type : 'value' }; // 값 설정 column. value = 123.456 ; console . log ( document . querySelector ( '#price-input' ). value ); // Out: '$123.45' setFilter 함수의 반환값이 selector 속성를 통해 UI에 설정됩니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"selector","url":"api/html-column.html#selector","text":"selector 컬럼과 HTML 요소 간의 동기화를 정의하기 위한 속성입니다. ts type selector = { key : string ; type : 'value' | 'text' | 'html' | 'prop' | 'attr' | 'css' ; }; key : HTML 요소를 식별하기 위한 셀렉터 문자열 type : 동기화 방식 value : HTML 요소의 값(value)을 동기화합니다. text : HTML 요소의 텍스트 내용을 동기화합니다. html : HTML 요소의 내부 HTML을 동기화합니다. prop : 요소의 속성(property) 값을 동기화합니다. attr : 요소의 특정 속성(attribute)을 동기화합니다. css : CSS 스타일을 동기화합니다. selector 속성은 컬럼과 HTML 요소 간의 값을 동기화하는 데 사용됩니다. 컬럼 값과 HTML 요소 값이 상호 반영됩니다. getFilter 함수 또는 setFilter 함수와 함께 사용하여 데이터를 가공할 수 있습니다. getter 함수가 정의된 경우, selector 지정 값은 가져오지 않습니다. Tip : value 값 설정은 setter → setFilter → selector 순으로 수행되며, 값 조회는 우선순위에 따라 getter, getFilter, selector 중 하나가 선택되어 실행됩니다. 참조 : 컬럼값 호출 구조 js const column = new HTMLColumn ( 'status' ); // selector 설정 column. selector = { key : '#status-input' , type : 'value' }; // 값 설정 column. value = 'Active' ; // HTML 요소의 값이 업데이트됨 console . log ( document . querySelector ( '#status-input' ). value ); // Out: 'Active' // DOM 값 입력 document . querySelector ( '#status-input' ). value = 'Inactive' ; console . log (column. value ); // Out: 'Inactive' 다양한 type 옵션을 통해 HTML 요소와의 동작 방식을 세부적으로 제어할 수 있습니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"required","url":"api/html-column.html#required","text":"required 컬럼 값이 필수인지 여부를 정의하는 속성입니다. ts type required = boolean ; true : 컬럼 값이 필수입니다. false : 컬럼 값이 선택적입니다. required 속성은 컬럼 값의 필수 여부를 지정합니다. true 로 설정되면 값(value)이 비어 있거나 미설정 상태일 경우 유효성 검사가 실패합니다. 참조 : 컬럼 관리 > 제약조건 js const column = new HTMLColumn ( 'username' ); // 필수 설정 column. required = true ; // 유효성 검사 if (!column. valid (column. value )) { console . error ( 'Value is required for username.' ); } else { console . log ( 'Value is valid.' ); } valid() 메서드를 사용하여 값이 유효한지 검사합니다. 값이 비어 있으면 오류가 발생합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"constraints","url":"api/html-column.html#constraints","text":"constraints 컬럼 값의 제약 조건을 정의하는 속성입니다. ts // 1. 정규식 기반 조건 type ConstraintType = { regex : RegExp , // 검사할 정규식 msg : string , // 조건 미충족 시 출력할 메시지 code ?: string , // 조건 미충족 시 반환할 코드 (선택적) condition ?: boolean // true: 매칭 조건, false: 비매칭 조건 (기본값: true) }; // 2. 함수 기반 조건 type FailMsgType = { msg : string , code : string }; type FunctionType = ( value : any , _this ) => boolean | FailMsgType | void ; // 3. 복합 타입 (ConstraintType 또는 FunctionType) type complexType = ConstraintType | FunctionType ; // constraints 타입 (단일 또는 배열) type constraints = complexType[] | complexType; ConstraintType : 정규식과 메시지를 포함하여 값의 패턴 condition 값이 true 이면 정규식 매칭 조건, false 이면 정규식 비매칭 조건 FunctionType : 값의 유효성을 확인하기 위한 사용자 정의 함수 true 또는 undefined : 성공 false 또는 FailMsgType : 실패 complexType : ConstraintType 과 FunctionType 의 조합 constraints : 단일 조건 또는 복합 배열 조건 constraints 속성은 컬럼 값이 특정 조건을 만족하는지 검사하는 규칙을 설정합니다. 정규식 또는 사용자 정의 함수를 사용하여 유효성을 확인할 수 있으며, 여러 조건을 배열로 설정하여 복합 검사 가 가능합니다. 값이 조건을 만족하지 못하면 유효성 검사가 실패로 처리됩니다. 사용자 함수로 제약 조건을 설정할 경우, 반환값이 true 또는 undefined 이면 성공, FailMsgType 객체 또는 false 이면 실패로 처리됩니다. Tip : 정규식 속성 condition = false 로 설정하면 정규식과 비매칭될 경우 성공을 반환하며, 매칭되면 실패 메세지를 반환합니다. js const column = new HTMLColumn ( 'email' ); let check; // constraints 설정 column. constraints = [ { regex : /^[^@]+@[^@]+\\.[^@]+$/ , msg : 'Invalid email format.' }, ( value ) => value. length > 3 ]; // 값 설정 및 유효성 검사 column. value = 'example@example.com' ; check = column. valid (column. value ); if (check) { console . error (check. msg ); } column. value = 'a@b' ; check = column. valid (column. value ); if (check) { console . error (check. msg ); // Out: 'function constraint failed.' } column. value = 'invalid-email' ; check = column. valid (column. value ); if (check) { console . error (check. msg ); // Out: 'Invalid email format.' } constraints 속성에 정규식과 사용자 정의 함수를 사용하여 값을 검사합니다. valid() 메서드는 검사가 실패하면 객체를 반환하고, 성공하면 undefined 를 반환합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"columnName","url":"api/html-column.html#columnname","text":"columnName 컬럼의 고유 이름을 정의하는 속성입니다. ts type columnName = string ; string : 컬럼의 이름 columnName 속성은 컬럼을 식별하는 속성입니다. 컬럼 이름은 컬렉션 내에서 고유해야 합니다. columnName 속성은 상위 속성 _name 으로 조회할 수 있습니다. js const column = new HTMLColumn ( 'username' ); console . log (column. columnName ); // Out: 'username' console . log (column. _name ); // OUt: 'username' 컬럼 생성시 columnName 속성이 인자로 전달됩니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"alias","url":"api/html-column.html#alias","text":"alias 컬럼의 별칭 속성입니다. ts type alias = string ; string : 컬럼의 별칭으로 사용되는 문자열 Tip : alias 속성이 설정되어 있으면 getValue() 및 newRow() 에서 컬럼 대신 별칭이 사용합니다. alias 속성은 컬럼명과 행(row) 데이터 간의 매칭 역할을 합니다. 서버의 데이터 키와 컬럼 이름이 다를 경우, alias 속성을 활용하여 데이터를 매핑할 수 있습니다. alias 속성은 컬렉션 내에서 고유해야 하며, columnName 속성 또는 기존의 다른 alias 속성과 중복될 수 없습니다. js const view = new MetaView ( 'userView' ); // 컬럼 추가 및 별칭 설정 view. columns . add ( 'u_name' , { alias : 'user_name' }); let row = view. newRow (); row[ 'user_name' ] = 'John' ; view. rows . add (row); console . log (view. rows [ 0 ][ 'user_name' ]); // Out: 'John' alias 속성은 MetaRow 객체에 매핑되는 값으로 사용됩니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"caption","url":"api/html-column.html#caption","text":"caption 컬럼의 설명이나 라벨로 사용되는 속성입니다. ts type caption = string ; caption 컬럼의 설명 js const column = new HTMLColumn ( 'username' ); // caption 설정 column. caption = 'User Name' ; console . log (column. caption ); // Out: 'User Name' caption 은 컬럼의 용도를 사람이 읽기 쉬운 텍스트로 표현하는 데 사용됩니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"주요 메소드","url":"api/html-column.html#주요-메소드","text":"주요 메소드"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"addConstraint()","url":"api/html-column.html#addconstraint","text":"addConstraint() 컬럼에 제약 조건(constraints)을 추가하는 메서드입니다. ts type FailMsg = { msg : string , code ?: string }; declare function addConstraint ( regex : RegExp | (val: any , _this: this ) => boolean | FailMsg | undefined , msg ?: string , code ?: string , condition ?: boolean ): void ; regex : 값을 검증하기 위한 정규식 또는 사용자 정의 함수 RegExp : 값이 특정 패턴과 일치하는지 확인합니다. Function : 값을 인자로 받아 유효성을 검사합니다. true 또는 undefined : 성공으로 간주됩니다. FailMsgType : 오류 메시지를 포함하여 실패 처리합니다. false : 기본 실패 처리가 가능합니다. msg(선택) : 검증 실패 시 출력될 메시지 code(선택) : 오류 코드 condition(선택) : 매칭 및 비매칭 여부 (기본값 true ) true 는 정규식과 매칭되면 성공합니다. false 의 정규식과 비매칭되면 성공합니다. addConstraint() 메서드는 constraints 속성에 새로운 유효성 검사 규칙을 추가하며, 모든 조건이 만족되어야 유효성 검사를 통과합니다. 여러 조건을 일괄 등록하려면 constraints 속성에 배열로 직접 추가할 수 있습니다. js const column = new HTMLColumn ( 'age' ); // 제약 조건 추가: 숫자만 허용 column. addConstraint ({ regex : /^\\d+$/ , msg : 'must be a valid number.' }); // 제약 조건 추가: 사용자 정의 함수 column. addConstraint ( ( value ) => value > 10 ); // 값 설정 및 유효성 검사 column. value = 25 ; console . log (column. valid (column. value )); // Out: undefined column. value = 'A' ; console . log (column. valid (column. value )); // { msg: 'must be a valid number.' } column. value = 5 ; console . log (column. valid (column. value )); // { msg: 'valid(value); function constraint failed...' } 추가된 모든 조건을 기반으로 값이 유효한지 검사합니다. (제약 조건 : 10 보다 큰 숫자)"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"valid()","url":"api/html-column.html#valid","text":"valid() 컬럼값(value)이 제약 조건을 충족하는지 확인하는 메서드입니다. ts type FailMsg = { msg : string , code ?: string }; declare function valid ( value : any ): FailMsg | undefined ; value : 검사할 값 반환값: undefined : 값이 유효한 경우 성공 FailMsg 객체 : 오류 메시지와 선택적인 오류 코드를 포함한 객체를 반환합니다. valid() 메서드는 컬럼에 설정된 constraints 와 required 속성을 기반으로 값의 유효성을 검사합니다. 정규식 또는 사용자 정의 함수로 제약 조건을 평가하며, 모든 조건을 충족해야 유효합니다. 실패 시 이유를 포함한 객체를 반환합니다. js const column = new HTMLColumn ( 'age' ); // 제약 조건 추가: 숫자만 허용 column. addConstraint ({ regex : /^\\d+$/ , msg : 'must be a valid number.' }); // 제약 조건 추가: 사용자 정의 함수 column. addConstraint ( ( value ) => value > 10 ); // 값 설정 및 유효성 검사 column. value = 25 ; console . log (column. valid (column. value )); // Out: undefined column. value = 'A' ; console . log (column. valid (column. value )); //{ msg: 'must be a valid number.' } column. value = 5 ; console . log (column. valid (column. value )); // { msg: 'valid(value); function constraint failed...' } 값이 조건을 만족하지 못하는 경우, 오류 메시지 객체를 반환하여 실패 원인을 제공합니다."},{"title":"HTMLColumn","group":"API 레퍼런스","section":"clone()","url":"api/html-column.html#clone","text":"clone() 컬럼을 복제하여 새로운 인스턴스를 생성하는 메서드입니다. ts declare function clone ( entity ?: MetaTable | MetaView ): HTMLColumn ; entity(선택) : 컬럼이 소속되는MetaTable 또는 MetaView 반환값: 복제된 HTMLColumn 객체를 반환합니다. clone() 메서드는 현재 컬럼 객체를 복제하여 원본과 동일한 초기 속성을 가진 독립적인 새로운 객체를 생성합니다. js const column = new HTMLColumn ( 'username' ); // 값 설정 column. value = 'John' ; // 컬럼 복제 const clonedColumn = column. clone (); // 복제된 컬럼 확인 console . log (clonedColumn. columnName ); // Out: 'username' console . log (clonedColumn. value ); // Out: 'John' 복제된 컬럼과 원본은 서로 독립적으로 동작하며, 값 변경이 서로에게 영향을 미치지 않습니다. entity 지정된 컬럼의 경우 동일 이름으로 복제 되므로 문제가 있음 #이슈"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"주요 이벤트","url":"api/html-column.html#주요-이벤트","text":"주요 이벤트"},{"title":"HTMLColumn","group":"API 레퍼런스","section":"onChanged","url":"api/html-column.html#onchanged","text":"onChanged 컬럼 값이 변경될 때 호출되는 이벤트 입니다. ts type onChanged = ( nVal : any , oVal : any , _this : this ) => void ; newValue : 새로 설정된 값 oldValue : 이전 값 _this : 현재 컬럼 객체에 대한 참조 반환값: 없음 ( void ) 컬럼 값이 변경될 때 호출되는 이벤트로, 변경 전 후 값을 비교하거나 특정 동작을 실행하는 데 사용됩니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const column = new HTMLColumn ( 'status' ); // onChanged 이벤트 설정 column. onChanged = ( newValue, oldValue ) => { console . log ( `Value changed from ' ${oldValue} ' to ' ${newValue} '` ); }; // 값 변경 column. value = 'Active' ; // Out: \"Value changed from 'null' to 'Active'\" column. value = 'Inactive' ; // Out: \"Value changed from 'Active' to 'Inactive'\" 값(value)이 변경될 때마다 onChanged 이벤트가 호출됩니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 MetaView 다음 문서 PropertyCollection"},{"title":"PropertyCollection","group":"API 레퍼런스","section":"PropertyCollection","url":"api/property-collection.html","text":"문서 API 레퍼런스 API 레퍼런스 05 PropertyCollection 키와 인덱스로 접근하는 컬렉션의 속성과 메서드를 확인합니다. 한국어 문서 약 32분 모델(BindModel)의 컬렉션 관리 • command, fn, items, columns 의 컬렉션 속성에 사용됩니다. 명령(BindCommand)의 뷰 컬렉션 관리 • valid.columns, bind.columns, output.columns 속성에 사용됩니다. 엔티티 컬렉션 관리 • MetaTable과 MetaView의 columns 컬렉션으로 사용됩니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"구성 요소","url":"api/property-collection.html#구성-요소","text":"구성 요소"},{"title":"PropertyCollection","group":"API 레퍼런스","section":"속성","url":"api/property-collection.html#속성","text":"속성 항목 설명 _owner 소유한 객체를 참조합니다. _elemTypes 컬렉션에 포함될 수 있는 요소들의 타입을 제한합니다. _list 컬렉션에 포함된 모든 요소를 저장하는 내부 배열입니다. count 컬렉션의 요소 개수를 나타냅니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"메소드","url":"api/property-collection.html#메소드","text":"메소드 항목 설명 add() 컬렉션에 새로운 요소를 추가합니다. clear() 컬렉션의 모든 요소를 제거합니다. exists() 컬렉션에 특정 키가 존재하는지 확인합니다. remove() 컬렉션에서 특정 요소를 제거합니다. removeAt() 컬렉션에서 지정된 위치의 요소를 제거합니다. contains() 컬렉션에 특정 요소가 포함되어 있는지 확인합니다. indexOf() 컬렉션에서 특정 요소의 인덱스를 반환합니다. keyToIndex() 컬렉션에서 특정 키에 해당하는 인덱스를 반환합나다. indexToKey() 컬렉션에서 지정된 인덱스에 해당하는 요소의 키를 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"고차 함수","url":"api/property-collection.html#고차-함수","text":"고차 함수 항목 설명 map() 컬렉션의 각 요소에 함수를 적용하여 새로운 배열을 반환합니다. filter() 조건을 만족하는 요소만 포함하는 새로운 배열을 반환합니다. reduce() 컬렉션의 모든 요소를 순회하며 누적 값을 계산합니다. find() 컬렉션에서 조건을 만족하는 첫 번째 요소를 반환합니다. findIndex() 컬렉션에서 조건을 만족하는 첫 번째 요소의 인덱스를 반환합니다. forEach() 컬렉션의 각 요소에 대해 주어진 작업을 수행합니다. some() 조건을 만족하는 요소가 하나라도 있으면 true를 반환합니다. every() 컬렉션의 모든 요소가 주어진 조건을 만족하면 true 를 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"이벤트","url":"api/property-collection.html#이벤트","text":"이벤트 항목 설명 onAdd 컬렉션에 요소를 추가하기 직전에 호출됩니다. onAdded 컬렉션에 요소가 성공적으로 추가된 후 호출됩니다. onRemove 컬렉션에서 요소가 제거되기 전에 호출됩니다. onRemoved 컬렉션에서 요소가 성공적으로 제거된 후 호출됩니다. onClear 컬렉션의 모든 요소가 제거되기 전에 호출됩니다. onCleared 컬렉션의 모든 요소가 성공적으로 제거된 후 호출됩니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"주요 속성","url":"api/property-collection.html#주요-속성","text":"주요 속성"},{"title":"PropertyCollection","group":"API 레퍼런스","section":"_owner","url":"api/property-collection.html#_owner","text":"_owner 소유한 객체를 참조하는 속성입니다. ts type _owner = Object | null ; Object : 현재 객체를 소유한 개체 null : 소유 개체가 없을 때 (기본값) _owner 속성은 객체의 소유자를 참조하는 속성으로, 소유 관계를 정의하고 추적하는 데 사용됩니다. js class UserTable { constructor ( ) { this . data = new PropertyCollection ( this ); } } // UserTable 객체 생성 const user = new UserTable (); // _owner가 올바르게 설정되었는지 확인 user. data . _owner === user // true 생성자를 통해서 _onwer 속성이 설정됩니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"_elemTypes","url":"api/property-collection.html#_elemtypes","text":"_elemTypes 컬렉션에 포함될 수 있는 요소들의 타입을 제한하는 속성입니다. ts type _elemTypes = any []; _elemTypes 속성은 컬렉션에서 허용되는 데이터 유형을 정의하며, 특정 유형만 추가할 수 있습니다. 값을 지정하지 않으면 모든 유형이 허용됩니다. 타입 관리 추후 정보가 제공될 예정입니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"_list","url":"api/property-collection.html#_list","text":"_list 컬렉션에 포함된 모든 요소를 저장하는 내부 배열 속성입니다. ts declare const _list : any []; _list 속성은 컬렉션 객체에서 데이터를 저장하는 핵심 속성으로, 요소의 추가, 제거, 검색을 담당하는 내부 배열입니다. 직접 접근하기보다는 제공된 메서드를 통해 조작하는 것을 권장합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); console . log (collection. _list ); // Out: ['item1', 'item2'] add() 메소드로 요소를 추가하면 내부적으로 _list 에 저장됩니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"count 또는 length","url":"api/property-collection.html#count-또는-length","text":"count 또는 length 컬렉션의 요소 개수를 나타내는 속성입니다. 별칭으로 length 참조 속성을 제공합니다. ts declare const count : number ; count 는 컬렉션 객체에서 요소의 개수를 나타내는 읽기 전용 속성입니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); console . log (collection. count ); // Out: 2 console . log (collection. length ); // Out: 2 count 속성과 length 속성을 통해 현재 컬렉션의 요소 개수를 확인합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"주요 메소드","url":"api/property-collection.html#주요-메소드","text":"주요 메소드"},{"title":"PropertyCollection","group":"API 레퍼런스","section":"add()","url":"api/property-collection.html#add","text":"add() 컬렉션에 새로운 요소를 추가하는 메서드입니다. ts declare function add ( key : string , elem : any , desc ?: PropertyDescriptor ): number ; key : string: 추가할 요소의 고유 키 elem : any: 컬렉션에 추가할 요소 desc(선택) : 속성을 설명하는 디스크립터 반환값 : 추가한 요소의 인덱스 add() 메서드는 컬렉션에 새로운 요소를 추가하고, 고유 키를 기반으로 관리합니다. 선택적으로 PropertyDescriptor 를 사용하여 요소의 속성을 정의할 수 있습니다. 중복된 키가 사용될 경우 예외가 발생합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' , { writable : true }); console . log (collection. count ); // Out: 2 console . log (collection. length ); // Out: 2 console . log (collection. contains ( 'key1' )); // Out: true add() 메서드를 사용하여 컬렉션에 고유 키와 함께 새로운 요소를 추가합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"clear()","url":"api/property-collection.html#clear","text":"clear() 컬렉션의 모든 요소를 제거하는 메서드입니다. ts declare function clear ( ): void ; clear() 메서드는 컬렉션의 모든 데이터를 삭제하여 초기화합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); console . log (collection. contains ( 'key1' )); // Out: true // 컬렉션 초기화 collection. clear (); console . log (collection. contains ( 'key1' )); // Out: false 컬렉션의 모든 데이터를 제거하여 비어 있는 상태로 만듭니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"exist()","url":"api/property-collection.html#exist","text":"exist() 컬렉션에 특정 키가 존재하는지 확인하는 메서드입니다. ts declare function exist ( key : string ): boolean ; key : 확인할 키 반환값 : 키가 존재하면 true , 존재하지 않으면 false 를 반환합니다. exist() 메서드는 컬렉션에 특정 키가 포함되어 있는지 boolean 값으로 나타냅니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); console . log (collection. exist ( 'key1' )); // Out: true console . log (collection. exist ( 'key3' )); // Out: false exist() 메서드를 사용하여 특정 요소가 컬렉션에 포함되어 있는지 확인합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"remove()","url":"api/property-collection.html#remove","text":"remove() 컬렉션에서 특정 요소를 제거하는 메서드입니다. ts declare function remove ( elem : any ): number ; elem : 제거할 요소 반환값 : 제거된 요소의 인덱스 반환하고, 요소가 존재하지 않을 경우 -1 을 반환합니다. remove() 메서드는 컬렉션에서 특정 요소를 제거하고, 제거된 요소의 인덱스를 반환합니다. 요소가 존재하지 않으면 -1을 반환하며, 첫 번째로 매칭된 요소만 제거합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 요소 제거 console . log (collection. remove ( 'item1' )); // Out: 0 (인덱스 번호) console . log (collection. remove ( 'item3' )); // Out: -1 (요소가 존재하지 않음) // 요소 확인 console . log (collection. exist ( 'key1' )); // Out: false console . log (collection. exist ( 'key2' )); // Out: true remove() 메서드는 지정된 요소를 기준으로 제거를 수행하며, 제거된 요소의 인덱스를 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"removeAt()","url":"api/property-collection.html#removeat","text":"removeAt() 컬렉션에서 지정된 위치의 요소를 제거하는 메서드입니다. ts declare function removeAt ( pos : number ): boolean ; pos : 제거할 요소의 위치(인덱스) 반환값 : 요소 제거에 성공하면 true , 인덱스가 유효하지 않으면 false 를 반환합니다. removeAt() 메서드는 컬렉션에서 지정된 위치의 요소를 제거합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 인덱스로 요소 제거 console . log (collection. removeAt ( 0 )); // Out: true console . log (collection. removeAt ( 2 )); // Out: false (유효하지 않은 인덱스) // 요소 확인 console . log (collection. exist ( 'key1' )); // Out: false console . log (collection. exist ( 'key2' )); // Out: true removeAt() 메서드를 호출하여 지정된 인덱스의 요소를 제거합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"contains()","url":"api/property-collection.html#contains","text":"contains() 컬렉션에 특정 요소가 포함되어 있는지 확인하는 메서드입니다. ts declare function contains ( elem ): boolean ; elem : 확인할 요소 반환값 : 요소가 컬렉션에 포함되어 있으면 true , 그렇지 않으면 false 를 반환합니다. contains() 메서드는 컬렉션에 특정 요소가 포함되어 있는지 여부를 확인합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 요소 포함 여부 확인 console . log (collection. contains ( 'item1' )); // Out: true console . log (collection. contains ( 'item3' )); // Out: false contains() 메서드를 호출하여 특정 요소가 컬렉션에 포함되어 있는지 확인합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"indexOf()","url":"api/property-collection.html#indexof","text":"indexOf() 컬렉션에서 특정 요소의 인덱스를 반환하는 메서드입니다. ts declare function indexOf ( elem : any ): number ; elem : 인덱스를 찾을 요소 반환값 : 요소의 인덱스를 반환하고, 요소가 존재하지 않을 경우 -1 을 반환합니다. indexOf() 메서드는 컬렉션에서 특정 요소의 인덱스를 검색하는 데 사용됩니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 요소 인덱스 확인 console . log (collection. indexOf ( 'item1' )); // Out: 0 console . log (collection. indexOf ( 'item2' )); // Out: 1 console . log (collection. indexOf ( 'item3' )); // Out: -1 indexOf() 메서드를 호출하여 특정 요소의 인덱스를 검색합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"keyToIndex()","url":"api/property-collection.html#keytoindex","text":"keyToIndex() 컬렉션에서 특정 키에 해당하는 인덱스를 반환하는 메서드입니다. ts declare function keyToIndex ( key : string ): number ; key : 인덱스를 찾을 요소의 키 반환값 : 키의 인덱스를 반환하고, 키가 없으면 -1 을 반환합니다. keyToIndex() 메서드는 컬렉션에서 특정 키에 매핑된 요소의 인덱스를 검색합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 키의 인덱스 검색 console . log (collection. keyToIndex ( 'key1' )); // Out: 0 console . log (collection. keyToIndex ( 'key2' )); // Out: 1 console . log (collection. keyToIndex ( 'key3' )); // Out: -1 keyToIndex() 메서드를 호출하여 특정 키에 매핑된 요소의 인덱스를 검색합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"indexToKey()","url":"api/property-collection.html#indextokey","text":"indexToKey() 컬렉션에서 지정된 인덱스에 해당하는 요소의 키를 반환하는 메서드입니다. ts declare function indexToKey ( idx : number ): string | undefined ; index : 키를 검색할 요소의 인덱스 반환값 : 인덱스에 해당하는 키를 반환하며, 유효하지 않은 인덱스일 경우 undefined 를 반환합니다. indexToKey() 메서드는 컬렉션에서 지정된 인덱스의 요소에 매핑된 키를 반환합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 인덱스를 기반으로 키 검색 console . log (collection. indexToKey ( 0 )); // Out: 'key1' console . log (collection. indexToKey ( 1 )); // Out: 'key2' console . log (collection. indexToKey ( 2 )); // Out: undefined (유효하지 않은 인덱스) indexToKey() 메서드를 호출하여 특정 인덱스에 매핑된 키를 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"주요 고차 함수","url":"api/property-collection.html#주요-고차-함수","text":"주요 고차 함수"},{"title":"PropertyCollection","group":"API 레퍼런스","section":"map()","url":"api/property-collection.html#map","text":"map() 컬렉션의 각 요소에 함수를 적용하여 새로운 배열을 반환하는 고차 함수입니다. ts declare function map<T, U>( callbackfn : ( value : T, index : number , key : string , array : T[] ) => U, thisArg ?: any ): U[]; callbackfn : 새로운 배열 요소를 생성하는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : map() 을 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 U[] : 콜백 함수의 결과를 포함한 새로운 배열을 반환합니다. map() 함수는 컬렉션의 모든 요소에 대해 순차적으로 주어진 콜백 함수를 실행하고, 각 실행 결과를 새로운 배열로 반환합니다. 원본 컬렉션은 변경되지 않으며, 데이터 변환이나 계산 작업에 유용합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 1 ); collection. add ( 'key2' , 2 ); // 요소 값을 두 배로 변환 const doubledValues = collection. map ( ( value ) => value * 2 ); console . log (doubledValues); // Out: [2, 4] map() 함수를 호출하여 각 요소의 값을 두 배로 변환하는 콜백을 전달합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"filter()","url":"api/property-collection.html#filter","text":"filter() 조건을 만족하는 요소만 포함하는 새로운 배열을 반환하는 고차 함수입니다. ts declare function filter<T>( callbackfn : ( value : T, index : number , key : string , array : T[] ) => boolean , thisArg ?: any ): T[]; callbackfn : 조건을 검사하는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : filter() 를 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 T[] : 조건을 만족하는 요소들로 구성된 새로운 배열. filter() 함수는 컬렉션에서 주어진 조건을 만족하는 요소만 추출하여 새로운 배열을 반환합니다. 원본 컬렉션은 변경되지 않으며, 데이터 필터링 작업에 유용합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 1 ); collection. add ( 'key2' , 2 ); collection. add ( 'key3' , 3 ); // 짝수 값만 필터링 const evenValues = collection. filter ( ( value ) => value % 2 === 0 ); console . log (evenValues); // Out: [2] filter() 함수를 호출하여 짝수 조건에 만족하는 요소만 추출하여 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"reduce()","url":"api/property-collection.html#reduce","text":"reduce() 컬렉션의 모든 요소를 순회하며 누적 값을 계산하는 고차 함수입니다. ts declare function reduce<T, U>( callbackfn : ( previousValue : U, currentValue : T, currentIndex : number , currentKey : string , array : T[] ) => U, initialValue : U ): U; callbackfn : 누적 값을 계산하는 함수 previousValue : 이전 콜백 실행의 반환값 또는 초기값 currentValue : 처리할 현재 요소 currentIndex : 처리할 현재 요소의 인덱스 currentKey : 처리할 현재 요소의 키 array : reduce() 를 호출한 배열 initialValue : 누적 연산의 초기값 T: 배열 요소 타입 U : 최종 계산 결과 reduce() 함수는 컬렉션의 모든 요소를 순회하며, 주어진 콜백 함수를 사용해 누적 결과를 계산합니다. 초기값이 설정되면 첫 번째 콜백 호출 시 previousValue 로 사용되며, 설정하지 않으면 컬렉션의 첫 번째 요소가 초기값이 됩니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 1 ); collection. add ( 'key2' , 2 ); collection. add ( 'key3' , 3 ); // 모든 값을 합산 const sum = collection. reduce ( ( acc, value ) => acc + value, 0 ); console . log (sum); // Out: 6 reduce() 함수를 호출하여 각 요소를 순회하며 누적 값을 계산하는 콜백을 전달합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"find()","url":"api/property-collection.html#find","text":"find() 컬렉션에서 조건을 만족하는 첫 번째 요소를 반환하는 고차 함수입니다. ts declare function find<T>( callbackfn : ( value : T, index : number , key : string , array : T[] ) => boolean , thisArg ?: any ): T | undefined ; callbackfn : 조건을 검사하는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : find() 를 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 반환값 : 조건을 만족하는 첫 번째 요소를 반환하며, 조건에 맞는 요소가 없으면 undefined 를 반환합니다. find() 함수는 컬렉션에서 조건을 만족하는 첫 번째 요소를 반환합니다. Tip : 데이터 검색이나 특정 조건에 부합하는 값을 찾는 데 유용합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 10 ); collection. add ( 'key2' , 20 ); collection. add ( 'key3' , 30 ); // 조건을 만족하는 첫 번째 요소 검색 const found = collection. find ( ( value ) => value > 15 ); console . log (found); // Out: 20 find() 함수를 호출하여 값이 15보다 큰 첫 번째 요소를 찾아 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"findIndex()","url":"api/property-collection.html#findindex","text":"findIndex() 컬렉션에서 조건을 만족하는 첫 번째 요소의 인덱스를 반환하는 고차 함수입니다. ts declare function findIndex<T>( callbackfn : ( value : T, index : number , key : string , array : T[] ) => boolean , thisArg ?: any ): number ; callbackfn : 조건을 검사하는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : findIndex() 를 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 반환값 : 조건을 만족하는 첫 번째 요소의 인덱스를 반환하며, 조건에 맞는 요소가 없으면 -1 을 반환합니다. findIndex() 함수는 컬렉션에서 조건에 만족하는 첫 번째 요소의 인덱스를 반환합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 10 ); collection. add ( 'key2' , 20 ); collection. add ( 'key3' , 30 ); // 조건을 만족하는 첫 번째 요소의 인덱스 검색 const index = collection. findIndex ( ( value ) => value > 15 ); console . log (index); // Out: 1 findIndex 함수를 호출하여 값이 15보다 큰 첫 번째 요소의 인덱스를 찾아 반환합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"forEach","url":"api/property-collection.html#foreach","text":"forEach 컬렉션의 각 요소에 대해 주어진 작업을 수행하는 고차 함수입니다. ts declare function forEach<T>( callbackfn : ( value : T, index : number , key : string , array : T[] ) => void , thisArg ?: any ): void ; callbackfn : 각 요소에 대해 호출되는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : forEach() 를 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 forEach() 함수는 컬렉션의 각 요소에 대해 주어진 콜백 함수를 실행합니다. 이 함수는 반환값이 없으며 원본 컬렉션은 변경되지 않습니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 10 ); collection. add ( 'key2' , 20 ); collection. add ( 'key3' , 30 ); // 각 요소 출력 collection. forEach ( ( value, index ) => { console . log ( `인덱스 ${index} , 키 \" ${ this .indexToKey(index)} \", 값 ${value} ` ); }); // Out: // '인덱스 0, 키 \"key1\", 값 10' // '인덱스 1, 키 \"key2\", 값 20' // '인덱스 2, 키 \"key3\", 값 30' forEach 함수를 호출하여 각 요소와 해당 인덱스를 출력합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"some()","url":"api/property-collection.html#some","text":"some() 조건을 만족하는 요소가 하나라도 있으면 true를 반환하는 고차 함수입니다. ts type callbackFn = ( value : any , index : number , key : string , array : this ) => any ; type some = ( callbackFn, thisArg ?: any ) => boolean ; callbackfn : 조건을 검사하는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : some() 을 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 반환값 : 조건을 만족하는 요소가 하나라도 있으면 true , 그렇지 않으면 false 를 반환합니다. some() 함수는 컬렉션에서 조건을 만족하는 요소가 하나라도 있으면 순회를 중단하고 true 를 반환합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 10 ); collection. add ( 'key2' , 20 ); collection. add ( 'key3' , 30 ); // 조건 검사 console . log (collection. some ( item => item > 25 )); // Out: true some() 함수는 첫 번째로 조건을 만족하는 요소를 찾으면 true 를 반환하고 즉시 종료합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"every()","url":"api/property-collection.html#every","text":"every() 컬렉션의 모든 요소가 주어진 조건을 만족하면 true 를 반환하는 고차 함수입니다. ts declare function some<T>( callbackfn : ( value : T, index : number , key : string , array : T[] ) => boolean , thisArg ?: any ): boolean ; callbackfn : 조건을 검사하는 함수 value : 처리할 현재 요소 index : 처리할 현재 요소의 인덱스 key : 처리할 현재 요소의 키 array : some() 을 호출한 배열 thisArg(선택) : callback 을 실행할 때 this 로 사용되는 값 반환값 : 모든 요소가 조건을 만족하면 true , 그렇지 않으면 false 를 반환합니다. every() 함수는 컬렉션의 모든 요소가 주어진 조건을 만족하면 true 를 반환합니다. js const collection = new PropertyCollection (); // 요소 추가 collection. add ( 'key1' , 10 ); collection. add ( 'key2' , 20 ); collection. add ( 'key3' , 30 ); // 모든 조건이 만족하는 확인 console . log (collection. every ( ( value ) => value > 25 )); // Out: false every() 함수를 호출하여 모든 값이 25보다 큰 요소인지 확인합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"주요 이벤트","url":"api/property-collection.html#주요-이벤트","text":"주요 이벤트"},{"title":"PropertyCollection","group":"API 레퍼런스","section":"onAdd","url":"api/property-collection.html#onadd","text":"onAdd 컬렉션에 요소를 추가하기 직전에 호출되는 이벤트입니다. ts type onAdd = ( elem : any , idx : number , _this : object ) => void ; elem : 추가하려는 요소 idx : 추가되는 요소의 인덱스 _this : 이벤트를 호출한 객체 onAdd 는 컬렉션에 요소가 추가되기 전에 실행되는 이벤트로, 요소 추가 전에 유효성 검사나 기타 사전 작업을 수행하는 데 활용됩니다. 콜백 함수에서 false 를 반환하면 해당 요소의 추가와 이벤트 처리가 중단됩니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const collection = new PropertyCollection (); // onAdd 이벤트 설정 collection. onAdd = function ( idx, elem, _this ) { if ( typeof elem !== \"string\" ) { console . log ( `인덱스 ${idx} : 문자열만 추가 가능합니다.` ); return false ; } console . log ( `인덱스 ${idx} : 추가된 요소는 ' ${elem} '입니다.` ); }; // 요소 추가 collection. add ( 'key1' , \"Item\" ); // Out: '인덱스 0: 추가된 요소는 'Item'입니다.' collection. add ( 'key2' , 123 ); // Out: '인덱스 1: 문자열만 추가 가능합니다.' console . log (collection. count ); // Out: 1 요소 추가시 요소 타입에 따라 콘솔에 로그를 출력합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"onAdded","url":"api/property-collection.html#onadded","text":"onAdded 컬렉션에 요소가 성공적으로 추가된 후 호출되는 이벤트입니다. ts type onAdded = ( elem : any , idx : number , _this : object ) => void ; elem : 추가된 요소 idx : 추가된 요소의 인덱스 _this : 이벤트를 호출한 객체 onAdded 는 컬렉션에 요소가 성공적으로 추가된 후 실행되는 이벤트로, 후속 처리를 수행하거나 사용자에게 알림을 제공하는 데 활용됩니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const collection = new PropertyCollection (); // onAdded 이벤트 설정 collection. onAdded = function ( idx, elem, _this ) { console . log ( `인덱스 ${idx} : ${elem} 이(가) 추가되었습니다.` ); }; // 요소 추가 collection. add ( 'key1' , 'item1' ); // Out: '인덱스 0: item1이(가) 추가되었습니다.' collection. add ( 'key2' , 'item2' ); // Out: '인덱스 1: item2이(가) 추가되었습니다.' 요소 추가시 콘솔에 로그를 출력합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"onRemove","url":"api/property-collection.html#onremove","text":"onRemove 컬렉션에서 요소가 제거되기 전에 호출되는 이벤트입니다. ts type onRemove = ( elem : any , idx : number , _this : object ) => void ; elem : 제거될 요소 idx : 제거될 요소의 인덱스 _this : 이벤트를 호출한 객체 onRemove 는 컬렉션에서 요소가 제거되기 전에 실행되는 이벤트로, 제거 작업을 제어하는 데 사용됩니다. 콜백 함수에서 false 를 반환하면 해당 요소의 제거가 중단됩니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const collection = new PropertyCollection (); // onRemove 이벤트 설정 collection. onRemove = function ( idx, elem, _this ) { if (elem === \"protected\" ) { console . log ( `인덱스 ${idx} : 보호된 요소는 제거할 수 없습니다.` ); return false ; } console . log ( `인덱스 ${idx} : ${elem} 이(가) 제거됩니다.` ); return true ; }; // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , \"protected\" ); // 요소 제거 collection. remove ( 'key1' ); // Out: '인덱스 0: item1이(가) 제거됩니다.' collection. remove ( 'key2' ); // Out: '인덱스 1: 보호된 요소는 제거할 수 없습니다.' onRemove 이벤트를 설정하여 유효성 검사를 통과한 요소만 제거됩니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"onRemoved","url":"api/property-collection.html#onremoved","text":"onRemoved 컬렉션에서 요소가 성공적으로 제거된 후 호출되는 이벤트입니다. ts type onRemoved = ( elem : any , idx : number , _this : object ) => void ; elem : 제거된 요소 idx : 제거된 요소의 인덱스 _this : 이벤트를 호출한 객체 onRemoved 는 컬렉션에서 요소가 성공적으로 제거된 후 실행되는 이벤트로, 후속 작업을 수행하거나 로그를 기록하는 데 활용됩니다. 데이터 변경 후 UI를 업데이트하거나 제거 작업의 결과를 사용자에게 알리는 데 사용됩니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const collection = new PropertyCollection (); // onRemoved 이벤트 설정 collection. onRemoved = function ( idx, elem, _this ) { console . log ( `인덱스 ${idx} : ${elem} 이(가) 제거되었습니다.` ); }; // 요소 추가 collection. add ( 'key1' , 'item1' ); collection. add ( 'key2' , 'item2' ); // 요소 제거 collection. remove ( 'key1' ); // Out: '인덱스 0: item1이(가) 제거되었습니다.' collection. remove ( 'key2' ); // Out: '인덱스 1: item2이(가) 제거되었습니다.' 요소 제거 시 콘솔에 로그를 출력합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"onClear","url":"api/property-collection.html#onclear","text":"onClear 컬렉션의 모든 요소가 제거되기 전에 호출되는 이벤트입니다. ts type onClear = ( _this : object ) => void ; _this : 이벤트를 호출한 객체 onClear 는 컬렉션의 모든 요소가 제거되기 전에 실행되는 이벤트로, 초기화 작업 전에 후속 작업을 설정하거나 로그를 남기는 데 활용됩니다. 콜백 함수에서 false 를 반환하면 요소 제거가 중단됩니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const collection = new PropertyCollection (); // onClear 이벤트 설정 collection. onClear = function ( _this ) { console . log ( \"컬렉션 초기화 작업을 시작합니다.\" ); console . log ( `초기화되는 컬렉션:` , _this); }; // 컬렉션 초기화 collection. clear (); onClear 이벤트를 설정하여 초기화 작업 전 콘솔에 로그를 출력합니다."},{"title":"PropertyCollection","group":"API 레퍼런스","section":"onCleared","url":"api/property-collection.html#oncleared","text":"onCleared 컬렉션의 모든 요소가 성공적으로 제거된 후 호출되는 이벤트입니다. ts type onCleared = ( _this : object ) => void ; _this : 이벤트를 호출한 객체 onCleared 는 컬렉션이 성공적으로 초기화된 후 실행되는 이벤트로, 초기화 후 후속 작업을 처리하거나 사용자에게 알림을 제공하는 데 유용합니다. Tip : 이벤트 속성에 콜백함수를 설정하면, 기존 이벤트는 그대로 유지되며 새 이벤트가 추가됩니다. js const collection = new PropertyCollection (); // onCleared 이벤트 설정 collection. onCleared = function ( _this ) { console . log ( '컬렉션이 성공적으로 초기화되었습니다.' ); console . log ( `초기화된 컬렉션:` , _this); }; // 컬렉션 초기화 collection. clear (); // Out: // '컬렉션이 성공적으로 초기화되었습니다.' // `초기화된 컬렉션:` [Object PropertyCollection] onCleared 이벤트를 설정하여 초기화 작업 완료 후 콘솔에 로그를 출력합니다. 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 HTMLColumn 다음 문서 MetaObject"},{"title":"MetaObject","group":"API 레퍼런스","section":"MetaObject","url":"api/meta-object.html","text":"문서 API 레퍼런스 API 레퍼런스 05 MetaObject 객체 식별, 타입 확인, 직렬화를 위한 기본 API입니다. 한국어 문서 약 10분 MetaObject 는 모델(BindModel)과 연관된 모든 클래스의 최상위 클래스 입니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"구성 요소","url":"api/meta-object.html#구성-요소","text":"구성 요소"},{"title":"MetaObject","group":"API 레퍼런스","section":"속성","url":"api/meta-object.html#속성","text":"속성 항목 설명 _guid 객체의 고유 식별자입니다. _type 객체의 생성 함수를 참조합니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"메소드","url":"api/meta-object.html#메소드","text":"메소드 항목 설명 equal() 두 객체를 비교하여 동일성을 확인합니다. getTypes() 객체의 상속 계층 구조를 반환합니다. instanceOf() 객체가 특정 클래스의 인스턴스인지 확인합니다. getObject() 현재 객체를 직렬화된 객체로 반환합니다. setObject() 직렬화된 객체를 현재 객체에 설정합니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"주요 속성","url":"api/meta-object.html#주요-속성","text":"주요 속성"},{"title":"MetaObject","group":"API 레퍼런스","section":"_guid","url":"api/meta-object.html#_guid","text":"_guid 객체의 고유 식별자 속성입니다. ts type _guid = string ; _guid 속성은 객체의 고유성을 보장하는 중요한 속성입니다. BindModel의 모든 객체는 _guid 값을 가지며, 객체 생성 시 자동으로 설정됩니다. 이 값은 수동으로 수정하거나 변경할 수 없습니다. js // 객체 생성 const obj1 = new MetaObject (); const obj2 = new MetaObject (); console . log ( \"Object 1 GUID:\" , obj1. _guid ); console . log ( \"Object 2 GUID:\" , obj2. _guid ); console . log ( \"Are GUIDs unique? \" , obj1. _guid !== obj2. _guid ); // Out: true obj1._guid 와 obj2._guid 를 비교하여 두 값이 서로 다른지 확인합니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"_type","url":"api/meta-object.html#_type","text":"_type 객체의 생성 함수를 참조하는 속성입니다. ts type _type = Function ; _type 속성은 MetaObject 클래스를 상속한 모든 객체가 생성될 때 자동으로 설정되며, 객체의 클래스 또는 생성자를 가르킵니다. js // 객체 생성 const obj1 = new MetaTable ( 't1' ); const obj2 = new MetaColumn ( 'c1' ); console . log (obj1. _type === MetaTable ); // Out: true console . log (obj2. _type === MetaColumn ); // Out: true _type 속성은 MetaObject 을 상속한 객체의 생성자를 확인하는데 사용됩니다. js // MetaObject 자식 클래스 정의 class MyClass extends MetaObject {} // 객체 생성 const metaObj = new MetaObject (); const myObj = new MyClass (); console . log (metaObj. _type === MetaObject ); // Out: true console . log (myObj. _type === MyClass ); // Out: true MetaObject 클래스를 상속한 클래스에서 _type 을 통해 생성자를 확인할 수 있습니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"주요 메소드","url":"api/meta-object.html#주요-메소드","text":"주요 메소드"},{"title":"MetaObject","group":"API 레퍼런스","section":"equal()","url":"api/meta-object.html#equal","text":"equal() 현재 객체와 지정된 객체가 동일하는 메서드입니다. ts declare function equal ( target : MetaObject ): boolean ; target : 비교할 대상 객체 equal() 메서드는 _guid 속성을 제외하고 객체가 동일한지 비교합니다. js // 객체 생성 const obj1 = new MetaObject (); const obj2 = new MetaObject (); const obj3 = {}; // equal() 메서드 사용 console . log (obj1. equal (obj2)); // Out: true console . log (obj1. equal (obj3)); // Out: false equal() 메서드 사용하여 객체가 동일한지 확인합니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"getTypes()","url":"api/meta-object.html#gettypes","text":"getTypes() 객체의 상속 계층 구조를 반환하는 메서드입니다. ts declare function getTypes ( ) : Function []; Array<Function> : 상속 계층의 함수 배열 배열의 첫 번째 요소는 생성자 함수입니다. 이후 요소는 상위 클래스 생성자 함수가 순서대로 포함됩니다. getTypes() 메서드는 객체의 클래스의 상속 계층 구조를 배열로 반환합니다. js // 클래스 정의 class MyClass extends MetaObject {} // 객체 생성 const obj = new MyClass (); console . log (obj. getTypes ()); // Out: [MyClass, MetaObject] 반환된 배열은 MyClass 부터 시작하여 MetaObject 순으로 상속 계층 구조를 보여줍니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"instanceOf()","url":"api/meta-object.html#instanceof","text":"instanceOf() 객체가 특정 클래스의 인스턴스인지 확인하는 메서드입니다. ts declare function instanceOf ( target : object | string ): boolean ; target : 클래스 생성자 함수 또는 클래스 이름(문자열) 반환값 : 객체의 생성자 함수와 일치하거나, 상속 관계에 있는 경우 true 를 반환합니다. instanceOf() 메서드는 객체의 생성자 함수 또는 생성자 이름을 사용하여 인스턴스 여부를 검사합니다. instanceof 연산자 같은 역활을 수행하지만 추가적으로 다음 기능을 제공합니다. 인터페이스 타입 검사 : 정의된 인터페이스 타입을 함께 검사할 수 있습니다. (별도 제공 예정) 느슨한 검사 지원 : 생성자 함수를 문자열로 검사하여 의존성 문제를 우회할 수 있습니다. 인스턴스 검사 예제 js // 클래스 정의 class MyClass extends MetaObject { /* 클래스 정의 */ } // 객체 생성 const obj = new MyClass (); const meta = new MetaObject (); // 생성자 기반 타입 확인 console . log (obj. instanceOf ( MetaObject )); // Out: true console . log (obj. instanceOf ( MyClass )); // Out: true console . log (meta. instanceOf ( MetaObject )); // Out: true // 문자열 기반 타입 확인 console . log (obj. instanceOf ( 'MetaObject' )); // Out: true console . log (obj. instanceOf ( 'MyClass' )); // Out: true console . log (meta. instanceOf ( 'MetaObject' )); // Out: true instanceOf() 메소드를 사용해서 생성자 또는 생성자명으로 인스턴스 여부를 검사합니다. 정적 인터페이스 타입 ts declare class MyClass { static _UNION : Function []; } // 또는 declare class MyClass {} declare namespace MyClass { const _UNION : Function []; } _UNION 정적 배열 타입으로 인터페이스를 정의할 수 있습니다. 인터페이스 구현 검사 예제 js // 인터페이스 정의 class IClassA {} class IClassB {} // 클래스 정의 class MyClass extends MetaObject {} // 인터페이스 구현 지정 MyClass . _UNION = [ IClassA , IClassB ]; const obj = new MyClass (); console . log (obj. instanceOf ( MyClass )); // Out: true console . log (obj. instanceOf ( IClassA )); // Out: true console . log (obj. instanceOf ( IClassB )); // Out: true obj 객체가 MyClass 의 인스턴스이거나, IClassA , IClassB 인터페이스를 구현했는지 검사합니다. 추후 인터페이스 사용 방법이 제공될 예정입니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"getObject()","url":"api/meta-object.html#getobject","text":"getObject() 현재 객체를 직렬화된 객체로 반환하는 메서드입니다. ts declare function getObject ( vOpt ?: number , owned ?: object | object [] ): object ; vOpt(선택) : 직렬화 옵션 (기본값 0 ) 0 : guid 참조 구조를 유지합니다 ( _guid: 예 , $ref: 예 ) 1 : guid 중복 구조로 출력합니다 ( _guid: 예 , $ref: 예 ) 2 : 비참조 구조로 출력합니다 ( _guid: 아니오 , $ref: 아니오 ). owned(선택) : 소유 객체나 소유 객체 배열 기본값은 빈 객체이며, 데이터 출력 시 소유 관계를 포함하거나 필터링할 때 사용됩니다. getObject() 메서드는 현재 객체를 직렬화된 JSON 형식의 객체로 반환합니다. 이를 활용하여 객체의 내부 데이터를 시각화하거나 외부로 전달할 수 있습니다. 반환된 데이터는 객체의 현재 상태를 복사한 값이며, 원본 객체에 영향을 주지 않습니다. js // 객체 생성 const v1 = new MetaView ( 'view1' ); const v2 = new MetaView ( 'view2' ); // 객체 직렬화 const obj = v1. getObject (); // 객체 역직렬화 v2. setObject (obj); console . log (v1. _guid === v2. _guid ); // Out: false console . log (v1. viewName ); // Out: 'view1' console . log (v2. viewName ); // Out: 'view1' v1 객체는 v2 와 동일한 데이터를 갖지만, 고유 식별자( _guid )는 서로 다릅니다."},{"title":"MetaObject","group":"API 레퍼런스","section":"setObject()","url":"api/meta-object.html#setobject","text":"setObject() 직렬화된 객체를 현재 객체에 설정하는 메서드입니다. ts declare function setObject ( oGuid : object , origin ?: object ): void ; oGuid : 직렬화된 객체 데이터로, 현재 객체에 설정할 속성과 값을 포함합니다. origin(선택) : 내부 컨텍스트 객체 설정시 내부적으로 사용되면 추가적인 컨텍스트 정보를 설정할 수 있습니다. setObject() 메서드는 getObject() 를 통해 얻은 직렬화 객체를 사용하여 현재 객체를 설정합니다. 이 과정에서 기존에 설정된 데이터는 모두 삭제됩니다. js // 객체 생성 const v1 = new MetaView ( 'view1' ); const v2 = new MetaView ( 'view2' ); // 객체 직렬화 const obj = v1. getObject (); // 객체 역직렬화 v2. setObject (obj); console . log (v1. _guid === v2. _guid ); // Out: false console . log (v1. viewName ); // Out: 'view1' console . log (v2. viewName ); // Out: 'view1' v1 객체는 v2 와 동일한 데이터를 가지지만, 고유 식별자( _guid )는 다릅니다. #메모 Util.implements() : 메소드에서는 대상 객체가 인터페이스를 구현하였으면, _inteface 속성이 추가 됩니다. Function._UNION = [] : 함수 정의된 정적 인터페이스 {}._interface = [] : 객체에 정의된 동적 인터페이스 더 나은 문서를 함께 만들어요. 오류 제보 및 개선 제안 이전 문서 PropertyCollection"}];
